-- Battlegrounds rules engine. Pure Lua 5.2 with no Tabletop Simulator calls.
-- Depends on BG_CARDS (Scripts/bg_cards.lua) and BG_HEROES/BG_TRINKETS/BG_ANOMALIES (Scripts/bg_meta.lua).
-- v4: hero powers, trinkets, anomalies and buddies plug in through E.hooks (Scripts/bg_heroes.lua).
BG = {}
local E = BG
E.HP, E.TR, E.AN, E.BUDDY = {}, {}, {}, {}

E.MAX_BOARD, E.MAX_HAND, E.TAVERN_SIZE = 7, 10, {3, 4, 4, 5, 5, 6, 6}
-- Real values (hearthstone.wiki.gg/wiki/Battlegrounds, 2026): copies per tier, upgrade base costs.
E.COPIES = {15, 15, 13, 11, 9, 7, 5}
E.UPGRADE = {[2] = 5, [3] = 7, [4] = 8, [5] = 11, [6] = 11, [7] = 11}
E.LOBBY_TRIBES = 5
E.RACE_NAME = {BEAST = "Beast", MECHANICAL = "Mech", DEMON = "Demon", PIRATE = "Pirate",
    DRAGON = "Dragon", ELEMENTAL = "Elemental", MURLOC = "Murloc", UNDEAD = "Undead",
    NAGA = "Naga", QUILBOAR = "Quilboar", ABERRATION = "Aberration"}
local KEYWORDS = {"taunt", "shield", "reborn", "windfury", "venom", "stealth", "poison"}
E.KEYWORD_NAMES = {resilient="Resilient",taunt="Taunt",shield="Divine Shield",reborn="Reborn",windfury="Windfury",
    venom="Venomous",stealth="Stealth",poison="Poisonous"}
E.KEYWORDS = KEYWORDS

-------------------------------------------------------------------------------
-- helpers
local function rnd(g, n) return g.rand(n) end
local function pick(g, list) if #list == 0 then return nil end return list[rnd(g, #list)] end
local function card(id) return BG_CARDS[id] end
local function mult(m) return m.golden and 2 or 1 end
local function hasRace(m, race)
    local c = card(m.id)
    if c.all or (m.darkGift and m.darkGift.allTypes) then return true end
    for _, r in ipairs(c.races) do if r == race then return true end end
    return false
end
E.hasRace = hasRace
local function indexOf(list, x) for i, v in ipairs(list) do if v == x then return i end end return nil end
E.deityConduits=setmetatable({},{__mode="k"})
local elementalBonusA,elementalBonusH=0,0
function E.withElementalAura(p,m,fn,...)
    if not p or not hasRace(m,"ELEMENTAL") then return fn(...) end
    local trinket=p.trinkets and indexOf(p.trinkets,"BG36_MagicItem_380") and 1+(p.essence or 0) or 0
    local a,h=(p.elementalGrantA or 0)+trinket,(p.elementalGrantH or 0)+trinket
    for _,ally in ipairs(p.board or {}) do
        local f=E.FX and E.FX[ally.id]
        if f and f.elementalAura then
            a,h=a+f.elementalAura[1]*mult(ally),h+f.elementalAura[2]*mult(ally)
        end
    end
    if a==0 and h==0 then return fn(...) end
    local oldA,oldH=elementalBonusA,elementalBonusH
    elementalBonusA,elementalBonusH=a,h
    local ok,result,reason=pcall(fn,...)
    elementalBonusA,elementalBonusH=oldA,oldH
    if not ok then error(result) end
    return result,reason
end
local function buff(m, a, h, skipKeep)
    if m.id=="BG36_205" then return end
    if not skipKeep and (a>0 or h>0) then a,h=a+elementalBonusA,h+elementalBonusH end
    local conduit=not m.inCombat and E.deityConduits[m]
    if conduit and not skipKeep and (a>0 or h>0) then E.deityBless(conduit,math.max(0,a),math.max(0,h)) end
    if not m.inCombat and (a > 0 or h > 0) and E.questStat then E.questStat(m) end
    m.atk = m.atk + a; m.hp = m.hp + h; if m.maxhp then m.maxhp = m.maxhp + h end
    if m.inCombat then
        m.gA,m.gH=(m.gA or 0)+a,(m.gH or 0)+h
        local factor=math.max(m.keepersFactor or 0,m.poetFactor or 0)
        if factor>0 and not skipKeep then
            m.keptAtk,m.keptHp=(m.keptAtk or 0)+a*factor,(m.keptHp or 0)+h*factor
        end
    end
    if E.notifyStats and (a>0 or h>0) then E.notifyStats(m,a,h) end
end
local function shuffle(g, t) for i = #t, 2, -1 do local j = rnd(g, i); t[i], t[j] = t[j], t[i] end return t end
local function copyTable(t)
    local r = {}
    for k, v in pairs(t) do r[k] = type(v) == "table" and copyTable(v) or v end
    return r
end
E.copy = copyTable

