    function E.activateSeason(key)
        for id, def in pairs(original) do BG_CARDS[id] = def end
        original = {}
        for id, stats in pairs(E.seasonStats[key] or {}) do
            local def = BG_CARDS[id]
            original[id] = def
            local version = {}
            for field, value in pairs(def) do version[field] = value end
            version.tier, version.atk, version.hp, version.gatk, version.ghp = table.unpack(stats)
            version.historicalStats = true
            BG_CARDS[id] = version
        end
    end
end


local function event(g, color, fx, msg)
    table.insert(g.events, {color = color, fx = fx, msg = msg})
end
E.event = event

-- Fire a named hook on the player's hero, trinkets, the lobby Anomaly and the Buddy system.
function E.hasPower(p,id)
    return (p.powerHero or p.hero)==id or p.secondPowerHero==id
end
local function hooks(g,p,name,...)
    if not p then return end
    E.lastGame=g
    local h=p.hero and E.HP[p.hero]
    if h and h[name] then h[name](g,p,...) end
    local copied=p.powerHero and p.powerHero~=p.hero and E.HP[p.powerHero]
    if copied and copied~=h and copied[name] then copied[name](g,p,...) end
    local secondary=p.secondPowerHero and E.HP[p.secondPowerHero]
    if secondary and secondary~=h and secondary~=copied and secondary[name] then secondary[name](g,p,...) end
    for _, tid in ipairs(E.passives and E.passives(p) or p.trinkets or {}) do
        local t = E.TR[tid]
        if t and t[name] then t[name](g, p, ...) end
    end
    local a = g.anomaly and E.AN[g.anomaly]
    if a and a[name] then a[name](g, p, ...) end
    if g.buddies and E.BUDDY[name] then E.BUDDY[name](g, p, ...) end
    if E.SYS and E.SYS[name] then E.SYS[name](g, p, ...) end
end
E.hooks = hooks

function E.newMinion(g, id, golden)
    local c = card(id)
    if id == "BG32_236" then golden = true end -- Aureate Laureate: always Golden
    g.uid = g.uid + 1
    local m = {uid = g.uid, id = id, golden = golden or false,
        atk = golden and c.gatk or c.atk, hp = golden and c.ghp or c.hp}
    for _, k in ipairs(KEYWORDS) do if c[k] then m[k] = true end end
    if c.resilient then m.resilient = true end
    if g.season == "s15" then E.s15MarkKeywords(m) end
    if id=="BG36_360" then E.initParadox(g,m) end
    return m
end

