-- game setup
function E.new(opts)
    opts = opts or {}
    local g = {phase = "lobby", turn = 0, players = {}, order = {}, pool = {}, uid = 0,
        events = {}, rand = opts.rand or math.random, eliminated = {}, placements = {},
        heroChoices = opts.heroChoices or 4, lastResults = {}, history = {}, allCards = opts.allCards or false,
        season = opts.season, allowed = nil, trinkets = opts.trinkets and true or false, buddies = opts.buddies and true or false,
        anomalies = opts.anomalies and true or false}
    g.timewarpEnabled=opts.timewarp and true or false
    g.questsEnabled=opts.quests and true or false
    g.maxTier = (opts.tierSeven or opts.anomalies) and 7 or 6
    g.fullMinions=opts.fullMinions or g.allCards
    g.allTribes=opts.allTribes and true or false
    local enabled = {}
    local allowed = nil
    if opts.pool then allowed = {}; for _, id in ipairs(opts.pool) do allowed[id] = true end; g.allowed = allowed end
    for id, c in pairs(BG_CARDS) do
        local inPool = allowed and allowed[id] or (not allowed and c.pool)
        if inPool and not c.buddy and c.tier <= g.maxTier and (g.fullMinions or c.fx ~= "none") then enabled[id] = c end
    end
    -- Lobby minion types: five random types per game (neutral and all-type minions always in).
    g.tribes = opts.tribes
    if not g.tribes then
        -- In "scripted only" mode a type needs at least 4 scripted minions to be drawn for the lobby.
        local count, types = {}, {}
        for _, c in pairs(enabled) do
            for _, r in ipairs(c.races) do count[r] = (count[r] or 0) + 1 end
        end
        for r, n in pairs(count) do if n >= (g.fullMinions and 1 or 4) then table.insert(types, r) end end
        table.sort(types)
        if opts.allTribes then
            g.tribes = types
        else
            shuffle(g, types)
            g.tribes = {}
            for i = 1, math.min(opts.tribeCount or E.LOBBY_TRIBES, #types) do g.tribes[i] = types[i] end
            table.sort(g.tribes)
        end
    end
    local inLobby = {}
    for _, r in ipairs(g.tribes) do inLobby[r] = true end
    for id, c in pairs(enabled) do
        local ok = c.all or #c.races == 0
        for _, r in ipairs(c.races) do if inLobby[r] then ok = true end end
        if ok then g.pool[id] = E.COPIES[E.poolDefinition(g,c).tier] end
    end
    if g.anomalies and BG_ANOMALIES and #BG_ANOMALIES > 0 then
        local list = {}
        for _, a in ipairs(BG_ANOMALIES) do
            local rule = E.AN[a.id]
            if rule and (not opts.anomaly or opts.anomaly == a.id)
                and (not rule.canChoose or rule.canChoose(g)) then table.insert(list, a.id) end
        end
        g.anomaly = pick(g, list)
        local a = g.anomaly and E.AN[g.anomaly]
        if a and a.setup then a.setup(g) end
    end
    E.initDeity(g)
    return g
end

function E.addPlayer(g, color, name, bot)
    local p = {color = color, name = name or color, bot = bot and true or false, alive = true,
        hand = {}, board = {}, tavern = {}, tier = 1, maxTier = g.tierSevenUnlocked and 7 or 6, gold = 0, maxGold = 0, upgradeCost = E.UPGRADE[2],
        frozen = false, freeRefreshes = 0, hp = 30, armor = 0, ready = false, heroOptions = {},
        counters = {pogo = 0, bought = 0, piratesBought = 0, elementals = 0, buysTotal = 0},
        powerUsed = false, renoUsed = false, discover = nil, discoverQueue = {}}
    E.ensurePlayer(p)
    g.players[color] = p
    table.insert(g.order, color)
    return p
end

-- v3 per-player "this game" state (Blood Gems, tavern buffs, Undead attack, Beetles, ...).
function E.ensurePlayer(p)
    local d = {nextGold = 0, gemA = 1, gemH = 1, pendingGems = 0, refreshBuffs = 0, undeadAtk = 0,
        beetleA = 0, beetleH = 0, ekDeaths = 0, baller = 0, lobster = 0, spent = 0, lostLast = false,
        refreshBig = 0, goldenPlayed = 0, drTriggered = 0, malLeft = 0}
    for k, v in pairs(d) do if p[k] == nil then p[k] = v end end
    p.tavBuff = p.tavBuff or {}
    p.spellShop, p.spellHand = p.spellShop or {}, p.spellHand or {}
    return p
end

function E.player(g, color) return g.players[color] end

function E.alivePlayers(g)
    local list = {}
    for _, color in ipairs(g.order) do if g.players[color].alive then table.insert(list, g.players[color]) end end
    return list
end

function E.heroById(id)
    if not E._heroMap then
        E._heroMap = {}
        for _, h in ipairs(BG_HEROES or {}) do E._heroMap[h.id] = h end
    end
    return id and E._heroMap[id] or nil
end
function E.hero(p) return p.hero and E.heroById(p.hero) or nil end
function E.powerHero(p) return E.heroById(p.powerHero or p.hero) end
local function heroKey(p) local h = E.hero(p); return h and h.key or "" end
E.heroKey = heroKey

