local deityBans = {BG34_HERO_004=true, BG34_HERO_000=true, BG23_HERO_306=true}
local resurrectBans = {TB_BaconShop_HERO_33=true, TB_BaconShop_HERO_22=true, BG25_HERO_103=true, TB_BaconShop_HERO_93=true}
function E.heroAvailable(g, id)
    local tribes=heroAssociatedRaces[id]
    local tribe=heroTribe[id]
    if tribes then
        local present=false
        for _,r in ipairs(tribes) do if indexOf(g.tribes,r) then present=true;break end end
        if not present then return false end
    elseif tribe and not indexOf(g.tribes,tribe) then return false end
    if g.allTribes then return true end
    if g.deity and deityBans[id] then return false end
    return not (g.deity == "BGFYM_011" and resurrectBans[id])
end

function E.startGame(g)
    if #g.order < 2 then return false, "Battlegrounds needs at least two players (add bots)." end
    local ids={}
    for _,h in ipairs(BG_HEROES) do
        if E.heroAvailable(g,h.id) then ids[#ids+1]=h.id end
    end
    if #ids==0 then return false,"No solo heroes are eligible for this lobby." end
    shuffle(g,ids)
    local n = 1
    for _, color in ipairs(g.order) do
        local p = g.players[color]
        p.heroOptions = {}
        for _ = 1, g.heroChoices do
            table.insert(p.heroOptions, ids[((n - 1) % #ids) + 1]); n = n + 1
        end
    end
    g.phase = "hero"
    for _, color in ipairs(g.order) do
        local p = g.players[color]
        if p.bot then E.chooseHero(g, color, rnd(g, #p.heroOptions)) end
    end
    return true
end

-- No hero draft: every player starts as a plain tavern-goer with default health and armor.
E.DEFAULT_HP, E.DEFAULT_ARMOR = 30, 10
function E.startGameDefault(g)
    if #g.order < 2 then return false, "Battlegrounds needs at least two players (add bots)." end
    for _, color in ipairs(g.order) do
        local p = g.players[color]
        p.hero, p.heroOptions = nil, {}
        p.hp, p.armor = E.DEFAULT_HP, E.DEFAULT_ARMOR
    end
    g.phase = "ready"
    return true
end

function E.chooseHero(g, color, index)
    local p = g.players[color]
    if g.phase ~= "hero" or not p or p.hero then return false, "Hero already chosen." end
    local heroId = p.heroOptions[index]
    if not heroId then return false, "No such hero." end
    local h = E.heroById(heroId)
    if not E.heroAvailable(g, heroId) then return false, "That hero is unavailable in this lobby." end
    p.hero = heroId
    p.hp, p.armor = h.hp, h.armor
    p.powerUses = 0
    hooks(g, p, "chooseHero")
    event(g, color, "hero_select", p.name .. " chose " .. h.name .. ".")
    return true
end

function E.allHeroesChosen(g)
    for _, color in ipairs(g.order) do if not g.players[color].hero then return false end end
    return true
end

function E.autoChooseHeroes(g)
    for _, color in ipairs(g.order) do
        if not g.players[color].hero then E.chooseHero(g, color, 1) end
    end
end

-------------------------------------------------------------------------------
-- pool and tavern
local function returnToPool(g, m)
    for id, count in pairs(m.magneticCopies or {}) do
        if g.pool[id] ~= nil then g.pool[id] = g.pool[id] + count end
    end
    if m.poolCopies then
        for id,count in pairs(m.poolCopies) do if g.pool[id] then g.pool[id]=g.pool[id]+count end end
        return
    end
    if not m.generated and g.pool[m.id] ~= nil then
        local copies = m.golden and m.id ~= "BG32_236" and 3 or 1 -- Aureate Laureate is drawn already Golden.
        g.pool[m.id] = g.pool[m.id] + copies
    end
end
E.returnToPool = returnToPool

local poolOrder = setmetatable({}, {__mode = "k"})
local function drawFromPool(g, maxTier, minTier, filter)
    local ids = poolOrder[g.pool]
    if not ids then
        ids = {}
        for id in pairs(g.pool) do ids[#ids + 1] = id end
        table.sort(ids)
        poolOrder[g.pool] = ids
    end
    local total, candidates, cumulative = 0, {}, {}
    minTier = minTier or 1
    for _, id in ipairs(ids) do
        local n, c = g.pool[id], E.poolDefinition(g,card(id))
        if n and n > 0 and c.tier <= maxTier and c.tier >= minTier and (not filter or filter(c)) then
            total = total + n
            candidates[#candidates + 1], cumulative[#cumulative + 1] = id, total
        end
    end
    if total == 0 then return nil end
    local roll = rnd(g, total)
    for i, id in ipairs(candidates) do
        if roll <= cumulative[i] then
            g.pool[id] = g.pool[id] - 1
            return E.newMinion(g, id, false)
        end
    end
end
E.drawFromPool = drawFromPool

local function clearTavern(g, p)
    for _, m in ipairs(p.tavern) do returnToPool(g, m) end
    p.tavern = {}
end

local function tavernSize(p)
    local n = E.TAVERN_SIZE[p.tier]
    return n
end

function E.rollTavern(g,p,higher,minTier,keepIndividuallyFrozen)
    local kept={}
    if keepIndividuallyFrozen then
        for i=#p.tavern,1,-1 do
            if p.tavern[i].timewarpFrozen then
                local m=table.remove(p.tavern,i)
                m.timewarpFrozen=nil
                kept[#kept+1]=m
            end
        end
    end
    clearTavern(g,p)
    local n=math.max(0,(p.timewarpRecruit and 6 or tavernSize(p))-#kept
        -(E.hasPower(p,"TB_BaconShop_HERO_27") and 1 or 0))
    if higher and p.tier < (g.maxTier or 6) then
        for _ = 1, 2 do
            local m = drawFromPool(g, p.tier + 1, p.tier + 1)
            if m then table.insert(p.tavern, m); n = n - 1 end
        end
    end
    for _ = 1, n do
        local m = drawFromPool(g, p.tier, minTier)
        if m then table.insert(p.tavern, m) end
    end
    if heroKey(p) == "ysera" then
        local m = drawFromPool(g, p.tier, minTier or 1, function(c) return indexOf(c.races, "DRAGON") ~= nil end)
        if m then table.insert(p.tavern, m) end
    end
    for _,buddy in ipairs(p.board) do
        local f=E.FX[buddy.id]
        if f and f.tavernExtra then f.tavernExtra(g,p,mult(buddy)) end
    end
    while #p.tavern>8 do returnToPool(g,table.remove(p.tavern,1)) end
    E.darkmoonStock(g,p,p.darkmoonExtra or 0)
    for _, m in ipairs(p.tavern) do
        E.applyTavernBuff(p, m)
        E.updateCardAuras(p, m)
    end
    for _ = 1, (p.refreshBuffs or 0) do
        local m = pick(g, p.tavern)
        if m then buff(m, 4, 4) end
    end
    for _ = 1, (p.refreshBig or 0) do -- En-Djinn Blazer
        local m = pick(g, p.tavern)
        if m then buff(m, 10, 10) end
    end
    for i=#kept,1,-1 do p.tavern[#p.tavern+1]=kept[i] end
    E.spellRefresh(g, p)
    E.refreshFodder(g, p)
    E.rollSpellShop(g, p, false, minTier == p.tier)
    E.spellcraftTavern(g,p)
    E.silasTickets(g,p)
    E.tavernShown(g,p)
end

-- "Minions in the Tavern have +X/+Y this game" (by race key or "all").
function E.applyTavernBuff(p, m)
    for race, b in pairs(p.tavBuff or {}) do
        if race == "all" or hasRace(m, race) then buff(m, b[1], b[2]) end
    end
    if p.pupTrainerBuff and (m.cardTier or card(m.id).tier)<=3 then buff(m,p.pupTrainerBuff,p.pupTrainerBuff) end
    if p.ashenAtk then E.applyAshen(m,p.ashenAtk,p.ashenHp) end
end

-------------------------------------------------------------------------------
-- costs
function E.buyCost(p)
    if p.grapnel or E.hasPower(p,"TB_BaconShop_HERO_59") and (p.arannaAttacks or 0)>=14 and not p.arannaUsed then return 0 end
    local base = (p.darkmoonBuyCut or E.hasPower(p,"TB_BaconShop_HERO_27") or heroKey(p) == "millhouse") and 2 or 3
    if p.minionPrice then base = math.min(base, p.minionPrice) end
    return base
end
-- Malchezaar, Prince of Dance: Refreshes left this turn that cost Health (2, or 4 if Golden; counted from the turn he arrives).
function E.malchezaarActive(g, p)
    local most = 0
    for _, o in ipairs(p.board or {}) do if o.id == "BG26_524" then most = math.max(most, o.golden and 4 or 2) end end
    if most == 0 then return false end
    g = g or E.lastGame
    if g and p.malUsedTurn ~= g.turn then p.malUsedTurn, p.malUsed = g.turn, 0 end
    p.malLeft = math.max(0, most - (p.malUsed or 0))
    return p.malLeft > 0
end
function E.refreshCost(p,g)
    if p.freeRefreshes>0 or E.magnusRefreshes(g,p)>0 then return 0 end
    return heroKey(p) == "millhouse" and 2 or 1
end
function E.upgradeCost(p)
    if p.tier >= (p.maxTier or 6) then return nil end
    return math.max(0, p.upgradeCost + (heroKey(p) == "millhouse" and 1 or 0))
end
function E.powerCost(p,second)
    local h=second and E.heroById(p.secondPowerHero) or E.powerHero(p)
    local hp=h and E.HP[h.id]
    if not hp or not hp.active then return nil end
    local c=h.cost
    if hp.cost then c = hp.cost(p, c) end
    return math.max(0, c)
end
function E.sellValue(m)
    if m.id == "BGS_049" then return m.golden and 6 or 3 end
    if m.id == "BG24_018" and m.lostLastSell then return m.golden and 10 or 5 end
    return 1
end

-------------------------------------------------------------------------------
-- shop triggers
local FX = {}
E.FX = FX

local function damageHero(g,p,n)
    if n<=0 then return end
    if E.iceBlock and E.iceBlock(g,p,n) then return end
    local armor,hp=p.armor,p.hp
    local absorbed=math.min(armor,n)
    p.armor,p.hp=armor-absorbed,hp-(n-absorbed)
    if g.season == "s15" then
        p.s15HeroDamage = (p.s15HeroDamage or 0) + n
        E.refreshCardAuras(p, "S15_pain_promoter")
    end
    if g.phase~="recruit" then E.refreshCardAuras(p,"BG36_372");return end
    local rewind=false
    for _,m in ipairs(p.board) do
        if m.id=="BG26_174" then buff(m,0,2*mult(m)); rewind=true end
        if m.id=="BG32_873" then E.ashenRewind(g,p,m,mult(m)); rewind=true end
    end
    for _,m in ipairs(p.board) do
        local f=E.FX and E.FX[m.id]
        if f and f.rewind then f.rewind(g,p,m,mult(m),n);rewind=true end
    end
    if rewind then p.armor,p.hp=armor,hp end
    E.refreshCardAuras(p,"BG36_372")
    for _,m in ipairs(p.board) do
        local f=FX[m.id]
        if f and f.heroDamaged then f.heroDamaged(g,p,m,mult(m),n) end
    end
end
E.damageHero = damageHero

-- Gold spent this turn ("whenever you spend 5 Gold" counters).
local function spendGold(g, p, n)
    if n <= 0 then return end
    p.spent = (p.spent or 0) + n
    p.totalGoldSpent=(p.totalGoldSpent or 0)+n
    E.refreshCardAuras(p,"BG32_HERO_001_Buddy")
    hooks(g,p,"spendGold",n)
    for _, m in ipairs(p.board) do
        if FX[m.id] and FX[m.id].spend then FX[m.id].spend(g, p, m, n, mult(m)) end
    end
end
E.spendGold = spendGold

-- Blood Gems: +gemA/+gemH each. The engine plays them right away on a random friendly minion.
local function gainGems(g, p, n)
    for _ = 1, n do
        local t = pick(g, p.board)
        if t then E.applyGems(g,p,t,1) else p.pendingGems = (p.pendingGems or 0) + 1 end
    end
end
E.gainGems = gainGems

-- Buff until the start of the next turn (Spellcraft).
local function tempBuff(m, a, h, kw)
    buff(m, a, h)
    m.tA, m.tH = (m.tA or 0) + a, (m.tH or 0) + h
    if kw and not m[kw] then m[kw] = true; m.tKw = m.tKw or {}; table.insert(m.tKw, kw) end
end
E.tempBuff = tempBuff

local function clearTemp(m)
    if m.tA then m.atk = math.max(0, m.atk - m.tA); m.hp = math.max(1, m.hp - m.tH); m.tA, m.tH = nil, nil end
    if m.tKw then for _, kw in ipairs(m.tKw) do m[kw] = false end; m.tKw = nil end
end

-- "Your Undead have +X Attack this game (wherever they are)".
local function applyUndead(p)
    for _, list in ipairs({p.hand, p.board}) do
        for _, m in ipairs(list) do
            if hasRace(m, "UNDEAD") then
                local d = (p.undeadAtk or 0) - (m.uAtk or 0)
                if d ~= 0 then m.atk = m.atk + d; m.uAtk = p.undeadAtk end
            end
            if hasRace(m, "BEAST") and ((p.beastA or 0) ~= (m.bA or 0) or (p.beastH or 0) ~= (m.bH or 0)) then
                m.atk, m.hp = m.atk + (p.beastA or 0) - (m.bA or 0), m.hp + (p.beastH or 0) - (m.bH or 0)
                m.bA, m.bH = p.beastA, p.beastH
            end
        end
    end
end
E.applyUndead = applyUndead

local function makeGolden(m)
    if m.golden then return end
    local c = card(m.id)
    m.golden = true
    if not m.generated and not m.poolCopies then m.poolCopies={[m.id]=1} end
    if m.paradox then E.goldenParadox(m); return end
    buff(m, c.gatk - c.atk, c.ghp - c.hp)
end
E.makeGolden = makeGolden

local BONUS_KW = {"taunt", "shield", "reborn", "windfury", "venom", "stealth"}
local function randomKeyword(g, m)
    local opts = {}
    for _, kw in ipairs(BONUS_KW) do
        local candidate = g.season == "s15" and kw == "stealth" and "resilient" or kw
        if not m[candidate] then table.insert(opts, candidate) end
    end
    local kw = pick(g, opts)
    if kw then m[kw] = true end
    return kw
end

local function others(list, self, race)
    local r = {}
    for _, m in ipairs(list) do if m ~= self and (not race or hasRace(m, race)) then table.insert(r, m) end end
    return r
end

local function addToHand(g, p, m)
    if E.handCount(p) >= E.MAX_HAND then event(g, p.color, nil, "Hand is full; " .. card(m.id).name .. " was lost."); return false end
    E.updateCardAuras(p,m)
    E.bindStatCard(p,m)
    table.insert(p.hand,m)
    E.raiseHandGained(g,p)
    return true
end
E.addToHand = addToHand

-- Shop summon: put a minion on the board and fire "whenever you summon" triggers.
E.buff = function(m, a, h) return buff(m, a, h) end
E.pick = function(g, list) return pick(g, list) end
E.hasRace = function(m, r) return hasRace(m, r) end
E.mult = mult
E.drawFromPool = function(...) return drawFromPool(...) end
E.returnToPool = function(...) return returnToPool(...) end
E.others = others
E.event = event
E.indexOf = indexOf
E.shuffle = shuffle

local function shopSummon(g, p, m, pos)
    if #p.board >= E.MAX_BOARD then return nil end
    pos = math.max(1, math.min(pos or (#p.board + 1), #p.board + 1))
    if g.season == "s15" then E.s15MarkKeywords(m) end
    table.insert(p.board,pos,m)
    E.bindStatCard(p,m)
    E.automatonSummoned(p,m,p.board)
    E.buddySummoned(p,m,p.board)
    hooks(g,p,"summonTrinket",m)
    for _, o in ipairs(p.board) do
        local f=o~=m and FX[o.id]
        if f then
            if f.summon then f.summon(o,m,false) end
            if f.recruitSummon then f.recruitSummon(g,p,o,mult(o),m) end
        end
    end
    E.s15Summon(g, p, m)
    return m
end

E.shopSummon = shopSummon
local function runBattlecry(g, p, m, times)
    local f = FX[m.id]
    if not (f and f.bc) then return end
    local extra = 1
    for _, o in ipairs(p.board) do
        if o~=m and (o.id=="BG_LOE_077" or o.id=="BG34_Giant_376") then extra=math.max(extra,1+mult(o)) end
    end
    for _, id in ipairs(E.passives(p)) do
        local t=E.TR[id]
        if t and t.extraBattlecry then extra=extra+t.extraBattlecry(p,m) end
    end
    if p.prizeBrannTurn==g.turn then extra=extra+(p.prizeBrannCount or 0) end
    times=times*extra
    for _=1,times do
        E.withElementalAura(p,m,f.bc,g,p,m,mult(m))
        E.s15ObserveKeywords(g, p)
        p.battlecries=(p.battlecries or 0)+1
        E.refreshGiftAuras(p,"battlecries")
        hooks(g,p,"battlecry",m)
        E.refreshCardAuras(p,"BG36_360")
    end
    for _, o in ipairs(p.board) do
        if o.id == "BGS_041" then -- Kalecgos
            for _ = 1, times do
                for _, d in ipairs(p.board) do if hasRace(d, "DRAGON") then buff(d, 2 * mult(o), 2 * mult(o)) end end
            end
        end
    end
end
E.runBattlecry = runBattlecry

-------------------------------------------------------------------------------
-- player actions (shop)
local function checkTriples(g, p)
    applyUndead(p)
    for _, m in ipairs(p.board) do
        if m.id == "BG35_814" and m.atk >= 6 then m.shield = true end -- Scarlet Survivor
    end
    local counts = {}
    for _, list in ipairs({p.hand,p.board}) do
        for _,m in ipairs(list) do
            if not m.golden and not card(m.id).noTriple then counts[m.id]=(counts[m.id] or 0)+1 end
        end
    end
    local needed=(E.hasPower(p,"BG34_HERO_002") or p.pairTriples) and 2 or 3
    local ids={}
    for id in pairs(counts) do ids[#ids+1]=id end
    table.sort(ids)
    for _,id in ipairs(ids) do
        local n,wild=counts[id],0
        if n<needed and id~="BG26_175" and hasRace({id=id},"ELEMENTAL") then wild=counts.BG26_175 or 0 end
        if n+wild>=needed then
            local matching,wildNeeded=math.min(n,needed),math.max(0,needed-n)
            local gold=E.newMinion(g,id,true)
            gold.poolCopies={}
            gold.triple=needed==3; p.triplesMade=(p.triplesMade or 0)+1
            gold.clockReward=needed==2 or nil
            local taken=0
            for _, list in ipairs({p.hand, p.board}) do
                local i = 1
                while i<=#list and taken<needed do
                    local m = list[i]
                    local exact=m.id==id and matching>0
                    local substitute=m.id=="BG26_175" and wildNeeded>0
                    if (exact or substitute) and not m.golden then
                        if exact then matching=matching-1 else wildNeeded=wildNeeded-1 end
                        if not m.generated then gold.poolCopies[m.id]=(gold.poolCopies[m.id] or 0)+1 end
                        local own=card(m.id)
                        local baseA,baseH=E.originalStats(m,own)
                        gold.atk=gold.atk+math.max(0,m.atk-baseA-(m.volumeAttack or 0)-(m.bruiserAtk or 0)-(m.dynamicAtk or 0)-(m.giftAuraA or 0))
                        gold.hp=gold.hp+math.max(0,m.hp-baseH-(m.volumeHealth or 0)-(m.bruiserHealth or 0)-(m.dynamicHp or 0)-(m.giftAuraH or 0))
                        gold.gemAttack = (gold.gemAttack or 0)+(m.gemAttack or 0)
                        gold.gemHealth = (gold.gemHealth or 0)+(m.gemHealth or 0)
                        gold.magnetizedCount = (gold.magnetizedCount or 0)+(m.magnetizedCount or #(m.attachments or {}))
                        for _, k in ipairs(KEYWORDS) do if m[k] then gold[k] = true end end
                        if m.attachments then
                            gold.attachments, gold.magneticCopies = gold.attachments or {}, gold.magneticCopies or {}
                            for _, part in ipairs(m.attachments) do gold.attachments[#gold.attachments + 1] = part end
                            for partId, copies in pairs(m.magneticCopies or {}) do
                                gold.magneticCopies[partId] = (gold.magneticCopies[partId] or 0) + copies
                            end
                        end
                        if m.resilient then gold.resilient = true end
                        if m.missionProgress then
                            gold.missionProgress = (gold.missionProgress or 0) + m.missionProgress
                        end
                        if m.artisan then gold.artisan = (gold.artisan or 0) + m.artisan end
                        gold.darkGift = gold.darkGift or m.darkGift
                        table.remove(list, i); taken = taken + 1
                    else
                        i = i + 1
                    end
                end
            end
            E.updateCardAuras(p, gold)
            E.giftAura(p,gold)
            table.insert(p.hand, gold)
            p.selected = nil
            event(g, p.color, "combine", p.name .. " tripled " .. card(id).name .. "!")
            return checkTriples(g, p)
        end
    end
end
E.checkTriples = checkTriples

function E.hasChoice(p)
    return p and (p.timewarpVisit or p.discover or p.offer and p.offer.kind == "trinket")
end

local function canAct(g, p)
    if g.phase ~= "recruit" or not p or not p.alive then return false, "You can only do that during your recruit phase." end
    if E.skipsRecruit(g, p) then return false, "Expedition Plans skips your first Recruit turn." end
    if E.hasChoice(p) then return false, "Finish the choice above your board first." end
    if g.recruitClosed then return false, "The Tavern has closed for combat." end
    return true
end
E.canAct = canAct

function E.buy(g, color, i)
    local p = g.players[color]
    local ok, err = canAct(g, p); if not ok then return false, err end
    local m = p.tavern[i]
    if not m then return false, "That tavern slot is empty." end
    if m.id=="BG35_150t" then return false,"Demon Fodder feeds a friendly Demon." end
    local aranna=E.hasPower(p,"TB_BaconShop_HERO_59") and (p.arannaAttacks or 0)>=14 and not p.arannaUsed
    local cost = E.s15MinionPrice(p, m, g.turn)
    if p.gold < cost then return false, "Not enough Gold (" .. cost .. " needed)." end
    if E.handCount(p) >= E.MAX_HAND then return false, "Your hand is full." end
    p.grapnel=false
    if aranna then p.arannaUsed=true end
    p.gold=p.gold-cost
    spendGold(g, p, cost)
    table.remove(p.tavern, i)
    E.expireAshen(m)
    E.updateCardAuras(p,m)
    table.insert(p.hand, m)
    E.raiseHandGained(g, p)
    p.counters.bought = p.counters.bought + 1
    p.counters.buysTotal = p.counters.buysTotal + 1
    if hasRace(m, "PIRATE") then p.counters.piratesBought = p.counters.piratesBought + 1 end
    if heroKey(p) == "kaelthas" and p.counters.buysTotal % 3 == 0 then
        p.gold = p.gold + 1
        for _,buddy in ipairs(p.board) do
            local f=FX[buddy.id]
            if f and f.verdant then f.verdant(g,p,buddy,mult(buddy),m) end
        end
        event(g, color, "hero_power", "Verdant Spheres: +1 Gold.")
    end
    m.s15Discount = nil
    if card(m.id).battlecry then p.s15NextBattlecry = nil end
    E.purchaseCardActions(g, p, m)
    E.cardPurchased(g, p)
    E.timewarpBuyCard(g,p,m)
    hooks(g,p,"buyCard",m)
    hooks(g, p, "buy", m)
    E.buddyPurchaseHooks(g, p, m, false, cost)
    event(g, color, "buy", nil)
    checkTriples(g, p)
    return true
end

function E.sell(g, color, i)
    local p = g.players[color]
    local ok, err = canAct(g, p); if not ok then return false, err end
    local m = p.board[i]
    if not m then return false, "No minion there." end
    table.remove(p.board, i)
    m.lostLastSell=p.lostLast
    if p.timewarpSoldTurn~=g.turn then p.timewarpSoldTurn,p.timewarpSoldAtk,p.timewarpSoldHp=g.turn,0,0 end
    p.timewarpSoldAtk,p.timewarpSoldHp=p.timewarpSoldAtk+m.atk,p.timewarpSoldHp+m.hp
    p.gold = math.min(p.gold + E.sellValue(m), 99)
    returnToPool(g, m)
    if FX[m.id] and FX[m.id].sell then FX[m.id].sell(g, p, m, mult(m)) end
    if (m.buddyHats or 0) > 0 then
        local target = pick(g, p.board)
        if target then
            target.buddyHats = (target.buddyHats or 0) + m.buddyHats
            buff(target, m.buddyHats, m.buddyHats)
        end
    end
    for _, ally in ipairs(p.board) do
        local f = FX[ally.id]
        if f and f.afterSell then f.afterSell(g,p,ally,mult(ally),m) end
    end
    p.selected = nil
    hooks(g, p, "sell", m)
    event(g, color, "sell", nil)
    checkTriples(g, p)
    return true
end

local function startDiscover(g, p, tier, filter, label, unlockTier, source)
    local ids = {}
    for id,n in pairs(g.pool) do
        local c=E.poolDefinition(g,card(id))
        if n > 0 and c.tier <= tier and id ~= source and (not filter or filter(c)) then ids[#ids + 1] = id end
    end
    if #ids == 0 then return false end
    table.sort(ids)
    shuffle(g, ids)
    local options = {}
    for i = 1, math.min(3, #ids) do options[i] = ids[i] end
    local d = {options = options, label = label or "Discover", unlockTier = unlockTier, fromPool = true}
    if p.discover then table.insert(p.discoverQueue, d) else p.discover = d end
    return true
end
E.startDiscover = startDiscover

function E.discoverPick(g, color, i)
    local p = g.players[color]
    if not p or not p.discover then return false, "Nothing to discover." end
    if p.timewarpVisit then return false,"Return from the Timewarped Tavern first." end
    if p.discover.s15Effect then return E.s15ChooseEffect(g, p, i) end
    if p.discover.kind == "activate_target" then return E.pickActivation(g,p,i) end
    if p.discover.moreHeroChoice then return E.moreHeroPick(g,p,i) end
    if p.discover.kind == "hero_option" then return E.pickHeroOption(g,p,i) end
    if p.discover.battleAction then return E.finishRecruitTarget(g,p,i) end
    if p.discover.minionId == "BG25_034" then return E.chooseCaptain(g, p, i) end
    if p.discover.kind == "minion_mode" or p.discover.kind == "minion_target" then return E.pickMinionChoice(g, p, i) end
    if p.discover.kind then return E.pickSpellChoice(g, p, i) end
    local id = p.discover.options[i]
    if not id then return false, "No such option." end
    local discovery=p.discover
    if discovery.timewarpMixed and E.SPELLS[id] then
        local ok,err=E.awardDiscoveredTimewarpSpell(g,p,id,discovery.unlockTurn)
        if not ok then return false,err end
        p.discover=#p.discoverQueue>0 and table.remove(p.discoverQueue,1) or nil
        E.onDiscovered(g,p)
        return true
    end
    local transform,index
    if discovery.transformTimewarp then
        local info=discovery.transformTimewarp
        transform=p[info.zone]
        for i,target in ipairs(transform or {}) do if target.uid==info.uid then index=i;break end end
        if not index then return false,"That minion is no longer available." end
    end
    local reserved = not discovery.generated and (g.pool[id] or 0) > 0
    if not reserved and discovery.fromPool then
        table.remove(discovery.options, i)
        if #discovery.options == 0 then p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue, 1) or nil end
        return false, "Another player took the last copy."
    end
    if reserved then g.pool[id] = g.pool[id] - 1 end
    local m = E.newMinion(g, id, p.discover.golden and true or false)
    if not reserved then m.generated = true end
    if discovery.gifts then E.applyGift(m, discovery.gifts[id], p) end
    local unlock = p.discover.unlockTier
    local turn = p.discover.unlockTurn
    m.diesIfPlayed = p.discover.diesIfPlayed
    if discovery.timewarpReborn then m.reborn=true end
    if transform then
        local old=transform[index]
        returnToPool(g,old)
        if discovery.transformTimewarp.fixedStats then
            m.atk,m.hp=discovery.transformTimewarp.fixedStats,discovery.transformTimewarp.fixedStats
        elseif discovery.transformTimewarp.keepStats then
            m.atk,m.hp=old.atk,old.hp
        end
        m.uid=old.uid
        transform[index]=m
    elseif discovery.timewarpCrew then
        for _,ship in ipairs(p.board) do if ship.uid==discovery.timewarpCrew then ship.timewarpPirate=id;break end end
        if reserved then returnToPool(g,m) end
    elseif discovery.clunkerTarget then
        for _,target in ipairs(p.board) do
            if target.uid==discovery.clunkerTarget then E.attachMagnetic(g,p,m,target,1); break end
        end
    elseif discovery.thorim then
        p.thorimChampion=m
        if (p.totalGoldSpent or 0)>=60 and addToHand(g,p,m) then p.thorimChampion=nil end
    elseif (unlock and p.tier<unlock) or (turn and g.turn<turn) then
        p.expeditions = p.expeditions or {}
        table.insert(p.expeditions, {tier = unlock, turn = turn, minion = m, reserved = reserved})
    else
        if addToHand(g, p, m) then E.giftCopy(g, p, m)
        elseif reserved then returnToPool(g, m) end
    end
    if p.discover.damageHero then damageHero(g, p, m.cardTier or card(id).tier) end -- Imposing Percussionist
    -- MoonSharp (TTS) rejects table.remove(t, 1) on an empty table, unlike Lua 5.2.
    p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue, 1) or nil
    E.onDiscovered(g,p,m)
    event(g, color, "card_draw", nil)
    checkTriples(g, p)
    return true
end

function E.play(g, color, handIndex, pos)
    local p = g.players[color]
    local ok, err = canAct(g, p); if not ok then return false, err end
    local m = p.hand[handIndex]
    if not m then return false, "No card there." end
    if #p.board >= E.MAX_BOARD then return false, "Your warband is full (7)." end
    table.remove(p.hand, handIndex)
    pos = pos or (#p.board + 1)
    shopSummon(g, p, m, pos)
    E.playVolumizer(p, m)
    E.bruiserStats(p, m)
    E.grantSpellcraft(g, p, m)
    E.feedFodder(g,p)
    E.startMinionChoice(g,p,m)
    runBattlecry(g, p, m, 1)
    if m.diesIfPlayed == g.turn then
        local slot = indexOf(p.board, m)
        if slot then table.remove(p.board, slot); returnToPool(g, m) end
    end
    m.diesIfPlayed = nil
    if hasRace(m,"ELEMENTAL") then
        p.counters.elementals=p.counters.elementals+1
        p.elementalsPlayed=(p.elementalsPlayed or 0)+1
        E.refreshCardAuras(p,"BG26_537")
    end
    if m.id=="BG35_140" or m.id=="BG35_141" then p.mrrgltonsPlayed=(p.mrrgltonsPlayed or 0)+1 end
    if m.golden then
        p.goldenPlayed = p.goldenPlayed+1
        E.refreshCardAuras(p,"BG36_524")
    end
    for _, h in ipairs(p.hand) do
        if FX[h.id] and FX[h.id].handAfterPlay then FX[h.id].handAfterPlay(g, p, h, m, mult(h)) end
    end
    for _, o in ipairs(p.board) do
        if o ~= m and FX[o.id] and FX[o.id].afterPlay then E.withElementalAura(p,o,FX[o.id].afterPlay,g,p,o,m,mult(o)) end
    end
    if m.id == "BGS_028" then p.counters.pogo = p.counters.pogo + 1 end
    if m.clockReward then m.clockReward=nil;E.giveSpell(g,p,"BG28_810") end
    if m.triple then
        m.triple=nil
        local tier = math.min(g.maxTier or 6, p.tier + 1)
        startDiscover(g, p, tier, function(c) return c.tier == tier end, "Triple reward: Discover a Tier " .. tier .. " minion", nil, m.id)
    end
    E.s15ObserveKeywords(g, p)
    E.recordMinionPlayed(g,p,m)
    E.giftAfterPlay(p, m)
    hooks(g,p,"cardPlayed",m)
    hooks(g, p, "play", m)
    E.cardPlayed(g,p)
    E.discardPartner(g, p, m)
    event(g, color, "card_play", nil)
    checkTriples(g, p)
    return true
end

function E.move(g, color, from, to)
    local p = g.players[color]
    if not canAct(g, p) then return false end
    if not p.board[from] or to < 1 or to > #p.board then return false end
    local m = table.remove(p.board, from)
    table.insert(p.board, to, m)
    p.selected = to
    return true
end

function E.refresh(g, color, free)
    local p = g.players[color]
    local ok, err = canAct(g, p); if not ok then return false, err end
    local cost = free and 0 or E.refreshCost(p,g)
    local mal = not free and cost > 0 and E.malchezaarActive(g, p)
    if not mal and p.gold < cost then return false, "Not enough Gold to refresh." end
    if mal then -- Malchezaar: Refresh costs Health
        p.malUsed = (p.malUsed or 0) + 1; p.malLeft = math.max(0, p.malLeft - 1); damageHero(g, p, cost)
    elseif not free and p.freeRefreshes > 0 then p.freeRefreshes = p.freeRefreshes - 1
    elseif not free and E.magnusRefreshes(g,p)>0 then
        p.magnusUsed=(p.magnusTurn==g.turn and (p.magnusUsed or 0) or 0)+1
        p.magnusTurn=g.turn
    else p.gold = p.gold - cost; spendGold(g, p, cost) end
    p.frozen = false
    E.feedFodder(g,p,true)
    E.rollTavern(g, p)
    hooks(g, p, "refresh")
    event(g, color, "refresh", nil)
    return true
end

function E.toggleFreeze(g, color)
    local p = g.players[color]
    local ok, err = canAct(g, p); if not ok then return false, err end
    p.frozen = not p.frozen
    return true
end

function E.upgrade(g, color)
    local p = g.players[color]
    local ok, err = canAct(g, p); if not ok then return false, err end
    local cost = E.upgradeCost(p)
    if not cost then return false, "Your Tavern is already at its highest Tier." end
    if p.gold < cost then return false, "Upgrading costs " .. cost .. " Gold." end
    p.gold = p.gold - cost
    spendGold(g, p, cost)
    p.tier = p.tier + 1
    p.upgradeCost = E.UPGRADE[p.tier + 1] or 0
    hooks(g, p, "upgrade")
    E.releaseExpeditions(g, p)
    event(g, color, "upgrade", p.name .. " upgraded to Tavern Tier " .. p.tier .. ".")
    return true
end

function E.setReady(g, color, value)
    local p = g.players[color]
    if g.phase ~= "recruit" or g.recruitClosed or not p or E.hasChoice(p) then return false end
    if E.skipsRecruit(g, p) then p.ready = true else p.ready = value end
    return true
end

-- Hero powers. target = index of the selected friendly minion when needed.
local POWERS = {}
E.POWERS = POWERS
local function needTarget(p, target)
    local m = target and p.board[target]
    if not m then return nil, "Click one of your minions to select it, then use the Hero Power." end
    return m
end
POWERS.vancleef = function(g, p, t) local m, e = needTarget(p, t); if not m then return false, e end buff(m, 2, 2); return true end
POWERS.george = function(g, p, t) local m, e = needTarget(p, t); if not m then return false, e end
    if m.shield then return false, "That minion already has Divine Shield." end m.shield = true; return true end
POWERS.lichking = function(g, p, t) local m, e = needTarget(p, t); if not m then return false, e end
    if m.reborn then return false, "That minion already has Reborn." end m.reborn = true; m.tempReborn = true; return true end
POWERS.pyramad = function(g, p)
    if #p.tavern == 0 then return false, "The Tavern is empty." end
    if E.handCount(p) >= E.MAX_HAND then return false, "Your hand is full." end
    local m = table.remove(p.tavern, rnd(g, #p.tavern)); m.hp = m.hp * 2; addToHand(g, p, m); return true end
POWERS.bazhial = function(g, p)
    if #p.tavern == 0 then return false, "The Tavern is empty." end
    if E.handCount(p) >= E.MAX_HAND then return false, "Your hand is full." end
    local m = table.remove(p.tavern, 1); addToHand(g, p, m); damageHero(g, p, 2); return true end
POWERS.toki = function(g, p) p.frozen = false; E.rollTavern(g, p, true); event(g, p.color, "refresh", nil); return true end
POWERS.reno = function(g, p, t)
    if p.renoUsed then return false, "Gonna Be Rich! can only be used once per game." end
    local m, e = needTarget(p, t); if not m then return false, e end
    if m.golden then return false, "That minion is already Golden." end
    local c = card(m.id)
    m.golden = true; m.atk = m.atk + (c.gatk - c.atk); m.hp = m.hp + (c.ghp - c.hp); p.renoUsed = true; return true end
POWERS.patches = function(g, p)
    if E.handCount(p) >= E.MAX_HAND then return false, "Your hand is full." end
    local m = drawFromPool(g, p.tier, 1, function(c) return indexOf(c.races, "PIRATE") ~= nil end)
    if not m then return false, "No Pirates are left in the pool." end
    addToHand(g, p, m); return true end
POWERS.yogg = function(g, p)
    if #p.tavern == 0 then return false, "The Tavern is empty." end
    if #p.board >= E.MAX_BOARD then return false, "Your warband is full." end
    local m = table.remove(p.tavern, rnd(g, #p.tavern)); buff(m, 1, 1); shopSummon(g, p, m); return true end
POWERS.shudderwock = function(g, p, t) local m, e = needTarget(p, t); if not m then return false, e end
    if not (FX[m.id] and FX[m.id].bc) then return false, "That minion has no Battlecry." end
    runBattlecry(g, p, m, 1); return true end
POWERS.galakrond = function(g, p)
    if #p.tavern == 0 then return false, "The Tavern is empty." end
    local old = p.tavern[1]
    local t = math.min(g.maxTier or 6, card(old.id).tier + 1)
    local m = drawFromPool(g, t, t)
    if not m then return false, "No higher-tier minion is available." end
    returnToPool(g, old); p.tavern[1] = m; return true end

-- target: a warband index (number) or {zone = "board"|"tavern", index = i}.
function E.powerLock(g,p,hp,second)
    local h=second and E.heroById(p.secondPowerHero) or E.powerHero(p)
    if hp.unlock then
        local open, why = hp.unlock(g, p)
        if not open then return h.power .. ": " .. (why or "not unlocked yet.") end
    end
    local uses=(hp.uses or 1)+E.extraHeroUses(p)
    local used=second and p.secondPowerUses or p.powerUses
    if (used or 0)>=uses then return "Hero Power already used" .. (uses > 1 and " twice" or "") .. " this turn." end
end

function E.heroPower(g,color,target,second)
    local p=g.players[color]
    local ok,err=canAct(g,p);if not ok then return false,err end
    local h=second and E.heroById(p.secondPowerHero) or E.powerHero(p)
    if not h then return false,"No hero." end
    local hp=E.HP[h.id]
    if not hp or not hp.active then
        return false, h.power .. (hp and " is passive." or " is not scripted yet (the hero plays with its Health and Armor).")
    end
    local locked=E.powerLock(g,p,hp,second);if locked then return false,locked end
    local uses=(hp.uses or 1)+E.extraHeroUses(p)
    local cost=E.powerCost(p,second)
    if p.gold < cost then return false, h.power .. " costs " .. cost .. " Gold." end
    local done, msg = hp.active(g, p, target)
    if not done then return false, msg end
    p.gold = p.gold - cost
    spendGold(g, p, cost)
    if second then p.secondPowerUses=(p.secondPowerUses or 0)+1
    else p.powerUses=(p.powerUses or 0)+1;p.powerUsed=p.powerUses>=uses end
    if hp.after then hp.after(g,p) end
    if E.heroPowerUsed then E.heroPowerUsed(g,p,h.id,target) end
    event(g, color, "hero_power", msg)
    checkTriples(g, p)
    return true
end

-------------------------------------------------------------------------------
-- turn flow
function E.beginRecruit(g, report)
    local function optional(stage, p, fn, ...)
        if not report then return fn(g, p, ...) end
        local ok, err = pcall(fn, g, p, ...)
        if not ok then report(stage, p.color, err) end
    end
    g.turn = g.turn + 1
    g.phase, g.recruitClosed = "recruit", nil
    for _, p in ipairs(E.alivePlayers(g)) do
        p.maxGold = math.min(10, g.turn + 2) + (p.extraMaxGold or 0)
        p.gold = p.maxGold
        if g.turn > 1 and p.tier < (p.maxTier or 6) then p.upgradeCost = math.max(0, p.upgradeCost - 1) end
        p.powerUsed,p.ready,p.powerUses,p.secondPowerUses=false,false,0,0
        p.arannaUsed,p.darkmoonSpellCut=nil,nil
        p.freeRefreshes=p.freeRefreshes+(p.roundRefresh or 0)
        if p.majorPrizeRepeat and g.turn>=p.majorPrizeRepeat then
            E.discoverDarkmoon(g,p,3);p.majorPrizeRepeat=g.turn+3
        end
        p.s15TavernSpellsTurn = 0
        p.counters.bought, p.counters.piratesBought, p.counters.elementals = 0, 0, 0
        E.ensurePlayer(p)
        E.bindExistingStatCards(p)
        E.releaseExpeditions(g,p)
        E.refreshCardAuras(p,"BG36_372")
        E.openLockbox(g, p)
        p.gold, p.nextGold, p.spent = math.min(p.gold + p.nextGold, 20), 0, 0
        p.malLeft = 0
        for _, m in ipairs(p.board) do
            if m.id == "BG26_524" then p.malLeft = math.max(p.malLeft, m.golden and 4 or 2) end
            m.age = (m.age or 0) + 1
        end
        for _, m in ipairs(p.board) do
            E.deityConduits[m], m.deityConduitTurn = nil, nil
            clearTemp(m)
        end
        for _, m in ipairs(p.board) do m.s15Deathrattles = nil; E.s15MarkKeywords(m) end
        for _,m in ipairs(p.tavern) do clearTemp(m);E.expireAshen(m) end
        p.ashenAtk,p.ashenHp=nil,nil
        p.trinketGameTurn=g.turn
        if p.pendingGems > 0 and #p.board > 0 then
            local n = p.pendingGems; p.pendingGems = 0; gainGems(g, p, n)
        end
        for _, m in ipairs(p.board) do
            m.timewarpDiscountUses=nil
            if m.tempReborn then m.reborn = false; m.tempReborn = nil end
            if FX[m.id] and FX[m.id].startTurn then E.withElementalAura(p,m,FX[m.id].startTurn,g,p,m,mult(m)) end
            E.dispatchAttached(m, "startTurn", function(fn, k) fn(g, p, m, k) end)
            E.grantSpellcraft(g, p, m)
            E.giftStartTurn(g, p, m)
        end
        E.s15ObserveKeywords(g, p)
        E.spellStartTurn(g, p)
        if p.frozen then
            p.frozen = false
            if #p.spellShop == 0 then E.rollSpellShop(g, p) end
        else
            E.rollTavern(g,p,nil,nil,true)
        end
        if g.turn == 1 then optional("game start effect", p, hooks, "gameStart") end
        E.s15AfterShopRoll(g, p)
        optional("start of turn effect", p, hooks, "startTurn")
        E.timewarpOnTurn(g,p)
        event(g, p.color, "turn_start", nil)
    end
    for _, p in ipairs(E.alivePlayers(g)) do
        if p.bot then optional("bot recruit", p, function(g, bot) E.botTurn(g, bot.color) end) end
    end
end

function E.allReady(g)
    for _, p in ipairs(E.alivePlayers(g)) do
        if not p.bot and not p.ready and not E.skipsRecruit(g, p) then return false end
    end
    return true
end

local function endOfTurn(g, p)
    local times = 1
    for _, m in ipairs(p.board) do
        if m.id == "BG26_ICC_901" then times = math.max(times, m.golden and 3 or 2) end -- Drakkari Enchanter
    end
    for _,m in ipairs(p.board) do if m.id=="TB_BaconShop_HERO_11_Buddy" then times=times+mult(m) end end
    times=times+(p.extraEndTurn or 0)
    local list={}
    for i,m in ipairs(p.board) do list[i]=m end
    for _,m in ipairs(list) do
        for _=1,times do
            if FX[m.id] and FX[m.id].endTurn then E.withElementalAura(p,m,FX[m.id].endTurn,g,p,m,mult(m)) end
            E.dispatchAttached(m,"endTurn",function(fn,k,part) fn(g,p,m,k,part) end)
            if m.darkmoonGruul then buff(m,m.darkmoonGruul,m.darkmoonGruul) end
            E.giftEndTurn(g, p, m)
        end
    end
    E.s15ObserveKeywords(g, p)
    E.expireSpellcraft(g,p)
    for _=1,p.darkmoonReturnCoin or 0 do E.giveSpell(g,p,"BGS_Treasures_014") end
    p.darkmoonReturnCoin=nil
    for _=1,times do hooks(g,p,"endTurn") end
    applyUndead(p)
    if p.offer and p.offer.forced then E.offerPick(g, p.color, nil) end
    event(g, p.color, "turn_end", nil)
end

-------------------------------------------------------------------------------
-- combat
local C_ = {}

local function snapshotSide(S)
    local r = {}
    for _, m in ipairs(S.list) do
        r[#r + 1] = {u = m.uid, id = m.id, a = m.atk, h = m.hp, g = m.golden or nil, t = m.taunt or nil,
            s = m.shield or nil, r = m.reborn or nil, w = m.windfury or nil, v = m.venom or nil, p = m.poison or nil, x = m.stealth or nil}
    end
    return r
end

local function captureHands(C)
    C.hands = C.hands or {}
    local snapshots = {}
    for i, side in ipairs(C.sides) do
        local p = side.spec.color and C.g.players[side.spec.color]
        if p and not p.bot then
            local prior = C.hands[i]
            local changed = not prior or #p.hand ~= #prior.hand or #p.spellHand ~= #prior.spellHand
            if not changed then
                for j, m in ipairs(p.hand) do
                    local old = prior.hand[j]
                    if m.uid ~= old.uid or m.id ~= old.id or m.golden ~= old.golden or m.atk ~= old.atk or m.hp ~= old.hp then
                        changed = true
                        break
                    end
                end
            end
            if not changed then
                for j, spell in ipairs(p.spellHand) do
                    if spell.uid ~= prior.spellHand[j].uid or spell.id ~= prior.spellHand[j].id then changed = true; break end
                end
            end
            if changed then
                prior = {hand = copyTable(p.hand), spellHand = copyTable(p.spellHand)}
                C.hands[i] = prior
            end
            snapshots[i] = prior
        end
    end
    return snapshots
end

local function frame(C, text, au, tu, fx)
    C_.recordKeptKeywords(C)
    if C.noFrames then
        if fx~="deity_summon" then return end
        local observed=false
        for _,side in ipairs(C.sides) do
            local color=side.spec.color
            local player=color and C.g.players[color]
            if player and not player.bot then observed=true; break end
        end
        if not observed then return end
    end
    local sacrifices
    if C.g.deity then
        sacrifices={}
        for _,side in ipairs(C.sides) do sacrifices[side.n]=math.min(E.deityNeed(C.g.deity),side.deityCount or #(side.sacrificed or {})) end
    end
    local questNow = {}
    for i, side in ipairs(C.sides) do
        local qp = side.spec and side.spec.color and C.g.players[side.spec.color]
        questNow[i] = qp and qp.quest and not qp.quest.done and qp.quest.progress or nil
    end
    table.insert(C.frames, {a=snapshotSide(C.sides[1]),b=snapshotSide(C.sides[2]),t=text,au=au,tu=tu,fx=fx,quests=questNow,
        hands=captureHands(C),sacrifices=sacrifices,effectTarget=fx=="shield_break" and C.shieldTarget or nil})
end

local function cname(m) return (m.golden and "Golden " or "") .. card(m.id).name end

local function otherSide(C, S) return C.sides[S.n == 1 and 2 or 1] end

local function ownerOf(C, S)
    local color = S.spec and S.spec.color
    return color and C.g.players[color] or nil
end
C_.owner = ownerOf
function C_.trinketHook(C,S,name,...)
    local p=ownerOf(C,S)
    if not p then return end
    for _,id in ipairs(E.passives(p)) do
        local t=E.TR[id]
        if t and t[name] then t[name](C.g,p,C,S,...) end
    end
end

local function combatMinion(C, src, S)
    C.uid = C.uid + 1
    local m = copyTable(src)
    m.src, m.uid, m.side = src.uid, C.uid, S.n
    m.tempReborn = nil
    m.tKw, m.tA, m.tH = nil, nil, nil
    m.inCombat, m.gA, m.gH, m.maxhp = true, 0, 0, m.hp
    if C.g.season == "s15" then E.s15MarkKeywords(m) end
    if m.id=="BG21_015" then C_.keep(C,m,mult(m)) end
    local p=ownerOf(C,S)
    if p then
        E.updateCardAuras(p,m)
        E.bindStatCard(p,m,C,S)
    end
    return m
end

-- Combat-time Blood Gem from the side's owner (default +1/+1).
local function combatGem(C, S, m, n)
    local p = ownerOf(C, S)
    E.applyGems(C.g,p or {},m,n or 1,S.list)
end
C_.gem = combatGem

local function handBuff(C, S, a, h)
    local p = ownerOf(C, S)
    if not p then return end
    local t = pick(C.g, p.hand)
    if t then buff(t, a, h) end
end

local function summon(C, S, id, golden, pos, setup)
    if #S.list >= E.MAX_BOARD then E.s15ExcessSummon(C, S); return nil end
    local fresh=E.newMinion(C.g,id,golden)
    if C.recruit then fresh.generated=true end
    local m=C.recruit and fresh or combatMinion(C,fresh,S)
    if not C.recruit then m.src=nil end
    if id == "BG28_603t" then -- Beetles carry "this game" bonuses
        local p = ownerOf(C, S)
        if p then buff(m, p.beetleA or 0, p.beetleH or 0) end
    end

    if hasRace(m, "UNDEAD") then
        local p = ownerOf(C, S)
        if p then m.atk = m.atk + (p.undeadAtk or 0) end
    end
    if setup then setup(m) end
    if C.g.season == "s15" then E.s15MarkKeywords(m) end
    pos = math.max(1, math.min(pos or (#S.list + 1), #S.list + 1))
    C_.recordKeptKeywords(C)
    table.insert(S.list,pos,m)
    local p=ownerOf(C,S)
    if p then
        E.bindStatCard(p,m,not C.recruit and C or nil,not C.recruit and S or nil)
        E.automatonSummoned(p,m,S.list)
        E.buddySummoned(p,m,S.list)
        E.heroCombatSummon(C,S,m,p)
        if p.trinkets or p.questRewards or p.quest then
            hooks(C.g,p,"summonTrinket",m)
            C_.trinketHook(C,S,"summoned",m)
        end
    end
    if not C.recruit then C_.updatePoets(C,S) end
    if S.humming and hasRace(m,"BEAST") then buff(m,S.humming,0) end
    for _,o in ipairs(S.list) do
        local f=o~=m and o.hp>0 and FX[o.id]
        if f then
            if f.summon then f.summon(o,m,not C.recruit) end
            if not C.recruit and f.combatSummon then f.combatSummon(C,S,o,mult(o),m) end
        end
    end
    E.s15Summon(C.g, p, m, C, S)
    return m
end
C_.summon = summon
function C_.summonCopy(C,S,saved,pos,statScale)
    return summon(C,S,saved.id,saved.golden,pos,function(m)
        local keep={uid=true,src=true,side=true,inCombat=true,gA=true,gH=true,trackedPermanent=true,
            originalKeywords=true,keptKeywords=true,keepersFactor=true,poetFactor=true,keptAtk=true,keptHp=true,
            permanent=true,permAtk=true,permHp=true,
            kodoSummons=true,dead=true,killedBy=true,ownAutomatonSummons=true}
        for key,value in pairs(saved) do
            if not keep[key] then m[key]=type(value)=="table" and copyTable(value) or value end
        end
        if m.id=="BG_TTN_401" and m.dynamicAtk and saved.ownAutomatonSummons then
            m.atk,m.hp=m.atk-m.dynamicAtk,m.hp-m.dynamicHp
            m.dynamicAtk,m.dynamicHp=0,0
        end
        if statScale then m.atk,m.hp=m.atk*statScale,m.hp*statScale end
        m.maxhp=m.hp
    end)
end
E.C = C_

local function dealDamage(C, S, target, amount, source)
    if amount <= 0 or target.hp <= 0 and target.dead or target.giftImmune then return 0 end
    if target.shield then
        if C.g.season == "s15" and E.s15ShieldPrevented then E.s15ShieldPrevented(C, S, target, amount) end
        if target.darkGift and target.darkGift.toreth and not target.shieldHits then target.shieldHits=3 end
        if target.shieldHits and target.shieldHits>1 then target.shieldHits=target.shieldHits-1; return 0 end
        target.shieldHits=nil
        C_.recordKeptKeywords(C)
        E.s15ObserveKeywords(C.g, ownerOf(C,S), C, S)
        target.shield = false
        C.fx="shield_break"
        C.shieldTarget=target.uid
        for _, o in ipairs(S.list) do
            if FX[o.id] and FX[o.id].shieldLost then FX[o.id].shieldLost(C, S, o, target) end
        end
        E.s15ObserveKeywords(C.g, ownerOf(C,S), C, S)
        return 0
    end
    target.hp = target.hp - amount
    if source and source.venom and not C.recruit then
        source.venom=false
        target.hp=math.min(0,target.hp)
    elseif source and source.poison then
        target.hp=math.min(0,target.hp)
    end
    if target.hp<=0 and source and not target.killedBy then
        target.killedBy=source
        if not C.recruit then C_.buddyKill(C,S,source,target) end
    end
    local f = FX[target.id]
    if f and f.damaged then f.damaged(C, S, target, mult(target), amount) end
    if source then C_.damageDealt(C,S,source,amount) end
    return amount
end
C_.dealDamage = dealDamage

local function livingOf(S)
    local r = {}
    for _, m in ipairs(S.list) do if m.hp > 0 then table.insert(r, m) end end
    return r
end
C_.living = livingOf

function C_.hasDeathrattle(m)
    local f,gift=FX[m.id],m.darkGift
    if f and f.dr and (m.id~="BG31_HERO_801pt" or m.cruiserReactor) or m.roameDeathrattle
        or m.frogRattles or m.timewarpDeathrattles or m.s15Deathrattles or m.earthInvocation or gift and (gift.freeRefreshes or gift.spellDeath or gift.sacrificeA or gift.sacrificeH or gift.golem) then return true end
    for _,part in ipairs(m.attachments or {}) do if FX[part.id] and FX[part.id].dr then return true end end
    return false
end

local function runDeathrattle(C, S, m, pos)
    local f = FX[m.id]
    local gift=m.darkGift
    local extra=gift and (gift.freeRefreshes or gift.spellDeath or gift.sacrificeA or gift.sacrificeH or gift.golem)
    if m.firingDeathrattle or not C_.hasDeathrattle(m) then return end
    m.firingDeathrattle=true
    local times=1
    for _, o in ipairs(S.list) do
        if o.hp>0 and (o.id=="BG25_354" or o.id=="BG34_Giant_376") then times=times+mult(o) end
    end
    local p = ownerOf(C, S)
    if p and p.extraDeathrattles then times=times+p.extraDeathrattles end
    for _ = 1, times do
        local function fire(fn, k)
            fn(C,S,m,pos,k)
            for _,ally in ipairs(S.list) do
                local effect=ally.hp>0 and FX[ally.id]
                if effect and effect.afterDeathrattle then effect.afterDeathrattle(C,S,ally,mult(ally)) end
            end
            if p then
                p.drTriggered=(p.drTriggered or 0)+1
                if E.questNote then E.questNote(C.g,p,"deathrattle",1,not C.recruit) end
                E.refreshGiftAuras(p,"drTriggered",C.recruit and nil or S.list)
                E.refreshCardAuras(p,"BG35_342")
                if not C.recruit then
                    for _,ally in ipairs(S.list) do if ally.id=="BG35_342" then E.updateCardAuras(p,ally) end end
                end
            end
        end
        if f and f.dr then
            fire(function(...) return E.withElementalAura(p,m,f.dr,...) end,mult(m))
        end
        E.dispatchAttached(m,"dr",fire)
        for _,k in ipairs(m.frogRattles or {}) do fire(C_.frogRattle,k) end
        for _,part in ipairs(m.timewarpDeathrattles or {}) do fire(FX[part.id].dr,part.k) end
        for _, part in ipairs(m.s15Deathrattles or {}) do fire(FX[part.id].dr, part.k) end
        if extra then fire(C_.giftDeathrattle,1) end
        if m.earthInvocation then fire(C_.earthInvocation,m.earthInvocation) end
        if m.roameDeathrattle then fire(C_.roameDeath,1) end
    end
    m.firingDeathrattle=nil
end
C_.runDeathrattle = runDeathrattle

local function resolveDeaths(C)
    for _ = 1, 50 do
        C_.recordKeptKeywords(C)
        local dead = {}
        for _, n in ipairs({C.active, C.active == 1 and 2 or 1}) do
            local S = C.sides[n]
            local kept = {}
            for _, m in ipairs(S.list) do
                if m.hp <= 0 then
                    m.dead = true
                    table.insert(dead, {m = m, S = S, pos = #kept + 1})
                else
                    table.insert(kept, m)
                end
            end
            local removed=#S.list~=#kept
            S.list=kept
            if C.recruit and S.n==1 then C.recruit.board=kept
            elseif removed and not C.recruit then C_.updatePoets(C,S) end
        end
        if #dead == 0 then return end
        for _, d in ipairs(dead) do
            local m, S = d.m, d.S
            if hasRace(m, "MECHANICAL") then table.insert(S.deadMechs, m.id) end
            local before = #S.list
            if not C.recruit then
                local owner=ownerOf(C,S)
                if owner and owner.lastCombatDead then owner.lastCombatDead[m.id]=true end
                E.heroCombatDeath(C,S)
                if hasRace(m,"ABERRATION") and not card(m.id).deity then S.lastSacrificePos=d.pos end
                C_.recordSacrifice(C,S,m)
                C_.awakeDeity(C,S)
            end
            runDeathrattle(C,S,m,d.pos)
            C_.trinketHook(C,S,"death",m)
            if not C.recruit then C_.trinketHook(C,C.sides[S.n==1 and 2 or 1],"enemyDeath",m) end
            if C.recruit then
                if S.n==1 then returnToPool(C.g,m) end
            else
                C_.awakeDeity(C,S)
                E.heroCombatSpace(C,S)
            end
            if not C.recruit then E.s15CombatSpace(C, S) end
            local added = #S.list - before
            for _, o in ipairs(S.list) do
                if o.hp > 0 and FX[o.id] and FX[o.id].friendlyDeath then FX[o.id].friendlyDeath(C, S, o, m, mult(o)) end
            end
            for _, o in ipairs(S.list) do
                local av = o.hp > 0 and FX[o.id] and FX[o.id].avenge
                if av then
                    o.avenged = (o.avenged or 0) + 1
                    if o.avenged >= av.n then o.avenged = 0; av.fn(C, S, o, mult(o)) end
                end
            end
            if S.reanimation and #S.list<E.MAX_BOARD then
                local plan=S.reanimation;S.reanimation=nil;C_.summonCopy(C,S,plan.saved,plan.pos)
            end
            if m.id == "BG25_008" then
                local p = ownerOf(C, S)
                if p then
                    p.ekDeaths=(p.ekDeaths or 0)+1
                    E.refreshCardAuras(p,"BG25_008")
                    if not C.recruit then
                        for _,ally in ipairs(S.list) do if ally.id=="BG25_008" then E.updateCardAuras(p,ally) end end
                    end
                end
            end
            if m.reborn then
                local r = summon(C,S,m.id,m.golden,d.pos+added,function(r)
                    r.reborn=false
                    if m.timewarpFullReborn or m.darkGift and m.darkGift.persist then
                        r.atk,r.hp=m.atk,math.max(1,m.maxhp or card(m.id).hp)
                        if r.inCombat then r.maxhp=r.hp end
                        r.darkGift,r.giftAuraA,r.giftAuraH=m.darkGift,m.giftAuraA,m.giftAuraH
                        for _, key in ipairs(BONUS_KW) do if key~="reborn" then r[key]=m[key] end end
                    else r.hp=1 end
                end)
                if r then
                    for _,o in ipairs(S.list) do
                        if o.hp>0 and FX[o.id] and FX[o.id].reborned then FX[o.id].reborned(C,S,o,r,mult(o)) end
                    end
                    C_.trinketHook(C,S,"reborn",r)
                    frame(C,cname(r).." is Reborn.",r.uid,nil,"reborn")
                end
            end
            -- Later deaths on the same side shift right by the minions inserted here.
            for _, e in ipairs(dead) do
                if e.S == S and e.pos > d.pos and e ~= d then e.pos = e.pos + (#S.list - before) end
            end
            frame(C, cname(m) .. " dies.", nil, m.uid, "defeat")
        end
        if not C.recruit then for _, S in ipairs(C.sides) do E.s15CombatSpace(C, S) end end
        if not C.recruit then for _, S in ipairs(C.sides) do E.spellSummons(C,S) end end
    end
end
C_.resolveDeaths = resolveDeaths

local function chooseTarget(C, attacker, enemy)
    local living = livingOf(enemy)
    if #living == 0 then return nil end
    if attacker.id == "BGS_022" then -- Zapp Slywick
        local low, list = math.huge, {}
        for _, m in ipairs(living) do
            if m.atk < low then low, list = m.atk, {m} elseif m.atk == low then table.insert(list, m) end
        end
        return pick(C.g, list)
    end
    local visible = {}
    for _, m in ipairs(living) do if not m.stealth then table.insert(visible, m) end end
    if #visible > 0 then living = visible end
    local taunts = {}
    for _, m in ipairs(living) do if m.taunt then table.insert(taunts, m) end end
    if #taunts > 0 then return pick(C.g, taunts) end
    return pick(C.g, living)
end

local function attack(C,S,attacker,forced)
    local enemy=otherSide(C,S)
    local target=forced or chooseTarget(C,attacker,enemy)
    if not target then return end
    C.fx,C.shieldTarget=nil,nil
    local f=FX[attacker.id]
    attacker.stealth=false
    E.heroCombatAttack(C,S)
    C_.firstAttackProtection(C,S,attacker)
    if f and f.onAttack then
        local n=1
        if card(attacker.id).rally then
            for _,m in ipairs(S.list) do if m.id=="BG34_Giant_376" and m.hp>0 then n=math.max(n,1+mult(m)) end end
        end
        if card(attacker.id).rally and ownerOf(C,S) then n=n+(ownerOf(C,S).extraRallies or 0) end
        for _=1,n do E.withElementalAura(ownerOf(C,S),attacker,f.onAttack,C,S,attacker,mult(attacker),target) end
    end
    E.dispatchAttached(attacker,"onAttack",function(fn,k) fn(C,S,attacker,k,target) end)
    C_.giftRally(C,S,attacker)
    C_.trinketHook(C,S,"attack",attacker,target)
    C_.trinketHook(C,enemy,"attacked",target,attacker)
    if target.hp<=0 then
        resolveDeaths(C)
        if attacker.hp<=0 then return end
        target=chooseTarget(C,attacker,enemy)
        if not target then return end
    end
    for _, o in ipairs(S.list) do
        if o.hp > 0 and FX[o.id] and FX[o.id].allyAttack then FX[o.id].allyAttack(C, S, o, attacker, mult(o)) end
    end
    if target.taunt then
        for _, o in ipairs(enemy.list) do
            if o.hp > 0 and o.id == "BGS_110" then -- Arm of the Empire
                target.atk = target.atk + 3 * mult(o)
                target.permAtk = (target.permAtk or 0) + 3 * mult(o)
            end
        end
    end
    for _,ally in ipairs(enemy.list) do
        local f=ally.hp>0 and FX[ally.id]
        if f and f.afterAllyTargeted then f.afterAllyTargeted(C,enemy,ally,target,mult(ally)) end
    end
    local hpBefore, hadShield = target.hp, target.shield
    local ti = indexOf(enemy.list, target)
    if FX[target.id] and FX[target.id].beAttacked then FX[target.id].beAttacked(C, enemy, target, attacker) end
    E.s15ObserveKeywords(C.g, ownerOf(C,S), C, S)
    E.s15ObserveKeywords(C.g, ownerOf(C,enemy), C, enemy)
    local aAtk,tAtk=attacker.atk,target.atk
    dealDamage(C, enemy, target, target.resilient and math.ceil(aAtk / 2) or aAtk, attacker)
    if card(attacker.id).cleave and ti then
        for _, j in ipairs({ti - 1, ti + 1}) do
            local n = enemy.list[j]
            if n and n.hp > 0 then dealDamage(C, enemy, n, aAtk, attacker) end
        end
    end
    attacker.giftImmune=attacker.id=="BG24_004" or attacker.id=="BG34_Treasure_990" or attacker.buddyImmuneAttack
        or attacker.darkGift and attacker.darkGift.immuneAttack or nil
    dealDamage(C,S,attacker,tAtk,target)
    attacker.giftImmune,attacker.buddyImmuneAttack=nil,nil
    if target.hp <= 0 and f and f.onKill then f.onKill(C, S, attacker, target, mult(attacker)) end
    if attacker.id == "BGS_126" and not hadShield and target.hp <= 0 and ti then -- Wildfire Elemental
        local excess = aAtk - math.max(0, hpBefore)
        if excess > 0 then
            local adj = {}
            for _, j in ipairs({ti - 1, ti + 1}) do
                local n = enemy.list[j]
                if n and n.hp > 0 then table.insert(adj, n) end
            end
            if attacker.golden then
                for _, n in ipairs(adj) do dealDamage(C, enemy, n, excess, attacker) end
            elseif #adj > 0 then
                dealDamage(C, enemy, pick(C.g, adj), excess, attacker)
            end
        end
    end
    if f and f.afterAttack and attacker.hp > 0 then f.afterAttack(C, S, attacker, mult(attacker), target) end
    if attacker.questVolatile and attacker.hp > 0 then attacker.hp = 0 end
    frame(C, cname(attacker) .. " attacks " .. cname(target) .. ".", attacker.uid, target.uid, C.fx or "attack")
    resolveDeaths(C)
end
C_.attack = attack

local function nextAttacker(S)
    local n = #S.list
    if n == 0 then return nil end
    if S.next > n or S.next < 1 then S.next = 1 end
    for k = 0, n - 1 do
        local i = ((S.next - 1 + k) % n) + 1
        if S.list[i].atk > 0 and S.list[i].hp > 0 then S.next = i; return S.list[i] end
    end
    return nil
end

local function tierOf(m) return m.cardTier or card(m.id).tier end

-- side spec: {color=, name=, tier=, hero=heroIndex or nil, board={minions}}
function E.simulate(g, specA, specB, opts)
    opts = opts or {}
    local C = {g = g, uid = 0, frames = {}, sides = {}, noFrames = opts.noFrames, immediate = {}}
    for n, spec in ipairs({specA, specB}) do
        local S = {n = n, list = {}, next = 1, deadMechs = {}, spec = spec}
        local owner=spec.color and g.players[spec.color]
        if owner then owner.lastCombatDead,owner.lastCombatStart={},{} end
        for _,m in ipairs(spec.board) do
            local copy=combatMinion(C,m,S)
            if owner then owner.lastCombatStart[#owner.lastCombatStart+1]=m.id end
            if owner and copy.id=="BG36_372" then E.updateCardAuras(owner,copy) end
            table.insert(S.list,copy)
        end
        C.sides[n] = S
    end
    C.active = 1
    for _,S in ipairs(C.sides) do
        C_.updatePoets(C,S)
        for _,m in ipairs(S.list) do if m.darkGift and m.darkGift.keep then C_.keep(C,m,2,false) end end
    end
    -- start of combat
    for n, S in ipairs(C.sides) do
        local sh = S.spec.hero and E.heroById(S.spec.hero)
        local key = sh and sh.key or ""
        if key=="deathwing" or (sh and sh.id=="TB_BaconShop_HERO_52") then
            for _,T in ipairs(C.sides) do
                for _,m in ipairs(T.list) do C_.trinketPermanent(C,m,2,0) end
            end
        elseif key == "wagtoggle" then
            for _, race in ipairs({"BEAST", "MECHANICAL", "DEMON", "PIRATE", "DRAGON", "ELEMENTAL"}) do
                local list = others(S.list, nil, race)
                local m = pick(g, list)
                if m then buff(m, 1, 1) end
            end
        end
    end
    for n, S in ipairs(C.sides) do
        local other = C.sides[n == 1 and 2 or 1]
        E.spellStartCombat(C, S, other)
        E.spellSummons(C, S)
        local owner=ownerOf(C,S)
        local hp=S.spec.hero and E.HP[S.spec.hero]
        if hp and hp.soc then hp.soc(C,S,other,g) end
        local extra=owner and E.HP[owner.secondPowerHero]
        if extra and extra~=hp and extra.soc then extra.soc(C,S,other,g) end
        E.heroCombatSpace(C,S)
        for _, tid in ipairs(E.specPassives(S.spec, owner)) do
            local t = E.TR[tid]
            if t and t.soc then t.soc(C, S, other, g) end
        end
        local an = g.anomaly and E.AN[g.anomaly]
        if an and an.soc then an.soc(C, S, other, g) end
    end
    local a, b = #C.sides[1].list, #C.sides[2].list
    if a > b then C.active = 1 elseif b > a then C.active = 2 else C.active = rnd(g, 2) end
    frame(C, "Combat begins.", nil, nil, "turn_start")
    for _, S in ipairs(C.sides) do
        S.startIds = {}
        for _, m in ipairs(S.list) do table.insert(S.startIds, m.id) end
    end
    -- Start of Combat minion effects, attacking player first.
    for _, n in ipairs({C.active, C.active == 1 and 2 or 1}) do
        local S = C.sides[n]
        local list = {}
        for i, m in ipairs(S.list) do list[i] = m end
        for _, m in ipairs(list) do
            local f = FX[m.id]
            if m.hp > 0 and m.darkGift then C_.startGift(C, S, m) end
            if m.hp > 0 and f and f.soc then
                E.withElementalAura(ownerOf(C,S),m,f.soc,C,S,m,mult(m))
                frame(C, cname(m) .. ": Start of Combat.", m.uid, nil, "start_of_combat")
            end
        end
        local p = C_.owner(C, S)
        for _, h in ipairs(p and p.hand or {}) do
            local f = FX[h.id]
            if f and f.handSoc then f.handSoc(C, S, h, mult(h)) end
        end
        E.s15ObserveKeywords(g, ownerOf(C,S), C, S)
        resolveDeaths(C)
    end
    C.s15StartComplete = true
    for _, S in ipairs(C.sides) do E.s15CombatSpace(C, S) end
    while #C.immediate > 0 do
        local imm = table.remove(C.immediate, 1)
        local IS = C.sides[imm.side]
        if imm.hp > 0 and #otherSide(C, IS).list > 0 then attack(C, IS, imm) end
    end
    for _ = 1, 400 do
        local S, O = C.sides[C.active], C.sides[C.active == 1 and 2 or 1]
        if #S.list == 0 or #O.list == 0 then break end
        local attacker = nextAttacker(S)
        if not attacker then
            if not nextAttacker(O) then break end
        else
            local idx = indexOf(S.list, attacker)
            local swings = attacker.windfury and 2 or 1
            for _ = 1, swings do
                if attacker.hp > 0 and #O.list > 0 then attack(C, S, attacker) end
            end
            while #C.immediate > 0 do
                local imm = table.remove(C.immediate, 1)
                local IS = C.sides[imm.side]
                if imm.hp > 0 and #otherSide(C, IS).list > 0 then attack(C, IS, imm) end
            end
            local now = indexOf(S.list, attacker)
            S.next = now and (now + 1) or idx
        end
        C.active = C.active == 1 and 2 or 1
    end
    local A,B=C.sides[1].list,C.sides[2].list
    for _,side in ipairs(C.sides) do
        local owner=ownerOf(C,side)
        if owner then
            owner.rafaamPrimed=nil
            for _,m in ipairs(side.list) do
                if m.id=="BG34_Giant_039" and m.src then
                    for _,original in ipairs(owner.board) do
                        if original.uid==m.src then original.lastSurvived=g.turn;break end
                    end
                end
            end
        end
    end
    local result = {frames = C.frames, survivorsA = #A, survivorsB = #B, permanent = {},
        final = {a = snapshotSide(C.sides[1]), b = snapshotSide(C.sides[2]), hands = captureHands(C)}}
    if g.deity then
        result.final.sacrifices={}
        for _,side in ipairs(C.sides) do result.final.sacrifices[side.n]=math.min(E.deityNeed(g.deity),side.deityCount or #(side.sacrificed or {})) end
    end
    C_.recordKeptKeywords(C)
    local kept={}
    local function log(m,keep,explicit)
        if not m.src then return end
        local atk,hp=explicit and (m.permAtk or 0) or 0,explicit and (m.permHp or 0) or 0
        if keep then
            atk=atk+math.max(0,m.keptAtk or 0)
            hp=hp+math.max(0,m.keptHp or 0)
        end
        result.permanent[#result.permanent+1]={side=m.side,src=m.src,atk=atk,hp=hp,kw=keep and m.keptKeywords or nil,
            shieldGrowth=m.shieldGrowth,parrotDamage=m.parrotDamage,parrotReward=m.parrotReward,lastStanding=m.lastStanding}
        kept[m]=true
    end
    for _,m in ipairs(C.keepers or {}) do log(m,true,true) end
    for _,m in ipairs(C.permanentMinions or {}) do if not kept[m] then log(m,false,true) end end
    for _,S in ipairs(C.sides) do
        for _,m in ipairs(S.list) do if not kept[m] and (m.permAtk or m.permHp) then log(m,false,true) end end
    end
    local function damageOf(list, spec)
        local parts = {base = spec.tier or 1, tiers = {}}
        local d = parts.base
        for _, m in ipairs(list) do
            local tier = tierOf(m)
            parts.tiers[#parts.tiers + 1] = tier
            d = d + tier
        end
        result.parts = parts
        return d
    end
    if #A > 0 and #B == 0 then
        result.winner, result.damage = 1, damageOf(A, specA)
    elseif #B > 0 and #A == 0 then
        result.winner, result.damage = 2, damageOf(B, specB)
    else
        result.winner, result.damage = 0, 0
    end
    return result
end
E.combat = C_

local function sideSpec(p)
    return {color = p.color, name = p.name, tier = p.tier, hero = p.hero, board = p.board, trinkets = p.trinkets}
end

function E.damageCap(g)
    local alive = #E.alivePlayers(g)
    -- Season 9+ solo rule: 5 until turn 4, 10 until turn 8, then 15; no cap once in the top four.
    if alive <= 4 then return 999 end
    if g.turn <= 3 then return 5 elseif g.turn <= 7 then return 10 end
    return 15
end

-- Pair living players; an odd player fights the most recently eliminated player's ghost.
function E.pairings(g)
    local alive = E.alivePlayers(g)
    local best
    for _ = 1, 60 do
        local list = {}
        for i, v in ipairs(alive) do list[i] = v end
        shuffle(g, list)
        local pairs_, repeats = {}, 0
        -- Real matchmaking (33.2+): with everyone alive, meet each opponent once before a repeat;
        -- after an elimination, avoid anyone met in the last three rounds when possible.
        local full = #g.eliminated == 0
        for i = 1, #list - 1, 2 do
            local x, y = list[i], list[i + 1]
            local met = x.met and x.met[y.color]
            if met and (full or g.turn - met <= 3) then repeats = repeats + (full and 1 or (4 - (g.turn - met))) end
            if x.lastOpponent == y.color then repeats = repeats + 10 end
            table.insert(pairs_, {x, y})
        end
        if #list % 2 == 1 then table.insert(pairs_, {list[#list], nil}) end
        if not best or repeats < best.repeats then best = {pairs = pairs_, repeats = repeats} end
        if repeats == 0 then break end
    end
    return best.pairs
end

function E.closeRecruit(g, interactive)
    if g.recruitClosed then return end
    g.recruitClosed = true
    for _, p in ipairs(E.alivePlayers(g)) do
        E.finishTimewarp(g,p)
        E.feedFodder(g,p,true)
        endOfTurn(g, p)
        if p.bot or not interactive then
            while p.discover do
                local d = p.discover
                local count = #(d.options or {})
                if count == 0 or not E.discoverPick(g, p.color, rnd(g, count)) then
                    if p.discover == d and #(d.options or {}) == count then
                        p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue, 1) or nil
                    end
                end
            end
        end
    end
end

function E.recruitPairings(g)
    if g.pairingTurn~=g.turn then
        g.pairingTurn,g.roundPairIds=g.turn,{}
        for _,pair in ipairs(E.pairings(g)) do
            g.roundPairIds[#g.roundPairIds+1]={a=pair[1].color,b=pair[2] and pair[2].color}
        end
    end
    local pairs={}
    for _,ids in ipairs(g.roundPairIds or {}) do pairs[#pairs+1]={g.players[ids.a],ids.b and g.players[ids.b]} end
    return pairs
end

function E.endRecruit(g, opts)
    E.closeRecruit(g,false)
    g.phase = "combat"
    local results={}
    for _,pair in ipairs(E.recruitPairings(g)) do
        local x, y = pair[1], pair[2]
        local specB = nil
        if y then
            specB = sideSpec(y)
        else
            local ghost = g.eliminated[#g.eliminated]
            if not ghost then
                local others_ = {}
                for _, p in ipairs(E.alivePlayers(g)) do if p ~= x then table.insert(others_, p) end end
                local src = pick(g, others_) or x
                ghost = {color = src.color, name = src.name, tier = src.tier, hero = src.hero, board = copyTable(src.board)}
            end
            specB = {color = nil, name = "Ghost of " .. ghost.name, tier = ghost.tier, hero = ghost.hero, board = ghost.board}
        end
        local noFrames = opts and (opts.fast or x.bot and (not y or y.bot))
        local r = E.simulate(g, sideSpec(x), specB, {noFrames = noFrames})
        if not y then r.ghostHero = specB.hero end
        r.a, r.b, r.bName, r.ghost = x.color, y and y.color or nil, specB.name, y == nil
        x.lastOpponent = y and y.color or "ghost"
        if y then y.lastOpponent = x.color end
        if y then
            x.met, y.met = x.met or {}, y.met or {}
            x.met[y.color], y.met[x.color] = g.turn, g.turn
        end
        table.insert(results, r)
    end
    g.pending = results
    return results
end

-- Apply damage and eliminations after combat playback.
function E.applyCombat(g)
    local results = g.pending or {}
    g.pending=nil
    E.resolveCombatWagers(g,results)
    local cap=E.damageCap(g)
    local newlyDead = {}
    for _, r in ipairs(results) do
        local A, B = g.players[r.a], r.b and g.players[r.b] or nil
        for _, perm in ipairs(r.permanent or {}) do
            local owner = perm.side == 1 and A or B
            if owner then
                for _, m in ipairs(owner.board) do
                    if m.uid==perm.src then
                        buff(m,perm.atk,perm.hp or 0)
                        for key in pairs(perm.kw or {}) do m[key]=true end
                        for _,field in ipairs({"shieldGrowth","parrotDamage","parrotReward","lastStanding"}) do
                            if perm[field]~=nil then m[field]=perm[field] end
                        end
                    end
                end
            end
        end
        local dmg = math.min(r.damage, cap)
        if B then A.lastOpponentBoard = copyTable(B.board); B.lastOpponentBoard = copyTable(A.board) end
        r.dealt = dmg
        A.lostLast = r.winner == 2
        if B then B.lostLast = r.winner == 1 end
        if r.winner == 1 then
            if B then damageHero(g, B, dmg) end
            event(g, A.color, "round_win", nil)
            if B then event(g, B.color, "damage", nil) end
        elseif r.winner == 2 then
            damageHero(g, A, dmg)
            if B then event(g, B.color, "round_win", nil) end
            event(g, A.color, "damage", nil)
        else
            event(g, A.color, "round_tie", nil)
            if B then event(g, B.color, "round_tie", nil) end
        end
        E.spellBattle(g, A, r.winner == 1, r.winner == 0)
        if B then E.spellBattle(g, B, r.winner == 2, r.winner == 0) end
        hooks(g, A, "afterCombat", r.winner == 1, dmg, r.winner == 2)
        if B then hooks(g, B, "afterCombat", r.winner == 2, dmg, r.winner == 1) end
    end
    for _, p in ipairs(E.alivePlayers(g)) do
        if p.hp <= 0 then table.insert(newlyDead, p) end
    end
    table.sort(newlyDead, function(x, y) return x.hp > y.hp end)
    local remaining = #E.alivePlayers(g)
    for i = #newlyDead, 1, -1 do
        local p = newlyDead[i]
        p.alive=false
        E.heroEliminated(g,p)
        p.place=remaining; remaining = remaining - 1
        table.insert(g.eliminated, {color = p.color, name = p.name, tier = p.tier, hero = p.hero, board = copyTable(p.board)})
        for _, m in ipairs(p.board) do returnToPool(g, m) end
        for _, m in ipairs(p.hand) do returnToPool(g, m) end
        clearTavern(g, p)
        for _, plan in ipairs(p.expeditions or {}) do
            if plan.reserved then returnToPool(g, plan.minion) end
        end
        p.board, p.hand, p.expeditions, p.spellHand, p.spellShop = {}, {}, nil, {}, {}
        event(g, p.color, "defeat", p.name .. " was eliminated in place " .. p.place .. ".")
    end
    local alive = E.alivePlayers(g)
    if #alive <= 1 then
        g.phase = "over"
        if alive[1] then
            alive[1].place = 1
            g.winner = alive[1].color
            event(g, alive[1].color, "match_end", alive[1].name .. " wins Battlegrounds!")
        else
            g.winner = nil
            event(g, nil, nil, "Everyone was eliminated together. It's a draw!")
        end
        return true
    end
    return false
end

