-- bots
local function score(m)
    local c = card(m.id)
    local s = m.atk + m.hp + c.tier * 3
    for _, k in ipairs(KEYWORDS) do if m[k] then s = s + 2 end end
    if m.golden then s = s + 6 end
    return s
end
E.score = score

function E.botTurn(g, color)
    local p = g.players[color]
    E.botTimewarp(g,p)
    E.botSpells(g, p)
    if E.skipsRecruit(g, p) then p.ready = true; return end
    if g.buddies then E.buyBuddy(g, color) end
    local targetTier = math.min(p.maxTier or 6, 1 + math.floor((g.turn + 1) / 2))
    local cost = E.upgradeCost(p)
    if cost and p.tier < targetTier and p.gold >= cost and (g.turn > 1) then E.upgrade(g, color) end
    local refreshes = 0
    for _ = 1, 30 do
        -- play cards from hand first
        while #p.hand > 0 and #p.board < E.MAX_BOARD do
            local best, bi = -1, nil
            for i, m in ipairs(p.hand) do if score(m) > best then best, bi = score(m), i end end
            if not E.play(g, color, bi) then break end
            if p.discover then E.botSpells(g, p) end
        end
        if #p.hand > 0 and #p.board >= E.MAX_BOARD then
            local wi, worst = nil, math.huge
            for i, m in ipairs(p.board) do if score(m) < worst then worst, wi = score(m), i end end
            local hb = 0
            for _, m in ipairs(p.hand) do hb = math.max(hb, score(m)) end
            if hb > worst then E.sell(g, color, wi) else break end
        else
            local pc=E.powerCost(p)
            local key=heroKey(p)
            local power=E.powerHero(p)
            local hpx=power and E.HP[power.id]
            if pc and not p.powerUsed and p.gold>=pc and pc<=2 and (#p.board>0 or hpx and hpx.target~="board") then
                local bi, bs = 1, -1
                for i, m in ipairs(p.board) do if score(m) > bs then bs, bi = score(m), i end end
                local zone=hpx and hpx.target
                local t=zone and ((zone=="tavern" or zone=="shop" or zone=="any") and {zone="tavern",index=1} or {zone="board",index=bi})
                if key~="reno" or (p.board[bi] and not p.board[bi].golden) then E.heroPower(g,color,t) end
                if p.discover then E.botSpells(g,p) end
            end
            if p.gold >= E.buyCost(p) and #p.tavern > 0 then
                local bi, bs = nil, -1
                for i, m in ipairs(p.tavern) do
                    local s = score(m)
                    for _, o in ipairs(p.board) do if o.id == m.id and not o.golden then s = s + 8 end end
                    if s > bs then bs, bi = s, i end
                end
                local weakest = math.huge
                for _, o in ipairs(p.board) do weakest = math.min(weakest, score(o)) end
                if #p.board < E.MAX_BOARD or bs > weakest + 2 then
                    E.buy(g, color, bi)
                elseif refreshes < 2 and p.gold >= E.buyCost(p) + E.refreshCost(p) then
                    E.refresh(g, color); refreshes = refreshes + 1
                else
                    break
                end
            elseif p.gold >= E.refreshCost(p) + E.buyCost(p) and refreshes < 3 then
                E.refresh(g, color); refreshes = refreshes + 1
            else
                break
            end
        end
    end
    E.botSpells(g, p)
    -- taunts and shields to the right, attack-heavy minions to the left
    table.sort(p.board, function(x, y)
        local kx = (x.taunt and 1 or 0) * 100 - x.atk
        local ky = (y.taunt and 1 or 0) * 100 - y.atk
        if kx == ky then return x.uid < y.uid end
        return kx < ky
    end)
    p.ready = true
end

