-- v3 current-pool cards (ids, stats and text imported from HearthstoneJSON)
local function ownerC(C, S) return C_.owner(C, S) end
local function livingRace(S, race, except)
    local r = {}
    for _, o in ipairs(S.list) do if o.hp > 0 and o ~= except and (not race or hasRace(o, race)) then table.insert(r, o) end end
    return r
end
local function tokenSummon(id, count, keepGolden)
    return function(C, S, m, pos, k)
        local n = (count or 1) * (keepGolden and 1 or k)
        for i = 1, n do summonC(C, S, id, keepGolden and m.golden or false, pos + i - 1) end
    end
end
local function randomPoolMinion(g, maxTier, filter)
    return drawFromPool(g, maxTier, 1, filter)
end
local function raceFilter(race) return function(c) return indexOf(c.races, race) ~= nil or c.all end end

