local copies = {5, 7, 9, 11, 7, 5}
local function spell(id, target, cast)
    local data = assert(metadata[id], id)
    data.id, data.target, data.cast = id, target, cast
    spells[id] = data
    table.insert(ordered, id)
end

function E.handCount(p)
    return #p.hand + #(p.spellHand or {})
end

local function instance(g, id)
    g.uid = g.uid + 1
    return {id = id, uid = g.uid}
end

function E.giveSpell(g,p,id,timewarpOverflow)
    if not spells[id] or not timewarpOverflow and E.handCount(p)>=E.MAX_HAND then return false end
    table.insert(p.spellHand,instance(g,id))
    E.raiseHandGained(g,p)
    if id=="BG20_GEM" then
        for _=1,E.extraBloodGems(p) do
            if E.handCount(p)>=E.MAX_HAND then break end
            table.insert(p.spellHand,instance(g,id))
            E.raiseHandGained(g,p)
        end
    end
    return true
end

function E.cloneSpellEntry(g, p, entry)
    if E.handCount(p) >= E.MAX_HAND then return false end
    local copy = copyTable(entry)
    copy.uid = instance(g, entry.id).uid
    copy.discardPair, copy.discardAfter = nil, nil
    table.insert(p.spellHand, copy)
    E.raiseHandGained(g, p)
    return true
end

local function drawSpell(g, tier, exact, excluded, filter)
    local inShop = {}
    for _, p in ipairs(E.alivePlayers(g)) do
        for _, s in ipairs(p.spellShop or {}) do inShop[s.id] = (inShop[s.id] or 0) + 1 end
    end
    local allowed = E.seasonSpells[g.season]
    local candidates, total = {}, 0
    for _, id in ipairs(ordered) do
        local s = spells[id]
        local available = (copies[s.tier] or 0) - (inShop[id] or 0)
        local inRotation = allowed and allowed[id] or (not allowed and s.pool)
        if inRotation and available > 0 and s.tier >= (g.minimumTier or 1) and s.tier <= tier and (not exact or s.tier == tier) and not (excluded and excluded[id])
            and (not filter or filter(s)) then
            total = total + available
            candidates[#candidates + 1] = {id = id, upto = total}
        end
    end
    if total == 0 then return nil end
    local roll = rnd(g, total)
    for _, s in ipairs(candidates) do if roll <= s.upto then return s.id end end
end

function E.getRandomSpell(g, p, tier, exact, filter)
    if E.handCount(p) >= E.MAX_HAND then return false, "Your hand is full." end
    local id = drawSpell(g, tier or p.tier, exact, nil, filter)
    if not id then return false, "No spells are available." end
    return E.giveSpell(g, p, id)
end

function E.rollSpellShop(g, p, onlySpells, exact)
    p.spellShop = {}
    local slots, limit = tavernSize(p), 7
    if onlySpells then
        clearTavern(g,p)
    else
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and (f.tavernExtra or f.extraSpellShop) then limit=9 end
        end
        if #p.tavern==7 and limit==7 then returnToPool(g,table.remove(p.tavern)) end
        slots=1
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and f.extraSpellShop then slots=slots+1 end
        end
    end
    for _=1,math.min(slots,limit-#p.tavern) do
        local id = drawSpell(g, p.tier, exact)
        if id then table.insert(p.spellShop, instance(g, id)) end
    end
end

function E.raiseTavernSpells(g, p, amount)
    for i, entry in ipairs(p.spellShop) do
        local current = spells[entry.id].tier
        local tier = math.min(p.maxTier or 6, current + amount)
        if tier > current then
            local id = drawSpell(g, tier, true, entry.id)
            if id then p.spellShop[i] = instance(g, id) end
        end
    end
end

function E.spellPrice(p, entry)
    local s = spells[entry.id]
    if s.health then return s.cost, true end
    if p.hero == "BG28_HERO_800" and ((p.spellsBought or 0) + 1) % 3 == 0 then return 0, false end
    return math.max(0, (entry.s15PriceOverride or s.cost) - (entry.s15Discount or 0)
        - (p.spellDiscount or 0) - (p.darkmoonSpellCut or 0) - E.timewarpSpellDiscount(p)), false
end

function E.buyTavernSpell(g, color, i)
    local p = g.players[color]
    local ok, err = canAct(g, p); if not ok then return false, err end
    local entry = p.spellShop[i]
    if not entry then return false, "That spell is no longer in the Tavern." end
    if E.handCount(p) >= E.MAX_HAND then return false, "Your hand is full." end
    local price, health = E.spellPrice(p, entry)
    if health and p.hp + p.armor <= price then return false, "Not enough Health." end
    if not health and p.gold < price then return false, "Not enough Gold (" .. price .. " needed)." end
    if health then damageHero(g, p, price)
    else
        p.gold = p.gold - price
        spendGold(g, p, price)
        p.spellDiscount = 0
    end
    p.spellsBought=(p.spellsBought or 0)+1
    if not health then E.consumeTimewarpDiscount(p) end
    table.remove(p.spellShop,i)
    entry.s15Discount, entry.s15PriceOverride = nil, nil
    table.insert(p.spellHand, entry)
    E.raiseHandGained(g, p)
    if p.doubleHeader then
        p.doubleHeader = false
        E.giveSpell(g, p, entry.id)
    end
    E.cardPurchased(g,p)
    entry.paidGold=not health and price or nil
    E.onSpellBought(g,p,entry)
    E.timewarpBuyCard(g,p,entry)
    hooks(g,p,"buyCard",entry)
    hooks(g,p,"buySpell",entry)
    E.buddyPurchaseHooks(g,p,entry,true,price)
    event(g, color, "buy", nil)
    return true
end

local function enqueue(p, choice)
    if p.discover then table.insert(p.discoverQueue, choice) else p.discover = choice end
end

function E.discoverSpell(g, p, tier, exact, label, filter)
    local seen, options = {}, {}
    for _ = 1, 3 do
        local id = drawSpell(g, tier, exact, seen, filter)
        if not id then break end
        options[#options + 1], seen[id] = id, true
    end
    if #options == 0 then return false, "No spells are available." end
    enqueue(p, {kind = "spell", label = label or "Discover a Tavern spell", options = options})
    return true
end

local modes = {}
local function choose(g,p,id,labels,target)
    if E.useCombinedChoice(g,p) then
        for _,effect in ipairs(modes[id]) do effect(g,p,target) end
        return true
    end
    enqueue(p, {kind = "spell_mode", label = spells[id].name, spellId = id, options = labels, target = target and target.uid})
    return true
end

function E.pickSpellChoice(g, p, i)
    local d = p.discover
    local item = d.options[i]
    if not item then return false, "No such option." end
    if d.kind == "spell" then
        if not spells[item] then return false, "No such spell." end
        E.giveSpell(g,p,item)
        E.onDiscovered(g,p)
    elseif d.kind == "spell_mode" then
        local target
        if d.target then
            for _, list in ipairs({p.board, p.tavern}) do
                for _, m in ipairs(list) do if m.uid == d.target then target = m end end
            end
        end
        if d.target and not target then return false, "That minion is no longer in play." end
        local ok, err = modes[d.spellId][i](g, p, target)
        if not ok and err then event(g, p.color, "card_play", err) end
    end
    p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue, 1) or nil
    event(g, p.color, "card_draw", nil)
    checkTriples(g, p)
    return true
end

function E.spellBonuses(p,board)
    local auraAttack,auraHealth=E.boardSpellAura(board and {board=board} or p)
    local trinketAtk,trinketHp=E.trinketSpellAura({turn=p.trinketGameTurn or 0},p)
    return (p.spellAtk or 0)+(p.bonusSpellAtk or 0)+auraAttack+trinketAtk,
        (p.spellHp or 0)+(p.bonusSpellHp or 0)+auraHealth+trinketHp
end

-- ===== Spell power (Season 15) ===========================================
-- A Tavern spell's numbers have one source. Its effect and its card text both
-- go through E.spellAmount, so the number the text shows is the number it gives.
--   E.spellPower(p, entry)        -> extra Attack, extra Health for this player
--                                    (spell auras, trinkets, bonuses on that card such as Squirky)
--   E.spellAmount(p, a, h, entry) -> a and h after spell power (a 0 stays 0, except a per-card
--                                    bonus such as Squirky's, which adds +X/+X to any stat grant)
--   E.SPELL_TEXT[id]              -> editable text template for one spell, e.g.
--       {text = "Give a minion +{a}/+{h}.", a = 3, h = 3}
--       {a} and {h} are the template's a/h plus spell power, {a:N} and {h:N} are N plus
--       spell power, and {n:N} is N with no bonus. E.setSpellText(id, template) swaps one in.
--   Spells without a template get every "+X/+Y", "+X Attack" and "+X Health" in their
--   printed text raised by spell power. E.SPELL_POWER_EXEMPT lists spells left alone.
E.SPELL_TEXT = E.SPELL_TEXT or {}
E.SPELL_POWER_TEXT = true
E.SPELL_POWER_EXEMPT = {BG20_GEM = true, BG34_689 = true}

function E.spellPower(p, entry)
    if not p then return 0, 0, 0 end
    local a, h = E.spellBonuses(p)
    local extra = entry and entry.s15StatBonus or p.s15SpellStatBonus or 0
    return a, h, extra
end

-- Spell power raises a stat the spell already gives. A per-card bonus (Squirky)
-- always adds +X/+X on top, even to a spell that gives only Attack or only Health.
function E.spellAmount(p, a, h, entry)
    local extraAttack, extraHealth, extra = E.spellPower(p, entry)
    if a <= 0 and h <= 0 then return a, h end
    if a > 0 then a = a + extraAttack end
    if h > 0 then h = h + extraHealth end
    return a + extra, h + extra
end

local function buffSpell(p, m, a, h)
    a, h = E.spellAmount(p, a, h)
    buff(m, a, h)
end

function E.spellScales(id)
    local s = spells[id]
    if not s or E.SPELL_POWER_EXEMPT[id] or s.spellcraft or s.timewarp then return false end
    if E.SPELL_TEXT[id] then return true end
    if (s.text or ""):find("spells give") then return false end
    return (s.pool or s.tavern or s.s15Invocation or not s.generated) and true or false
end

local function boosted(n, extra)
    n = tonumber(n) or 0
    if n > 0 then return n + extra end
    return n
end

-- "+5 Attack" becomes "+5/+3" when a per-card bonus of 3 is on the spell.
local function withExtra(text, e)
    if not e or e <= 0 then return text end
    local out = text:gsub("%+(%d+) Attack and %+(%d+) Health", "\1%1\2%2\3")
    out = out:gsub("%+(%d+) Attack", function(x) return "+" .. x .. "/+" .. e end)
    out = out:gsub("%+(%d+) Health", function(x) return "+" .. e .. "/+" .. x end)
    return (out:gsub("\1(%d+)\2(%d+)\3", "+%1 Attack and +%2 Health"))
end

function E.renderSpellTemplate(t, a, h, e)
    e = e or 0
    local text = ((t.text or ""):gsub("{(%a):?(%d*)}", function(kind, n)
        local base = n ~= "" and tonumber(n) or t[kind] or 0
        if kind == "a" then
            if base <= 0 then return tostring(base) end
            return tostring(base + (a or 0) + e)
        end
        if kind == "h" then
            if base <= 0 then return tostring(base) end
            return tostring(base + (h or 0) + e)
        end
        return tostring(base)
    end))
    return withExtra(text, e)
end

function E.spellText(p, id, entry)
    local s, t = spells[id], E.SPELL_TEXT[id]
    if not s then return nil end
    local a, h, e = 0, 0, 0
    if p and E.SPELL_POWER_TEXT and E.spellScales(id) then a, h, e = E.spellPower(p, entry) end
    if t then return E.renderSpellTemplate(t, a, h, e) end
    local text = s.text or ""
    if a == 0 and h == 0 and e == 0 then return text end
    text = text:gsub("%+(%d+)/%+(%d+)", function(x, y) return "+" .. boosted(x, a + e) .. "/+" .. boosted(y, h + e) end)
    text = text:gsub("%+(%d+) Attack", function(x) return "+" .. boosted(x, a + e) .. " Attack" end)
    text = text:gsub("%+(%d+) Health", function(x) return "+" .. boosted(x, h + e) .. " Health" end)
    return withExtra(text, e)
end

function E.setSpellText(id, template)
    E.SPELL_TEXT[id] = template
    local s = spells[id] or metadata[id]
    if s then s.text = E.renderSpellTemplate(template, 0, 0, 0) end
end

local function buffAll(p, list, a, h, filter)
    for _, m in ipairs(list) do if not filter or filter(m) then buffSpell(p, m, a, h) end end
end

local function castTrigger(g,p,id,entry)
    p.spellsCast=(p.spellsCast or 0)+1
    local isTavern=not spells[id].generated or spells[id].tavern or entry and entry.alsoTavern
    if isTavern then
        if g.season == "s15" then p.s15TavernSpellsTurn = (p.s15TavernSpellsTurn or 0) + 1 end
        p.lastSpell, p.tavernSpellsCast = id, (p.tavernSpellsCast or 0) + 1
        p.trinketSpellTurnCount=(p.trinketSpellTurn==g.turn and p.trinketSpellTurnCount or 0)+1
        p.trinketSpellTurn=g.turn
        E.refreshGiftAuras(p,"tavernSpellsCast")
        hooks(g,p,"tavernSpell",id)
        E.updateBruisers(p)
    end
    hooks(g,p,"anySpell",id)
    for _, m in ipairs(p.board) do
        local f = FX[m.id]
        if f then
            local k = mult(m)
            if isTavern and f.tavernSpell then E.withElementalAura(p,m,f.tavernSpell,g,p,m,k,id) end
            if f.anySpell then E.withElementalAura(p,m,f.anySpell,g,p,m,k,spells[id]) end
        end
    end
end

function E.castGeneratedSpell(g, p, id)
    local s = spells[id]
    if not s or not s.cast(g, p) then return false end
    castTrigger(g, p, id)
    return true
end

function E.castSpellOnBoard(g,p,id,m)
    local s = spells[id]
    local i = indexOf(p.board,m)
    if not i or not s or not s.cast(g,p,m,{zone="board",index=i}) then return false end
    castTrigger(g,p,id)
    E.s15ObserveKeywords(g, p)
    E.afterTargetedSpell(g,p,m,{id=id})
    return true
end

function E.recastTrinketSpell(g,p,entry,m)
    local s=spells[entry.id]
    local i=indexOf(p.board,m)
    if not s or not s.target or not i then return false end
    p.locketCasting=true
    local checked,ok=pcall(s.cast,g,p,m,{zone="board",index=i},entry)
    if checked and ok then
        local triggers,sent=pcall(function() castTrigger(g,p,entry.id);E.afterTargetedSpell(g,p,m,entry) end)
        p.locketCasting=nil
        if not triggers then error(sent) end
        return true
    end
    p.locketCasting=nil
    if not checked then error(ok) end
    return false
end

function E.autoCast(g,p,id,preferred,entry)
    local spell=spells[id]
    if not spell then return false end
    if not spell.target then
        if not E.s15Cast(g, p, spell, nil, nil, entry) then return false end
        castTrigger(g, p, id, entry)
        E.s15ObserveKeywords(g, p)
        return true
    end
    local function attempt(zone,list,m)
        local i=indexOf(list,m)
        if not i or not E.s15Cast(g, p, spell, m, {zone=zone,index=i}, entry) then return false end
        castTrigger(g, p, id, entry)
        E.afterTargetedSpell(g, p, m, entry or {id=id})
        E.s15ObserveKeywords(g, p)
        return true
    end
    if preferred and attempt("board",p.board,preferred) then return true end
    local targets={}
    for _,m in ipairs(p.board) do if m~=preferred then targets[#targets+1]={zone="board",m=m,list=p.board} end end
    if spell.target=="any" then
        for _,m in ipairs(p.tavern) do targets[#targets+1]={zone="tavern",m=m,list=p.tavern} end
    end
    shuffle(g,targets)
    for _,item in ipairs(targets) do if attempt(item.zone,item.list,item.m) then return true end end
    return false
end

function E.castRandomTavern(g,p,m,excluded)
    local id=drawSpell(g,6,false,excluded)
    return id and E.autoCast(g,p,id,m)
end

function E.recordCombatSpell(g,p,id,board)
    local original=p.board
    p.board=board
    local ok,reason=pcall(castTrigger,g,p,id)
    p.board=original
    if not ok then error(reason) end
    E.updateBruisers(p)
end

function E.castTavernSpell(g, color, i, target)
    local p = g.players[color]
    local ok, err = canAct(g, p); if not ok then return false, err end
    local entry = p.spellHand[i]
    local s = entry and spells[entry.id]
    if not s then return false, "There is no Tavern spell in that slot." end
    local m
    if s.target then
        local list = target and (target.zone == "board" and p.board or (s.target == "any" and target.zone == "tavern" and p.tavern))
        m = list and list[target.index]
        if not m then return false, "Drop the spell onto " .. (s.target == "board" and "a friendly minion." or "a minion.") end
    end
    local casts, castEntry, lurkerCount = 1, entry, nil
    if m and target.zone == "board" then
        for _, caster in ipairs(p.board) do
            if caster.id == "BG35_883" then casts = math.max(casts, 1 + mult(caster)) end
        end
        if m.id == "BG23_009" and s.spellcraft then
            local used = m.lurkerTurn == g.turn and (m.lurkerCasts or 0) or 0
            if used < mult(m) then
                castEntry = copyTable(entry)
                castEntry.permanent = true
                lurkerCount = used + 1
            end
        end
    end
    if not s.spellcraft and s.id~="BG20_GEM" then casts=casts+(p.extraSpellCasts or 0) end
    if s.id=="BG20_GEM" then casts=casts+E.gemCasts(p)-1 end
    if s.id:match("^BG33_81[1-5]$") then
        for _, pirate in ipairs(p.board) do
            if pirate.id == "BG33_825" then casts = math.max(casts, 1 + mult(pirate)) end
        end
    end
    table.remove(p.spellHand, i)
    ok, err = E.s15Cast(g, p, s, m, target, castEntry)
    if not ok then table.insert(p.spellHand, i, entry); return false, err or "That spell has no valid target." end
    if lurkerCount then m.lurkerTurn, m.lurkerCasts = g.turn, lurkerCount end
    castTrigger(g,p,s.id,entry)
    if m then E.afterTargetedSpell(g, p, m, entry) end
    for _ = 2, casts do
        if m and not indexOf(p.board, m) then break end
        if not E.s15Cast(g, p, s, m, target, castEntry) then break end
        castTrigger(g,p,s.id,entry)
        if m then E.afterTargetedSpell(g, p, m, entry) end
    end
    E.s15ObserveKeywords(g, p)
    hooks(g,p,"castFromHand",entry.id)
    E.discardPartner(g, p, entry)
    hooks(g,p,"cardPlayed",entry)
    E.giftAfterPlay(p)
    E.cardPlayed(g,p)
    event(g,color,"card_play",nil)
    checkTriples(g, p)
    return true
end

local function stats(a, h, taunt)
    return function(_, p, m)
        buffSpell(p, m, a, h)
        if taunt then m.taunt = not m.taunt or taunt == "add" end
        return true
    end
end

local function gold(n)
    return function(_, p) p.gold = math.min(99, p.gold + n); return true end
end

local function team(a, h)
    return function(_, p) buffAll(p, p.board, a, h); return true end
end

local function shop(a, h, forever)
    return function(_, p)
        if forever then
            local prior = p.tavBuff.all or {0, 0}
            local boostedA, boostedH = E.spellAmount(p, a, h)
            p.tavBuff.all = {prior[1] + boostedA, prior[2] + boostedH}
        end
        buffAll(p, p.tavern, a, h)
        return true
    end
end

local function exact(tier)
    return function(c) return c.tier == tier end
end

local function giveMinion(g, p, low, high, filter)
    local m = drawFromPool(g, high, low, filter)
    if not m then return false, "No eligible minion remains in the pool." end
    if addToHand(g, p, m) then return true end
    returnToPool(g, m)
    return false, "Your hand is full."
end

local function discover(g, p, tier, filter, label)
    if startDiscover(g, p, tier, filter, label) then return true end
    return false, "No eligible Discover options remain in the pool."
end

local function sameType(a, b)
    local c = card(a.id)
    for _, race in ipairs(c.races) do if hasRace(b, race) then return true end end
    return c.all and (#(card(b.id).races) > 0 or card(b.id).all)
end

local function commonType(p)
    local tally, best, count = {}, nil, 0
    for _, m in ipairs(p.board) do
        for _, r in ipairs(card(m.id).races) do tally[r] = (tally[r] or 0) + 1 end
    end
    for r, n in pairs(tally) do
        if n > count or (n == count and r < best) then best, count = r, n end
    end
    return best and function(c) return c.all or indexOf(c.races, best) ~= nil end or nil
end

local function four(a, h)
    return function(g, p)
        local list = {}
        for i, m in ipairs(p.board) do list[i] = m end
        shuffle(g, list)
        for i = 1, math.min(4, #list) do buffSpell(p, list[i], a, h) end
        return true
    end
end

local function golden(m)
    if not m or m.golden then return false, "Choose a non-Golden minion." end
    local c = card(m.id)
    m.golden = true
    buff(m, c.gatk - c.atk, c.ghp - c.hp)
    return true
end

local function consume(num, keywords)
    return function(g, p, m)
        if not hasRace(m, "DEMON") then return false, "Choose a friendly Demon." end
        if #p.tavern == 0 then return false, "The Tavern has no minions to consume." end
        for _ = 1, math.min(num, #p.tavern) do
            local victim = table.remove(p.tavern, rnd(g, #p.tavern))
            buff(m, victim.atk, victim.hp)
            if keywords then for _, keyword in ipairs(KEYWORDS) do if victim[keyword] then m[keyword] = true end end end
            E.observeConsumption(g,p,victim)
            returnToPool(g,victim)
        end
        return true
    end
end

