spell("EBG_Spell_038", "any", function(g, p, m)
    local nextShop = {}
    for _ = 1, tavernSize(p) do
        local t = drawFromPool(g, p.tier, 1, function(c) return sameType(m, {id = c.id}) end)
        if t then nextShop[#nextShop + 1] = t end
    end
    if #nextShop == 0 then return false, "No minions of that type are available." end
    clearTavern(g, p)
    p.tavern, p.frozen = nextShop, false
    for _, t in ipairs(p.tavern) do E.applyTavernBuff(p, t) end
    E.rollSpellShop(g, p)
    return true
end)
