modes.BG31_893 = {function(_, p) p.gemA = p.gemA + 1; return true end,
    function(_, p) p.gemH = p.gemH + 1; return true end}
do
    local sources = {}
    local function register(source, id, name, target, cast)
        sources[source] = id
        metadata[id] = {name = name, tier = 1, cost = 0, generated = true, spellcraft = true,
            text = card(source).text}
        spell(id, target, cast)
        local c = card(source)
        c.fx, c.note = "full", nil
        if FX[source] then FX[source].endTurn = nil end
    end
    local function amount(entry) return entry and entry.craftPower or 1 end
    local function enhanced(entry, m, a, h, keyword)
        if entry and entry.permanent then
            buff(m, a, h)
            if keyword then
                m[keyword] = true
                local temporary = m.tKw and indexOf(m.tKw, keyword)
                if temporary then table.remove(m.tKw, temporary) end
            end
        else
            tempBuff(m, a, h, keyword)
        end
    end
    local function stats(a, h, keyword, tribe)
        return function(_, _, m, _, entry)
            local k = amount(entry)
            enhanced(entry, m, a * k, h * k, (not tribe or hasRace(m, tribe)) and keyword or nil)
            return true
        end
    end
    register("BG23_000", "BG23_000t", "Mini-Trident", "any", stats(2, 0))
    register("BG23_004", "BG23_004t", "Angler's Lure", "any", stats(2, 6, "taunt"))
    register("BG23_007", "BG23_007t", "Undersea Mount", "any", stats(2, 2, "windfury", "NAGA"))
    register("BG23_008", "BG23_008t", "Glowing Crown", "any", stats(0, 0, "shield"))
    register("BG26_171", "BG26_171t", "Just Keep Swimming", "any", stats(3, 4, "stealth"))
    register("BG31_830", "BG31_830t", "Reinvigoration", "any", stats(2, 2, "reborn", "NAGA"))
    register("BG26_501", "BG26_501t", "Sick Riffs", "any", function(_, p, m, _, e)
        local n = p.tier * amount(e); enhanced(e, m, n, n); return true
    end)
    register("BG26_502", "BG26_502t", "Deep Blues", "any", function(_, p, m, _, e)
        local n = (2 + (p.blues or 0)) * amount(e)
        enhanced(e, m, n, n); p.blues = (p.blues or 0) + amount(e); return true
    end)
    register("BG31_924", "BG31_924t", "Thaumaturgy", "any", function(_, p, m, _, e)
        local n = (1 + math.floor((p.spellsCast or 0) / 3)) * amount(e)
        enhanced(e, m, n, n); return true
    end)
    register("BG32_835", "BG32_835t", "Meditation", nil, function(_, p, _, _, e)
        local k = amount(e)
        p.bonusSpellAtk, p.bonusSpellHp = (p.bonusSpellAtk or 0) + k, (p.bonusSpellHp or 0) + k
        return true
    end)
    register("BG23_015", "BG23_015t", "Azshara's Hatchery", nil, function(g, p, _, _, e)
        local found = false
        for _ = 1, amount(e) do
            found = startDiscover(g, p, p.tier, function(c) return c.all or indexOf(c.races, "NAGA") end,
                "Discover a Naga", nil, e and e.craftSource or "BG23_015") or found
        end
        return found, "No eligible Naga remain."
    end)
    register("BG28_405", "BG28_405t", "Sunken Spells", nil, function(g, p, _, _, e)
        local found = false
        for _ = 1, amount(e) do found = E.discoverSpell(g, p, p.tier, false) or found end
        return found, "No eligible Tavern spells remain."
    end)

    register("BG27_514", "BG27_514t", "Siren's Song", "any", function(g,p,m,target,entry)
        if not target or target.zone ~= "tavern" or m.id == "BG27_514" then
            return false,"Choose a different minion in the Tavern."
        end
        local added = false
        for _=1,amount(entry) do
            if E.handCount(p) >= E.MAX_HAND then break end
            local copy = copyTable(m)
            g.uid = g.uid+1
            copy.uid,copy.generated = g.uid,true
            added = addToHand(g,p,copy) or added
        end
        return added,"Your hand is full."
    end)
    metadata.BG27_514t.onlyTavern = true
    register("BG31_920", "BG31_920t", "Evolving Strategy", nil, function(g,p,_,_,entry)
        local tier = (entry and entry.craftTier) or 1
        local found = false
        for _=1,amount(entry) do
            if E.handCount(p) >= E.MAX_HAND then break end
            local reward = drawFromPool(g,tier,tier,function(c)
                return c.id ~= "BG31_920" and (c.all or indexOf(c.races,"NAGA"))
            end)
            if not reward then break end
            found = addToHand(g,p,reward) or found
        end
        return found,"No eligible Naga remain."
    end)
    register("BG33_319", "BG33_319t", "Rime or Reason", nil, function(g,p,_,_,entry)
        local found = false
        for _=1,amount(entry) do
            found = E.getRandomSpell(g,p,6,false,function(s)
                return s.text:find("%+%d+/") or s.text:find("%+%d+ Attack") or s.text:find("%+%d+ Health")
                    or s.id=="BG28_607" or s.id=="BG28_838" or s.id=="BG34_889" or s.id=="BG36_880" or s.id=="EBG_Spell_032"
            end) or found
        end
        return found,"No qualifying Tavern spells remain."
    end)

    function E.copySpellcraft(g, p, m)
        local id = sources[m.id]
        if not id or not E.giveSpell(g, p, id) then return false end
        local spellEntry = p.spellHand[#p.spellHand]
        spellEntry.expireTurn, spellEntry.craftPower = g.turn, mult(m)
        spellEntry.craftSource, spellEntry.permanent = m.id, m.permanentCraft
        if m.id == "BG31_920" then spellEntry.craftTier = math.min(g.maxTier or 6,1+(m.age or 0)) end
        return true
    end

    function E.grantSpellcraft(g, p, m)
        if m.lastCraft ~= g.turn and E.copySpellcraft(g, p, m) then m.lastCraft = g.turn end
    end

    E.trinketTableware="BG34_272"
    if not E.SPELLS[E.trinketTableware] then
        metadata[E.trinketTableware]={name="Menagerie Tableware",tier=7,cost=4,generated=true,tavern=true}
        spell(E.trinketTableware,nil,function(g,p)
            local seen,n={},1
            for _,m in ipairs(p.board) do
                for _,r in ipairs(card(m.id).races) do if not seen[r] then seen[r]=true;n=n+1 end end
            end
            for _=1,n do
                for _,m in ipairs(p.board) do buffSpell(p,m,3,3) end
            end
            return true
        end)
    end

    metadata.BG36_MagicItem_208t={name="Floating Candle Set",tier=1,cost=0,generated=true,spellcraft=true,
        text="Trigger a friendly minion's Deathrattle."}
    spell("BG36_MagicItem_208t","board",function(g,p,m)
        E.trinketDeathrattle(g,p,m)
        return true
    end)

    metadata.BG36_MagicItem_417t={name="Makeshift Master",tier=1,cost=0,generated=true,spellcraft=true,
        text="After this gains stats outside combat this turn, your Deity also gains them."}
    spell("BG36_MagicItem_417t","board",function(g,p,m)
        E.deityConduits[m],m.deityConduitTurn=p,g.turn
        return true
    end)

    metadata.BG27_002t={name="Slimy Shield",tier=2,cost=0,generated=true,text="Give a minion +1/+1 and Taunt."}
    spell("BG27_002t","any",function(_,p,m)
        buffSpell(p,m,1,1);m.taunt=true;return true
    end)
    metadata.BG35_149={name="Deepwater Clan",tier=3,cost=2,generated=true,tavern=true,
        text="Give a minion +2/+2. Give your Murlocs +2/+2."}
    spell("BG35_149","any",function(_,p,target)
        if not target then return false end
        buffSpell(p,target,2,2)
        buffAll(p,p.board,2,2,function(m) return hasRace(m,"MURLOC") end)
        return true
    end)

