register("BG34_Giant_035","BG34_Giant_035t","Timewarped Crown","any",function(_,_,m)
    m.shield=true
    return true
end)
register("BG34_Giant_210","BG34_Giant_210t","Timewarped Shoal","any",function(_,p,m,_,entry)
    local n=0
    for _,t in ipairs(p.board) do if hasRace(t,"NAGA") then n=n+1 end end
    buffSpell(p,m,2*n*amount(entry),2*n*amount(entry))
    return true
end)
register("BG34_Giant_212","BG34_Giant_212t","Timewarped Eelectrify","any",function(_,p,m,_,entry)
    buffSpell(p,m,12*amount(entry),0)
    return true
end)
register("BG34_Giant_324","BG34_Giant_324t","Timewarped Summoning","any",function(g,p,m)
    for i,t in ipairs(p.tavern) do
        local tier=t.cardTier or card(t.id).tier
        local replacement=drawFromPool(g,tier,tier,function(c) return sameType(m,{id=c.id}) end)
        if replacement then
            returnToPool(g,t)
            p.tavern[i]=replacement
            E.applyTavernBuff(p,replacement)
            E.updateCardAuras(p,replacement)
        end
    end
    return true
end)

do
    for key,hero in pairs({
        ["003"]="TB_BaconShop_HERO_76",["005"]="TB_BaconShop_HERO_42",["006"]="TB_BaconShop_HERO_15",
        ["008"]="TB_BaconShop_HERO_23",["009"]="BG25_HERO_103",["010"]="TB_BaconShop_HERO_22",
        ["012"]="TB_BaconShop_HERO_91",["015"]="BG20_HERO_242",["016"]="TB_BaconShop_HERO_55",
        ["017"]="BG23_HERO_306",["018"]="BG22_HERO_000",["022"]="TB_BaconShop_HERO_75",
    }) do
        local id=hero
        local spellId="BG34_HeroPowerSpell_"..key
        BG_TIMEWARP[spellId].heroPower=id
        spell(spellId,nil,function(g,p)
            if E.hasPower(p,id) or not E.HP[id] then return false,"You already have this power." end
            p.secondPowerHero,p.secondPowerUses=id,0
            if E.HP[id].startTurn then E.HP[id].startTurn(g,p) end
            return true
        end)
    end
    metadata.TB_BaconShop_Triples_01={name="Triple Reward",tier=1,cost=0,generated=true,
        text="Discover a minion from a Tavern Tier higher than yours."}
    spell("TB_BaconShop_Triples_01",nil,function(g,p)
        local tier=math.min(p.maxTier or 6,p.tier+1)
        return startDiscover(g,p,tier,exact(tier),"Triple Reward · Tier "..tier)
    end)
    function E.discoverTriple(g,p) return E.giveSpell(g,p,"TB_BaconShop_Triples_01") end
    if not E.SPELLS.BG28_606 then
        metadata.BG28_606={name="Spitescale Special",tier=5,cost=2,generated=true,tavern=true,
            text="Get 3 random Spellcraft spells."}
        spell("BG28_606",nil,function(g,p)
            for _=1,3 do E.randomSpellcraft(g,p,true) end
            return true
        end)
    end
    local function ongoing(id, reward)
        spell(id,nil,function(g,p)
            p.timewarpRewards=p.timewarpRewards or {}
            p.timewarpRewards[reward]=(p.timewarpRewards[reward] or 0)+1
            E.giveSpell(g,p,reward)
            return true
        end)
    end
    local function copyOnBoard(g,p,m)
        if #p.board>=E.MAX_BOARD then return false,"Your warband is full." end
        g.uid=g.uid+1
        local other=copyTable(m)
        other.uid,other.generated,other.poolCopies,other.magneticCopies=g.uid,true,nil,nil
        E.shopSummon(g,p,other,(indexOf(p.board,m) or #p.board)+1)
        return true
    end
    local function currentDiscover(g,p,n,tier,filter,label)
        local success=false
        for _=1,n do
            if not startDiscover(g,p,tier,filter,label) then break end
            success=true
        end
        return success
    end
    spell("BG34_Treasure_300",nil,function(_,p)
        p.nextChronum=(p.nextChronum or 0)+1
        return true
    end)
    spell("BG34_Treasure_301",nil,function(g,p)
        return E.discoverTimewarp(g,p,5,1,nil,g.turn+1)
    end)
    spell("BG34_Treasure_302","board",copyOnBoard)
    spell("BG34_Treasure_607",nil,function(g,p)
        for t=1,3 do giveMinion(g,p,t,t) end
        return true
    end)
    ongoing("BG34_Treasure_608","BG28_168")
    ongoing("BG34_Treasure_609","BG28_512")
    ongoing("BG34_Treasure_900","BG30_804")
    spell("BG34_Treasure_902",nil,function(g,p) return E.discoverLastWarband(g,p,true) end)
    spell("BG34_Treasure_966",nil,function(g,p) return E.discoverLastWarband(g,p,false) end)
    spell("BG34_Treasure_620",nil,function(_,p)
        p.timewarpApples=(p.timewarpApples or 0)+1
        return true
    end)
    spell("BG34_Treasure_903",nil,function(g,p)
        return currentDiscover(g,p,3,p.tier,exact(p.tier),"Discover a minion of your Tier")
    end)
    spell("BG34_Treasure_905","any",function(_,p,m)
        buffSpell(p,m,2,2)
        buff(m,m.atk,m.hp)
        return true
    end)
    spell("BG34_Treasure_912",nil,function(g,p)
        while E.giveSpell(g,p,"BG28_897") do end
        p.bonusSpellAtk,p.bonusSpellHp=(p.bonusSpellAtk or 0)+3,(p.bonusSpellHp or 0)+3
        return true
    end)
    spell("BG34_Treasure_917",nil,function(_,p)
        p.timewarpRecruit=true
        return shop(2,2,true)(nil,p)
    end)
    spell("BG34_Treasure_919",nil,function(g,p)
        return E.discoverTierSeven(g,p,2,false)
    end)
    spell("BG34_Treasure_625",nil,function(g,p)
        return E.discoverTierSeven(g,p,1,true)
    end)
    spell("BG34_Treasure_932",nil,function(_,p)
        p.extraMaxGold,p.maxGold=(p.extraMaxGold or 0)+4,p.maxGold+4
        p.gold=math.min(99,p.gold+4)
        return true
    end)
    spell("BG34_Treasure_933","any",function(g,p,m,zone)
        if not startDiscover(g,p,6,exact(6),"Discover a Tier 6 form") then return false end
        local d=p.discoverQueue[#p.discoverQueue] or p.discover
        d.transformTimewarp={uid=m.uid,zone=zone.zone,fixedStats=30}
        return true
    end)
    spell("BG34_Treasure_934",nil,function(_,p) p.armor=p.armor+10;return true end)
    spell("BG34_Treasure_937",nil,function(g,p)
        if not startDiscover(g,p,math.max(g.maxTier or 6,6),function(c) return c.tier>=5 and c.deathrattle end,
            "Discover a Deathrattle minion with Reborn") then return false end
        local d=p.discoverQueue[#p.discoverQueue] or p.discover
        d.timewarpReborn=true
        return true
    end)
    spell("BG34_Treasure_940","any",function(g,p,m)
        for i=4,6 do
            giveMinion(g,p,i,i,function(c)
                return c.id~=m.id and (c.all or sameType({id=c.id},m))
            end)
        end
        return true
    end)
    spell("BG34_Treasure_950",nil,function(g,p)
        while E.handCount(p)<E.MAX_HAND and E.randomSpellcraft(g,p,false) do end
        return true
    end)
    spell("BG34_Treasure_951","board",function(g,p,m)
        if not hasRace(m,"MURLOC") then return false,"Choose a friendly Murloc." end
        return copyOnBoard(g,p,m)
    end)
    spell("BG34_Treasure_953",nil,function(g,p)
        local first=E.discoverTimewarp(g,p,3,1,"minion")
        local second=E.discoverTimewarp(g,p,3,2,"minion")
        return first or second
    end)
    spell("BG34_Treasure_955","any",function(_,p,m)
        if m.golden then return false,"That minion is already Golden." end
        makeGolden(m)
        E.updateCardAuras(p,m)
        return true
    end)
end

do
    local function prize(id, tier, target, effect)
        local key="BGS_Treasures_"..id
        spell(key,target,effect)
        local list=E.darkmoonPrizes[tier] or {}
        E.darkmoonPrizes[tier]=list
        list[#list+1]=key
    end
    E.darkmoonPrizes={}
    function E.discoverDarkmoon(g,p,tier)
        local ids=copyTable(E.darkmoonPrizes[math.max(1,math.min(tier,4))] or {})
        shuffle(g,ids)
        if #ids==0 then return false end
        local options={}
        for i=1,math.min(3,#ids) do options[i]=ids[i] end
        enqueue(p,{kind="spell",label="Discover a Darkmoon Prize",options=options})
        return true
    end
    local function discoverLastOpponent(g,p)
        local options,seen={},{}
        for _,m in ipairs(p.lastOpponentBoard or {}) do
            if not seen[m.id] then options[#options+1]=m.id;seen[m.id]=true end
        end
        shuffle(g,options)
        while #options>3 do table.remove(options) end
        return E.offerMinionChoice(g,p,options,"Discover from your last opponent")
    end
    local function goldNext(target)
        if target.golden then return false,"Choose a non-Golden minion." end
        makeGolden(target)
        return true
    end
    local function backToHand(g,p,m)
        local i=indexOf(p.board,m)
        if not i or E.handCount(p)>=E.MAX_HAND then return false,"You need room in your hand." end
        table.remove(p.board,i)
        return addToHand(g,p,m)
    end
    prize("004",1,nil,function(g,p) return startDiscover(g,p,1,exact(1),"Discover a Tier 1 minion") end)
    prize("013",1,nil,shop(1,1,true))
    prize("029",1,nil,function(_,p) p.roundRefresh=(p.roundRefresh or 0)+1;return true end)
    prize("033",1,nil,function(g,p)
        p.darkmoonExtra=(p.darkmoonExtra or 0)+1
        E.darkmoonStock(g,p,1)
        return true
    end)
    prize("040",1,nil,function(g,p) for _=1,2 do E.giveSpell(g,p,"BG28_897") end;return true end)
    prize("100",1,nil,function(g,p) return E.getRandomSpell(g,p,6,false,function(s) return s.cost>=2 end) end)
    prize("110",1,nil,function(_,p)
        p.bonusSpellAtk,p.bonusSpellHp=(p.bonusSpellAtk or 0)+1,(p.bonusSpellHp or 0)+1
        return true
    end)
    prize("006",2,nil,function(g,p)
        for i,m in ipairs(p.tavern) do
            local tier=math.min(g.maxTier or 6,(m.cardTier or card(m.id).tier)+1)
            local x=drawFromPool(g,tier,tier)
            if x then returnToPool(g,m);p.tavern[i]=x;E.applyTavernBuff(p,x) end
        end
        E.raiseTavernSpells(g,p,1)
        return true
    end)
    prize("009",2,"board",function(_,_,m) m.darkmoonGruul=(m.darkmoonGruul or 0)+4;return true end)
    prize("010",2,nil,discoverLastOpponent)
    prize("012",2,nil,function(g,p) return startDiscover(g,p,p.tier,exact(p.tier),"Discover a minion of your Tier") end)
    prize("014",2,nil,function(_,p)
        p.gold=math.min(99,p.gold+1)
        p.darkmoonReturnCoin=(p.darkmoonReturnCoin or 0)+1
        return true
    end)
    prize("018",2,"any",function(_,p,m) buffSpell(p,m,2,0);buff(m,m.atk,0);return true end)
    prize("026",2,"board",function(_,_,m) m.taunt=true;buff(m,0,m.hp);return true end)
    prize("030",2,nil,function(g,p)
        if p.prizeBrannTurn~=g.turn then p.prizeBrannTurn,p.prizeBrannCount=g.turn,0 end
        p.prizeBrannCount=p.prizeBrannCount+1
        return true
    end)
    prize("101",2,nil,function(g,p) return E.discoverSpell(g,p,p.tier,true) end)
    prize("011",3,nil,function(g,p) return E.discoverHeroPower(g,p,1) end)
