    -- Quest Reward spells (Enhance-a-matic parts, Spellcraft rewards, Accelerator, Coin Pouch).
    local QUEST_SPELL_ART = BG_QUEST_ART_BASE .. "cards/"
    local function questSpell(id, art, data, target, cast)
        data.tier, data.cost, data.generated = data.tier or 1, data.cost or 0, true
        data.timewarpArt = QUEST_SPELL_ART .. art .. ".png"
        metadata[id] = data
        spell(id, target, cast)
    end
    for i, kw in ipairs({"taunt", "windfury", "shield", "reborn"}) do
        local id = "BG24_Reward_715t" .. (i == 1 and "" or tostring(i))
        local names = {"Mega Horn", "Blazing Blades", "Bunker Plating", "Death Rewinder"}
        local words = {"Taunt", "Windfury", "Divine Shield", "Reborn"}
        questSpell(id, "BG24_Reward_715", {name = names[i], text = "Give a minion +5/+5 and " .. words[i] .. "."}, "board",
            function(g, p, m) buff(m, 5, 5); m[kw] = true; return true end)
    end
    questSpell("BG24_Reward_718t", "BG24_Reward_718", {name = "Kidnap Sack", spellcraft = true,
        text = "Choose a non-Golden minion in the Tavern. Move it to your hand."}, "any",
        function(g, p, m, target)
            if not target or target.zone ~= "tavern" or m.golden then return false, "Drop Kidnap Sack on a non-Golden minion in the Tavern." end
            if E.handCount(p) >= E.MAX_HAND then return false, "Your hand is full." end
            local i = indexOf(p.tavern, m)
            if not i then return false end
            table.remove(p.tavern, i)
            E.addToHand(g, p, m)
            return true
        end)
    questSpell("BG24_Reward_719t", "BG24_Reward_719", {name = "The Golden Hammer", spellcraft = true,
        text = "Make a friendly minion Golden until next turn."}, "board",
        function(g, p, m)
            if m.golden then return false, "That minion is already Golden." end
            E.makeGolden(m)
            m.hammerUntil = g.turn + 1
            return true
        end)
    questSpell("BG27_Reward_504t", "BG27_Reward_504", {name = "Accelerator",
        text = "Transform a minion into one from a Tier higher."}, "board",
        function(g, p, m)
            local i = indexOf(p.board, m)
            local tier = math.min(7, (card(m.id).tier or 1) + 1)
            local new = E.drawFromPool(g, tier, tier)
            if not new or not i then return false, "No minion of the next Tier is available." end
            returnToPool(g, m)
            new.uid = m.uid
            p.board[i] = new
            return true
        end)
    questSpell("BG33_Reward_006t", "BG33_Reward_006", {name = "Rushing Winds", spellcraft = true,
        text = "Give a minion Windfury and Divine Shield until next turn."}, "board",
        function(g, p, m) E.tempBuff(m, 0, 0, "windfury"); E.tempBuff(m, 0, 0, "shield"); return true end)
    questSpell("BG33_Reward_012t", "BG33_Reward_012", {name = "Coin Pouch", text = "Gain 5 Gold."}, nil,
        function(g, p) p.gold = math.min(99, p.gold + 5); return true end)


    function E.spellcraftTavern(g, p)
        for _, m in ipairs(p.board) do
            local f = FX[m.id]
            if f and f.spellcraftOffer then f.spellcraftOffer(g, p, mult(m)) end
        end
    end

    function E.randomSpellcraft(g, p, permanent)
        local ids = {}
        for _, id in pairs(sources) do ids[#ids + 1] = id end
        table.sort(ids)
        if not E.giveSpell(g, p, pick(g, ids)) then return false end
        if not permanent then p.spellHand[#p.spellHand].expireTurn = g.turn end
        return true
    end

    function E.expireSpellcraft(g, p)
        for i = #p.spellHand, 1, -1 do
            local expires = p.spellHand[i].expireTurn
            if expires and expires <= g.turn then table.remove(p.spellHand, i) end
        end
    end
end

