table.sort(ordered)

function E.spellRefresh(g,p)
    for _,m in ipairs(p.board) do
        local f=FX[m.id]
        if f and f.refresh then f.refresh(g,p,m,mult(m)) end
    end
    for _=1,p.timewarpApples or 0 do E.castGeneratedSpell(g,p,"BG28_966") end
    if p.gemShop then for _,m in ipairs(p.tavern) do E.applyGems(g,p,m,p.gemShop) end end
    for _ = 1, p.spellEast or 0 do local m = pick(g, p.tavern); if m then buffSpell(p, m, 9, 9) end end
end

function E.spellStartTurn(g, p)
    if p.timewarpRewards then
        local ids={}
        for id in pairs(p.timewarpRewards) do ids[#ids+1]=id end
        table.sort(ids)
        for _,id in ipairs(ids) do
            for _=1,p.timewarpRewards[id] do if not E.giveSpell(g,p,id) then break end end
        end
    end
    for _ = 1, p.timeManagement or 0 do for _ = 1, 2 do buffAll(p, p.board, 2, 2) end end
    p.timeManagement = nil
    if p.breadNext then
        for _, m in ipairs(p.board) do
            for _ = 1, p.breadNext[tostring(m.uid)] or 0 do buffSpell(p, m, 4, 6) end
        end
    end
    p.breadNext = nil
    if p.hero == "TB_BaconShop_HERO_75" then p.spellAtk, p.spellHp = 1 + math.floor(g.turn / 3), 1 + math.floor(g.turn / 3) end
end

function E.spellBattle(g, p, won, tied)
    p.nextGold = p.nextGold + (p.overconfidence or 0) * (won and 3 or (tied and 1 or 0))
    p.overconfidence = nil
    p.breadNext, p.winnerBread = won and p.winnerBread or nil, nil
end

function E.spellStartCombat(C, S, other)
    local p = ownerOf(C, S)
    if not p then return end
    if S.list[1] then S.list[1].atk = S.list[1].atk * (2 ^ (p.brood or 0)) end
    for _ = 1, p.upperHand or 0 do local m = pick(C.g, other.list); if m then m.hp = 1 end end
    S.beetleSpells = p.beetleSpells
    p.brood, p.upperHand, p.beetleSpells = nil, nil, nil
end

function E.spellSummons(C, S)
    while (S.beetleSpells or 0) > 0 and #S.list < E.MAX_BOARD do
        local beetle = C_.summon(C, S, "BG28_603t", false)
        if not beetle then break end
        beetle.atk, beetle.hp, beetle.taunt = math.max(2, beetle.atk), math.max(2, beetle.hp), true
        S.beetleSpells = S.beetleSpells - 1
    end
end

local function finishBotChoices(g, p)
    for _ = 1, 12 do
        local d = p.discover
        if not d then break end
        local chosen = E.discoverPick(g, p.color, 1)
        if not chosen then chosen = E.discoverPick(g, p.color, 2) end
        if not chosen then p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue, 1) or nil end
    end
end

function E.botSpells(g, p)
    if p.offer and not E.offerPick(g, p.color) then p.offer = nil end
    finishBotChoices(g, p)
    if #p.spellShop > 0 and (p.gold < E.buyCost(p) or #p.board == E.MAX_BOARD) then
        E.buyTavernSpell(g, p.color, 1)
    end
    for i = #p.spellHand, 1, -1 do
        local entry = p.spellHand[i]
        local s = entry and spells[entry.id]
        local target
        if s and s.target then
            local best = -1
            local zone = s.onlyTavern and "tavern" or "board"
            for j, m in ipairs(s.onlyTavern and p.tavern or p.board) do
                if (not s.onlyTavern or m.id ~= "BG27_514") and score(m) > best then
                    target, best = {zone = zone, index = j}, score(m)
                end
            end
        end
        E.castTavernSpell(g, p.color, i, target)
        finishBotChoices(g, p)
    end
end

FX.BG28_550 = {bc = function(g, p, _, k) for _ = 1, k do E.discoverSpell(g, p, p.tier) end end}
FX.BG31_330 = {bc = function(_, p, _, k) p.spellDiscount = (p.spellDiscount or 0) + k end}
FX.BG27_005 = {tavernSpell = function(_, p, _, k) buffAll(p, p.board, k, 0) end}
FX.BG28_707 = {tavernSpell = function(_, p, _, k)
    local prior = p.tavBuff.ELEMENTAL or {0, 0}
    p.tavBuff.ELEMENTAL = {prior[1] + 3 * k, prior[2] + 3 * k}
    for _, m in ipairs(p.tavern) do if hasRace(m, "ELEMENTAL") then buff(m, 3 * k, 3 * k) end end
end}
do
    local choices = {}

    local function getSpells(g, p, id, count)
        for _ = 1, count do if not E.giveSpell(g, p, id) then break end end
    end

    local function register(id, labels, a, b, targetRace)
        choices[id] = {labels = labels, effects = {a, b}, targetRace = targetRace}
        FX[id] = FX[id] or {}
        FX[id].bc = nil
        local c = card(id)
        c.fx, c.note = "full", nil
    end

    register("BG27_084", {"Give a Beast +1/+1 and Reborn", "Give a Beast +4 Attack and Windfury"},
        function(_, _, _, k, target) buff(target, k, k); target.reborn = true end,
        function(_, _, _, k, target) buff(target, 4 * k, 0); target.windfury = true end, "BEAST")
    register("BG30_123", {"Improve your Blood Gems", "Get Blood Gems"},
        function(_, p, _, k) p.gemA, p.gemH = p.gemA + k, p.gemH + k end,
        function(g, p, _, k) getSpells(g, p, "BG20_GEM", 4 * k) end)
    register("BG31_320", {"Get Blood Gems", "Get Gem Day"},
        function(g, p, _, k) getSpells(g, p, "BG20_GEM", 2 * k) end,
        function(g, p, _, k) getSpells(g, p, "BG31_893", k) end)
    register("BG32_237", {"Improve your Tavern spell Attack", "Improve your Tavern spell Health"},
        function(g, p, _, k) p.bonusSpellAtk = (p.bonusSpellAtk or 0) + k * (g and g.season == "s15" and 2 or 1) end,
        function(g, p, _, k) p.bonusSpellHp = (p.bonusSpellHp or 0) + k * (g and g.season == "s15" and 2 or 1) end)
    register("BG36_330", {"Gain free Refreshes", "Get Blood Gems"},
        function(_, p, _, k) p.freeRefreshes = p.freeRefreshes + 2 * k end,
        function(g, p, _, k) getSpells(g, p, "BG20_GEM", 3 * k) end)
    register("BG36_332", {"Get a random Quilboar", "Increase your maximum Gold"},
        function(g, p, _, k)
            for _ = 1, k do
                if E.handCount(p) >= E.MAX_HAND then break end
                local m = drawFromPool(g, p.tier, 1, function(c) return c.all or indexOf(c.races, "QUILBOAR") end)
                if m then addToHand(g, p, m) end
            end
        end,
        function(_, p, _, k) p.extraMaxGold, p.maxGold = (p.extraMaxGold or 0) + k, p.maxGold + k end)
    register("BG36_341", {"Play Blood Gems on your warband", "Cast Blood Gem Barrage"},
        function(g,p,_,k) for _,m in ipairs(p.board) do E.applyGems(g,p,m,3*k) end end,
        function(g, p, _, k) for _ = 1, 3 * k do E.castGeneratedSpell(g, p, "BG34_689") end end)
    register("BG31_144", {"Gain Attack and Divine Shield", "Gain Health and Taunt"},
        function(_, _, m, k) if m then buff(m, 3 * k, 0); m.shield = true end end,
        function(_, _, m, k) if m then buff(m, 0, 3 * k); m.taunt = true end end)
    register("BG30_128", {"Double this minion's Attack", "Double this minion's Health"},
        function(_, _, m, k) if m then m.atk = m.atk * (k + 1) end end,
        function(_, _, m, k) if m then m.hp = m.hp * (k + 1) end end)

    FX.BG31_326 = {endTurn = function(g, p, _, k) getSpells(g, p, "BG31_893", k) end}
    FX.BG27_028 = {endTurn = function(g, p, _, k) getSpells(g, p, "BG20_GEM", k) end}
    FX.BG26_531 = {endTurn = function(g, p, m, k)
        getSpells(g, p, "BG20_GEM", 2 * k)
        E.applyGems(g,p,m,2*k)
    end}
    FX.BG29_029 = {endTurn = function(g, p, _, k)
        for _ = 1, k do
            if E.handCount(p) >= E.MAX_HAND then break end
            local m = drawFromPool(g, 6, 1, function(c) return c.all or indexOf(c.races, "MURLOC") end)
            if not m then break end
            addToHand(g, p, m)
        end
    end}
    FX.BG35_123 = {endTurn = function(g, p, _, k)
        if p.lastSpell then getSpells(g, p, p.lastSpell, k) end
    end}
    local function getRandomTavernSpells(g, p, count, filter)
        for _ = 1, count do
            if not E.getRandomSpell(g, p, 6, false, filter) then break end
        end
    end
    FX.BG36_764 = {endTurn = function(g, p, _, k)
        getRandomTavernSpells(g, p, 2 * k, function(s) return s.cost == 1 end)
    end}
    FX.BG28_595 = {endTurn = function(g, p, _, k) getRandomTavernSpells(g, p, 2 * k) end}
    FX.BG31_178 = {endTurn = function(g, p, _, k) getRandomTavernSpells(g, p, k) end}
    FX.BG20_101.onAttack = function(C, S, _, k)
        local p = ownerOf(C, S)
        if p then getSpells(C.g, p, "BG20_GEM", k) end
    end
    FX.BG36_331 = {onAttack = function(C, S, _, k)
        local p = ownerOf(C, S)
        if not p then return end
        for _ = 1, k do
            if E.handCount(p) >= E.MAX_HAND then break end
            local g, options = C.g, {}
            for id, count in pairs(g.pool) do
                if count > 0 and card(id).chooseOne then options[#options + 1] = id end
            end
            local rotation = E.seasonSpells[g.season]
            for id, spell in pairs(E.SPELLS) do
                local offered = rotation and rotation[id] or (not rotation and spell.pool)
                if offered and spell.text:find("Choose One", 1, true) then options[#options + 1] = id end
            end
            table.sort(options)
            local id = pick(g, options)
            if not id then break end
            if E.SPELLS[id] then
                E.giveSpell(g, p, id)
            else
                g.pool[id] = g.pool[id] - 1
                addToHand(g, p, E.newMinion(g, id, false))
            end
        end
    end}
    for _, id in ipairs({"BG31_326", "BG27_028", "BG26_531", "BG29_029", "BG35_123", "BG36_764", "BG28_595",
        "BG31_178", "BG20_101", "BG36_331"}) do
        card(id).fx, card(id).note = "full", nil
    end

    local function boardMinion(p, uid)
        for _, m in ipairs(p.board) do if m.uid == uid then return m end end
    end

    function E.startMinionChoice(g,p,m)
        local def=choices[m.id]
        if not def then return end
        if E.useCombinedChoice(g,p) then
            if not def.targetRace then
                for _,effect in ipairs(def.effects) do effect(g,p,m,mult(m)) end
                return
            end
            local options={}
            for _,target in ipairs(p.board) do if hasRace(target,def.targetRace) then options[#options+1]=target.uid end end
            if #options>0 then
                local d={kind="minion_target",label=card(m.id).name,minionId=m.id,uid=m.uid,mult=mult(m),mode="both",options=options}
                if p.discover then table.insert(p.discoverQueue,d) else p.discover=d end
            end
            return
        end
        local labels = {}
        for _, label in ipairs(def.labels) do labels[#labels + 1] = label end
        local selection = {kind = "minion_mode", label = card(m.id).name .. " · Choose One", minionId = m.id,
            uid = m.uid, mult = mult(m), options = labels}
        if p.discover then table.insert(p.discoverQueue, selection) else p.discover = selection end
    end

    function E.pickMinionChoice(g, p, index)
        local selection = p.discover
        local def = choices[selection.minionId]
        local value = selection.options[index]
        if not def or value == nil then return false, "No such option." end
        local source = boardMinion(p, selection.uid)
        local choice = selection.mode or index
        local target = selection.mode and boardMinion(p, value)
        if selection.mode and (not target or not hasRace(target, def.targetRace)) then
            return false, "That minion is no longer a valid target."
        end
        p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue, 1) or nil
        if def.targetRace and not target then
            local targets = {}
            for _, m in ipairs(p.board) do if hasRace(m, def.targetRace) then targets[#targets + 1] = m.uid end end
            if #targets == 0 then return true end
            if p.discover then table.insert(p.discoverQueue, 1, p.discover) end
            p.discover = {kind = "minion_target", label = "Choose a friendly " .. E.RACE_NAME[def.targetRace],
                minionId = selection.minionId, uid = selection.uid, mult = selection.mult, mode = choice, options = targets}
            return true
        end
        if choice=="both" then
            for _,effect in ipairs(def.effects) do effect(g,p,source,selection.mult or 1,target) end
        else
            def.effects[choice](g,p,source,selection.mult or 1,target)
        end
        checkTriples(g, p)
        return true
    end
end

do
