        gid="BGFYM_011_G", races={"ABERRATION"}, deity=true, fx="full", deathrattle=true,
        text="Deathrattle: Resummon the first two friendly Aberrations that died in this combat."}
    FX.BG26_147 = {startTurn = function(_, p, _, k) p.gold = p.gold + k end}
end

do
    function E.dispatchAttached(m, hook, invoke)
        for _, part in ipairs(m.attachments or {}) do
            local f = FX[part.id]
            if f and f[hook] then invoke(f[hook], part.golden and 2 or 1, part) end
        end
    end

    function E.canMagnetize(source, target)
        local def = source and card(source.id)
        if not target or not def or not def.magnetic then return false end
        return hasRace(target, "MECHANICAL")
            or source.id == "BG31_859" and hasRace(target, "ELEMENTAL")
            or source.id == "BG_DEEP_015" and hasRace(target, "UNDEAD")
    end

    local function attachParts(p, source, target, times)
        target.attachments = target.attachments or {}
        target.magnetizedCount = (target.magnetizedCount or #target.attachments) + times
        for _ = 1, times do
            buff(target, source.atk, source.hp)
            for _, kw in ipairs(KEYWORDS) do if source[kw] then target[kw] = true end end
            target.attachments[#target.attachments + 1] = {id=source.id,golden=source.golden,atk=source.atk,hp=source.hp}
            for _, part in ipairs(source.attachments or {}) do target.attachments[#target.attachments + 1] = part end
        end
        p.magnetizations = (p.magnetizations or 0) + times
        if source.id=="BG34_Giant_677" then
            local n=mult(source)
            buff(target,target.atk*n,target.hp*n)
        end
        if source.id=="BG34_Giant_121" or source.id=="BG31_HERO_802_Buddy" then makeGolden(target) end
        for _, m in ipairs(p.board) do
            if m.id == "BG31_177" then buff(target, 3 * mult(m), mult(m)) end
        end
    end

    function E.attachMagnetic(g, p, source, target, times)
        E.playVolumizer(p, source)
        attachParts(p, source, target, times)
        target.magneticCopies = target.magneticCopies or {}
        if source.poolCopies then
            for id,n in pairs(source.poolCopies) do target.magneticCopies[id]=(target.magneticCopies[id] or 0)+n end
        elseif not source.generated then
            local copies=source.golden and 3 or 1
            target.magneticCopies[source.id]=(target.magneticCopies[source.id] or 0)+copies
        end
        for id, copies in pairs(source.magneticCopies or {}) do
            target.magneticCopies[id] = (target.magneticCopies[id] or 0) + copies
        end
        for _, m in ipairs(p.board) do
            if m ~= target and m.id == "BG26_149" then attachParts(p, source, m, mult(m)) end
        end
    end

    function E.magnetize(g, color, handIndex, boardIndex)
        local p = g.players[color]
        local ok, reason = canAct(g, p)
        if not ok then return false, reason end
        local source, target = p.hand[handIndex], p.board[boardIndex]
        if not E.canMagnetize(source, target) then return false, "Choose a compatible minion in your warband." end
        table.remove(p.hand, handIndex)
        local times = target.extraMagnetTurn == g.turn and 2 or 1
        target.extraMagnetTurn = nil
        E.attachMagnetic(g, p, source, target, times)
        p.lastMagnetTarget = target
        E.discardPartner(g,p,source)
        if hasRace(source,"MECHANICAL") then
            for _,m in ipairs(p.board) do
                local f=FX[m.id]
                if f and f.magnetized then f.magnetized(g,p,m,mult(m)) end
            end
        end
        event(g,color,"card_play",nil)
        return true
    end

    local activate = {}
    local function activation(id, cost, effect, accepts, zone, partial)
        activate[id] = {cost = cost, effect = effect, accepts = accepts, zone = zone or "board"}
        local c = card(id)
        if not partial then c.fx, c.note = "full", nil end
    end
    local function another(_, source, target) return target ~= source end
    local function discardActivation(id,effect)
        activation(id,0,function(g,p,m,k,target)
            local list=p.hand
            local index=indexOf(list,target)
            if not index then list=p.spellHand;index=indexOf(list,target) end
            if not index or not E.discardCard(g,p,list,index) then return false,"That card is no longer in your hand." end
            effect(g,p,m,k)
            if m.darkGift and m.darkGift.doubleActivate then effect(g,p,m,k) end
            return true
        end,function() return true end,"hand")
    end
    activation("BG36_201",2,function(g,p,_,k,target)
        return E.fishbait(g,p,target,k==2)
    end,function(_,_,m) return m.id~="BG36_205" end,"tavern_any")
    activation("BG36_243",1,function(g,p,_,k,target)
        return E.triggerRally(g,p,target,k)
    end,function(p,source,target) return E.canRallyInRecruit(p,source,target) end)
    activation("BG36_508",1,function(g,p,m,k)
        for _=1,2*k do
            for _=1,12 do if E.castRandomTavern(g,p,m) then break end end
        end
        return true
    end)
    activation("BG36_511",1,function(g,p,m,k,target)
        target.reborn=true
        E.recruitDeath(g,p,target)
        if indexOf(p.board,m) then buff(m,4*k,4*k) end
        return true
    end,function(_,m,t) return t~=m and hasRace(t,"UNDEAD") end)
    activation("BG36_362",1,function(_,_,m)
        m.wrathguardLevel=(m.wrathguardLevel or 0)+1
        return true
    end)
    activation("BG36_240", 2, function(g, p, _, k) return E.chromadrakeReward(g, p, k) end)
    activation("BG36_342", 2, function(g, p) return E.discoverSpell(g, p, p.tier, false) end)
    activation("BG36_346", 1, function(g, p, _, k)
        if E.handCount(p) >= E.MAX_HAND then return false, "Your hand is full." end
        for _ = 1, 2 * k do E.giveSpell(g, p, "BG28_897") end
        return true
    end)
    activation("BG36_345", 1, function(_, _, _, k, target) buff(target, 3 * k, 3 * k); return true end, another)
    activation("BG36_356", 1, function(_, _, _, k, target) target.atk, target.hp = 50 * k, 50 * k; return true end, another)
    activation("BG36_701", 1, function(g, p, _, k, target) runBattlecry(g, p, target, k); return true end,
        function(_, _, target) return FX[target.id] and FX[target.id].bc end)
    activation("BG36_506", 1, function(g, _, m) m.extraMagnetTurn = g.turn; return true end)
    activation("BG36_354", 2, function(g, p, _, k)
        if #p.tavern == 0 or E.handCount(p) >= E.MAX_HAND then return false, "A Tavern minion and hand space are required." end
        for _ = 1, k do
            local best
            for i, m in ipairs(p.tavern) do if not best or m.atk > p.tavern[best].atk then best = i end end
            if not best or E.handCount(p) >= E.MAX_HAND then break end
            addToHand(g, p, table.remove(p.tavern, best))
        end
        return true
    end)
    activation("BG36_370", 2, function(g, p, _, k)
        for _ = 1, 6 * k do
            if not E.giveSpell(g, p, "BG20_GEM") and p.board[1] then buff(p.board[1], p.gemA, p.gemH) end
        end
        return true
    end)
    activation("BG36_700", 1, function(g, _, _, k, target)
        buff(target, 7 * k, 7 * k)
        for _ = 1, k do randomKeyword(g, target) end
        return true
    end, function(_, source, target) return target ~= source and hasRace(target, "MURLOC") end)
    discardActivation("BG36_099", function(_, p, _, k) E.deityBless(p, 2 * k, 2 * k) end)
    discardActivation("BG36_300", function(_, p, _, k)
        p.bonusSpellAtk, p.bonusSpellHp = (p.bonusSpellAtk or 0) + k, (p.bonusSpellHp or 0) + k
    end)
    discardActivation("BG36_311", function(g, p, _, k)
        for _ = 1, k do E.getRandomSpell(g, p, 6, false) end
    end)
    discardActivation("BG36_312", function(g, p, _, k)
        for _ = 1, k do
            if E.handCount(p) >= E.MAX_HAND then break end
            local m = drawFromPool(g, 6, 1, function(c) return c.all or indexOf(c.races, "ABERRATION") end)
            if m then addToHand(g, p, m) end
        end
    end)
    discardActivation("BG28_582", function(g, p, _, k)
        for _ = 1, 3 * k do E.giveSpell(g, p, "BG20_GEM") end
    end)
    activation("BG36_180", 1, function(g, _, m) m.prisonTurn = g.turn; return true end)
    activation("BG36_503", 2, function(g, p, _, k)
        if #p.tavern == 0 then return false, "There are no Tavern minions." end
        local count = 0
        for _, m in ipairs(p.board) do
            if hasRace(m, "DEMON") and #p.tavern > 0 then
                local eaten = table.remove(p.tavern, rnd(g, #p.tavern))
                buff(m,eaten.atk*k,eaten.hp*k)
                E.observeConsumption(g,p,eaten)
                returnToPool(g,eaten)
                count=count+1
            end
        end
        return count > 0, "A friendly Demon is required."
    end)
    activation("BG36_621", 1, function(g, p, _, k)
        if #p.tavern == 0 then return false, "There are no Tavern minions." end
        local keyword = pick(g, {"taunt", "shield", "windfury"})
        for _, m in ipairs(p.tavern) do buff(m, 8 * k, 8 * k); m[keyword] = true end
        return true
    end)

    activation("BG36_507",2,function(g,p,_,k)
        local ok,reason=giveMinion(g,p,1,6,raceFilter("MURLOC"))
        if ok and k==2 then giveMinion(g,p,1,6,raceFilter("MURLOC")) end
        return ok,reason
    end)
    activation("BG36_509",1,function(_,p,_,k)
        p.nextGold=(p.nextGold or 0)+2*k
        return true
    end)

    function E.purchaseCardActions(g, p, purchased)
        for _, m in ipairs(p.board) do
            local f = FX[m.id]
            if f and f.afterBuyMinion then f.afterBuyMinion(g, p, m, mult(m), purchased) end
            if m.prisonTurn == g.turn then
                local k = mult(m)
                buff(m, purchased.atk * k, purchased.hp * k)
                m.prisonTurn = nil
            end
        end
    end


    -- Season 15 activations
    activation("S15_crooked_banker", 1, function(_, p, _, k)
        E.s15DiscountShop(p, k)
        return true
    end)
    activation("S15_cunning_chameleon", 2, function(...) return E.s15ChooseDeathrattle(...) end)
    activation("S15_shambling_shadowfiend", 0, function(g, p, _, k, target)
        return E.s15DiscardNeighbors(g, p, target, k)
    end, function() return true end, "hand")
    activation("S15_squirky", 0, function(_, _, _, k, target)
        target.s15StatBonus = (target.s15StatBonus or 0) + 3 * k
        return true
    end, function(_, _, target) return E.s15CanImproveSpell(target) end, "hand")
    activation("S15_graveyard_skulker", 0, function(g, p, m, k, target)
        E.recruitDeath(g, p, target)
        p.gold = p.gold + 2 * k
        return true
    end, function(_, m, t) return t ~= m and hasRace(t, "UNDEAD") end)
    activation("S15_temple_keeper", 0, function(g, p, m, k, target)
        for _ = 1, 2 * k do
            local opts = {}
            for _, kw in ipairs({"taunt", "shield", "reborn", "windfury", "venom", "resilient"}) do if not target[kw] then opts[#opts + 1] = kw end end
            local kw = E.pick(g, opts)
            if kw then E.tempBuff(target, 0, 0, kw) end
        end
        return true
    end, another)
    activation("S15_scaretaker", 1, function(g, p, m, k, target)
        for _ = 1, k do E.castSpellOnBoard(g, p, "S15S_unholy_ritual", target) end
        return true
    end, function(_, m, target) return target ~= m and hasRace(target, "UNDEAD") end)
    activation("S15_scaled_sovereign", 2, function(g, p, m, k) for _ = 1, k do E.castDragonstorm(p) end; return true end)
    activation("S15_faceless_necromancer", 0, function(g, p, m, k, target)
        for _, list in ipairs({p.hand, p.spellHand}) do
            for i, c in ipairs(list) do if c == target then E.discardCard(g, p, list, i) break end end
        end
        for _, o in ipairs(p.board) do if hasRace(o, "ABERRATION") then E.tempBuff(o, 0, 0, "reborn"); break end end
        return true
    end, function() return true end, "hand")
    E.registerActivation, E.registerDiscardActivation, E.ACTIVATE = activation, discardActivation, activate
    function E.activation(g, m)
        local def = m and activate[m.id]
        if not def or (def.season and def.season ~= g.season) then return nil end
        return def.cost, m.activatedTurn == g.turn
    end

    local function performActivation(g, p, m, def, target)
        local ok, reason = def.effect(g, p, m, mult(m), target)
        if not ok then return false, reason end
        if def.zone~="hand" and m.darkGift and m.darkGift.doubleActivate then def.effect(g,p,m,mult(m),target) end
        m.activatedTurn = g.turn
        p.gold = p.gold - def.cost
        spendGold(g, p, def.cost)
        E.s15ObserveKeywords(g, p)
        checkTriples(g, p)
        return true
    end

    local function activationTargets(p,zone)
        if zone=="board" then return p.board end
        if zone~="tavern_any" and zone~="hand" then return p.tavern end
        local list={}
        for _,t in ipairs(zone=="hand" and p.hand or p.tavern) do list[#list+1]=t end
        for _,t in ipairs(zone=="hand" and p.spellHand or p.spellShop) do list[#list+1]=t end
        return list
    end

    function E.activateMinion(g, color, index)
        local p = g.players[color]
        local ok, reason = canAct(g, p)
        if not ok then return false, reason end
        local m = p.board[index]
        local cost, used = E.activation(g, m)
        if not cost or used then return false, "This ability is unavailable." end
        if p.gold < cost then return false, "Not enough Gold." end
        local def = activate[m.id]
        if not def.accepts then return performActivation(g, p, m, def) end
        local options = {}
        local list=activationTargets(p,def.zone)
        for _, t in ipairs(list) do if def.accepts(p, m, t) then options[#options + 1] = t.uid end end
        if #options == 0 then return false, "There are no eligible targets." end
        p.discover = {kind = "activate_target", uid = m.uid, zone = def.zone, options = options,
            label = card(m.id).name .. " · Choose a target"}
        return true
    end

    function E.pickActivation(g, p, index)
        local d = p.discover
        local m, target
        for _, candidate in ipairs(p.board) do if candidate.uid == d.uid then m = candidate; break end end
        local list=activationTargets(p,d.zone)
        for _, candidate in ipairs(list) do if candidate.uid == d.options[index] then target = candidate; break end end
        local def = m and activate[m.id]
        if not def or not target or not def.accepts(p, m, target) then return false, "That target is unavailable." end
        if m.activatedTurn == g.turn or p.gold < def.cost then return false, "This ability is unavailable." end
        p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue, 1) or nil
        return performActivation(g, p, m, def, target)
    end

    local function asleep(p)
        return p.deityAtk or 0, p.deityHealth or 0
    end
    function E.deityBless(p, a, h)
        if not p then return end
        local attack, health = asleep(p)
        p.deityAtk, p.deityHealth = attack + a, health + h
    end
    function E.initDeity(g)
        if not g.deity and indexOf(g.tribes or {},"ABERRATION") then
            if g.season=="s15" then g.deity=({"BGFYM_000","BGFYM_011","S15_nzoth"})[rnd(g,3)]
            else g.deity=rnd(g,2)==1 and "BGFYM_000" or "BGFYM_011" end
        end
    end
    function C_.recordSacrifice(C, S, minion)
        if not C.g.deity or not hasRace(minion, "ABERRATION") or card(minion.id).deity then return end
        S.sacrificed = S.sacrificed or {}
        S.deityCount = (S.deityCount or #S.sacrificed) + 1
        S.sacrificed[#S.sacrificed + 1] = {id = minion.id, golden = minion.golden, atk = minion.atk,
            hp = math.max(1, minion.maxhp or card(minion.id).hp)}
    end
    function C_.awakeDeity(C, S)
        if not C.g.deity or S.awoke or (S.deityCount or #(S.sacrificed or {})) < E.deityNeed(C.g.deity) or #S.list >= E.MAX_BOARD then return end
        local p = ownerOf(C, S)
        local a, h = 0, 0
        if p then a, h = asleep(p) end
        local m=summon(C,S,C.g.deity,p and p.goldenDeity or false,C.g.season=="s15" and S.lastSacrificePos or nil,function(deity) buff(deity,a,h) end)
        if not m then return end
        S.awoke=true
        C_.trinketHook(C,S,"deity",m)
        if m.id == "BGFYM_000" then
            local allies = others(livingOf(S), m)
            if #allies > 0 then
                for i, ally in ipairs(allies) do
                    buff(ally, math.floor((m.atk + #allies - i) / #allies), math.floor((m.hp + #allies - i) / #allies))
                end
            end
        end
        frame(C,cname(m).." awakens.",m.uid,nil,"deity_summon")
    end
    FX.BGFYM_011 = {dr = function(C, S, _, pos, k)
        for i = 1, math.min(2 * k, #(S.sacrificed or {})) do
            local saved = S.sacrificed[i]
            summon(C, S, saved.id, saved.golden, pos + i - 1, function(m) m.atk, m.hp, m.maxhp = saved.atk, saved.hp, saved.hp end)
        end
    end}
    FX.BG36_110 = {bc = function(_, p, _, k) E.deityBless(p, 2 * k, k) end}
    FX.BG36_113 = {dr = function(C, S, _, _, k) E.deityBless(ownerOf(C, S), 2 * k, k) end}
    FX.BG36_104 = {dr = function(C, S, _, _, k)
        local p = ownerOf(C, S)
        if p then p.bonusSpellHp = (p.bonusSpellHp or 0) + 4 * k end
    end}
    FX.BG36_101 = {dr = function(C, S, _, _, k)
        local p = ownerOf(C, S)
        if p then for _ = 1, k do E.getRandomSpell(C.g, p, 6, false, function(s) return s.cost == 1 end) end end
    end}
    for _, id in ipairs({"BG36_110", "BG36_113", "BG36_104", "BG36_101"}) do card(id).fx, card(id).note = "full", nil end

    local function buddy(id, handlers, note)
        if not card(id) then return end
        FX[id] = handlers
        card(id).fx, card(id).note = note and "simplified" or "full", note
    end
    buddy("TB_BaconShop_HERO_27_Buddy", {endTurn = function(g, p, _, k)
        if p.frozen then for _ = 1, k do
            local pool = {}
            for _, m in ipairs(p.tavern) do if not m.golden then pool[#pool + 1] = m end end
            local m = pick(g, pool)
            if m then makeGolden(m) end
        end end
    end})
    buddy("TB_BaconShop_HERO_75_Buddy", {endTurn = function(g, p, _, k)
        for _ = 1, 2 * k do E.getRandomSpell(g, p, 6, false, function(s) return s.text:find("+", 1, true) end) end
    end}, "Draws from the implemented stat-buff Tavern spells.")
    buddy("TB_BaconShop_HERO_18_Buddy", {
        bc = function(g,p,_,k) for _ = 1,k do E.getRandomSpell(g,p,6,false,function(s) return s.name:find("Bounty",1,true) end) end end,
        dr = function(C,S,_,_,k)
            local p = ownerOf(C,S)
            if p then for _=1,k do E.getRandomSpell(C.g,p,6,false,function(s) return s.name:find("Bounty",1,true) end) end end
        end,
        onAttack = function(C,S,_,k)
            local p = ownerOf(C,S)
            if p then for _=1,k do E.getRandomSpell(C.g,p,6,false,function(s) return s.name:find("Bounty",1,true) end) end end
        end,
    }, "Draws from the available scripted Bounties.")
    buddy("TB_BaconShop_HERO_93_Buddy", {bc = function(g,p,source,k)
        for _ = 1,k do
            local targets = {}
            for _, m in ipairs(p.board) do if m ~= source and card(m.id).deathrattle and not m.golden then targets[#targets+1] = m end end
            local m = pick(g,targets)
            if m then makeGolden(m) end
        end
    end}, "Selects a random eligible friendly Deathrattle minion.")
    buddy("BG25_HERO_105_Buddy", {bc = function(g,p,source,k)
        for _=1,k do
            local targets = {}
            for _, m in ipairs(p.board) do if m ~= source and card(m.id).buddy and not m.golden then targets[#targets+1] = m end end
            local m = pick(g, targets)
            if m then makeGolden(m) end
        end
    end}, "Selects a random eligible friendly Buddy.")
    buddy("BG23_HERO_304_Buddy", {spellcraftOffer = function(g, p, k)
        for _, offered in ipairs(p.tavern) do
            for _ = 1, k do E.copySpellcraft(g, p, offered) end
        end
    end}, "Copies currently implemented Spellcraft spells.")
end

do
    local definitions = {
