        {id="BG36_MidGameEffect_000t28",title="Battle Scars",label="Battle Scars",description="Has +3/+3 for each Battlecry you've triggered this game. (0)",minTurn=7,maxTurn=9,counter="battlecries",scaleA=3,scaleH=3,noDeathrattle=true,parasite=true},
