        {id="BG36_MidGameEffect_000t7",title="Resistance",label="Resistance",description="+15 Health. Start of Combat: Double this minion's Health.",minTurn=7,maxTurn=10,hp=15,doubleHp=true,typed=true,noRaces={"BEAST","UNDEAD"},noLobby={"DRAGON"},noDeathrattle=true,parasite=true},
        {id="BG36_MidGameEffect_000t71",title="Hostility",label="Hostility",description="+15 Attack. Start of Combat: Double this minion's Attack.",minTurn=7,maxTurn=10,atk=15,doubleAtk=true,typed=true,noAvenge=true,noPoison=true,noDeathrattle=true,parasite=true},
        {id="BG36_MidGameEffect_000t64t",title="Dexterity",label="Dexterity",description="Whenever you play a card, gain +4/+4.",minTurn=8,maxTurn=9,onPlay=4,typed=true,noDeathrattle=true},
        {id="BG36_MidGameEffect_000t61",title="Golemancy",label="Golemancy",description="Deathrattle: Summon a Golem with this minion's stats.",minTurn=9,maxTurn=12,golem=true,typed=true,parasite=true},
        {id="BG36_MidGameEffect_000t12",title="Persisting Horror",label="Persisting Horror",description="Reborn. Is Reborn with full stats and Bonus Keywords.",minTurn=10,reborn=true,persist=true,typed=true,rare=true,parasite=true},
        {id="BG36_MidGameEffect_000t72",title="Titanic Strength",label="Titanic Strength",description="+1000 Attack.",minTurn=11,atk=1000,rare=true,noRaces={"DRAGON"},noDeathrattle=true,parasite=true},
