    register("BG33_821", {bc=bounty,dr=function(C,S,m,_,k) bounty(C.g,ownerOf(C,S),m,k) end})
    register("BG33_822", {onAttack=function(C,S,m,k) bounty(C.g,ownerOf(C,S),m,k) end})
    register("BG33_823", {spend=function(g,p,m,n,k)
        m.bountyGold = (m.bountyGold or 0) + n
        while m.bountyGold >= 9 do
            m.bountyGold = m.bountyGold - 9
            bounty(g,p,m,k)
        end
    end})
    register("BG27_017", {onAttack=function(C,S,m,k,target)
        local enemy = otherSide(C,S)
        local i = indexOf(enemy.list,target)
        local left, right = enemy.list[i-1], enemy.list[i+1]
        if left and left.hp <= 0 then left = nil end
        if right and right.hp <= 0 then right = nil end
        C_.dealDamage(C,enemy,target,m.atk)
        if k == 2 then
            if left then C_.dealDamage(C,enemy,left,m.atk) end
            if right then C_.dealDamage(C,enemy,right,m.atk) end
        else
            local adjacent = left and right and pick(C.g,{left,right}) or left or right
            if adjacent then C_.dealDamage(C,enemy,adjacent,m.atk) end
        end
    end}, "The Rally damage uses the normal attack resolution sequence.")
    register("BG34_950", {afterBuyMinion = function(g,_,m,k,bought)
        if m.slabTurn == g.turn then return end
        m.slabTurn = g.turn
        buff(bought,20,20)
        buff(bought,bought.atk*k,bought.hp*k)
    end})
    register("BG34_858", {spend = function(g,p,m,n,k)
        m.revenantGold = (m.revenantGold or 0) + n
        while m.revenantGold >= 7 do
