    local INV = {"S15S_invocation_earth", "S15S_invocation_fire", "S15S_invocation_air", "S15S_invocation_water"}
    local function invocation(a, kw)
        return function(g, p, m)
            if not m then return false, "Choose a friendly minion." end
            buffSpell(p, m, a, a)
            if hasRace(m, "ELEMENTAL") then E.tempBuff(m, 0, 0, kw) end
            return true
        end
    end
    spell("S15S_invocation_earth", "board", invocation(3, "taunt"))
    spell("S15S_invocation_fire", "board", invocation(4, "reborn"))
    spell("S15S_invocation_air", "board", invocation(5, "windfury"))
    spell("S15S_invocation_water", "board", invocation(6, "shield"))
    spell("S15S_command_elements", nil, function(g, p)
        for _, id in ipairs(INV) do E.giveSpell(g, p, id) end
        return true
    end)
    spell("S15S_goldrinns_blessing", nil, function(g, p) E.beastAura(p, 1, 1); return true end)
    FX["S15E_dragonstorm"] = {endTurn = function(g, p, m) buff(m, 2, 2) end}
    FX["S15E_echo"] = {endTurn = function(g, p, m) buff(m, 3, 3) end}
    local function attach(m, id)
        m.attachments = m.attachments or {}
        m.magnetizedCount = m.magnetizedCount or #m.attachments
        table.insert(m.attachments, {id = id, atk = 0, hp = 0, enchant = true})
    end
    FX["S15E_unholy"] = {dr = FX.BG28_300.dr}
    spell("S15S_unholy_ritual", "board", function(g, p, m)
        if not m or not hasRace(m, "UNDEAD") then return false, "Choose a friendly Undead." end
        attach(m, "S15E_unholy")
        return true
    end)
    function E.castDragonstorm(p) for _, m in ipairs(p.board) do if hasRace(m, "DRAGON") then attach(m, "S15E_dragonstorm") end end end
    function E.castSanctify(p) for _, m in ipairs(p.board) do if m.shield then buffSpell(p, m, 4, 0) end end end
    spell("S15S_dragonstorm", nil, function(g, p) E.castDragonstorm(p); return true end)
    spell("S15S_tumultuous_growth", "board", function(g, p, m)
        if not m then return false, "Choose a minion." end
        for _ = 1, 2 do for _ = 1, 12 do if E.castRandomTavern(g, p, m, {S15S_tumultuous_growth = true}) then break end end end
        return true
    end)
    spell("S15S_echoing_roar", "board", function(g, p, m) if not m then return false, "Choose a minion." end; attach(m, "S15E_echo"); return true end)
    spell("S15S_sanctify", nil, function(g, p) E.castSanctify(p); return true end)

    -- Season 15 Tavern spell numbers. Edit a number here and both the card text and the
    -- effect change; spell power is added on top of a/h (see E.spellAmount).
    E.S15_SPELLS = {
        S15S_goldrinns_blessing = {text = "Your Beasts have +{a}/+{h} this game (wherever they are).", a = 1, h = 1},
        S15S_invocation_earth = {text = "Give a minion +{a}/+{h}. If it's an Elemental, also give it Taunt until next turn.", a = 3, h = 3, kw = "taunt"},
        S15S_invocation_fire = {text = "Give a minion +{a}/+{h}. If it's an Elemental, also give it Reborn until next turn.", a = 4, h = 4, kw = "reborn"},
        S15S_invocation_air = {text = "Give a minion +{a}/+{h}. If it's an Elemental, also give it Windfury until next turn.", a = 5, h = 5, kw = "windfury"},
        S15S_invocation_water = {text = "Give a minion +{a}/+{h}. If it's an Elemental, also give it Divine Shield until next turn.", a = 6, h = 6, kw = "shield"},
        S15S_dragonstorm = {text = "Give your Dragons \"At the end of your turn, gain +{a}/+{h}.\"", a = 2, h = 2},
        S15S_echoing_roar = {text = "Give a friendly minion \"At the end of your turn, gain +{a}/+{h}.\"", a = 3, h = 3},
        S15S_sanctify = {text = "Give your minions with Divine Shield +{a} Attack.", a = 4, h = 0},
    }
    for id, t in pairs(E.S15_SPELLS) do E.setSpellText(id, t) end
    local function s15Spell(id) return E.S15_SPELLS[id] end
    for _, id in ipairs(INV) do
        E.SPELLS[id].cast = function(g, p, m)
            if not m then return false, "Choose a friendly minion." end
            local t = s15Spell(id)
            buffSpell(p, m, t.a, t.h)
            if t.kw and hasRace(m, "ELEMENTAL") then E.tempBuff(m, 0, 0, t.kw) end
            return true
        end
    end
    E.SPELLS.S15S_goldrinns_blessing.cast = function(g, p)
        local t = s15Spell("S15S_goldrinns_blessing")
        E.beastAura(p, E.spellAmount(p, t.a, t.h))
        return true
    end
    -- Dragonstorm and Echoing Roar keep the spell power they were cast with.
    local function growth(m, id, a, h)
        m.attachments = m.attachments or {}
        m.magnetizedCount = m.magnetizedCount or #m.attachments
        table.insert(m.attachments, {id = id, atk = 0, hp = 0, enchant = true, s15a = a, s15h = h})
    end
    local function growthTrigger(spellId)
        return function(g, p, m, k, part)
            local t = s15Spell(spellId)
            k = k or 1
            buff(m, (part and part.s15a or t.a) * k, (part and part.s15h or t.h) * k)
        end
    end
    FX["S15E_dragonstorm"] = {endTurn = growthTrigger("S15S_dragonstorm")}
    FX["S15E_echo"] = {endTurn = growthTrigger("S15S_echoing_roar")}
    function E.castDragonstorm(p)
        local t = s15Spell("S15S_dragonstorm")
        local a, h = E.spellAmount(p, t.a, t.h)
        for _, m in ipairs(p.board) do if hasRace(m, "DRAGON") then growth(m, "S15E_dragonstorm", a, h) end end
    end
    E.SPELLS.S15S_echoing_roar.cast = function(g, p, m)
        if not m then return false, "Choose a minion." end
        local t = s15Spell("S15S_echoing_roar")
        local a, h = E.spellAmount(p, t.a, t.h)
        growth(m, "S15E_echo", a, h)
        return true
    end
    function E.castSanctify(p)
        local t = s15Spell("S15S_sanctify")
        for _, m in ipairs(p.board) do if m.shield then buffSpell(p, m, t.a, t.h) end end
    end
    -- Season 15 Tavern spell rotation: the 9 new spells (all four Invocations and Command
    -- the Elements included, as the patch notes list them with a Tier and Cost) plus the
    -- returning Pointy Arrow and Deepwater Clan (now Tier 4).
    E.SPELLS.S15S_command_elements.tavern = true
    if E.SPELLS.BG35_149 then E.SPELLS.BG35_149.tier = 4 end
    for _, id in ipairs({"S15S_invocation_earth", "S15S_invocation_fire", "S15S_invocation_air",
        "S15S_invocation_water", "S15S_command_elements", "EBG_Spell_014", "BG35_149"}) do
        if E.SPELLS[id] then E.seasonSpells.s15[id] = true end
    end

    -- ===== Season 15 minions that use them =====
    local GB, ER, CMD = "S15S_goldrinns_blessing", "S15S_echoing_roar", "S15S_command_elements"
    register("S15_patrolling_gargoyle", {bc = function(g, p, _, k) spells(g, p, "S15S_unholy_ritual", k) end})
    -- Season 15 recruit, combat and mission effects for the staged card set.
    local function isTavernSpell(spell)
        return spell and (spell.tavern or not spell.generated) and not BG_TIMEWARP[spell.id]
    end

    function E.s15CanImproveSpell(entry)
        local spell = metadata[entry.id]
        return isTavernSpell(spell) and (spell.text or ""):match("%+%d+") ~= nil
    end

    function E.s15Cast(g, p, spell, target, address, entry)
        local previous = p.s15SpellStatBonus
        p.s15SpellStatBonus = entry and entry.s15StatBonus
        local worked, ok, err = pcall(spell.cast, g, p, target, address, entry)
        p.s15SpellStatBonus = previous
        if not worked then error(ok) end
        return ok, err
    end

    local function undiscounted(m)
        return m and not m.s15Discount
    end

    local function discount(entry, amount)
        entry.s15Discount = (entry.s15Discount or 0) + amount
    end

    function E.s15DiscountShop(p, amount)
        for _, list in ipairs({p.tavern, p.spellShop}) do
            for _, entry in ipairs(list) do discount(entry, amount) end
        end
    end

    function E.s15MinionPrice(p, m)
        local base = E.trinketMinionCost(p, m, card(m.id).fixedCost or E.buyCost(p))
        local battlecryDiscount = card(m.id).battlecry and (p.s15NextBattlecry or 0) or 0
        return math.max(0, base - (m.s15Discount or 0) - battlecryDiscount)
    end

    function E.s15AfterShopRoll(g, p)
        for _, m in ipairs(p.board) do
            if m.id == "S15_hostile_haggler" then
                local entries = {}
                for _, list in ipairs({p.tavern, p.spellShop}) do
                    for _, entry in ipairs(list) do entries[#entries + 1] = entry end
                end
                shuffle(g, entries)
                for i = 1, math.min(#entries, 2 * mult(m)) do discount(entries[i], 1) end
            end
        end
    end

    function E.s15DiscardNeighbors(g, p, target, count)
        local hand = {}
        for _, list in ipairs({p.hand, p.spellHand}) do
            for _, entry in ipairs(list) do hand[#hand + 1] = {entry = entry, list = list} end
        end
        for i, item in ipairs(hand) do
            if item.entry == target then
                local discarded = 0
                for j = math.min(#hand, i + 1), math.max(1, i - 1), -1 do
                    local slot = hand[j]
                    local index = indexOf(slot.list, slot.entry)
                    if index and E.discardCard(g, p, slot.list, index) then discarded = discarded + 1 end
                end
                p.gold = math.min(99, p.gold + discarded * count)
                return true
            end
        end
        return false, "That card is no longer in your hand."
    end

    function E.s15ChooseEffect(g, p, index)
        local choice = p.discover
        local id = choice.options[index]
        if not id then return false, "That choice is unavailable." end
        local target
        if choice.s15Effect == "handBuff" then
            for _, m in ipairs(p.hand) do
                if m.uid == id then target = m; break end
            end
            if not target then return false, "That card is no longer in your hand." end
            buff(target, choice.s15Amount, choice.s15Amount)
        else
            for _, m in ipairs(p.board) do
                if m.uid == choice.s15Source then target = m; break end
            end
            if not target or not FX[id] or not FX[id].dr then return false, "That Deathrattle is unavailable." end
            target.s15Deathrattles = target.s15Deathrattles or {}
            target.s15Deathrattles[#target.s15Deathrattles + 1] = {id = id, k = choice.s15Amount}
            local reward = drawFromPool(g, p.tier, 1, function(c) return c.id == id end)
            if reward then addToHand(g, p, reward)
            else
                reward = E.newMinion(g, id, false)
                reward.generated = true
                addToHand(g, p, reward)
            end
        end
        p.discover = table.remove(p.discoverQueue, 1)
        E.onDiscovered(g, p, target)
        checkTriples(g, p)
        return true
    end

    function E.s15ChooseDeathrattle(g, p, source, count)
        if E.handCount(p) >= E.MAX_HAND then return false, "Your hand is full." end
        local ids = {}
        for id, copies in pairs(g.pool) do
            if copies > 0 and FX[id] and FX[id].dr and card(id).tier <= p.tier then ids[#ids + 1] = id end
        end
        table.sort(ids)
        shuffle(g, ids)
        local options = {}
        for i = 1, math.min(3, #ids) do options[i] = ids[i] end
        return E.offerMinionChoice(g, p, options, "Choose a Deathrattle minion",
            {s15Effect = "deathrattle", s15Amount = count, s15Source = source.uid})
    end

    local function living(C, p, S)
        return C and S.list or p.board
    end

    local function mission(g, p, m, goal, amount, reward)
        if not p then return end
        local actual = m
        if m.inCombat then
            for _, entry in ipairs(p.board) do
                if entry.uid == m.src then actual = entry; break end
            end
        end
        if actual.missionDone then return end
        actual.missionProgress = (actual.missionProgress or 0) + amount
        if actual.missionProgress < goal then return end
        actual.missionDone, m.missionDone = true, true
        reward(g, p, mult(m))
    end

    local function getGenerated(g, p, candidates, count, golden)
        if not p or #candidates == 0 then return end
        for _ = 1, count do
            if E.handCount(p) >= E.MAX_HAND then return end
            local m = E.newMinion(g, pick(g, candidates), golden)
            m.generated = true
            addToHand(g, p, m)
        end
    end

    local function generatedOptions(g, predicate, includeTierSeven)
        local ids = {}
        for id, c in pairs(BG_CARDS) do
            if (g.allowed[id] or includeTierSeven and c.tier == 7 and not c.buddy)
                and (c.fx == "full" or c.fx == "simplified") and predicate(c) then
                local eligible = c.all or #c.races == 0
                for _, race in ipairs(c.races) do if indexOf(g.tribes, race) then eligible = true; break end end
                if eligible then ids[#ids + 1] = id end
            end
        end
        table.sort(ids)
        return ids
    end

    local function markKeywords(m)
        local seen = {}
        for _, kw in ipairs(BONUS_KW) do if m[kw] then seen[kw] = true end end
        m.s15Keywords = seen
    end
    E.s15MarkKeywords = markKeywords

    function E.s15ObserveKeywords(g, p, C, S)
        if not p or g.season ~= "s15" then return end
        local list, added = living(C, p, S), 0
        for _, m in ipairs(list) do
            local old = m.s15Keywords
            if m.hp > 0 then
                markKeywords(m)
                if old then
                    for kw in pairs(m.s15Keywords) do if not old[kw] then added = added + 1 end end
                end
            end
        end
        if added == 0 then return end
        for _, m in ipairs(list) do
            local f = FX[m.id]
            if m.hp > 0 and f and f.bonusKeyword then f.bonusKeyword(g, p, m, mult(m), added, C, S) end
        end
    end

    function E.s15Summon(g, p, summoned, C, S)
        if not p or g.season ~= "s15" then return end
        for _, m in ipairs(living(C, p, S)) do
            local f = FX[m.id]
            if m ~= summoned and m.hp > 0 and f and f.s15Summon then f.s15Summon(g, p, m, mult(m), summoned) end
        end
        E.s15ObserveKeywords(g, p, C, S)
    end

    function E.s15CombatSpace(C, S)
        if C.g.season ~= "s15" or not C.s15StartComplete or #S.list >= E.MAX_BOARD then return end
        local sources = {}
        for _, m in ipairs(S.list) do
            if m.hp > 0 and m.id == "S15_prototype_builder" and not m.s15Built then sources[#sources+1] = m end
        end
        for _, m in ipairs(sources) do
            if #S.list >= E.MAX_BOARD then break end
            m.s15Built = true
            for _ = 1, mult(m) do
                if #S.list >= E.MAX_BOARD then break end
                summon(C, S, "BG_TTN_401", false, nil, function(created)
                    for _, kw in ipairs(BONUS_KW) do if m[kw] then created[kw] = true end end
                end)
            end
        end
    end

    function E.s15ExcessSummon(C, S)
        if C.g.season ~= "s15" then return end
        for _, m in ipairs(S.list) do
            if m.id == "S15_saronite_colossus" and m.hp > 0 then
                local highest
                for _, ally in ipairs(S.list) do
                    if ally.hp > 0 and (not highest or ally.hp > highest.hp) then highest = ally end
                end
                if highest then buff(highest, 10 * mult(m), 10 * mult(m)) end
            end
        end
    end

