      ["S15_tw_willbreaker"] = {gtext = "Activate (1): Get 6 random Tavern spells. After you cast two, discard the others."},
      ["S15_twilight_traverser"] = {gtext = "At the end of your turn, get 2 random Chromadrakes."},
      ["S15_ucha_mighty"] = {gtext = "Deathrattle: Summon a 4/4 Monkey. (Improved by each Tavern spell you've cast this game!)"},
      ["S15_underrot_infestor"] = {gtext = "Deathrattle: Summon four 1/1 Tentacles. Give them this minion's Attack."},
      ["S15_vindictive_preacher"] = {gtext = "Avenge (3): Give your Deity +14/+14."},
      ["S15_voidtouched_geopriestess"] = {gtext = "Whenever a friendly minion gains a Bonus Keyword, this plays 4 Blood Gems on all your minions.", text = "Whenever a friendly minion gains a Bonus Keyword, this plays 2 Blood Gems on all your minions."},
      ["S15_wave_watcher"] = {gtext = "At the end of your turn, give your Elementals +3/+3 twice. Repeat for each different Bonus Keyword in your warband."},
      ["S15_young_mukla"] = {gtext = "Battlecry: Get 4 Tavern Dish Bananas."},
    }
    E.S15_POOL = {"BG19_010","BG20_100","BG20_101","BG20_104","BG21_015","BG22_202","BG22_402","BG22_403","BG23_016","BG23_017","BG23_318","BG24_003","BG24_018","BG24_500","BG24_715","BG25_001","BG25_010","BG25_011","BG25_013","BG25_016","BG25_022","BG25_032","BG25_034","BG25_354","BG26_137","BG26_146","BG26_147","BG26_148","BG26_149","BG26_159","BG26_160","BG26_174","BG26_354","BG26_523","BG26_524","BG26_525","BG26_800","BG26_802","BG26_805","BG26_810","BG26_814","BG26_817","BG26_867","BG26_963","BG26_ICC_901","BG27_000","BG27_005","BG27_016","BG27_017","BG27_084","BG27_556","BG28_300","BG28_303","BG28_309","BG28_550","BG28_582","BG28_583","BG28_590","BG28_595","BG28_707","BG29_300","BG29_503","BG29_611","BG29_813","BG30_103","BG30_123","BG30_124","BG30_129","BG31_148","BG31_149","BG31_177","BG31_300","BG31_301","BG31_330","BG31_815","BG31_816","BG31_818","BG31_835","BG31_871","BG31_999","BG32_172","BG32_235","BG32_236","BG32_237","BG32_330","BG32_332","BG32_336","BG32_340","BG32_820","BG32_821","BG32_822","BG32_860","BG32_873","BG32_891","BG32_892","BG33_809","BG33_821","BG33_822","BG33_823","BG33_825","BG33_826","BG33_883","BG33_884","BG33_885","BG33_886","BG33_888","BG33_893","BG33_924","BG34_142","BG34_145","BG34_175","BG34_319","BG34_320","BG34_322","BG34_500","BG34_604","BG34_633","BG34_690","BG34_692","BG34_694","BG34_856","BG34_858","BG34_865","BG34_950","BG35_143","BG35_150","BG35_152","BG35_155","BG35_341","BG35_431","BG35_432","BG35_433","BG35_602","BG35_604","BG35_814","BG35_883","BG36_097","BG36_098","BG36_099","BG36_100","BG36_106","BG36_109","BG36_110","BG36_111","BG36_113","BG36_116","BG36_204","BG36_245","BG36_308","BG36_311","BG36_312","BG36_333","BG36_344","BG36_352","BG36_354","BG36_520","BG36_521","BG36_620","BG36_640","BG36_704","BG36_730","BG36_731","BG36_762","BG36_763","BG36_854","BGFYM_005","BGS_004","BGS_008","BGS_012","BGS_018","BGS_020","BGS_041","BGS_071","BGS_078","BGS_115","BGS_119","BGS_121","BGS_123","BGS_126","BGS_131","BG_BOT_911","BG_CFM_315","BG_DEEP_015","BG_LOE_077","BG_TTN_401","S15_ambitious_cannoneer","S15_ambitious_recruit","S15_bloodfin_scholar","S15_bot_launcher","S15_brutal_bristlethorn","S15_crafty_cookfire","S15_crooked_banker","S15_crypt_crawler","S15_cunning_chameleon","S15_cutrate_crewman","S15_dauntless_adventurer","S15_defense_mechanism","S15_desert_duelist","S15_driftaway_djinni","S15_eclectic_musician","S15_effusive_dancer","S15_elder_moonbeast","S15_erupting_eyestalk","S15_faceless_necromancer","S15_flying_monkey","S15_freedom_fighter","S15_future_fighter","S15_gorloc_gardener","S15_graveyard_skulker","S15_great_direwolf","S15_great_wolf_cub","S15_greymist_infiltrator","S15_hammer_hero","S15_hardy_felhound","S15_hostile_haggler","S15_imperial","S15_land_upheaver","S15_light_generator","S15_loti_devilsaur","S15_merciless_warden","S15_nonchalant_napper","S15_obsessive_artisan","S15_ominous_ooze","S15_ossifier","S15_pain_promoter","S15_patrolling_gargoyle","S15_patron_gatherer","S15_prototype_builder","S15_ribbiting_magician","S15_ruthless_pursuer","S15_saronite_colossus","S15_scaled_sovereign","S15_scaretaker","S15_shackled_shade","S15_shambling_shadowfiend","S15_sickly_ooze","S15_squirky","S15_surging_sanctifier","S15_tainted_tormentor","S15_temple_keeper","S15_tenacious_thornwitch","S15_thunder_knight","S15_timeless_mount","S15_tsunami_surfer","S15_twilight_traverser","S15_ucha_mighty","S15_underrot_infestor","S15_vindictive_preacher","S15_voidtouched_geopriestess","S15_wave_watcher","S15_young_mukla"}
    do
    -- ===== Season 15 v3: Blizzard card data, exact pool, golden effects that are not "do it twice" =====
    local P = E.S15_CARD_PATCH
    local TW = E.S15TW
    local function patchOf(id) P[id] = P[id] or {}; return P[id] end
    local function fields(id) local c = patchOf(id); c.fields = c.fields or {}; return c.fields end
    local function fx(id, hooks) local c = patchOf(id); c.fx = c.fx or {}; for k, v in pairs(hooks) do c.fx[k] = v end end

    -- 1. Card text, golden text, tier and stats from Blizzard's 37.2 card library (E.S15_DATA, generated).
    E.S15_SPELL_TEXT = {}
    for id, rec in pairs(E.S15_DATA) do
        if BG_CARDS[id] then
            local f = fields(id)
            for k, v in pairs(rec) do f[k] = v end
        elseif E.SPELLS[id] and rec.text then
            E.S15_SPELL_TEXT[id] = rec.text
        end
    end
    -- Sewer Rat itself has no Taunt (only its Turtle does).
    fields("BG19_010").taunt = false
    -- 2. Shop pool: exactly the 251 Season 15 solo minions (Naga rotated out; Rot Hide Gnoll is in).
    for _, s in ipairs(BG_SEASONS) do if s.key == "s15" then s.pool = E.S15_POOL end end

    -- Spell texts follow the season too.
    local activateSeason = E.activateSeason
    local savedSpellText = {}
    function E.activateSeason(key)
        for id, t in pairs(savedSpellText) do E.SPELLS[id].text = t end
        savedSpellText = {}
        activateSeason(key)
        if key ~= "s15" then return end
        for id, t in pairs(E.S15_SPELL_TEXT) do
            if E.SPELLS[id] then savedSpellText[id] = E.SPELLS[id].text or ""; E.SPELLS[id].text = t end
        end
    end

    -- 3. Golden effects whose golden text is not simply "twice".
    -- Stone Age Slab: +20/+20 and double (golden: +20/+20 and triple).
    fx("BG34_950", {afterBuyMinion = function(g, _, m, k, bought)
        if m.slabArmed ~= g.turn then return end
        m.slabArmed = nil
        buff(bought, 20, 20)
        buff(bought, bought.atk * k, bought.hp * k)
    end})
    -- Prototype Builder: golden summons one Golden Ancestral Automaton.
    function E.s15CombatSpace(C, S)
        if C.g.season ~= "s15" or not C.s15StartComplete or #S.list >= E.MAX_BOARD then return end
        local sources = {}
        for _, m in ipairs(S.list) do
            if m.hp > 0 and m.id == "S15_prototype_builder" and not m.s15Built then sources[#sources + 1] = m end
        end
        for _, m in ipairs(sources) do
            if #S.list >= E.MAX_BOARD then break end
            m.s15Built = true
            summon(C, S, "BG_TTN_401", m.golden and true or false, nil, function(created)
                for _, kw in ipairs({"taunt", "shield", "reborn", "windfury", "venom", "resilient"}) do if m[kw] then created[kw] = true end end
            end)
        end
    end
    -- Ruthless Pursuer: golden adds four Bounties.
    FX["S15_ruthless_pursuer"].sell = function(g, p, _, k)
        p.frozen = false
        E.rollTavern(g, p)
        local bounties = {"BG33_811", "BG33_812", "BG33_813", "BG33_814", "BG33_815"}
        for _ = 1, 2 * k do
            if #p.spellShop >= 6 then break end
            local entry = instance(g, pick(g, bounties))
            entry.s15PriceOverride = 1
            p.spellShop[#p.spellShop + 1] = entry
        end
    end
    -- Faceless Necromancer / Timewarped Necromancer: golden gives your 2 left-most Aberrations Reborn.
    local function leftAberrations(p, k, temp)
        local n = 0
        for _, o in ipairs(p.board) do
            if n >= k then break end
            if hasRace(o, "ABERRATION") then
                if temp then E.tempBuff(o, 0, 0, "reborn") else o.reborn = true end
                n = n + 1
            end
        end
    end
    local function discardTarget(g, p, target)
        for _, list in ipairs({p.hand, p.spellHand}) do
            for i, c in ipairs(list) do if c == target then return E.discardCard(g, p, list, i) end end
        end
        return false
    end
    E.registerActivation("S15_faceless_necromancer", 0, function(g, p, m, k, target)
        if not discardTarget(g, p, target) then return false, "That card is no longer in your hand." end
        leftAberrations(p, k, true)
        return true
    end, function() return true end, "hand")
    E.registerActivation("S15_tw_necromancer", 0, function(g, p, m, k, target)
        if not discardTarget(g, p, target) then return false, "That card is no longer in your hand." end
        leftAberrations(p, k, false)
        return true
    end, function() return true end, "hand")
    -- Cunning Chameleon: golden Discovers 2 Deathrattle minions (and copies both Deathrattles).
    E.registerActivation("S15_cunning_chameleon", 2, function(g, p, m, k)
        local ok, err
        for _ = 1, k do ok, err = E.s15ChooseDeathrattle(g, p, m, 1) end
        return ok, err
    end)
    -- Timewarped Holmes: one guess; golden gets 2 copies of the right answer.
    E.registerActivation("S15_tw_holmes", 0, function(g, p, m, k)
        local foe = TW.foeOf(g, p)
        local board = type(foe) == "table" and foe.board
        if type(board) ~= "table" or #board == 0 then return false, "Your next opponent has no minions to guess." end
        local answer = pick(g, board)
        local ids, seen = {answer.id}, {[answer.id] = true}
        local others = {}
        for id, n in pairs(g.pool) do if n > 0 and not seen[id] and card(id) then others[#others + 1] = id end end
        table.sort(others)
        shuffle(g, others)
        for i = 1, math.min(2, #others) do ids[#ids + 1] = others[i] end
        shuffle(g, ids)
        local copies = {}
        for i = 1, k do copies[i] = TW.copy(g, answer) end
        E.offerMinionChoice(g, p, ids, "Holmes: which minion is in your next opponent's warband?",
            {s15Effect = "holmes", holmesAnswer = answer.id, holmesCopy = copies[1], holmesCopies = copies})
        return true
    end)
    local holmesChoose = E.s15ChooseEffect
    function E.s15ChooseEffect(g, p, index)
        local d = p.discover
        if d and d.s15Effect == "holmes" and d.holmesCopies and d.options[index] == d.holmesAnswer then
            for i = 2, #d.holmesCopies do
                local copy = d.holmesCopies[i]
                g.uid = g.uid + 1
                copy.uid = g.uid
                TW.hand(g, p, copy)
            end
        end
        return holmesChoose(g, p, index)
    end
    -- Timewarped Soldier: golden gives double the stats to your Deity.
    FX["S15_tw_soldier"].gainObserved = function(p, _, _, m, target, k, a, h)
        if m == target then E.deityBless(p, a * mult(m), h * mult(m)) end
    end
    -- Timewarped Nightmare: golden gives "Deathrattle: Summon a Golden Timewarped Nightmare" (once).
    FX["S15E_nightmare_g"] = {dr = function(C, S, _, pos) summon(C, S, "S15_tw_nightmare", true, pos) end}
    FX["S15_tw_nightmare"].dr = function(C, S, m)
        local options = {}
        for _, t in ipairs(S.list) do if t ~= m and t.hp > 0 and hasRace(t, "UNDEAD") then options[#options + 1] = t end end
        local t = pick(C.g, options)
        if t then attach(t, m.golden and "S15E_nightmare_g" or "S15E_nightmare") end
    end
    -- Timewarped Replicator: discard your 2 right-most cards (Tavern spells sit right of minions in hand) to
    -- summon a Timewarped Replicator (golden: a Golden one).
    FX["S15_tw_replicator"].dr = function(C, S, m, pos)
        local p = ownerOf(C, S)
        if not p then return end
        local n = 0
        for _ = 1, 2 do
            local list = #p.spellHand > 0 and p.spellHand or p.hand
            if #list == 0 or not E.discardCard(C.g, p, list, #list) then break end
            n = n + 1
        end
        if n == 2 then summon(C, S, "S15_tw_replicator", m.golden and true or false, pos) end
    end
    -- Timewarped Muscle-o-Tron: Mission: double this minion's stats (golden: triple).
    FX["S15_tw_muscle_o_tron"].magnetized = function(g, p, m)
        if p.lastMagnetTarget ~= m then return end
        mission(g, p, m, 3, 1, function() local f = m.golden and 2 or 1; buff(m, m.atk * f, m.hp * f) end)
    end
    -- Timewarped Amalgadon: Deathrattle: Summon two 1/1 Plants (golden: four).
    FX["S15_tw_amalgadon"].dr = function(C, S, m, pos)
        for i = 1, 2 * mult(m) do summon(C, S, TW.PLANT, false, pos + i - 1) end
    end
    -- Timewarped Ball of Minions: give a different friendly minion this minion's stats (golden: double).
    E.registerActivation("S15_tw_ball_of_minions", 3, function(_, _, m, k, t)
        if not t or t == m then return false, "Choose a different friendly minion." end
        buff(t, m.atk * k, m.hp * k)
        return true
    end, function(_, m, t) return t ~= m end)
    -- Timewarped Looter: golden also replaces Tier 3 offers.
    local looterRoll = E.rollTavern
    function E.rollTavern(g, p, ...)
        local a, b, c = looterRoll(g, p, ...)
        if g.season == "s15" and p and p.board then
            local cap = 0
            for _, m in ipairs(p.board) do if m.id == "S15_tw_looter" then cap = math.max(cap, m.golden and 3 or 2) end end
            if cap == 3 then
                p.spellShop = p.spellShop or {}
                for i = #p.tavern, 1, -1 do
                    local t = p.tavern[i]
                    if not t.frozen and (t.cardTier or card(t.id).tier) == 3 then
                        table.remove(p.tavern, i)
                        returnToPool(g, t)
                        table.insert(p.spellShop, instance(g, TW.BOUNTIES[rnd(g, #TW.BOUNTIES)]))
                    end
                end
            end
        end
        return a, b, c
    end
    -- Timewarped Sergeant: improves permanently after this gains Attack, in combat too.
    FX["S15_tw_sergeant"].gainObserved = function(p, C, _, m, target, _, a)
        if m ~= target or not a or a <= 0 then return end
        m.sergeant = (m.sergeant or 0) + 1
        if C and p then
            for _, o in ipairs(p.board) do
                if o.uid == m.src or o.uid == m.uid then o.sergeant = (o.sergeant or 0) + 1; break end
            end
        end
    end
    -- Timewarped Graverobber counts as having a Deathrattle only while it holds a destroyed minion.
    if C_.hasDeathrattle then
        local hasDr = C_.hasDeathrattle
        function C_.hasDeathrattle(m, ...)
            if m and m.id == "S15_tw_graverobber" then return m.graveCopies ~= nil and #m.graveCopies > 0 end
            return hasDr(m, ...)
        end
    end
    end

    register("S15_great_wolf_cub", {bc = function(g, p, _, k) spells(g, p, GB, k) end})
    register("S15_great_direwolf", {onAttack = function(C, S, _, k) spells(C.g, ownerOf(C, S), GB, k) end})
    register("S15_timeless_mount", {dr = function(C, S, _, _, k) spells(C.g, ownerOf(C, S), ER, k) end,
        onAttack = function(C, S, _, k) spells(C.g, ownerOf(C, S), ER, k) end})
    register("S15_effusive_dancer", {bc = function(g, p, _, k) for _ = 1, k do spells(g, p, pick(g, INV), 1) end end,
        dr = function(C, S, _, _, k) for _ = 1, k do spells(C.g, ownerOf(C, S), pick(C.g, INV), 1) end end})
    register("S15_tsunami_surfer", {endTurn = function(g, p, _, k) for _ = 1, k do spells(g, p, pick(g, INV), 1) end end})
    register("S15_thunder_knight", {sell = function(g, p, _, k) spells(g, p, CMD, k) end})
    register("S15_twilight_traverser", {endTurn = function(g, p, _, k) E.chromadrakeReward(g, p, k) end})
    register("S15_surging_sanctifier", {spellTarget = function(g, p, m, k, target) if target == m then for _ = 1, k do E.castSanctify(p) end end end})
    register("S15_dauntless_adventurer", {bc = function(g, p, m, k)
        local opts = {}
        for _, o in ipairs(p.board) do if hasRace(o, "QUILBOAR") then opts[#opts + 1] = o end end
        local t = pick(g, opts)
        if t then E.applyGems(g, p, t, (2 + distinctBonus(p)) * k) end
    end})
    register("S15_land_upheaver", {dr = function(C, S, m, _, k)
        local p = ownerOf(C, S)
        local n = (2 + (p and p.elementalsPlayed or 0)) * k
        for _, o in ipairs(S.list) do if o.hp > 0 and o ~= m and hasRace(o, "ELEMENTAL") then buff(o, n, n) end end
    end}, "Improves by +1/+1 for each Elemental played this game.")
    register("S15_scaled_sovereign", {afterPlay = function(g, p, m, played) if hasRace(played, "DRAGON") then m.activatedTurn = nil end end})
    register("BG36_369", {sell = function(g,p,m)
        if not m.golden then return end
        local title = "Discover a Tier 7 minion"
        if startDiscover(g,p,7,function(c) return c.tier == 7 end,title,nil,m.id) then return end
        local candidates = {}
        for id in pairs(g.allowed or BG_CARDS) do
            local c = card(id)
            if c.tier == 7 and id ~= m.id and not c.buddy then
                local eligible = c.all or #c.races == 0
                for _, race in ipairs(c.races) do if indexOf(g.tribes,race) then eligible = true end end
                if eligible then candidates[#candidates+1] = id end
            end
        end
        if #candidates == 0 then return end
        table.sort(candidates)
        shuffle(g,candidates)
        local options = {}
        for i=1,math.min(3,#candidates) do options[i]=candidates[i] end
        local choice = {options=options,label=title,generated=true}
        if p.discover then table.insert(p.discoverQueue,choice) else p.discover=choice end
    end})
    register("BG36_097", {discard = function(_,p,m,k) friendly(p,4*k,4*k,nil,m) end})
    register("BG36_106", {discard = function(_,p,m,k) buff(m,4*k,4*k); E.deityBless(p,4*k,4*k) end})
    register("BGFYM_005", {discard = function(_,p,m,k)
        local times = m.appearanceCount or 0
        E.deityBless(p,(2+times)*k,(1+times)*k)
        m.appearanceCount = times + 1
    end}, "Each discard increases the bonus by +1/+1.")
    register("BG36_109", {handGained = function(_,p,_,k) E.deityBless(p,4*k,5*k) end})
    register("BG36_318", {dr = function(C,S,_,_,k)
        local p = ownerOf(C,S)
        if p then local n = p.tavernSpellsCast or 0; E.deityBless(p,(2+n)*k,(1+n)*k) end
    end})

    function E.raiseHandGained(g, p)
        for _, m in ipairs(p.board) do
            local f = FX[m.id]
            if f and f.handGained then f.handGained(g,p,m,mult(m)) end
        end
    end

    function E.discardCard(g, p, list, index)
        local entry = list[index]
        if not entry then return false end
        table.remove(list,index)
        if list == p.hand then returnToPool(g,entry) end
        p.discarded = (p.discarded or 0) + 1
        E.refreshGiftAuras(p,"discarded")
        hooks(g,p,"discard",entry,list==p.spellHand)
        for _, m in ipairs(p.board) do
            local f = FX[m.id]
            if f and f.discard then f.discard(g,p,m,mult(m)) end
        end
        if entry.id == "BG36_301t" or entry.id == "BG36_371" then
            E.castGeneratedSpell(g,p,entry.id)
            E.castGeneratedSpell(g,p,entry.id)
        end
        if entry.id == "S15_growing_ooze" then E.s15OozeDiscarded(g,p) end
        return true
    end

    local function linkRewards(g, entries, keep)
        if #entries <= keep then return end
        g.uid = g.uid + 1
        for _, entry in ipairs(entries) do
            entry.discardPair, entry.discardAfter = g.uid, keep
        end
    end
    function E.trinketSpellPair(g,p)
        local pair={}
        for _=1,2 do
            if E.getRandomSpell(g,p,6,false) then pair[#pair+1]=p.spellHand[#p.spellHand] end
        end
        linkRewards(g,pair,1)
    end
    function E.discardPartner(g,p,played)
        if not played.discardPair then return end
        local remaining = (played.discardAfter or 1) - 1
        for _, list in ipairs({p.hand,p.spellHand}) do
            for i = #list, 1, -1 do
                local entry = list[i]
                if entry.discardPair == played.discardPair then
                    if remaining == 0 then E.discardCard(g,p,list,i)
                    else entry.discardAfter = remaining end
                end
            end
        end
    end

    register("BG36_100", {sell = function(g,p,_,k)
        local entries = {}
        for _ = 1, 2*k do
            if not E.getRandomSpell(g,p,6,false) then break end
            entries[#entries+1] = p.spellHand[#p.spellHand]
        end
        linkRewards(g,entries,k)
    end})
    register("BG36_308", {sell = function(g,p,_,k)
        local function aberration(c) return c.all or indexOf(c.races,"ABERRATION") end
        local entries = {}
        for _=1,2*k do
            local reward = giveRandom(g,p,6,1,aberration)
            if not reward then break end
            entries[#entries+1] = reward
        end
        linkRewards(g,entries,k)
    end})
    register("BG36_320", {endTurn = function(g,p,m,k)
        for _=1,3*k do
