    function E.volumizerStats(p,m)
        if not volumeBonus[m.id] then return end
        local a,h = p.volumeAttack or 0,p.volumeHealth or 0
        local da,dh = a-(m.volumeAttack or 0),h-(m.volumeHealth or 0)
        if da ~= 0 or dh ~= 0 then buff(m,da,dh) end
        m.volumeAttack,m.volumeHealth = a,h
    end

    function E.playVolumizer(p,m)
        local effect = volumeBonus[m.id]
        if not effect or m.volumePlayed then return end
        m.volumePlayed = true
        local k = mult(m)
        p.volumeAttack = (p.volumeAttack or 0) + effect[1]*k
        p.volumeHealth = (p.volumeHealth or 0) + effect[2]*k
        for _, list in ipairs({p.hand,p.board,p.tavern}) do
            for _, target in ipairs(list) do E.volumizerStats(p,target) end
        end
        E.volumizerStats(p,m)
    end

    local function token(g,id)
        local m = E.newMinion(g,id,false)
        m.generated = true
        return m
