    function E.confiscateGems(g,p,m)
        E.applyGems(g,p,m,3)
        local i = indexOf(p.board,m)
        for offset=-1,1,2 do
            local adjacent = p.board[i+offset]
            if adjacent then
                local a,h = adjacent.gemAttack or 0,adjacent.gemHealth or 0
                adjacent.atk,adjacent.hp = math.max(0,adjacent.atk-a),math.max(1,adjacent.hp-h)
                adjacent.gemAttack,adjacent.gemHealth = nil,nil
                buff(m,a,h)
                m.gemAttack,m.gemHealth = m.gemAttack+a,m.gemHealth+h
            end
        end
        return true
    end

    function E.openLockbox(g,p)
        for i, entry in ipairs(p.spellHand) do
            if entry.id == "BG36_520t" and (entry.openTurn or math.huge) <= g.turn then
                local reward = drawFromPool(g,g.maxTier or 6,1,function(c) return c.all or #c.races>0 end)
                if reward then
                    table.remove(p.spellHand,i)
                    makeGolden(reward)
                    addToHand(g,p,reward)
                end
                return
            end
        end
    end
    local function lockbox(g,p,_,k)
        if not p then return end
        for _, entry in ipairs(p.spellHand) do
            if entry.id == "BG36_520t" then
                entry.openTurn = (entry.openTurn or g.turn+5)-k
                E.openLockbox(g,p)
                return
            end
        end
        if E.giveSpell(g,p,"BG36_520t") then
            p.spellHand[#p.spellHand].openTurn=g.turn+(indexOf(p.trinkets or {},"BG36_MagicItem_363") and 4 or 5)
        end
    end
    register("BG36_520",{bc=lockbox})
    register("BG36_521",{dr=function(C,S,m,_,k) lockbox(C.g,ownerOf(C,S),m,k) end})
    register("BG36_523",{spend=function(g,p,m,n,k)
        m.escapeGold = (m.escapeGold or 0)+n
        while m.escapeGold>=5 do
            m.escapeGold = m.escapeGold-5
            lockbox(g,p,m,k)
        end
    end})

    local function offerCaptain(p,source,count)
        local options = {}
        for _, m in ipairs(p.board) do
            if m ~= source and not m.golden and card(m.id).tier <= 6 then options[#options+1] = m.uid end
        end
        if #options == 0 then return end
        local choice = {kind="minion_target",minionId="BG25_034",label="Make a friendly minion Golden",
            uid=source.uid,options=options,count=count}
        if p.discover then table.insert(p.discoverQueue,choice) else p.discover=choice end
    end
    register("BG25_034",{bc=function(_,p,m,k) offerCaptain(p,m,k) end})
    function E.chooseCaptain(g,p,index)
        local choice = p.discover
        local id = choice.options[index]
        if not id then return false,"No such option." end
        local source,target
        for _, m in ipairs(p.board) do
            if m.uid == choice.uid then source=m end
            if m.uid == id then target=m end
        end
        p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue,1) or nil
        if target and not target.golden and card(target.id).tier <= 6 then
            makeGolden(target)
            E.bruiserStats(p,target)
        end
        if source and choice.count > 1 then offerCaptain(p,source,choice.count-1) end
        return true
    end

    register("BG32_837",{endTurn=function(g,p,m,k)
        local i = indexOf(p.board,m)
        for offset=-1,1,2 do
            local target = p.board[i+offset]
            if target then for _=1,k do E.castSpellOnBoard(g,p,"BG28_845",target) end end
        end
    end})

    register("BG35_921",{})
    function E.bruiserStats(p,m)
        if m.id ~= "BG35_921" then return end
        local count = p.tavernSpellsCast or 0
        local a,h = count*2*mult(m),count*mult(m)
        local da,dh = a-(m.bruiserAtk or 0),h-(m.bruiserHealth or 0)
        if da ~= 0 or dh ~= 0 then buff(m,da,dh) end
        m.bruiserAtk,m.bruiserHealth = a,h
    end
    function E.updateBruisers(p)
        for _, list in ipairs({p.hand,p.board,p.tavern}) do
            for _, m in ipairs(list) do E.bruiserStats(p,m) end
        end
    end

    function E.boardSpellAura(p)
        local a,h=0,0
        for _,m in ipairs(p.board) do
            local effects=FX[m.id]
            local bonus=effects and effects.spellAura
            if bonus then a,h=a+bonus[1]*mult(m),h+bonus[2]*mult(m) end
            for _,part in ipairs(m.attachments or {}) do
                local f=FX[part.id]
                local added=f and f.spellAura
                if added then local k=part.golden and 2 or 1; a,h=a+added[1]*k,h+added[2]*k end
            end
        end
        return a,h
    end

    function E.afterTargetedSpell(g,p,target,entry)
        hooks(g,p,"spellTarget",target,entry)
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and f.spellTarget then f.spellTarget(g,p,m,mult(m),target,entry) end
        end
    end
end

do
    local function complete(id, effects, note)
        local c = assert(card(id), id)
        c.fx, c.note = note and "simplified" or "full", note
        if effects then FX[id] = effects end
    end

    local function give(g,p,id,n)
        if not p then return end
        for _=1,n do if not E.giveSpell(g,p,id) then break end end
    end

    local function makeToken(g,id)
        local m=E.newMinion(g,id,false)
        m.generated=true
        return m
    end

    local function minionToken(id,name,type,atk,hp,keywords)
        local c=card(id) or {id=id,name=name,tier=1,atk=atk,hp=hp,gatk=atk*2,ghp=hp*2,races=type and {type} or {},fx="full"}
        for k,v in pairs(keywords or {}) do c[k]=v end
        BG_CARDS[id]=c
    end

    local function offer(p,source,label,k,kind,accepts)
        local options={}
        for _,m in ipairs(p.board) do if accepts(m) then options[#options+1]=m.uid end end
        if #options==0 then return end
        local d={kind="minion_target",battleAction=kind,uid=source.uid,label=label,options=options,count=k}
        if p.discover then table.insert(p.discoverQueue,d) else p.discover=d end
    end
    function E.clunkerBattlecry(_,p,m,k)
        offer(p,m,"Choose a friendly Mech",k,"clunker",function(x) return hasRace(x,"MECHANICAL") end)
    end
    function E.finishRecruitTarget(g,p,i)
        local d=p.discover
        local uid=d.options[i]
        local target
        for _,m in ipairs(p.board) do if m.uid==uid then target=m; break end end
        if not target then return false,"That target is unavailable." end
        p.discover= #p.discoverQueue>0 and table.remove(p.discoverQueue,1) or nil
        if d.battleAction=="consume" then
            if #p.tavern>0 then
                local eaten=table.remove(p.tavern,rnd(g,#p.tavern))
                buff(target,eaten.atk*d.count,eaten.hp*d.count)
                returnToPool(g,eaten)
            end
        elseif d.battleAction=="clunker" then
            for _=1,d.count do
                if startDiscover(g,p,p.tier,raceFilter("MECHANICAL"),"Discover a Mech to Magnetize",nil,"BG29_503") then
                    local latest=p.discoverQueue[#p.discoverQueue] or p.discover
                    latest.clunkerTarget=target.uid
                end
            end
        elseif d.battleAction=="copy" then
            E.recruitDeath(g,p,target)
            for _=1,d.count do
                if not addToHand(g,p,makeToken(g,target.id)) then break end
            end
        elseif d.battleAction=="discover" then
            E.recruitDeath(g,p,target)
            for _=1,d.count do startDiscover(g,p,p.tier,raceFilter("UNDEAD"),"Discover an Undead",nil,"BG32_340") end
        end
        checkTriples(g,p)
        return true
    end
    complete("BG23_357",{bc=function(_,p,m,k)
        if #p.tavern>0 then offer(p,m,"Choose a friendly Demon",k,"consume",function(x) return hasRace(x,"DEMON") end) end
    end})
    complete("BG28_303",{bc=function(_,p,m,k)
        offer(p,m,"Choose a friendly Undead",k,"copy",function(x) return x~=m and hasRace(x,"UNDEAD") end)
    end})
    complete("BG32_340",{bc=function(_,p,m,k)
        offer(p,m,"Choose a friendly Undead",k,"discover",function(x) return x~=m and hasRace(x,"UNDEAD") end)
    end})
    complete("BG20_100",{bc=function(g,p,_,k) give(g,p,"BG20_GEM",2*k) end})
    complete("BG23_002",{bc=function(g,p,_,k) give(g,p,"BG28_810",k) end})
    complete("BG26_175",{})
    complete("BG28_583",{})
    complete("BG30_121",{})
    complete("BG31_327",{})
    function E.useCombinedChoice(g,p)
        if p.trailblazer or indexOf(p.trinkets or {},"BG36_MagicItem_308") then return true end
        local available=0
        for _,m in ipairs(p.board) do if m.id=="BG31_327" then available=available+mult(m) end end
        local used=p.combinedTurn==g.turn and p.combinedCount or 0
        if used>=available then return false end
        p.combinedTurn,p.combinedCount=g.turn,used+1
        return true
    end
    function E.gemCasts(p)
        local n=1
        for _,m in ipairs(p.board) do if m.id=="BG30_121" then n=n+mult(m) end end
        return n
    end
    function E.applyGems(g,p,m,count,list,a,h)
        list=list or p.board
        local gemsA,gemsH=a or p.gemA or 1,h or p.gemH or 1
        local visited={}
        local function play(target,n)
            for _=1,n do
                buff(target,gemsA,gemsH)
                target.gemAttack,target.gemHealth=(target.gemAttack or 0)+gemsA,(target.gemHealth or 0)+gemsH
                if target.id=="BG28_583" and indexOf(list,target) and not visited[target] then
                    visited[target]=true
                    local candidates={}
                    for _,other in ipairs(list) do
                        if other~=target and other.hp>0 then candidates[#candidates+1]=other end
                    end
                    local other=pick(g,candidates)
                    if other then play(other,mult(target)) end
                    visited[target]=nil
                end
            end
        end
        play(m,count)
    end

    local function fodderBatch(p,turns,count)
        if not p then return end
        p.fodderBatches=p.fodderBatches or {}
        p.fodderBatches[#p.fodderBatches+1]={left=turns,count=count}
    end
    function E.giftFodder(p,turns) fodderBatch(p,turns or 3,1) end
    minionToken("BG35_150t","Demon Fodder",nil,2,2)
    complete("BG35_150",{bc=function(_,p,_,k) fodderBatch(p,3,k) end})
    complete("BG35_155",{afterSell=function(_,p,_,k) fodderBatch(p,1,k) end})
    complete("BG36_730",{dr=function(C,S,_,_,k) fodderBatch(ownerOf(C,S),3,k) end})
    if card("BG35_151") and not FX.BG35_151 then FX.BG35_151={endTurn=function(_,p,_,k) fodderBatch(p,3,k) end} end
    function E.feedFodder(g,p,resolve)
        local demons=others(p.board,nil,"DEMON")
        if #demons==0 then p.fodderPending=nil;return nil end
        if p.bot then resolve=true end
        local gains
        for i=#p.tavern,1,-1 do
            local food=p.tavern[i]
            if food.id=="BG35_150t" then
                if not resolve then p.fodderPending=true;return nil end
                local eater=pick(g,demons)
                local k=mult(food)
                local a,h=food.atk*k,food.hp*k
                buff(eater,a,h)
                hooks(g,p,"consume",eater,food)
                gains=gains or {}
                local total=gains[eater.uid] or {a=0,h=0}
                total.a,total.h=total.a+a,total.h+h
                gains[eater.uid]=total
                local replacement=drawFromPool(g,p.tier,1)
                if replacement then
                    p.tavern[i]=replacement
                    E.applyTavernBuff(p,replacement)
                    E.updateCardAuras(p,replacement)
                else table.remove(p.tavern,i) end
            end
        end
        p.fodderPending=nil
        return gains
    end

    function E.refreshFodder(g,p)
        p.fodderEpoch=(p.fodderEpoch or 0)+1
        p.fodderPending=nil
        if not p.fodderBatches then return end
        local count=0
        for i=#p.fodderBatches,1,-1 do
            local x=p.fodderBatches[i]
            count=count+x.count
            x.left=x.left-1
            if x.left<=0 then table.remove(p.fodderBatches,i) end
        end
        local max=math.max(6,#p.tavern)
        local extra=math.max(0,count-max)
        if extra>0 then p.fodderBatches[#p.fodderBatches+1]={left=1,count=extra} end
        for i=1,math.min(count,max) do
            local food=makeToken(g,"BG35_150t")
            E.applyTavernBuff(p,food)
            if #p.tavern<max then p.tavern[#p.tavern+1]=food
            else
                for j=#p.tavern,1,-1 do
                    if p.tavern[j].id~="BG35_150t" then
                        returnToPool(g,p.tavern[j]);p.tavern[j]=food;break
                    end
                end
            end
        end
        E.feedFodder(g,p)
    end

    complete("BG32_873",{})
    complete("BG36_733",{heroDamaged=function(g,p,m,k,n)
        m.damageTaken=(m.damageTaken or 0)+n
        while m.damageTaken>=5 do
            m.damageTaken=m.damageTaken-5
            give(g,p,"BG28_607",k)
        end
    end})
    function E.applyAshen(m,a,h)
        buff(m,a,h)
        m.ashenAtk,m.ashenHp=(m.ashenAtk or 0)+a,(m.ashenHp or 0)+h
    end
    function E.expireAshen(m)
        if not m.ashenAtk then return end
        m.atk,m.hp=math.max(0,m.atk-m.ashenAtk),math.max(1,m.hp-m.ashenHp)
        m.ashenAtk,m.ashenHp=nil,nil
    end
    function E.ashenRewind(g,p,m,k)
        p.ashenAtk,p.ashenHp=(p.ashenAtk or 0)+k,(p.ashenHp or 0)+2*k
        for _,target in ipairs(p.tavern) do E.applyAshen(target,k,2*k) end
    end

    function E.updateCardAuras(p,m)
        E.volumizerStats(p,m)
        E.bruiserStats(p,m)
        if p.timewarpBeastA and hasRace(m,"BEAST") then
            local d=p.timewarpBeastA-(m.timewarpBeastAura or 0)
            if d~=0 then buff(m,d,d,true);m.timewarpBeastAura=p.timewarpBeastA end
        end
        local id,k,n,a,h=m.id,mult(m)
        if id=="BG25_008" then n,a,h=(p.ekDeaths or 0)+(p.trinketKnights or 0),4,2
        elseif id=="BG26_537" then n,a,h=p.elementalsPlayed,2,1
        elseif id=="BG_TTN_401" then n,a,h=(p.automatonsSummoned or 0)-(m.ownAutomatonSummons or 0),3,2
        elseif id=="S15_pain_promoter" then n,a,h=p.s15HeroDamage,1,2
        elseif id=="BG36_372" then n,a,h=p.hp<=15 and 1 or 0,30,30
        elseif id=="BG32_HERO_001_Buddy" then n,a,h=math.floor((p.totalGoldSpent or 0)/3),1,1
        elseif id=="BG35_342" then n,a,h=p.drTriggered,4,2
        elseif id=="BG36_524" then n,a,h=p.goldenPlayed,7,7
        elseif id=="S15_tw_duke" then n,a,h=p.discarded,4,4
        elseif id=="BG36_360" and m.paradox==6 then n,a,h=p.battlecries,4,4
        else return end
        n=(n or 0)*k
        local da,dh=a*n-(m.dynamicAtk or 0),h*n-(m.dynamicHp or 0)
        if da~=0 or dh~=0 then buff(m,da,dh,true) end
        m.dynamicAtk,m.dynamicHp=a*n,h*n
        if m.inCombat then m.gA,m.gH=m.gA-da,m.gH-dh end
    end
    function E.refreshCardAuras(p,id)
        for _,list in ipairs({p.board,p.hand,p.tavern}) do
            for _,m in ipairs(list) do if m.id==id then E.updateCardAuras(p,m) end end
        end
    end
    function E.automatonSummoned(p,m,list)
        if m.id~="BG_TTN_401" then return end
        p.automatonsSummoned=(p.automatonsSummoned or 0)+1
        m.ownAutomatonSummons=(m.ownAutomatonSummons or 0)+1
        E.refreshCardAuras(p,m.id)
        if list~=p.board then
            for _,ally in ipairs(list) do if ally.id==m.id then E.updateCardAuras(p,ally) end end
        end
    end
    for _,id in ipairs({"BG25_008","BG35_342","BG36_524"}) do complete(id) end
    complete("BG36_114",{endTurn=function(_,p,_,k)
        local m=p.board[1]
        if m then local n=(2+(p.discarded or 0))*k; buff(m,n,n) end
    end})

    local function satellite(g,p,target,a,h,n)
        if not target or not indexOf(p.board,target) then return end
        local part=makeToken(g,"BG31_171t")
        part.atk,part.hp=a,h
        E.attachMagnetic(g,p,part,target,n)
    end
    minionToken("BG31_171t","Satellite","MECHANICAL",6,6,{magnetic=true})
    complete("BG36_851",{afterPlay=function(g,p,m,played,k)
        if hasRace(played,"MECHANICAL") then
            local n=(2+(m.snapperCount or 0))*k
            satellite(g,p,played,n,n,1)
            m.snapperCount=(m.snapperCount or 0)+1
        end
    end})
    complete("BG36_853",{spellTarget=function(g,p,_,k,target)
        if hasRace(target,"MECHANICAL") then satellite(g,p,target,5,5,k) end
    end})

    minionToken("BG33_890t","Magicfin Apprentice","MURLOC",1,1,{battlecry=true,noTriple=true})
    FX.BG33_890t={bc=function(g,p,m) if m.taughtSpell then E.autoCast(g,p,m.taughtSpell,m) end end}
    complete("BG33_891",{spellBought=function(g,p,m,k,entry)
        if m.lessonTurn~=g.turn then m.lessonTurn,m.lessonCount=g.turn,0 end
        if m.lessonCount>=k or E.handCount(p)>=E.MAX_HAND then return end
        local apprentice=makeToken(g,"BG33_890t")
        apprentice.taughtSpell=entry.id
        if addToHand(g,p,apprentice) then m.lessonCount=m.lessonCount+1 end
    end})
    function E.onSpellBought(g,p,entry)
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and f.spellBought then f.spellBought(g,p,m,mult(m),entry) end
        end
    end
    complete("BG36_344",{discovered=function(_,p,_,k)
        local n=(1+(p.goldenPlayed or 0))*k
        for _,m in ipairs(p.board) do if hasRace(m,"PIRATE") then buff(m,n,n) end end
    end})
    function E.onDiscovered(g,p,picked)
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and f.discovered then f.discovered(g,p,m,mult(m),picked) end
        end
    end

    complete("BG26_525")
    for _,id in ipairs({"BG31_035","BG31_177","BG31_810","BG31_816","BG31_818","BG31_925","BG33_828","BG33_886","BG36_181","BG34_684","BGFYM_005"}) do complete(id) end
end

do
    local function complete(id,effects,note)
        local c=assert(card(id),id)
        c.fx,c.note=note and "simplified" or "full",note
        if effects then FX[id]=effects end
    end
    local function permanent(C,m,a,h)
        buff(m,a,h,true)
        m.permAtk,m.permHp=(m.permAtk or 0)+a,(m.permHp or 0)+h
        C_.trackPermanent(C,m)
    end
    C_.trinketPermanent=permanent
    function C_.trackPermanent(C,m)
        if not m.src or m.trackedPermanent then return end
        m.trackedPermanent=true
        C.permanentMinions=C.permanentMinions or {}
        C.permanentMinions[#C.permanentMinions+1]=m
    end
    local function keywordBaseline(m)
        m.originalKeywords={}
        for _,key in ipairs(BONUS_KW) do m.originalKeywords[key]=m[key] and true or false end
    end
    function C_.keep(C,m,factor,poet)
        if not m.keptKeywords then
            keeper(C,m)
            m.keptKeywords={}
            keywordBaseline(m)
        end
        if poet then
            if not m.keepersFactor and not m.hadPoet then keywordBaseline(m) end
            m.poetFactor=math.max(m.poetFactor or 0,factor)
        else
            m.keepersFactor=factor
        end
    end
    function C_.recordKeptKeywords(C)
        if not C.keepers then return end
        for _,m in ipairs(C.keepers) do
            if m.keepersFactor or m.poetFactor then
                for _,key in ipairs(BONUS_KW) do
                    if m[key] and not m.originalKeywords[key] then m.keptKeywords[key]=true end
                end
            end
        end
    end
    complete("BG21_015")
    complete("BG29_813",{})
    function C_.updatePoets(C,S)
        if not S.hasPoet then
            for _,m in ipairs(S.list) do
                if m.id=="BG29_813" or m.id=="BG34_Giant_314" then S.hasPoet=true;break end
            end
            if not S.hasPoet then return end
        end
        for _,m in ipairs(S.list) do m.hadPoet,m.poetFactor=m.poetFactor,nil end
        for i,m in ipairs(S.list) do
            if m.id=="BG34_Giant_314" and m.hp>0 then
                for _,ally in ipairs(S.list) do if hasRace(ally,"DRAGON") then C_.keep(C,ally,mult(m),true) end end
            elseif m.id=="BG29_813" and m.hp>0 then
                for j=i-1,i+1,2 do
                    local ally=S.list[j]
                    if ally and hasRace(ally,"DRAGON") then C_.keep(C,ally,mult(m),true) end
                end
            end
        end
        for _,m in ipairs(S.list) do m.hadPoet=nil end
    end
    complete("BG26_805",{soc=function(_,S,_,k)
        S.humming=(S.humming or 0)+k
        for _,m in ipairs(S.list) do if m.hp>0 and hasRace(m,"BEAST") then buff(m,k,0) end end
    end})
    complete("BG36_364",{
        soc=function(_,S,m,k)
            local n=m.shieldGrowth or 0
            for _,ally in ipairs(S.list) do if ally.hp>0 then buff(ally,(4+n)*k,(3+n)*k) end end
        end,
        shieldLost=function(C,_,m)
            if m.hp<=0 then return end
            m.shieldGrowth=(m.shieldGrowth or 0)+1
            C_.trackPermanent(C,m)
        end,
    })
    complete("BG33_155",{demonHit=function(C,_,m,k) permanent(C,m,2*k,2*k) end})
    complete("BG33_828",{dr=function(C,S,_,_,k)
        for _,m in ipairs(S.list) do
            if m.hp>0 then
                if m.golden then permanent(C,m,8*k,8*k) else buff(m,8*k,8*k) end
            end
        end
    end})
    complete("BG36_763",{damageDealt=function(C,S,m,k,amount)
        if m.parrotReward then return end
        m.parrotDamage=(m.parrotDamage or 0)+amount
        C_.trackPermanent(C,m)
        if m.parrotDamage<35 then return end
        m.parrotReward=true
        local p=ownerOf(C,S)
        if p then for _=1,k do if not E.giveSpell(C.g,p,"BG28_830") then break end end end
    end})
    function C_.damageDealt(C,defenderSide,source,n)
        local S=source.side and C.sides[source.side] or otherSide(C,defenderSide)
        E.netherDamage(C,S,n)
        local f=FX[source.id]
        if f and f.damageDealt then f.damageDealt(C,S,source,mult(source),n) end
        if not hasRace(source,"DEMON") then return end
        for _,m in ipairs(S.list) do
            local effects=FX[m.id]
            if m~=source and m.hp>0 and effects and effects.demonHit then effects.demonHit(C,S,m,mult(m)) end
        end
    end
    complete("BG34_320",{onAttack=function(C,S,m,k)
        for _=1,k do
            local n=10+(m.lastStanding or 0)
            local used={}
            for _,race in ipairs(C.g.tribes or {}) do
                local options={}
                for _,x in ipairs(S.list) do
                    if x.hp>0 and not used[x] and hasRace(x,race) then options[#options+1]=x end
                end
                local x=pick(C.g,options)
                if x then used[x]=true; permanent(C,x,n,n) end
            end
            m.lastStanding=(m.lastStanding or 0)+1
            C_.trackPermanent(C,m)
        end
    end})
    complete("BG34_322",{combatSummon=function(_,_,m,k,summoned)
        local count=m.kodoSummons or 0
        if count<3 then
            m.kodoSummons=count+1
            buff(summoned,m.atk*(1+k),(m.maxhp or m.hp)*(1+k))
        end
    end})
    complete("BG31_999",{
        soc=function(_,S,m,k)
            local i=indexOf(S.list,m)
            m.stitched={}
            for offset=-1,1,2 do
                local target=S.list[i+offset]
                if (offset==-1 or k==2) and target and target.id~=m.id and target.hp>0 then
                    local saved=copyTable(target)
                    saved.hp=saved.maxhp or saved.hp
                    m.stitched[#m.stitched+1]=saved
                    target.hp=0
                end
            end
        end,
        dr=function(C,S,m,pos)
            for i,saved in ipairs(m.stitched or {}) do
                C_.summonCopy(C,S,saved,pos+i-1)
            end
        end,
    })
    complete("BG34_925",{onAttack=function(C,S,m,k)
        local p=ownerOf(C,S)
        local i=indexOf(S.list,m)
        local right=i and S.list[i+1]
        if not p or not right then return end
        local c=card(right.id)
        for _=1,k do
            if E.handCount(p)>=E.MAX_HAND then break end
            local reward=drawFromPool(C.g,p.tier,1,function(candidate)
                if candidate.id==c.id then return false end
                if c.all then return candidate.all or #candidate.races>0 end
                if candidate.all then return #c.races>0 end
                for _,r in ipairs(c.races) do if indexOf(candidate.races,r) then return true end end
                return false
            end)
            if not reward then break end
            addToHand(C.g,p,reward)
        end
    end})

    local function combatSpell(C,S,id)
        local p=ownerOf(C,S)
        if C.recruit then return E.castGeneratedSpell(C.g,p,id) end
        local a,h=0,0
        if p then a,h=E.spellBonuses(p,livingOf(S)) end
        for _,m in ipairs(S.list) do
            if m.hp>0 then
                if id=="BG28_168" then buff(m,1+a,1+h)
                else
                    local times=1+(hasRace(m,"DRAGON") and 1 or 0)+(m.shield and 1 or 0)
                    buff(m,(3+a)*times,(2+h)*times)
                end
            end
        end
        if p then E.recordCombatSpell(C.g,p,id,S.list) end
    end
    complete("BG36_241",{onAttack=function(C,S,_,k) for _=1,k do combatSpell(C,S,"BG36_246") end end})
    complete("BG36_245",{soc=function(C,S,_,k) for _=1,2*k do combatSpell(C,S,"BG28_168") end end})
    if not card("BG29_864t") then
        BG_CARDS.BG29_864t={id="BG29_864t",name="Deserted Golem",tier=1,atk=5,hp=5,gatk=10,ghp=10,
            races={},fx="full"}
    end
    local function statGolem(C,S,m,k,pos)
        return summon(C,S,"BG29_864t",false,pos,function(golem)
            golem.atk,golem.hp=m.atk*k,math.max(1,m.hp*k)
            if golem.inCombat then golem.maxhp=golem.hp end
        end)
    end
    complete("BG36_333",{onAttack=function(C,S,m,k,target)
        if target and target.hp>0 then
            local golem=statGolem(C,S,m,k,(indexOf(S.list,m) or 1)+1)
            if golem then
                attack(C,S,golem,target)
            end
        end
    end})

    local paradox={
        [3]={tier=2,a=6,h=2}, [4]={tier=5,a=8,h=4}, [5]={tier=4,a=2,h=6},
        [6]={tier=3,a=4,h=4}, [9]={tier=6,a=10,h=2},
    }
    function E.paradoxChoice(g)
        if not g.paradox then
            local options={3,5,6,9}
            if not indexOf(g.tribes or {},"UNDEAD") then options[#options+1]=4 end
            g.paradox=pick(g,options)
        end
        return paradox[g.paradox]
    end
    function E.poolDefinition(g,c)
        if c.id~="BG36_360" then return c end
        local spec=E.paradoxChoice(g)
        g.paradoxDefinition=g.paradoxDefinition or copyTable(c)
        g.paradoxDefinition.tier=spec.tier
        return g.paradoxDefinition
    end
    function E.initParadox(g,m)
        local spec=E.paradoxChoice(g)
        local k=mult(m)
        m.paradox,m.cardTier=g.paradox,spec.tier
        m.atk,m.hp=spec.a*k,spec.h*k
        if m.paradox==4 then m.shield,m.shieldHits=true,2+k end
    end
    function E.goldenParadox(m)
        local spec=paradox[m.paradox]
        if spec then
            buff(m,spec.a,spec.h)
            if m.paradox==4 then m.shieldHits=4 end
        end
    end
    function E.originalStats(m,c)
        local spec=paradox[m.paradox]
        if spec then return spec.a,spec.h end
        return c.atk,c.hp
    end
    function E.paradoxRally(C,S,m,k)
        if m.paradox~=5 then return end
        local p=ownerOf(C,S)
        if not p then return end
        local race,count
        for _,r in ipairs(C.g.tribes or {}) do
            local n=0
            for _,ally in ipairs(S.list) do if ally.hp>0 and hasRace(ally,r) then n=n+1 end end
            if n>0 and (not count or n>count) then race,count=r,n end
        end
        if not race then return end
        for _=1,k do
            if E.handCount(p)>=E.MAX_HAND then break end
            local reward=drawFromPool(C.g,p.tier,1,raceFilter(race))
            if reward then addToHand(C.g,p,reward) end
        end
    end
    complete("BG36_360",{
        onAttack=E.paradoxRally,
        dr=function(C,S,m,pos,k) if m.paradox==9 then statGolem(C,S,m,k,pos) end end,
        cardPlayed=function(_,_,m,k) if m.paradox==3 then buff(m,0,2*k) end end,
    })
    complete("BG27_017",{onAttack=function(C,S,m,k,target)
        if not target then return end
        local enemy=otherSide(C,S)
        local i=indexOf(enemy.list,target)
        if not i then return end
        local left,right=enemy.list[i-1],enemy.list[i+1]
        if left and left.hp<=0 then left=nil end
        if right and right.hp<=0 then right=nil end
        C_.dealDamage(C,enemy,target,m.atk,m)
        if k==2 then
            if left then C_.dealDamage(C,enemy,left,m.atk,m) end
            if right then C_.dealDamage(C,enemy,right,m.atk,m) end
        else
            local adjacent=left and right and pick(C.g,{left,right}) or left or right
            if adjacent then C_.dealDamage(C,enemy,adjacent,m.atk,m) end
        end
    end})
end

do
    local function recruitContext(g,p,enemy)
        return {g=g,active=1,recruit=p,noFrames=true,uid=0,immediate={},sides={
            {n=1,spec={color=p.color},list=p.board,deadMechs={}},
            {n=2,spec={},list=enemy and {enemy} or {},deadMechs={}},
        }}
    end
    function E.recruitDeath(g,p,m)
        if not indexOf(p.board,m) then return false end
        local C=recruitContext(g,p)
        m.recruitDeathHp=m.hp
        m.hp=0
        resolveDeaths(C)
        return true
    end
    local function leftBeast(p)
        for _,m in ipairs(p.board) do if hasRace(m,"BEAST") then return m end end
    end
    if not card("BG36_205") then
        BG_CARDS.BG36_205={id="BG36_205",gid="BG36_205_G",name="Fishbait",tier=1,atk=0,hp=1,gatk=0,ghp=2,
            races={"BEAST"},deathrattle=true,fx="full"}
    end
    BG_ART.BG36_205={n="https://raw.githubusercontent.com/Jnipko488/mtg-table-data/0d1188d1a8dbf1efadffb6d1220d9094c781323a/hsbg/hsjson/v1/bgs/latest/enUS/512x/BG36_205.png",
        g="https://raw.githubusercontent.com/Jnipko488/mtg-table-data/0d1188d1a8dbf1efadffb6d1220d9094c781323a/hsbg/hsjson/v1/bgs/latest/enUS/512x/BG36_205_G.png"}
    FX.BG36_205={dr=function(_,_,m,_,k)
        if m.killedBy and m.killedBy.hp>0 then buff(m.killedBy,5*k,5*k) end
    end}
    function E.fishbait(g,p,entry,golden)
        local pos=entry and indexOf(p.tavern,entry)
        local spellIndex=entry and not pos and indexOf(p.spellShop,entry)
        if entry and not pos and not spellIndex then return false,"That Tavern card is unavailable." end
        local bait=E.newMinion(g,"BG36_205",golden)
        bait.generated=true
        if pos then returnToPool(g,entry); p.tavern[pos]=bait
        else
            if spellIndex then table.remove(p.spellShop,spellIndex) end
            if #p.tavern>=7 then returnToPool(g,table.remove(p.tavern)) end
            p.tavern[#p.tavern+1]=bait
        end
        local beast=leftBeast(p)
        if beast then
            local C=recruitContext(g,p,bait)
            attack(C,C.sides[1],beast,bait)
            if bait.hp<=0 then
                local i=indexOf(p.tavern,bait)
                if i then table.remove(p.tavern,i) end
            end
        end
        return true
    end
    function E.sharkRefresh(g,p,k)
        E.rollTavern(g,p)
        hooks(g,p,"refresh")
        return E.fishbait(g,p,nil,k==2)
    end
    FX.BG36_206={sell=function(g,p,_,k) E.sharkRefresh(g,p,k) end}
    card("BG36_206").fx,card("BG36_206").note="full",nil

    function E.damageRecruitBoard(g,p,race,damage)
        local C=recruitContext(g,p)
        for _,m in ipairs(C.sides[1].list) do
            if m.hp>0 and hasRace(m,race) then dealDamage(C,C.sides[1],m,damage) end
        end
        resolveDeaths(C)
    end
    function E.trinketDeathrattle(g,p,m)
        local C=recruitContext(g,p)
        runDeathrattle(C,C.sides[1],m,indexOf(p.board,m) or #p.board+1)
        resolveDeaths(C)
    end
    function E.canRallyInRecruit(_,source,m)
        if m==source then return false end
        local gift=m.darkGift
        if gift and (gift.charisma or gift.fodderRally or gift.gemRally) then return true end
        return card(m.id).rally and FX[m.id] and FX[m.id].onAttack and m.id~="BG27_017" and m.id~="BG36_333"
    end
    function E.triggerRally(g,p,m,times)
        local C=recruitContext(g,p)
        local f=FX[m.id]
        local triggered=false
        for _=1,times do
            if f and f.onAttack and card(m.id).rally then f.onAttack(C,C.sides[1],m,mult(m)); triggered=true end
            if C_.giftRally(C,C.sides[1],m) then triggered=true end
        end
        return triggered
    end
    function E.cardPlayed(g,p)
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and f.cardPlayed then f.cardPlayed(g,p,m,mult(m)) end
        end
    end
    FX.BG36_362.dr=function(C,S,m,_,k)
        local p=ownerOf(C,S)
        if not p then return end
        local n=m.wrathguardLevel or 0
        local a,h=(2+n)*k,(1+n)*k
        local prior=p.tavBuff.all or {0,0}
        p.tavBuff.all={prior[1]+a,prior[2]+h}
        for _,target in ipairs(p.tavern) do buff(target,a,h) end
    end
end

do
    local function buddy(id, effects)
        local c=card(id)
        if not c then return end
        FX[id]=effects
        c.fx,c.note="full",nil
    end
    local function neighbor(C,S,m,step)
        local index=indexOf(S.list,m)
        return index and S.list[index+step]
    end
    local function grant(g,p,n,low,high,filter)
        if not p then return end
        for _=1,n do
            if E.handCount(p)>=E.MAX_HAND then break end
            local m=drawFromPool(g,high,low,filter)
            if not m then break end
            addToHand(g,p,m)
        end
    end
    buddy("BG20_HERO_102_Buddy",{afterBuyMinion=function(_,_,m,k,bought)
        buff(m,math.floor(bought.atk*k/2),math.floor(bought.hp*k/2))
    end})
    buddy("BG20_HERO_201_Buddy",{soc=function(C,S,m,k)
        local ally=neighbor(C,S,m,-1)
        if ally then buff(ally,0,ally.atk*k) end
    end})
    buddy("BG20_HERO_282_Buddy",{friendlyDeath=function(_,_,m,dead,k) buff(m,dead.atk*k,0) end})
    buddy("BG22_HERO_002_Buddy",{endTurn=function(_,p,_,k) if p.board[1] then buff(p.board[1],10*k,0) end end})
    buddy("BG22_HERO_003_Buddy",{endTurn=function(_,p,_,k) if p.board[#p.board] then buff(p.board[#p.board],0,10*k) end end})
    buddy("BG22_HERO_200_Buddy",{afterPlay=function(_,_,m,played,k)
        if hasRace(played,"MECHANICAL") then buff(m,3*k,3*k) end
    end})
    buddy("BG22_HERO_201_Buddy",{bc=function(g,p,_,k)
        for _,tier in ipairs({1,3,5}) do grant(g,p,k,tier,tier) end
    end})
    buddy("BG23_HERO_201_Buddy",{combatSummon=function(_,_,_,k,m)
        buff(m,m.atk*k,(m.maxhp or m.hp)*k)
    end})
    buddy("BG24_HERO_204_Buddy",{afterBuyMinion=function(_,_,m,k,bought)
        local count=0
        for _,keyword in ipairs(BONUS_KW) do if bought[keyword] then count=count+1 end end
        buff(m,3*k*count,3*k*count)
    end})
    buddy("BG25_HERO_103_Buddy",{friendlyDeath=function(_,_,m,dead,k)
        if not m.buddyDeathUsed then
            m.buddyDeathUsed=true
            buff(m,dead.atk*k,(dead.maxhp or 1)*k)
        end
    end})
    buddy("BG28_HERO_400_Buddy",{startTurn=function(g,p,_,k)
        for _=1,k do E.discoverSpell(g,p,rnd(g,6),true) end
    end})
    buddy("BG28_HERO_801_Buddy",{afterBuyMinion=function(g,p,m,k,bought)
        m.buddyBuys=(m.buddyBuys or 0)+1
        if m.buddyBuys%9~=0 then return end
        local tier=bought.cardTier or card(bought.id).tier
        for _=1,k do E.getRandomSpell(g,p,tier,true) end
    end})
    buddy("BG31_HERO_003_Buddy",{bc=function(g,p,_,k)
        for _=1,k do E.discoverSpell(g,p,6,false,nil,function(s) return s.cost>=3 end) end
    end})
    buddy("TB_BaconShop_HERO_01_Buddy",{cardBought=function(_,_,m,k) buff(m,2*k,2*k) end})
    buddy("TB_BaconShop_HERO_10_Buddy",{endTurn=function(_,p,_,k)
        p.extraMaxGold=(p.extraMaxGold or 0)+k
        p.maxGold=p.maxGold+k
    end})
    buddy("TB_BaconShop_HERO_22_Buddy",{reborned=function(_,_,m,reborn,k) buff(reborn,m.atk*k,0) end})
    buddy("TB_BaconShop_HERO_23_Buddy",{bc=function(g,p,_,k)
        grant(g,p,k,1,6,function(c) return c.battlecry end)
    end})
    buddy("TB_BaconShop_HERO_28_Buddy",{bc=function(g,p,m,k)
        local tier=math.min(g.maxTier or 6,p.tier+1)
        for _=1,k do startDiscover(g,p,tier,function(c) return c.tier==tier end,"Discover a higher-tier minion",nil,m.id) end
    end})
    buddy("TB_BaconShop_HERO_34_Buddy",{endTurn=function(_,p,m,k)
        local i=indexOf(p.board,m)
        if i and p.board[i-1] then buff(p.board[i-1],0,(1+math.max(0,30-p.hp))*k) end
    end})
    buddy("TB_BaconShop_HERO_37_Buddy",{dr=function(C,S,_,_,k)
        local p=ownerOf(C,S)
        grant(C.g,p,k,1,6,raceFilter("DEMON"))
    end})
    buddy("TB_BaconShop_HERO_56_Buddy",{onAttack=function(C,S,_,k) grant(C.g,ownerOf(C,S),k,1,6,raceFilter("DRAGON")) end})
    buddy("TB_BaconShop_HERO_64_Buddy",{endTurn=function(g,p,_,k)
        local options={}
        for _,m in ipairs(p.board) do if m.golden then options[#options+1]=m end end
        local target=pick(g,options)
        if target then buff(target,5*k,5*k) end
    end})
    buddy("TB_BaconShop_HERO_68_Buddy",{sell=function(_,p)
        p.powerUsed,p.powerUses=false,0
    end})
    buddy("TB_BaconShop_HERO_74_Buddy",{endTurn=function(g,p,_,k) grant(g,p,k,p.tier,p.tier) end})
    buddy("TB_BaconShop_HERO_76_Buddy",{dr=function(C,S,_,_,k)
        local targets=livingOf(S)
        shuffle(C.g,targets)
        for i=1,math.min(k,#targets) do
            local m=targets[i]
            m.windfury,m.shield,m.taunt=true,true,true
        end
    end})
    buddy("BG20_HERO_100_Buddy",{allyKill=function(C,_,m,k)
        buff(m,0,3*k)
        if m.src then
            m.permHp=(m.permHp or 0)+3*k
            C_.trackPermanent(C,m)
        end
    end})
    buddy("BG20_HERO_101_Buddy",{afterPlay=function(_,_,m,played,k)
        if played.atk<m.atk then
            local n=(1+(m.buddyGrowth or 0))*k
            buff(played,n,n)
            m.buddyGrowth=(m.buddyGrowth or 0)+1
        end
    end})
    buddy("BG20_HERO_103_Buddy",{})
    function E.extraBloodGems(p)
        local n=0
        for _,m in ipairs(p.board) do if m.id=="BG20_HERO_103_Buddy" then n=n+mult(m) end end
        return n
    end
    buddy("BG21_HERO_020_Buddy",{})
    function E.extraHeroUses(p)
        local n=0
        for _,m in ipairs(p.board) do if m.id=="BG21_HERO_020_Buddy" then n=n+mult(m) end end
        return n
    end
    buddy("TB_BaconShop_HERO_11_Buddy",{})
    buddy("TB_BaconShop_HERO_45_Buddy",{allyKill=function(C,S,m,k,defeated)
        m.buddyKills=(m.buddyKills or 0)+1
        if m.buddyKills~=2 then return end
        local p=ownerOf(C,S)
        if not p then return end
        for _=1,k do
            if E.handCount(p)>=E.MAX_HAND then break end
            local copy=E.newMinion(C.g,defeated.id,false)
            copy.generated=true
            addToHand(C.g,p,copy)
        end
    end})
    function C_.buddyKill(C,defending,source,target)
        local side=source.side and C.sides[source.side] or otherSide(C,defending)
        if side==defending then return end
        E.heroCombatKill(C,side,source,target)
        for _,m in ipairs(side.list) do
            local f=m.hp>0 and FX[m.id]
            if f and f.allyKill then f.allyKill(C,side,m,mult(m),target) end
            if f and m==source and f.onAnyKill then f.onAnyKill(C,side,m,target,mult(m)) end
        end
    end
    buddy("TB_BaconShop_HERO_72_Buddy",{tavernSpell=function(_,p,_,k)
        if p.lastSpell=="BG28_810" or p.lastSpell=="BG36_303" then p.gold=math.min(99,p.gold+k) end
    end})
    buddy("TB_BaconShop_HERO_90_Buddy",{discovered=function(_,_,m,k,picked)
        if not picked then return end
        local n=(2+(m.discoverGrowth or 0))*k
        buff(picked,n,n)
        m.discoverGrowth=(m.discoverGrowth or 0)+1
    end})
    buddy("BG31_HERO_006_Buddy",{spellBought=function(g,p,_,k,entry)
        if entry.paidGold~=0 then return end
        for _=1,k do if not E.cloneSpellEntry(g,p,entry) then break end end
    end})
    buddy("BG31_HERO_802_Buddy",{})
end

do
    local function complete(id, effect)
        local c = assert(card(id), id)
        assert(c.fx == "none", id)
        FX[id], c.fx, c.note = effect, "full", nil
    end

    local function higherTier(g, old, amount, limit)
        local current = card(old.id).tier
        local tier = math.min(current + amount, limit)
        if tier <= current then return nil end
        local replacement = drawFromPool(g, tier, tier)
        if replacement then returnToPool(g, old) end
        return replacement
    end

    complete("BG20_HERO_242_Buddy", {bc = function(g, p)
        clearTavern(g, p)
        p.frozen = false
        for tier = 1, p.maxTier or 6 do
            local m = drawFromPool(g, tier, tier)
            if m then
                E.applyTavernBuff(p, m)
                E.updateCardAuras(p, m)
                p.tavern[#p.tavern + 1] = m
            end
        end
        if #p.tavern == 7 then p.spellShop = {} else E.rollSpellShop(g, p) end
        E.spellRefresh(g, p)
        E.refreshFodder(g, p)
        E.spellcraftTavern(g, p)
        hooks(g, p, "refresh")
    end})

    complete("BG20_HERO_280_Buddy", {cardBought = function(_, p, _, k)
        local boost = 2 * k
        p.ashenAtk, p.ashenHp = (p.ashenAtk or 0) + boost, (p.ashenHp or 0) + boost
        for _, m in ipairs(p.tavern) do E.applyAshen(m, boost, boost) end
    end})

    complete("BG27_HERO_801_Buddy", {endTurn = function(g, p, m, k)
        local i = indexOf(p.board, m)
        local left = i and p.board[i - 1]
        if left then p.board[i - 1] = higherTier(g, left, k, g.maxTier or 6) or left end
    end})

    complete("BG28_HERO_800_Buddy", {tavernSpell = function(g, p, m, k)
        if m.reliquaryTurn == g.turn then return end
        m.reliquaryTurn = g.turn
        for _ = 1, k do if not E.giveSpell(g, p, p.lastSpell) then break end end
    end})

    complete("TB_BaconShop_HERO_02_Buddy", {bc = function(g, p, _, k)
        for i, old in ipairs(p.tavern) do
            local replacement = higherTier(g, old, k, p.maxTier or 6)
            if replacement then
                E.applyTavernBuff(p, replacement)
                E.updateCardAuras(p, replacement)
                p.tavern[i] = replacement
            end
        end
        E.raiseTavernSpells(g, p, k)
    end})

    complete("TB_BaconShop_HERO_17_Buddy", {dr = function(C, S, _, _, k)
        local enemy = otherSide(C, S)
        for _ = 1, #S.deadMechs do
            local alive = {}
            for _, m in ipairs(enemy.list) do if m.hp > 0 then alive[#alive + 1] = m end end
            local target = pick(C.g, alive)
            if not target then break end
            C_.dealDamage(C, enemy, target, 4 * k)
        end
    end})

    complete("TB_BaconShop_HERO_702_Buddy", {dr = function(C, S, _, slot, k)
        local options = {}
        for id in pairs(C.g.pool) do
            if card(id).tier <= (C.g.maxTier or 6) and hasRace({id = id}, "UNDEAD") then
                options[#options + 1] = id
            end
        end
        table.sort(options)
        for i = 1, 2 * k do
            local id = pick(C.g, options)
            if not id or not summon(C, S, id, false, slot + i - 1) then break end
        end
    end})

    complete("BG26_HERO_104_Buddy", {endTurn = function(g, p, m, k)
        if m.akaliTurn == g.turn then return end
        m.akaliTurn = g.turn
        m.akaliTicks = ((m.akaliTicks or 0) + 1) % (k == 2 and 1 or 2)
        if m.akaliTicks ~= 0 then return end
        local left = p.hand[1]
        if left then
            local copy = E.newMinion(g, left.id, left.golden)
            copy.generated = true
            E.addToHand(g, p, copy)
        elseif p.spellHand[1] then
            E.giveSpell(g, p, p.spellHand[1].id)
        end
    end})
end

do
    -- Out-of-rotation minions (seen with the full minion pool) scripted in the Quests update.
    local function done(id, effect, note)
        local c = card(id)
        if not c or c.fx ~= "none" or FX[id] then return end   -- never override an existing script
        FX[id], c.fx, c.note = effect, note and "simplified" or "full", note
    end
    local function give(g, p, id, n)
        if not p then return end
        for _ = 1, n do if not E.giveSpell(g, p, id) then break end end
    end
    local function others(list, m, filter)
        local out = {}
        for _, o in ipairs(list) do
            if o ~= m and (o.hp == nil or o.hp > 0) and (not filter or filter(o)) then out[#out + 1] = o end
        end
        return out
    end
    local function murloc(o) return hasRace(o, "MURLOC") end

    -- Deathrattle summons
    done("BG21_029", {dr = function(C, S, m, pos, k)                  -- Icky Imp: two 1/1 Imps
        for i = 1, 2 * k do summon(C, S, "BG_BRM_006t", m.golden, pos + i - 1) end end})
    -- Recruit-phase effects
    done("BG20_301", {sell = function(g, p, _, k) give(g, p, "BG20_GEM", 2 * k) end})          -- Sun-Bacon Relaxer
    done("BG28_590", {endTurn = function(_, _, m, k) buff(m, k, 0) end})                       -- Emerald Proto-Whelp
    done("BG28_402", {startTurn = function(_, _, m, k) m.atk = math.max(0, m.atk - k) end})    -- Beleaguered Battler
    done("BG20_203", {afterPlay = function(g, p, _, played, k)                                 -- Prophet of the Boar
        if hasRace(played, "QUILBOAR") then give(g, p, "BG20_GEM", k) end end})
    done("BG26_969", {endTurn = function(_, p, m, k)                                           -- Low-Flier
        for _, o in ipairs(p.board) do if o ~= m and o.atk < m.atk then buff(o, k, 0) end end end})
    done("BG28_593", {endTurn = function(_, p, m, k)                                           -- Bronze Sandspewer
        if #p.board >= 7 then buff(m, 2 * k, k) end end})
    done("BG32_331", {endTurn = function(g, p, m, k)                                           -- Grimscale Elegist
        for _ = 1, k do
            local a = pick(g, p.board); if a then buff(a, 1, 1) end
            local b = pick(g, p.hand or {}); if b then buff(b, 1, 1) end
        end end})
    done("BG33_826", {tavernSpell = function(_, _, m, k) buff(m, k, k) end})                   -- Wizened Captain
    done("BG23_001", {anySpell = function(g, _, m, k)                                          -- Snail Cavalry
        if m.snailTurn == g.turn then return end
        m.snailTurn = g.turn; buff(m, k, k) end})
    done("BG_EX1_103", {bc = function(_, p, m, k)                                              -- Coldlight Seer
        for _, o in ipairs(others(p.board, m, murloc)) do buff(o, 0, 2 * k) end end})
    done("BG_UNG_073", {bc = function(g, p, m, k)                                              -- Rockpool Hunter
        local o = pick(g, others(p.board, m, murloc)); if o then buff(o, k, k) end end},
        "Buffs a random friendly Murloc instead of a chosen one.")
    done("BG30_756", {bc = function(g, p, m, k)                                                -- Parched Wanderer
        local o = pick(g, others(p.board, m, murloc)); if o then buff(o, 2 * k, 3 * k); o.taunt = true end end},
        "Buffs a random friendly Murloc instead of a chosen one.")
    done("BG26_529", {endTurn = function(g, p, m, k)                                           -- Upbeat Frontdrake
        m.frontdrakeTurns = (m.frontdrakeTurns or 0) + 1
        if m.frontdrakeTurns % 3 ~= 0 then return end
        for _ = 1, k do
            if E.handCount(p) >= E.MAX_HAND then break end
            local d = drawFromPool(g, p.tier, 1, function(c) return indexOf(c.races, "DRAGON") end)
            if not d then break end
            if not addToHand(g, p, d) then returnToPool(g, d); break end
        end end})
    -- Combat effects
    done("BG29_814", {soc = function(C, S, m, k)                                               -- Misfit Dragonling
        local p = ownerOf(C, S); local t = (p and p.tier or 1) * k; buff(m, t, t) end})
    done("BG33_241", {onAttack = function(C, S, m, k)                                          -- Sleepy Supporter (Rally)
        local i = indexOf(S.list, m); local o = i and S.list[i + 1]
        if o and o.hp > 0 then buff(o, 2 * k, 2 * k) end end})
    done("BG33_325", {onAttack = function(C, S, m, k)                                          -- Geared Guard (Rally)
        for _ = 1, k do
            local o = pick(C.g, others(S.list, m, function(x) return not x.shield end))
            if o then o.shield = true end
        end end})
    done("BG23_350", {onAttack = function(C, S, m, k)                                          -- Yrel
        for race in pairs(E.RACE_NAME) do
            local o = pick(C.g, others(S.list, m, function(x) return hasRace(x, race) end))
            if o then buff(o, k, 2 * k) end
        end end}, "Triggers as it attacks rather than after.")
end

do
    local function finish(id,effect)
        local c=assert(card(id),id)
        assert(c.fx=="none",id)
        FX[id],c.fx,c.note=effect or assert(FX[id],id),"full",nil
    end
    local function copyInHand(g,p,id,n)
        for _=1,n do
            if E.handCount(p)>=E.MAX_HAND then break end
            local m=E.newMinion(g,id,false)
            m.generated=true
            addToHand(g,p,m)
        end
    end
    local function randomTop(g,list)
        local high,eligible=0,{}
        for _,m in ipairs(list) do
            local tier=m.cardTier or card(m.id).tier
            if tier>high then high,eligible=tier,{} end
            if tier==high then eligible[#eligible+1]=m end
        end
        return pick(g,eligible)
    end
    local function dress(p,m)
        E.applyTavernBuff(p,m)
        E.updateCardAuras(p,m)
        return m
    end
    finish("BG23_HERO_305_Buddy",{bc=function(g,p)
        clearTavern(g,p)
        p.frozen=false
        for _,color in ipairs(g.order) do
            local foe=g.players[color]
            if foe and foe~=p and foe.alive then
                local original=randomTop(g,foe.board)
                if original and #p.tavern<7 then
                    local m=E.newMinion(g,original.id,false)
                    m.generated=true
                    p.tavern[#p.tavern+1]=dress(p,m)
                end
            end
        end
        if #p.tavern<7 then E.rollSpellShop(g,p) else p.spellShop={} end
        E.spellRefresh(g,p)
        E.refreshFodder(g,p)
        E.spellcraftTavern(g,p)
        hooks(g,p,"refresh")
    end})
    finish("BG26_HERO_101_Buddy",{tavernExtra=function(g,p,k)
        for _=1,k do
            local m=drawFromPool(g,p.tier,1,function(c) return indexOf(c.races,"PIRATE") end)
            if m then p.tavern[#p.tavern+1]=m end
        end
    end})
    finish("BG32_HERO_001_Buddy",{})
    finish("TB_BaconShop_HERO_16_Buddy",{endTurn=function(g,p,m,k)
        local list={}
        for _,o in ipairs(p.board) do if o~=m and card(o.id).tier==3 then list[#list+1]=o end end
        for _=1,k do local o=pick(g,list);if o then buff(o,m.atk,m.hp) end end
    end})
    finish("TB_BaconShop_HERO_36_Buddy",{afterSell=function(_,_,m,k)
        m.buddyHats=(m.buddyHats or 0)+2*k
        buff(m,2*k,2*k)
    end})
    finish("TB_BaconShop_HERO_38_Buddy",{anySpell=function(_,_,m)
        m.monkeySpells=(m.monkeySpells or 0)+1
    end,sell=function(_,p,m,k)
        local n=k+math.floor((m.monkeySpells or 0)/2)
        for _,o in ipairs(p.board) do buff(o,n,n) end
    end})
    finish("TB_BaconShop_HERO_43_Buddy",{dr=function(C,S,_,pos,k)
        local p=ownerOf(C,S)
        for i=1,k do
            local m=drawFromPool(C.g,p and p.tier or 6,1,function(c)return c.battlecry end)
            if m then
                summon(C,S,m.id,false,pos+i-1)
                if not p or not addToHand(C.g,p,m) then returnToPool(C.g,m) end
            end
        end
    end})
    finish("TB_BaconShop_HERO_49_Buddy",{})
    function E.magnusRefreshes(g,p)
        local amount=0
        for _,m in ipairs(p.board) do if m.id=="TB_BaconShop_HERO_49_Buddy" then amount=amount+2*mult(m) end end
        local turn=g and g.turn or p.trinketGameTurn
        return math.max(0,amount-(p.magnusTurn==turn and (p.magnusUsed or 0) or 0))
    end
    finish("TB_BaconShop_HERO_50_Buddy",{startTurn=function(g,p,_,k)
        local foe=g.players[p.lastOpponent]
        if not foe and p.lastOpponent=="ghost" then foe=g.eliminated[#g.eliminated] end
        local buddy=foe and E.buddyFor(foe)
        if buddy then copyInHand(g,p,buddy.id,k) end
    end})
    finish("TB_BaconShop_HERO_55_Buddy",{bc=function(g,p,_,k)
        for i,old in ipairs(p.tavern) do
            local tier=math.min(p.maxTier or 6,card(old.id).tier+k-1)
            local m=drawFromPool(g,tier,tier,function(c) return indexOf(c.races,"MURLOC") end)
            if m then returnToPool(g,old);p.tavern[i]=dress(p,m) end
        end
    end})
    finish("TB_BaconShop_HERO_59_Buddy",{tavernExtra=function(g,p,k)
        local tier=math.min(p.tier+1,p.maxTier or 6)
        for _=1,k do
            local m=drawFromPool(g,tier,tier)
            if m then p.tavern[#p.tavern+1]=m end
        end
    end})
    finish("TB_BaconShop_HERO_60_Buddy",{verdant=function(_,_,m,k,bought) buff(m,bought.atk*k,bought.hp*k) end})
    finish("TB_BaconShop_HERO_70_Buddy",{startTurn=function(g,p,_,k)
        local hp,foes=math.huge,{}
        for _,color in ipairs(g.order) do
            local foe=g.players[color]
            if foe~=p and foe.alive then
                if foe.hp<hp then hp,foes=foe.hp,{} end
                if foe.hp==hp then foes[#foes+1]=foe end
            end
        end
        local foe=pick(g,foes)
        if foe then
            for _=1,k do local m=pick(g,foe.board);if m then copyInHand(g,p,m.id,1) end end
        end
    end})
    finish("TB_BaconShop_HERO_71_Buddy",{})
    function E.recordMinionPlayed(g,p,m)
        if p.repeatPlayTurn~=g.turn then p.repeatPlayTurn,p.repeatPlays=g.turn,{} end
        local old=p.repeatPlays[m.id]
        p.repeatPlays[m.id]=true
        if not old then return end
        for _,o in ipairs(p.board) do
            if o.id=="TB_BaconShop_HERO_71_Buddy" then
                local n=p.tier*mult(o)
                for _,ally in ipairs(p.board) do buff(ally,n,n) end
            end
        end
    end
    finish("TB_BaconShop_HERO_91_Buddy",{sell=function(g,p,m,k)
        local counts,ids={},{}
        for _,list in ipairs({p.board,p.hand}) do
            for _,o in ipairs(list) do if o.id~=m.id then counts[o.id]=(counts[o.id] or 0)+1 end end
        end
        for id,n in pairs(counts) do if n==1 then ids[#ids+1]=id end end
        if #ids==0 then return end
        table.sort(ids)
        for _=1,k do
            shuffle(g,ids)
            local d={options={},generated=true,label="Phyresz: Discover a plain copy"}
            for i=1,math.min(3,#ids) do d.options[i]=ids[i] end
            if p.discover then p.discoverQueue[#p.discoverQueue+1]=d else p.discover=d end
        end
    end})
    finish("TB_BaconShop_HERO_92_Buddy",{})
    function E.buddySummoned(p,m,list)
        if (m.cardTier or card(m.id).tier)~=p.tier then return end
        for _,o in ipairs(list) do
            if o~=m and o.id=="TB_BaconShop_HERO_92_Buddy" and o.hp>0 then
                local n=mult(o)
                for _,ally in ipairs(list) do if ally.hp>0 then buff(ally,n,n) end end
            end
        end
    end
end

do
    local function restored(id,effects)
        card(id).fx,card(id).note="full",nil
        if effects then FX[id]=effects end
    end

    local function gain(g,p,id,n)
        if not p then return end
        for _=1,n do if not E.giveSpell(g,p,id) then break end end
    end

    local function getMinions(g,p,n,high,filter)
        if not p then return end
        for _=1,n do
            if E.handCount(p)>=E.MAX_HAND then break end
            local m=drawFromPool(g,high,1,filter)
            if not m then break end
            addToHand(g,p,m)
        end
    end

    local function elementalShop(_,p,_,k,amount)
        if not p then return end
        local n=amount*k
        local prev=p.tavBuff.ELEMENTAL or {0,0}
        p.tavBuff.ELEMENTAL={prev[1]+n,prev[2]+n}
        for _,m in ipairs(p.tavern) do if hasRace(m,"ELEMENTAL") then buff(m,n,n) end end
    end

    local function giveSpellEffects(id,count)
        return {
            bc=function(g,p,_,k) gain(g,p,id,count*k) end,
            dr=function(C,S,_,_,k) gain(C.g,ownerOf(C,S),id,count*k) end,
        }
    end

    restored("BG24_004")
