            C.g.raptorBeasts=pool
        end
        local id=pick(C.g,C.g.raptorBeasts)
        if id then
            summon(C,S,id,false,pos,function(m)
                m.atk,m.hp,m.maxhp=6*k,6*k,6*k
                m.dynamicAtk,m.dynamicHp=0,0
            end)
        end
    end})
    restored("BG26_148",{dr=function(C,S,_,_,k)
