    restored("BG32_170",{dr=giveSpellEffects("EBG_Spell_014",1).dr})
    restored("BG32_172",{dr=function(C,S,m,slot,k) summon(C,S,"BG_TTN_401",k==2,slot) end})
    restored("BG32_822",{
        soc=function(_,S,m,k)
