    restored("BG35_140",{bc=function(_,p,m,k) mrrglton(p,m,k,true) end})
    restored("BG35_141",{bc=function(_,p,m,k) mrrglton(p,m,k,false) end})
    restored("BG35_142",{endTurn=function(g,p,_,k)
        for i=1,k do
            local id=(k==1 and pick(g,{"BG35_140","BG35_141"})) or (i==1 and "BG35_140" or "BG35_141")
            local m=E.newMinion(g,id,false)
