do
    local owners=setmetatable({},{__mode="k"})
    local active={}
    function E.bindStatCard(p,m,C,S)
        if not m or not p then return end
        local f=FX[m.id]
        if f and (f.gainObserved or f.handGainObserved) then p.statWatch=true end
        owners[m]={p=p,C=C,S=S}
    end
    function E.bindExistingStatCards(p)
        for _,list in ipairs({p.board,p.hand,p.tavern}) do
            for _,m in ipairs(list) do E.bindStatCard(p,m) end
        end
    end
    function E.notifyStats(m,a,h)
        if a<=0 and h<=0 then return end
        local entry=owners[m]
        local p=entry and entry.p
        if not p or not p.statWatch then return end
        local C,S=entry.C,entry.S
        local board=S and S.list or p.board
        local onBoard=indexOf(board,m)
        if not onBoard and (S or not indexOf(p.hand,m)) then return end
        local function apply(list,prop)
            for _,observer in ipairs(list) do
                local f=observer.hp>0 and FX[observer.id]
                if f and f[prop] and not active[observer] then
                    active[observer]=true
                    f[prop](p,C,S,observer,m,mult(observer),math.max(0,a),math.max(0,h),onBoard~=nil)
                    active[observer]=nil
                end
            end
        end
        apply(board,"gainObserved")
        if onBoard then apply(p.hand,"handGainObserved") end
    end
end

do
    local cardIds={}
    for id in pairs(BG_TIMEWARP) do cardIds[#cardIds+1]=id end
    table.sort(cardIds)

    local function matchesTribes(g,def)
        if #def.tribes==0 then return true end
        for _,race in ipairs(def.tribes) do
            if race=="ALL" or indexOf(g.tribes,race) then return true end
        end
        return false
    end

    function E.timewarpCards(g,tier,filter)
        local options={}
        for _,id in ipairs(cardIds) do
            local d=BG_TIMEWARP[id]
            if d.tier==tier and matchesTribes(g,d) and (not filter or filter(d,id)) then
                local implemented=d.kind=="minion" and card(id).fx=="full" or
                    d.kind~="minion" and E.SPELLS[id]~=nil
                if implemented then options[#options+1]=id end
            end
        end
        return options
    end

    function E.openTimewarp(g,p,tier)
        if p.timewarpVisit or E.skipsRecruit(g,p) then return false end
        local options=E.timewarpCards(g,tier,function(d,id)
            if id=="BG34_Treasure_902" or id=="BG34_Treasure_966" then return p.lastGameBoard and #p.lastGameBoard>0 end
            return (not d.heroPower or not E.hasPower(p,d.heroPower))
        end)
        if #options==0 then return false end
        shuffle(g,options)
        local budget=2+(p.nextChronum or 0)
        local slots=E.timewarpSlots(g,p,options,tier)
        p.nextChronum=0
        p.timewarpVisit={turn=g.turn,tier=tier,slots=slots,chronum=budget,revision=0}
        p.ready=false
        return true
    end

    function E.timewarpOnTurn(g,p)
        local h=E.powerHero(p)
        local id=h and h.id
        local morchie,murozond=E.hasPower(p,"BG34_HERO_004"),E.hasPower(p,"BG34_HERO_000")
        if g.turn==5 and morchie or g.turn==6 and g.timewarpEnabled and not morchie then
            E.openTimewarp(g,p,3)
        elseif g.turn==8 and murozond or g.turn==9 and g.timewarpEnabled and not murozond then
            E.openTimewarp(g,p,5)
        end
    end

    function E.finishTimewarp(g,p)
        if not p.timewarpVisit then return false end
        p.timewarpVisit=nil
        checkTriples(g,p)
        return true
    end

    function E.timewarpPick(g,color,index)
        local p=g.players[color]
        local visit=p and p.timewarpVisit
        if g.phase~="recruit" or g.recruitClosed or not p or not p.alive or not visit or visit.turn~=g.turn then
            return false,"The Timewarped Tavern is closed."
        end
        local slot=visit.slots[index]
        if not slot or slot.taken then return false,"That card is unavailable." end
        local id=slot.id
        local offer=BG_TIMEWARP[id]
        if visit.chronum<offer.cost then return false,"You need "..offer.cost.." Chronum." end
        if offer.kind=="minion" then
            local m=E.newMinion(g,id,false)
            m.generated=true
            E.updateCardAuras(p,m)
            E.bindStatCard(p,m)
            p.hand[#p.hand+1]=m
            E.raiseHandGained(g,p)
        elseif offer.immediate then
            if not E.castGeneratedSpell(g,p,id) then return false,"That effect is unavailable." end
        elseif not E.giveSpell(g,p,id,true) then
            return false,"That card is unavailable."
        end
        slot.taken=true
        visit.chronum=visit.chronum-offer.cost
        visit.revision=visit.revision+1
        for _,o in ipairs(visit.slots) do
            if not o.taken and BG_TIMEWARP[o.id].cost<=visit.chronum then return true end
        end
        E.finishTimewarp(g,p)
        return true
    end

    function E.discoverLastWarband(g,p,keep)
        local list=copyTable(p.lastGameBoard or {})
        shuffle(g,list)
        local ids,copies={},{}
        for i=1,math.min(3,#list) do ids[i]=list[i].id;copies[tostring(i)]=list[i] end
        local d={moreHeroChoice="bigglesworth",label="Discover from your last warband",options=ids,
            copies=copies,plainLastWarband=not keep}
        if #ids==0 then return false,"There is no previous warband saved." end
        if p.discover then p.discoverQueue[#p.discoverQueue+1]=d else p.discover=d end
        return true
    end

    function E.botTimewarp(g,p)
        while p.timewarpVisit do
            local visit=p.timewarpVisit
            local chosen,best
            for i,offer in ipairs(visit.slots) do
                local def=BG_TIMEWARP[offer.id]
                if not offer.taken and def.cost<=visit.chronum then
                    local c=def.kind=="minion" and card(offer.id)
                    local score=c and (c.atk+c.hp+1)/def.cost or 2
                    if not best or score>best then chosen,best=i,score end
                end
            end
            if not chosen or not E.timewarpPick(g,p.color,chosen) then E.finishTimewarp(g,p) end
        end
    end

    function E.timewarpBuyCard(g,p,entry)
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and f.buyCard then f.buyCard(g,p,m,mult(m),entry) end
        end
    end

    function E.observeConsumption(g,p,entry)
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and f.consumeObserved then f.consumeObserved(g,p,m,mult(m),entry) end
        end
    end

    local function discountMinion(p)
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            local d=f and f.spellDiscount
            if d and (m.timewarpDiscountUses or 0)<d.count*mult(m) then return m,d.amount end
        end
    end
    function E.timewarpSpellDiscount(p)
        local _,amount=discountMinion(p)
        return amount or 0
    end
    function E.consumeTimewarpDiscount(p)
        local m=discountMinion(p)
        if m then m.timewarpDiscountUses=(m.timewarpDiscountUses or 0)+1 end
    end
    function E.offerMinionChoice(g,p,options,label,details)
        if #options==0 then return false end
        local d=details or {}
        d.options,d.label,d.generated=options,label,true
        if p.discover then p.discoverQueue[#p.discoverQueue+1]=d else p.discover=d end
        return true
    end

    function E.timewarpWheel(g,p,count)
        local spin=rnd(g,6)
        if spin==1 then
            for _,m in ipairs(p.board) do buff(m,3*count,3*count) end
        elseif spin==2 then
            p.gold=math.min(99,p.gold+3*count)
        elseif spin==3 then
            for _=1,3*count do E.giveSpell(g,p,"BG28_897") end
        elseif spin==4 then
            for _=1,count do E.getRandomSpell(g,p,p.tier,false) end
        elseif spin==5 then
            for _,m in ipairs(p.tavern) do buff(m,3*count,3*count) end
        elseif #p.board>1 then
            local offering=pick(g,p.board)
            local a,h=offering.atk,offering.hp
            for _,m in ipairs(p.board) do if m~=offering then buff(m,a*count,h*count) end end
            offering.atk,offering.hp=1,1
        end
    end

    function E.copyCombatDeathrattles(m,from,times)
        m.timewarpDeathrattles=m.timewarpDeathrattles or {}
        for _=1,times do
            if FX[from.id] and FX[from.id].dr then
                m.timewarpDeathrattles[#m.timewarpDeathrattles+1]={id=from.id,k=mult(from)}
            end
            for _,part in ipairs(from.attachments or {}) do
                if FX[part.id] and FX[part.id].dr then
                    m.timewarpDeathrattles[#m.timewarpDeathrattles+1]={id=part.id,k=part.golden and 2 or 1}
                end
            end
        end
    end

    local function offerDiscovery(g,p,ids,details)
        if #ids==0 then return false end
        shuffle(g,ids)
        local options={}
        for i=1,math.min(3,#ids) do options[i]=ids[i] end
        details.options,details.generated=options,true
        if p.discover then p.discoverQueue[#p.discoverQueue+1]=details else p.discover=details end
        return true
    end

    function E.discoverTimewarp(g,p,tier,cost,kind,lock)
        local ids=E.timewarpCards(g,tier,function(d) return (not kind or d.kind==kind) and (not cost or d.cost==cost) end)
        return offerDiscovery(g,p,ids,{label=kind and "Discover a Timewarped minion" or "Discover a Timewarped card",
            timewarpMixed=not kind,unlockTurn=lock})
    end

    function E.discoverTierSeven(g,p,n,golden,transform)
        local ids={}
        for id in pairs(g.allowed or g.pool) do
            local c=card(id)
            if c.tier==7 and matchesTribes(g,{tribes=c.races}) and (g.fullMinions or c.fx=="full") then
                ids[#ids+1]=id
            end
        end
        table.sort(ids)
        for _=1,n do
            if not offerDiscovery(g,p,ids,{golden=golden,transformTimewarp=transform,
                label=golden and "Discover a Golden Tier 7 minion" or "Discover a Tier 7 minion"}) then return false end
        end
        return true
    end

    function E.awardDiscoveredTimewarpSpell(g,p,id,unlockTurn)
        if not E.giveSpell(g,p,id) then return false,"Your hand is full." end
        if unlockTurn and unlockTurn>g.turn then
            p.spellExpeditions=p.spellExpeditions or {}
            p.spellExpeditions[#p.spellExpeditions+1]={spell=table.remove(p.spellHand),turn=unlockTurn}
        end
        return true
    end

    for id,info in pairs({
        BG35_MagicItem_870={"BG34_Giant_031"},
        BG32_MagicItem_364={"BG34_Giant_314"},
        BG35_MagicItem_310={"BG34_Giant_330",true},
        BG35_MagicItem_303={"BG34_Giant_072"},
    }) do
        local minion,reborn=info[1],info[2]
        E.TR[id]={pick=function(g,p)
            local m=E.newMinion(g,minion,false)
            m.generated=true
            if reborn then m.reborn=true end
            addToHand(g,p,m)
        end}
    end
    E.TR.BG35_MagicItem_823={pick=function(g,p) E.discoverTimewarp(g,p,3,2,"minion") end}
    E.TR.BG35_MagicItem_823t={pick=function(g,p) E.discoverTimewarp(g,p,5,2,"minion") end}
    E.HP.BG34_HERO_004={passive=true}
    E.HP.BG34_HERO_000={passive=true}
end

do
    local function register(short,effects)
        local id=short:match("^BG") and short or "BG34_Giant_"..short
        FX[id]=effects or {}
        card(id).fx="full"
    end
    local function tribe(race)
        return function(c) return c.all or indexOf(c.races,race)~=nil end
    end
    local function grant(g,p,id,n)
        if not p then return end
        for _=1,n do if not E.giveSpell(g,p,id) then break end end
    end
    local function token(g,p,id,n)
        if not p or not card(id) then return end
        for _=1,n do
            if E.handCount(p)>=E.MAX_HAND then break end
            local m=E.newMinion(g,id,false)
            m.generated=true
            addToHand(g,p,m)
        end
    end
    local function randomMinion(g,p,n,low,high,race)
        if not p then return end
        local filter=race and tribe(race)
        for _=1,n do
            if E.handCount(p)>=E.MAX_HAND then break end
            local m=drawFromPool(g,high,low,filter)
            if not m then break end
            addToHand(g,p,m)
        end
    end
    local function reward(id)
        return function(g,p,_,k) grant(g,p,id,k) end
    end
    local function combatReward(id)
        return function(C,S,_,_,k) grant(C.g,ownerOf(C,S),id,k) end
    end
    local function repeatSpell(id)
        return function(g,p,_,k)
            for _=1,k do E.castGeneratedSpell(g,p,id) end
        end
    end
    local function boardBuff(list,a,h,race,exclude)
        for _,m in ipairs(list) do
            if m~=exclude and m.hp>0 and (not race or hasRace(m,race)) then buff(m,a,h) end
        end
    end
    local function foreverTavern(p,a,h)
        local old=p.tavBuff.all or {0,0}
        p.tavBuff.all={old[1]+a,old[2]+h}
        boardBuff(p.tavern,a,h)
    end
    local function adjacent(list,m,fn)
        local i=indexOf(list,m)
        if not i then return end
        if list[i-1] and list[i-1].hp>0 then fn(list[i-1]) end
        if list[i+1] and list[i+1].hp>0 then fn(list[i+1]) end
    end
    local function avenge(n,fn) return {avenge={n=n,fn=fn}} end
    local function afterPlay(race,a,h,hand)
        return function(_,p,_,played,k)
            if not hasRace(played,race) then return end
            boardBuff(p.board,a*k,h*k,hand and nil or race)
            if hand then boardBuff(p.hand,a*k,h*k) end
        end
    end
    local function castRandom(g,p,n,filter,tier,exact)
        if not p then return end
        for _=1,n do
            if not E.getRandomSpell(g,p,tier or 6,exact or false,filter) then break end
        end
    end
    local function otherLargest(list,property,n)
        local order={}
        for i,m in ipairs(list) do if m.hp>0 then order[#order+1]={i=i,m=m} end end
        table.sort(order,function(a,b)
            if a.m[property]==b.m[property] then return a.i<b.i end
            return a.m[property]>b.m[property]
        end)
        local out={}
        for i=1,math.min(n,#order) do out[i]=order[i].m end
        return out
    end
    local function undead(C,S,n)
        local p=ownerOf(C,S)
        if not p then return end
        p.undeadAtk=(p.undeadAtk or 0)+n
        applyUndead(p)
        if not C.recruit then
            for _,m in ipairs(S.list) do if m.hp>0 and hasRace(m,"UNDEAD") then m.atk=m.atk+n end end
        end
    end
    local function menagerie(g,list,stats)
        local used={}
        for _,r in ipairs(g.tribes) do
            local candidates={}
            for _,m in ipairs(list) do if not used[m] and m.hp>0 and hasRace(m,r) then candidates[#candidates+1]=m end end
            local m=pick(g,candidates)
            if m then used[m]=true;stats(m) end
        end
    end

    register("001",{bc=function(_,p,_,k) p.nextGold=p.nextGold+k end,
        dr=function(C,S,_,_,k) local p=ownerOf(C,S);if p then p.nextGold=p.nextGold+k end end})
    register("002",{afterSell=function(g,p,_,k,sold)
        if hasRace(sold,"QUILBOAR") then local m=pick(g,p.board);if m then E.applyGems(g,p,m,4*k) end end
    end})
    register("006",{afterPlay=function(_,_,m,played,k)
        if hasRace(played,"ELEMENTAL") then
            m.timewarpGrowth=(m.timewarpGrowth or 0)+1
            buff(m,m.timewarpGrowth*k,m.timewarpGrowth*k)
        end
    end})
    register("007")
    register("008",{spellDiscount={count=2,amount=2}})
    register("009",{endTurn=function(g,p,m,k)
        for i=1,k do
            if #p.board>=E.MAX_BOARD then break end
            local cat=E.newMinion(g,"BG_CFM_315t",false)
            cat.generated,cat.atk,cat.hp=true,m.atk,m.hp
            shopSummon(g,p,cat,(indexOf(p.board,m) or #p.board)+i)
        end
    end})
    register("010",{dr=function(C,S,m,_,k)
        for _=1,k do
            local t=pick(C.g,livingOf(S))
            if t then buff(t,m.atk,m.maxhp or m.recruitDeathHp or card(m.id).hp) end
        end
    end})
    register("012")
    register("015",{tavernSpell=function(_,p,_,k) boardBuff(p.board,2*k,2*k) end})
    register("017",{dr=function(C,S,_,slot,k)
        local p=ownerOf(C,S)
        local t=p and pick(C.g,p.hand)
        if t then
            buff(t,7*k,7*k)
            if not C.recruit then C_.summonCopy(C,S,t,slot) end
        end
    end})
    register("021",{endTurn=function(_,p,m,k)
        local n=1
        for _,t in ipairs(p.board) do if t.golden then n=n+1 end end
        adjacent(p.board,m,function(t) buff(t,8*k*n,8*k*n) end)
    end})
    register("024",{reborned=function(C,S,_,_,k)
        for _,m in ipairs(livingOf(S)) do C_.trinketPermanent(C,m,2*k,2*k) end
    end})
    register("027",{afterAllyTargeted=function(C,_,_,target,k) C_.trinketPermanent(C,target,8*k,0) end})
    register("029",{soc=function(C,S,m,k)
        local p=ownerOf(C,S)
        local n=(p and p.tier or S.spec.tier or 1)*k
        buff(m,n,n)
        adjacent(S.list,m,function(t) buff(t,n,n) end)
    end})
    function C_.frogRattle(C,S,_,_,k)
        local t=pick(C.g,others(livingOf(S),nil,"BEAST"))
        if t then
            buff(t,k,k)
            t.frogRattles=t.frogRattles or {}
            t.frogRattles[#t.frogRattles+1]=k
        end
    end
    register("031",{dr=C_.frogRattle})
    register("032",{afterPlay=function(_,p,_,played,k)
        if hasRace(played,"ELEMENTAL") then foreverTavern(p,4*k,3*k) end
    end})
    register("034",{dr=function(C,S,_,_,k)
        local p=ownerOf(C,S)
        if p then p.bonusSpellAtk,p.bonusSpellHp=(p.bonusSpellAtk or 0)+2*k,(p.bonusSpellHp or 0)+2*k end
    end})
    register("035")
    register("038",{refresh=function(_,p,m,k)
        m.timewarpCount=(m.timewarpCount or 0)+1
        if m.timewarpCount<5 then return end
        m.timewarpCount=0
        local list={}
        for _,t in ipairs(p.tavern) do if not t.golden then list[#list+1]=t end end
        for _,entry in ipairs(list) do entry.timewarpSortTier=entry.cardTier or card(entry.id).tier end
        local picked=otherLargest(list,"timewarpSortTier",k)
        for _,entry in ipairs(list) do entry.timewarpSortTier=nil end
        for _,t in ipairs(picked) do makeGolden(t);E.updateCardAuras(p,t) end
    end})
    register("039",{startTurn=function(g,p,m,k)
        if m.lastSurvived==g.turn-1 then for _=1,k do E.discoverTriple(g,p) end end
    end})
    register("040",{afterPlay=function(_,_,_,played) played.shield=true end})
    register("041",{onAttack=function(C,S,_,k)
        local p=ownerOf(C,S)
        if not p then return end
        for _=1,k do
            for i=#S.list,1,-1 do
                local m=S.list[i]
                if m.hp>0 and FX[m.id] and FX[m.id].bc then
                    runBattlecry(C.g,p,m,1)
                    break
                end
            end
            for i=#S.list,1,-1 do
                local m=S.list[i]
                if m.hp>0 and C_.hasDeathrattle(m) then C_.runDeathrattle(C,S,m,i);break end
            end
        end
    end})
    register("042",{soc=function(C,S,m)
        local i=indexOf(S.list,m)
        if i and i>1 then
            local t=S.list[i-1]
            if t.hp>0 then
                table.remove(S.list,i)
                C_.summonCopy(C,S,t,i)
            end
        end
    end})
    register("065",{endTurn=function(_,p,m,k)
        for _,t in ipairs(p.board) do
            if t~=m then buff(t,t.atk<m.atk and 2*k or 0,t.hp<m.hp and 2*k or 0) end
        end
    end})
    register("066",{spellAura={1,1},extraSpellShop=true})
    register("067",{endTurn=function(g,p,_,k) token(g,p,"BGS_115",k) end})
    register("068",{onAttack=function(C,S,m,k)
        local p=ownerOf(C,S)
        for _=1,k do
            local choices={}
            for _,t in ipairs(livingOf(S)) do if t~=m and not t.shield then choices[#choices+1]=t end end
            local t=pick(C.g,choices)
            if t then
                t.shield=true
                if p and t.src then for _,original in ipairs(p.board) do if original.uid==t.src then original.shield=true;break end end end
            end
        end
    end})
    register("069",{damaged=function(C,S,m,k)
        local p=ownerOf(C,S)
        if p and (m.timewarpCount or 0)<3 then
            m.timewarpCount=(m.timewarpCount or 0)+1
            p.gemA=p.gemA+k
        end
    end})
    register("071",{dr=function(C,S,_,slot,k)
        local p=ownerOf(C,S)
        if not p or C.recruit then return end
        for i,t in ipairs(otherLargest(p.hand,"hp",k)) do
            local m=C_.summonCopy(C,S,t,slot+i-1)
            if m then m.shield=true end
        end
    end})
    register("072",{afterSell=function(g,p,_,k,sold)
        if (sold.cardTier or card(sold.id).tier)==2 then randomMinion(g,p,k,1,1) end
    end})
    register("078",{bc=reward("BG34_689"),dr=combatReward("BG34_689")})
    register("081",{damaged=function(C,S,_,k) undead(C,S,k) end})
    register("082",avenge(4,function(C,S,_,k)
        local p=ownerOf(C,S)
        if p then p.extraMaxGold=(p.extraMaxGold or 0)+k end
    end))
    register("088",{endTurn=function(_,_,m) m.timewarpGrowth=(m.timewarpGrowth or 0)+1 end,
        soc=function(_,S,m,k) local n=(5+(m.timewarpGrowth or 0))*k;boardBuff(S.list,n,n) end})
    register("091",{afterPlay=function(_,_,m,t) if hasRace(t,"DRAGON") then m.timewarpGrowth=(m.timewarpGrowth or 0)+1 end end,
        soc=function(C,S,m,k)
            local list=livingOf(otherSide(C,S))
            for _=1,math.min(2*k,#list) do
                local t=table.remove(list,rnd(C.g,#list))
                C_.dealDamage(C,otherSide(C,S),t,(k==2 and 2 or 3)+(m.timewarpGrowth or 0),m)
            end
        end})
    register("102",{onAttack=function(C,S,m,k)
        local p=ownerOf(C,S)
        if not p then return end
        for _,t in ipairs(livingOf(S)) do
            if t~=m then
                local a,h=2*k*p.gemA,2*k*p.gemH
                C_.trinketPermanent(C,t,a,h)
            end
        end
    end})
    register("104",{dr=function(C,S,m,_,k)
        local list=others(livingOf(S),nil,"QUILBOAR")
        for _=1,math.min(2*k,#list) do
            local t=table.remove(list,rnd(C.g,#list))
            buff(t,m.gemAttack or 0,m.gemHealth or 0)
            t.gemAttack,t.gemHealth=(t.gemAttack or 0)+(m.gemAttack or 0),(t.gemHealth or 0)+(m.gemHealth or 0)
        end
    end})
    register("105",{spellTarget=function(g,p,m,k,target,entry)
        if m==target and entry.id=="BG20_GEM" then for _=1,k do E.castGeneratedSpell(g,p,"BG34_689") end end
    end})
    register("110",{onAttack=function(_,_,m,k)
        if (m.timewarpRallies or 0)>=2 then return end
