    end})
    register("206",{endTurn=function(_,p,m,k)
        local n=(2+(p.battlecries or 0))*k;buff(m,n,n)
    end})
    register("207",{onAnyKill=function(C,S,_,_,k)
        local p=ownerOf(C,S)
