    end))
    register("212")
    register("300",{rewind=function(_,p,_,k) boardBuff(p.board,0,k,"DEMON") end})
    register("302",avenge(3,function(C,S,_,k)
        randomMinion(C.g,ownerOf(C,S),k,1,6,"MECHANICAL")
    end))
    register("304",{dr=combatReward("BG28_606")})
    register("305",avenge(5,function(C,S,_,k)
