        if p then p.gemA,p.gemH=p.gemA+k,p.gemH+k;grant(C.g,p,"BG20_GEM",1) end
    end))
    register("306",{dr=function(C,S,_,_,k)
        local p=ownerOf(C,S);if p then p.gemH=p.gemH+2*k end
    end})
    register("309",{afterBuyMinion=function(g,p,m,k,bought)
