            castRandom(g,p,k,nil,bought.cardTier or card(bought.id).tier,true)
            m.timewarpCount=(m.timewarpCount or 0)+1
        end
    end})
    register("310",{endTurn=function(_,p,_,k)
        boardBuff(p.board,2*k,k);boardBuff(p.hand,2*k,k)
    end})
    register("314")
    register("318",{endTurn=function(g,p,_,k)
        local list={}
        for i,t in ipairs(p.board) do list[i]=t end
        for _=1,k do for _,t in ipairs(list) do if indexOf(p.board,t) then runBattlecry(g,p,t,1) end end end
    end})
    register("319",{afterPlay=function(_,_,m,c) if (c.cardTier or card(c.id).tier)<=3 then m.timewarpGrowth=(m.timewarpGrowth or 0)+1 end end,
        anySpell=function(_,_,m,_,d) if d.tier<=3 then m.timewarpGrowth=(m.timewarpGrowth or 0)+1 end end,
        endTurn=function(_,p,m,k)
            local n=m.timewarpGrowth or 0
