    local function extraTavern(race,n,stats,frozen)
        return function(g,p,k)
            for _=1,n*k do
                local m=drawFromPool(g,p.tier,1,tribe(race))
                if not m then break end
                if frozen then m.timewarpFrozen=true end
                if stats then local amount=stats(g);buff(m,amount,amount) end
                p.tavern[#p.tavern+1]=m
            end
        end
    end
