end

do
    local HP=E.HP
    local function passive(effects) effects.passive=true;return effects end
    local function token(g,p,id,golden)
        local m=E.newMinion(g,id,golden)
        m.generated=true
        return addToHand(g,p,m),m
    end
    local function randomRace(g,p,race,n)
        for _=1,n do
            if E.handCount(p)>=E.MAX_HAND then break end
            local m=drawFromPool(g,6,1,function(c) return indexOf(c.races,race) or c.all end)
            if not m then break end
            addToHand(g,p,m)
        end
    end
    local function choice(p,id,title,options,details)
        if #options==0 then return false,"No choices are available." end
        local d=details or {}
        d.moreHeroChoice,d.label,d.options=id,title,options
        if p.discover then p.discoverQueue[#p.discoverQueue+1]=d else p.discover=d end
        return true
    end
    local function randomChoices(g,list,n)
        list=copyTable(list)
        shuffle(g,list)
        while #list>n do table.remove(list) end
        return list
    end
    local function triggerPowerGrowth(g,p,field,amount,goal,fn)
        p[field]=(p[field] or 0)+amount
        while p[field]>=goal do
            p[field]=p[field]-goal
            fn(g,p)
        end
    end
    local function targetOn(list,t)
        return t and list[type(t)=="table" and t.index or t]
    end
    local function highest(list,key)
        local best
        for _,m in ipairs(list) do
            if m.hp>0 and (not best or m[key]>best[key]) then best=m end
        end
        return best
    end
    local function summonForHero(C,S,id,setup)
        if C.recruit or #S.list>=E.MAX_BOARD then return end
        return summon(C,S,id,false,nil,setup)
    end
    local function chooseHeroPowers(g,p,count)
        local ids={}
        for _,h in ipairs(BG_HEROES) do
            if h.id~=p.hero and HP[h.id] and HP[h.id].active and E.heroAvailable(g,h.id) then
                ids[#ids+1]=h.id
            end
        end
        return randomChoices(g,ids,count)
    end
    function E.discoverHeroPower(g,p,number)
        local found=false
        for i=1,number do
            found=choice(p,"power","Discover a Hero Power",chooseHeroPowers(g,p,3),
                {showPowerPortraits=true,powerSlot=i==2 and 2 or 1}) or found
        end
        return found
    end
    function E.activateSecondPower(g,color)
        local p=g.players[color]
        local ok,err=canAct(g,p)
        if not ok then return false,err end
        local h=E.heroById(p.secondPowerHero)
        local f=h and HP[h.id]
        if not (f and f.active) then return false,"This power is passive." end
        local locked=E.powerLock(g,p,f,true)
        if locked then return false,locked end
        if p.gold<E.powerCost(p,true) then return false,"You need more Gold." end
        if not f.target then return E.heroPower(g,color,nil,true) end
        local zone=f.target=="tavern" and "tavern" or "board"
        local options={}
        for _,m in ipairs(p[zone]) do options[#options+1]=m.uid end
        return choice(p,"secondTarget",h.power,options,{zone=zone,showTargets=true})
    end
    function E.darkmoonStock(g,p,n)
        for _=1,math.min(n,8-#p.tavern) do
            local m=drawFromPool(g,p.tier)
            if not m then break end
            E.applyTavernBuff(p,m);E.updateCardAuras(p,m);buff(m,2,2)
            p.tavern[#p.tavern+1]=m
        end
    end

    local protoss={"BG31_HERO_802pt","BG31_HERO_802pt1","BG31_HERO_802pt4","BG31_HERO_802pt5","BG31_HERO_802pt7"}
