    local undeadCreation="BG25_HERO_100pt"
    BG_CARDS[undeadCreation]={id=undeadCreation,gid=undeadCreation,name="Putricide's Creation",tier=1,
        atk=1,hp=1,gatk=1,ghp=1,races={"UNDEAD"},fx="full",noTriple=true,
        text="Created from two Undead."}
    local function components(g,p,first)
        local list={}
        for id in pairs(g.allowed or g.pool) do
            local d=card(id)
            if d.tier<=p.tier and indexOf(d.races,"UNDEAD") and d.fx=="full"
                and ((d.deathrattle or d.rally or (FX[id] and FX[id].avenge)) and first or
                    (not first and (d.reborn or d.taunt or d.shield or d.battlecry))) then
                list[#list+1]=id
            end
        end
        table.sort(list)
        return list
    end
    local function mergeUndead(g,a,b)
        local m=E.newMinion(g,undeadCreation,false)
        local x,y=card(a),card(b)
        m.generated,m.cardTier,m.atk,m.hp=true,math.max(x.tier,y.tier),x.atk+y.atk,x.hp+y.hp
        m.creationParts={a,b}
        m.attachments={{id=a,atk=0,hp=0},{id=b,atk=0,hp=0}}
        for _,kw in ipairs(KEYWORDS) do m[kw]=x[kw] or y[kw] end
        return m
    end
    function E.randomCreation(C,S,_,position,k)
        local g,p=C.g,ownerOf(C,S)
        if not p then return end
        local first,second=components(g,p,true),components(g,p,false)
        for i=1,k do
            local a,b=pick(g,first),pick(g,second)
            if not a or not b then break end
            local m=mergeUndead(g,a,b)
            addToHand(g,p,m)
            C_.summonCopy(C,S,m,position+i-1)
        end
    end
    function E.moreHeroPick(g,p,index)
        local d=p.discover
        local id=d.options[index]
        if not id then return false,"That choice is unavailable." end
        local effect=d.moreHeroChoice
        if effect=="drest" then
            local list,pos
            for _,zone in ipairs({p.hand,p.spellHand}) do
                for i,m in ipairs(zone) do if m.uid==id then list,pos=zone,i;break end end
                if list then break end
            end
            if not list then return false,"That card is unavailable." end
            E.discardCard(g,p,list,pos)
            randomRace(g,p,"ABERRATION",1)
        elseif effect=="eudora" then
            local ok=token(g,p,id,true)
            if not ok then return false,"Your hand is full." end
        elseif effect=="protoss" then
            p.protossAward=id
        elseif effect=="power" then
            if d.powerSlot==2 then p.secondPowerHero=id else p.powerHero=id end
        elseif effect=="putricide1" then
            local options=randomChoices(g,components(g,p,false),3)
            if #options==0 then return false,"There are no components left." end
            p.discover={moreHeroChoice="putricide2",label="Choose the second Undead",options=options,component=id}
            return true
        elseif effect=="putricide2" then
            if not addToHand(g,p,mergeUndead(g,d.component,id)) then return false,"Your hand is full." end
        elseif effect=="zergReward" then
            local ok,m=token(g,p,id)
            if not ok then return false,"Your hand is full." end
            m.atk,m.hp=6,6
        elseif effect=="bigglesworth" then
            local old=d.copies[tostring(index)]
            if E.handCount(p)>=E.MAX_HAND then return false,"Your hand is full." end
            local m=d.plainLastWarband and E.newMinion(g,id,false) or copyTable(old)
            if d.plainLastWarband then m.atk,m.hp=20,20 end
            g.uid=g.uid+1
            m.uid,m.generated,m.poolCopies,m.magneticCopies=g.uid,true,nil,nil
            addToHand(g,p,m)
        elseif effect=="secondTarget" then
            local list=p[d.zone]
            local i
            for j,m in ipairs(list or {}) do if m.uid==id then i=j;break end end
            if not i then return false,"That target is unavailable." end
            p.discover=nil
            local ok,err=E.heroPower(g,p.color,{zone=d.zone,index=i},true)
            if not ok then p.discover=d;return false,err end
            if p.discover then return true end
        elseif E.pickBuddyChoice then
            local ok,err=E.pickBuddyChoice(g,p,d,id)
            if not ok then return false,err end
        end
        p.discover=#p.discoverQueue>0 and table.remove(p.discoverQueue,1) or nil
        checkTriples(g,p)
        return true
    end

