        local counts={}
        for _,list in ipairs({p.board,p.hand}) do for _,m in ipairs(list) do
            if not m.golden and not card(m.id).noTriple then counts[m.id]=(counts[m.id] or 0)+1 end
        end end
        local eligible={}
        for id,n in pairs(counts) do if n==2 then eligible[#eligible+1]=id end end
