    function E.heroEliminated(g,loser)
        for _,p in ipairs(E.alivePlayers(g)) do
            if p~=loser and E.hasPower(p,"TB_BaconShop_HERO_70") then
                local ids,copies={},{}
                for i,m in ipairs(randomChoices(g,loser.board,3)) do ids[i]=m.id;copies[tostring(i)]=copyTable(m) end
                choice(p,"bigglesworth","Discover from the eliminated warband",ids,{copies=copies})
            end
        end
