    function E.heroCombatAttack(C,S)
        local p=ownerOf(C,S)
        if not p or C.recruit then return end
        if E.hasPower(p,"TB_BaconShop_HERO_59") and (p.arannaAttacks or 0)<14 then p.arannaAttacks=(p.arannaAttacks or 0)+1 end
        if E.hasPower(p,"BG33_HERO_001") then triggerPowerGrowth(C.g,p,"lohAttacks",1,15,E.discoverTriple) end
