        if p.rafaamPrimed then token(C.g,p,target.id);p.rafaamPrimed=nil end
        if E.hasPower(p,"BG20_HERO_100") then C_.trinketPermanent(C,source,1,0) end
    end
    function E.heroCombatDeath(C,S)
        local p=ownerOf(C,S)
        if not p or C.recruit then return end
        if E.hasPower(p,"BG22_HERO_200") then
            triggerPowerGrowth(C.g,p,"iniDeaths",1,9,function(g,p) randomRace(g,p,"MECHANICAL",1) end)
        end
        if E.hasPower(p,"BG22_HERO_305") then
            S.onyxiaDeaths=(S.onyxiaDeaths or 0)+1
            if S.onyxiaDeaths%4==0 and #S.list<E.MAX_BOARD then
                local n=1+(p.onyxiaBonus or 0)
                local t=summonForHero(C,S,"BG22_HERO_305t",function(m) m.atk,m.hp,m.maxhp=n,n,n end)
                if t then p.onyxiaBonus=n;C.immediate[#C.immediate+1]=t end
            end
        end
    end
    function E.heroCombatSpace(C,S)
        local p=ownerOf(C,S)
        if not p or C.recruit or #S.list>=E.MAX_BOARD or S.resolvingPowerSummon then return end
        S.resolvingPowerSummon=true
        local highAttack=E.hasPower(p,"BG22_HERO_002")
        local highHealth=E.hasPower(p,"BG22_HERO_003")
        if (highAttack or highHealth) and not S.twinsSummoned and C.g.turn>=7 then
            local best=highest(S.list,highAttack and "atk" or "hp")
            S.twinsSummoned=true
            if best then C_.summonCopy(C,S,best) end
        end
        if E.hasPower(p,"BG23_HERO_201") and not S.tentacleSummoned then
            S.tentacleSummoned=true
            local n=2+(p.ozumatStats or 0)
            summonForHero(C,S,"BG23_HERO_201pt",function(m) m.atk,m.hp,m.maxhp=n,n,n end)
        end
        if p.tavishShot and #S.list<E.MAX_BOARD then
            local shot=p.tavishShot
            p.tavishShot=nil
            local enemy=otherSide(C,S)
            local t=pick(C.g,livingOf(enemy))
            if t then C_.dealDamage(C,enemy,t,shot.atk) end
        end
        S.resolvingPowerSummon=nil
    end
    function E.heroCombatSummon(C,S,m,p)
        if not C.recruit and E.hasPower(p,"TB_BaconShop_HERO_95") then buff(m,1,2);m.taunt=true end
    end
    function C_.roameDeath(C,S,m)
        for _,t in ipairs(livingOf(S)) do if t~=m then buff(t,m.atk,m.maxhp or m.recruitDeathHp or 0) end end
    end
