end

do
    local function buddy(id,effect,note)
        local def=assert(card(id),id)
        def.fx,def.note=note and "simplified" or "full",note
        FX[id]=effect
    end
    local function give(g,p,id,count)
        if not id or not card(id) then return end
        for _=1,count do
            if E.handCount(p)>=E.MAX_HAND then break end
            local m=E.newMinion(g,id,false);m.generated=true
            addToHand(g,p,m)
        end
    end
    local function ownBuddy(g,p,k)
        local h=E.powerHero(p)
        if h then give(g,p,h.buddy,k) end
    end
    local function stockSpell(g,p,n)
        for _=1,n do
            if not E.getRandomSpell(g,p,6,false,function(s)
                return (s.text or ""):find("%+%d") or s.id=="BG28_838"
            end) then break end
        end
    end
    local function menu(p,id,label,options,zone)
        if #options==0 then return end
        local d={moreHeroChoice=id,label=label,options=options,zone=zone,showTargets=zone~=nil}
        if p.discover then p.discoverQueue[#p.discoverQueue+1]=d else p.discover=d end
    end
    buddy("BG20_HERO_202_Buddy",{startTurn=function(g,p,_,k) ownBuddy(g,p,k) end})
    buddy("BG21_HERO_000_Buddy",{endTurn=function(g,p,_,k)
        for _=1,k do
            local upgrade=rnd(g,3)
            if upgrade==1 then p.carielAttack=(p.carielAttack or 1)+1
            elseif upgrade==2 then p.carielHealth=(p.carielHealth or 1)+1
            else p.carielTargets=(p.carielTargets or 1)+1 end
        end
    end})
    buddy("BG21_HERO_010_Buddy",{startTurn=function(g,p,_,k)
        for _,pair in ipairs(E.recruitPairings(g)) do
            local nextOpponent=(pair[1]==p and pair[2]) or (pair[2]==p and pair[1])
            if nextOpponent then
                local h=E.hero(nextOpponent);if h then give(g,p,h.buddy,k) end
                break
            end
        end
    end})
    buddy("BG21_HERO_030_Buddy",{soc=function(_,S,m,k)
        local n=0
        for _,t in ipairs(S.list) do
            if t~=m and t.id~="BG21_HERO_030_Buddy" and t.id~="BG34_Giant_599" and C_.hasDeathrattle(t) then
                E.copyCombatDeathrattles(m,t,k);n=n+1
                if n==2 then break end
            end
        end
    end})
    buddy("BG22_HERO_000_Buddy",{})
    buddy("BG22_HERO_001_Buddy",{dr=function(C,S,m,_,k)
        if C.recruit then return end
        for _=1,k do
            for _,element in ipairs(m.rememberedElements or {}) do
                C_.applyInvocation(element,C,S,otherSide(C,S))
            end
        end
    end})
    buddy("BG22_HERO_004_Buddy",{})
    buddy("BG22_HERO_007_Buddy",{spellTarget=function(g,p,m,k,target,entry)
        if p.imperialRecast or target==m or not indexOf(p.board,target) then return end
        if m.imperialTurn~=g.turn then m.imperialTurn,m.imperialUses=g.turn,0 end
        if m.imperialUses>=k then return end
        p.imperialRecast=true
        if E.recastTrinketSpell(g,p,entry,m) then m.imperialUses=m.imperialUses+1 end
        p.imperialRecast=nil
    end})
    buddy("BG22_HERO_305_Buddy",{combatSummon=function(C,_,m,k,t)
        if t.id=="BG22_HERO_305t" or card(t.id).name:find("Whelp",1,true) then C_.trinketPermanent(C,m,2*k,2*k) end
    end,recruitSummon=function(_,_,m,k,t)
        if t.id=="BG22_HERO_305t" or card(t.id).name:find("Whelp",1,true) then buff(m,2*k,2*k) end
    end})
    buddy("BG23_HERO_304_Buddy",{tavernShown=function(g,p,_,k,t)
        for _=1,k do if not E.copySpellcraft(g,p,t) then break end end
    end})
    buddy("BG23_HERO_306_Buddy",{bc=function(_,p,m)
        local options={}
        for _,x in ipairs(p.board) do if x~=m then options[#options+1]=x.uid end end
        menu(p,"nathanos","Sell a friendly minion",options,"board")
    end})
    buddy("BG25_HERO_100_Buddy",{dr=E.randomCreation},"Uses the implemented Undead Creation components.")
    buddy("BG25_HERO_105_Buddy",{bc=function(_,p)
        local options={}
        for _,x in ipairs(p.board) do if card(x.id).buddy and not x.golden then options[#options+1]=x.uid end end
        menu(p,"talentScout","Make a Buddy Golden",options,"board")
    end})
    buddy("BG26_HERO_102_Buddy",{powerUsed=function(g,p,m,k,_,target)
        if not target or not target.zone or target.zone=="spellshop" then return end
        local list=p[target.zone]
        local t=list and list[target.index]
        if not t then return end
        if g.turn%2==1 then buff(t,math.floor(m.atk*k/2),0) else buff(t,0,math.floor(m.hp*k/2)) end
    end})
    buddy("BG31_HERO_005_Buddy",{bc=function(_,p,m)
        local options={}
        for _,x in ipairs(p.tavern) do options[#options+1]=x.uid end
        if #options==0 then return end
        menu(p,"miniZerek","Transform into a Tavern minion",options,"tavern")
        local d=p.discoverQueue[#p.discoverQueue] or p.discover
        d.source=m.uid
    end})
    buddy("BG31_HERO_811_Buddy",{sell=function(g,p,_,k) for _=1,k do E.zergChoice(g,p) end end})
    -- These depend on hero-power or shop transformations beyond the current effects.
    buddy("TB_BaconShop_HERO_08_Buddy",{})
    buddy("TB_BaconShop_HERO_14_Buddy",{soc=function(C,S,m,k)
        local types,n={},0
        local a,h=0,0
        for _,t in ipairs(S.list) do
            a,h=math.max(a,t.atk),math.max(h,t.hp)
            for _,r in ipairs(C.g.tribes) do
                if not types[r] and hasRace(t,r) then types[r]=true;n=n+1;break end
            end
        end
        if n>=4 then buff(m,a*k,h*k) end
    end})
    buddy("TB_BaconShop_HERO_15_Buddy",{powerUsed=function(_,p,_,k)
        for _,t in ipairs(p.board) do if t.shield then buff(t,2*k,0) end end
    end})
    buddy("TB_BaconShop_HERO_18_Buddy",{
        bc=function(g,p,_,k) for _=1,k do E.giveSpell(g,p,"BG33_81"..(rnd(g,5)+0)) end end,
        dr=function(C,S,_,_,k)
            local p=ownerOf(C,S);if p then for _=1,k do E.giveSpell(C.g,p,"BG33_81"..rnd(C.g,5)) end end
        end,
        onAttack=function(C,S,_,k)
            local p=ownerOf(C,S);if p then for _=1,k do E.giveSpell(C.g,p,"BG33_81"..rnd(C.g,5)) end end
        end,
    })
    buddy("TB_BaconShop_HERO_25_Buddy",{rewind=function(_,_,m,k,n) buff(m,n*k,n*k) end})
    buddy("TB_BaconShop_HERO_29_Buddy",{gainObserved=function(_,_,_,m,t,k)
        if m~=t then tempBuff(m,k,k) end
    end})
    buddy("TB_BaconShop_HERO_33_Buddy",{gainObserved=function(_,_,_,m,t,_,a,h)
        if t.id=="TB_BaconShop_HP_033t" then buff(m,a,h) end
    end})
    buddy("TB_BaconShop_HERO_35_Buddy",{startTurn=function(g,p,_,k) E.timewarpWheel(g,p,k) end},E.timewarpWheelNote)
    buddy("TB_BaconShop_HERO_39_Buddy",{gainObserved=function(_,_,_,m,t,k,_,h)
        if t~=m and h>0 then buff(m,0,h*k) end
    end})
    buddy("TB_BaconShop_HERO_40_Buddy",{sell=function(g,p,_,k) ownBuddy(g,p,k) end})
    buddy("TB_BaconShop_HERO_41_Buddy",{dr=function(C,S,_,_,k)
        for _=1,k do
            local target
            for i=#S.list,1,-1 do
                if S.list[i].hp>0 and not S.list[i].golden then target=S.list[i];break end
            end
            if target then makeGolden(target) end
        end
    end})
    buddy("TB_BaconShop_HERO_42_Buddy",{bc=function(_,p,_,k) p.eliseBuddyCut=(p.eliseBuddyCut or 0)+2*k end})
    buddy("TB_BaconShop_HERO_52_Buddy",{gainObserved=function(_,C,_,_,target,k,a)
        if C and a>0 then C_.trinketPermanent(C,target,0,k) end
    end})
    buddy("TB_BaconShop_HERO_53_Buddy",{
        summon=function(m,t) if hasRace(t,"DRAGON") then local k=mult(m);buff(m,k,k) end end,
        tavernShown=function(_,_,m,k,t) if hasRace(t,"DRAGON") then buff(m,k,k) end end,
    })
    buddy("TB_BaconShop_HERO_62_Buddy",{bc=function(_,p,_,k)
        p.goldenPowerTargets=(p.goldenPowerTargets or 0)+k
    end})
    buddy("TB_BaconShop_HERO_67_Buddy",{powerUsed=function(_,p,_,k,id)
        if id=="TB_BaconShop_HERO_67" and p.lastHeroSoldTier then
            p.gold=math.min(99,p.gold+p.lastHeroSoldTier*k)
        end
    end})
    buddy("TB_BaconShop_HERO_75_Buddy",{endTurn=function(g,p,_,k) stockSpell(g,p,2*k) end})
    local function helpful(g,p,n)
        if not p then return end
        for _=1,n do
            if E.handCount(p)>=E.MAX_HAND then break end
            local types,highest={},0
            for _,m in ipairs(p.board) do
                for _,r in ipairs(card(m.id).races) do types[r]=(types[r] or 0)+1;highest=math.max(highest,types[r]) end
            end
            local m
            if rnd(g,3)~=1 and highest>0 then
                m=drawFromPool(g,p.tier,1,function(c)
                    if c.all then return true end
                    for _,r in ipairs(c.races) do if types[r]==highest then return true end end
                    return false
                end)
            end
            if m then addToHand(g,p,m)
            else E.getRandomSpell(g,p,p.tier,false) end
        end
    end
    buddy("BG30_HERO_304_Buddy",{endTurn=function(g,p,_,k) helpful(g,p,k) end},
        "Uses local warband type weighting for helpful cards.")
    buddy("BG32_HERO_002_Buddy",{dr=function(C,S,_,_,k) helpful(C.g,ownerOf(C,S),k) end},
        "Uses local warband type weighting for helpful cards.")
    buddy("TB_BaconShop_HERO_78_Buddy",{tavernExtra=FX.BG34_Giant_586.tavernExtra})
    buddy("TB_BaconShop_HERO_93_Buddy",{bc=function(_,p)
        local options={}
        for _,x in ipairs(p.board) do
            if C_.hasDeathrattle(x) and not x.golden then options[#options+1]=x.uid end
        end
        menu(p,"talentScout","Make a friendly Deathrattle minion Golden",options,"board")
    end})
    buddy("TB_BaconShop_HERO_94_Buddy",{sell=function(g,p,_,k)
        for _=1,k do E.discoverDarkmoon(g,p,math.min(4,math.floor(g.turn/4)+1)) end
    end})
    buddy("TB_BaconShop_HERO_95_Buddy",{afterAllyTargeted=function(C,S,_,target,k)
        if target.taunt then for _,x in ipairs(livingOf(S)) do C_.trinketPermanent(C,x,k,k) end end
    end})
    function E.pickBuddyChoice(g,p,d,id)
        local target
        for _,m in ipairs(p[d.zone] or {}) do if m.uid==id then target=m;break end end
        if not target then return false,"That target is unavailable." end
        if d.moreHeroChoice=="talentScout" then
            makeGolden(target);E.updateCardAuras(p,target)
        elseif d.moreHeroChoice=="nathanos" then
            local i=indexOf(p.board,target)
            local left,right=p.board[i-1],p.board[i+1]
            local n=(left and 1 or 0)+(right and 1 or 0)
            if n==0 then return false,"The minion needs a neighbor." end
            table.remove(p.board,i);returnToPool(g,target)
            local a,h=math.floor(target.atk/n),math.floor(target.hp/n)
            if left then buff(left,a,h) end
            if right then buff(right,a,h) end
            p.gold=math.min(99,p.gold+E.sellValue(target))
        elseif d.moreHeroChoice=="miniZerek" then
            for i,m in ipairs(p.board) do if m.uid==d.source then
                local copy=copyTable(target)
                copy.uid,copy.generated,copy.poolCopies,copy.magneticCopies=m.uid,true,nil,nil
                returnToPool(g,m)
                p.board[i]=copy;E.bindStatCard(p,copy)
                return true
            end end
            return false,"Mini-Zerek is no longer available."
        end
        return true
    end
    function E.heroPowerUsed(g,p,id,target)
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and f.powerUsed then f.powerUsed(g,p,m,mult(m),id,target) end
        end
        if p.goldenPowerTargets and p.goldenPowerTargets>0 and target and target.zone then
            local list=p[target.zone]
            local m=list and list[target.index]
            if m and not m.golden then makeGolden(m);E.updateCardAuras(p,m);p.goldenPowerTargets=p.goldenPowerTargets-1 end
        end
    end
    function E.tavernShown(g,p)
        for _,m in ipairs(p.board) do
            local f=FX[m.id]
            if f and f.tavernShown then
                for _,t in ipairs(p.tavern) do f.tavernShown(g,p,m,mult(m),t) end
            end
        end
    end
    function C_.firstAttackProtection(C,S,m)
        if S.hadFirstAttack then return end
        S.hadFirstAttack=true
        for _,t in ipairs(S.list) do
            if t.hp>0 and t.id=="TB_BaconShop_HERO_08_Buddy" then m.buddyImmuneAttack=true;break end
        end
    end
end

FX.BG28_741 = {tavernSpell = function(_, p, _, k) for _, m in ipairs(p.board) do if m.shield then buff(m, 4 * k, 0) end end end}
card("BG28_741").fx, card("BG28_741").note = "full", nil
end



do
    -- Heroes and Buddies that had no script: Jim Raynor (Battlecruiser + Upgrades), Kerrigan (Larva and Zerg),
    -- Sire Denathrius (start-of-game Quest), The Great Akazamzarak (Secrets), and seven Buddies.
    local HP = E.HP
    BG_CARDS["EX1_554t"] = BG_CARDS["EX1_554t"] or {id = "EX1_554t", name = "Snake", tier = 1, atk = 1, hp = 1, races = {"BEAST"},
        all = false, text = "", pool = false, legend = false, gatk = 2, ghp = 2, gid = "", fx = "full"}
    BG_CARDS["EX1_170"] = BG_CARDS["EX1_170"] or {id = "EX1_170", name = "Emperor Cobra", tier = 2, atk = 2, hp = 3, races = {"BEAST"},
        all = false, text = "Venomous", pool = false, legend = false, gatk = 4, ghp = 6, gid = "", fx = "full", venom = true}
    local function passive(t) t.passive = true; return t end
    local function heroScripted(id)
        for _, h in ipairs(BG_HEROES) do if h.id == id then h.scripted = true end end
    end
    local function newToken(g, id, golden)
        local m = E.newMinion(g, id, golden or false)
        m.generated = true
        return m
    end
    -- Heroes that "start the game with" a minion get it in the warband, as in Battlegrounds.
    function E.boardToken(g, p, id, golden)
        local m = newToken(g, id, golden)
        if shopSummon(g, p, m) then return m end
        if addToHand(g, p, m) then return m end
    end
    local function giveToken(g, p, id, golden)
        if E.handCount(p) >= E.MAX_HAND then return nil end
        local m = newToken(g, id, golden)
        if addToHand(g, p, m) then return m end
        return nil
    end
    local function alive(list, except)
        local out = {}
        for _, m in ipairs(list) do if m.hp > 0 and m ~= except then out[#out + 1] = m end end
        return out
    end
    local function permanent(C, m, a, h)
        buff(m, a, h)
        if m.src then
            m.permAtk, m.permHp = (m.permAtk or 0) + a, (m.permHp or 0) + h
            C_.trackPermanent(C, m)
        end
    end
    local function choose(p, d)
        if p.discover then p.discoverQueue[#p.discoverQueue + 1] = d else p.discover = d end
    end

    ---------------------------------------------------------------------------
    -- Jim Raynor: Battlecruiser Upgrades (BG31_HERO_801pt<family><level>)
    local CRUISER = "BG31_HERO_801pt"
    local UPGRADE = {
        a = {name = "Hyperflight Rotors", first = 1, cost = 1, values = {6, 8, 11, 15, 20, 28, 40},
            text = "Give your Battlecruiser +%d Attack."},
        b = {name = "Smart Servos", first = 1, cost = 1, values = {6, 8, 11, 15, 20, 28, 40},
            text = "Give your Battlecruiser +%d Health."},
        c = {name = "Yamato Cannon", first = 1, cost = 1, values = {3, 6, 9, 18, 24, 30, 40},
            text = "Give your Battlecruiser \"Start of Combat: Deal %d damage to the highest-Health enemy minion.\""},
        d = {name = "Advanced Ballistics", first = 1, cost = 1, values = {2, 3, 4, 5, 6, 8, 10},
            text = "Give your Battlecruiser \"Rally: Give your other minions +%d Attack.\""},
        e = {name = "Caduceus Reactor", first = 2, cost = 1, values = {nil, 2, 4, 7, 10, 15, 25},
            text = "Give your Battlecruiser \"Deathrattle: Give your left-most minion +%d/+%d.\""},
        f = {name = "Advanced Construction", first = 4, cost = 3, values = {},
            text = "Give your Battlecruiser \"1 Battlecruiser Upgrade you buy each turn is free.\""},
        h = {name = "Fortified Bunker", first = 5, cost = 4, values = {},
            text = "Give your Battlecruiser \"At the end of your turn, get a random Magnetic Mech.\""},
        i = {name = "Missile Pod", first = 6, cost = 5, values = {},
            text = "Make your Battlecruiser's Yamato Cannon trigger twice."},
        j = {name = "Ultra-Capacitor", first = 6, cost = 6, values = {},
            text = "Give your Battlecruiser Reborn and \"This is Reborn with full Health and enchantments.\""},
    }
    local UPGRADE_OF = {}
    local function upgradeId(fam, tier)
        local u = UPGRADE[fam]
        local n = tier - u.first + 1
        return CRUISER .. fam .. (n == 1 and "" or tostring(n))
    end
    local function findCruiser(p)
        for _, zone in ipairs({p.board, p.hand}) do
            for _, m in ipairs(zone) do if m.id == CRUISER then return m end end
        end
    end
    local function applyUpgrade(p, fam, tier)
        local m = findCruiser(p)
        if not m then return false, "You need a Battlecruiser." end
        local v = UPGRADE[fam].values[tier]
        if fam == "a" then buff(m, E.spellAmount(p, v, 0))
        elseif fam == "b" then buff(m, E.spellAmount(p, 0, v))
        elseif fam == "c" then m.cruiserYamato = (m.cruiserYamato or 0) + v
        elseif fam == "d" then
            local a, h = E.spellAmount(p, v, 0)
            m.cruiserRally, m.cruiserRallyH = (m.cruiserRally or 0) + a, (m.cruiserRallyH or 0) + h
        elseif fam == "e" then
            local a, h = E.spellAmount(p, v, v)
            m.cruiserDRH = (m.cruiserDRH or m.cruiserDR or 0) + h
            m.cruiserDR = (m.cruiserDR or 0) + a; m.cruiserReactor = true
        elseif fam == "f" then m.cruiserFree = true
        elseif fam == "h" then m.cruiserBunker = (m.cruiserBunker or 0) + 1
        elseif fam == "i" then m.cruiserMissile = true
        elseif fam == "j" then m.reborn = true; m.cruiserCapacitor = true end
        return true
    end
    for fam, u in pairs(UPGRADE) do
        for tier = u.first, 7 do
            local id = upgradeId(fam, tier)
            local v = u.values[tier]
            E.SPELLS[id] = {id = id, name = u.name, tier = tier, cost = u.cost, generated = true, tavern = true, upgrade = true,
                text = v and string.format(u.text, v, v) or u.text, target = nil,
                cast = function(g, p) return applyUpgrade(p, fam, tier) end}
            UPGRADE_OF[id] = {fam = fam, tier = tier}
        end
    end
    E.CRUISER_UPGRADES = UPGRADE_OF
    function E.randomCruiserUpgrade(g, tier)
        local fams = {}
        for fam, u in pairs(UPGRADE) do if u.first <= tier then fams[#fams + 1] = fam end end
        table.sort(fams)
        return upgradeId(pick(g, fams), math.min(7, math.max(1, tier)))
    end
    function E.addCruiserUpgradeToTavern(g, p)
        if not findCruiser(p) then return end
        p.spellShop = p.spellShop or {}
        for _, entry in ipairs(p.spellShop) do if UPGRADE_OF[entry.id] then return end end
        g.uid = g.uid + 1
        table.insert(p.spellShop, {id = E.randomCruiserUpgrade(g, p.tier), uid = g.uid})
    end
    -- Advanced Construction: one Upgrade each turn is free.
    local basePrice = E.spellPrice
    E.spellPrice = function(p, entry)
        local cost, health = basePrice(p, entry)
        if UPGRADE_OF[entry.id] and not health and p.cruiserFreeTurn ~= (E.lastGame and E.lastGame.turn) then
            local m = findCruiser(p)
            if m and m.cruiserFree then return 0, false end
        end
        return cost, health
    end
    local baseBuySpell = E.buyTavernSpell
    E.buyTavernSpell = function(g, color, i)
        local p = g.players[color]
        local entry = p and p.spellShop and p.spellShop[i]
        local free = entry and UPGRADE_OF[entry.id] and E.spellPrice(p, entry) == 0
        local ok, err = baseBuySpell(g, color, i)
        if ok and free then
            local m = findCruiser(p)
            if m and m.cruiserFree then p.cruiserFreeTurn = g.turn end
        end
        return ok, err
    end
    FX[CRUISER] = {
        soc = function(C, S, m)
            local dmg = m.cruiserYamato or 0
            if dmg <= 0 then return end
            local foe = otherSide(C, S)
            for _ = 1, m.cruiserMissile and 2 or 1 do
                local best
                for _, t in ipairs(foe.list) do if t.hp > 0 and (not best or t.hp > best.hp) then best = t end end
                if best then dealDamage(C, foe, best, dmg, m) end
            end
        end,
        onAttack = function(C, S, m)
            local v, vh = m.cruiserRally or 0, m.cruiserRallyH or 0
            if v > 0 or vh > 0 then for _, o in ipairs(alive(S.list, m)) do buff(o, v, vh) end end
        end,
        dr = function(C, S, m)
            local v = m.cruiserDR or 0
            local vh = m.cruiserDRH or v
            local first = alive(S.list, m)[1]
            if (v > 0 or vh > 0) and first then buff(first, v, vh) end
        end,
        endTurn = function(g, p, m)
            for _ = 1, m.cruiserBunker or 0 do
                if E.handCount(p) >= E.MAX_HAND then break end
                local mech = drawFromPool(g, p.tier, 1, function(c) return c.magnetic end)
                if not mech then break end
                if not addToHand(g, p, mech) then returnToPool(g, mech); break end
            end
        end,
    }
    card(CRUISER).rally, card(CRUISER).fx = true, "full"
    HP.BG31_HERO_801 = passive({
        gameStart = function(g, p) E.boardToken(g, p, CRUISER) end,
        refresh = function(g, p) E.addCruiserUpgradeToTavern(g, p) end,
    })
    heroScripted("BG31_HERO_801")
    if E.TR and not E.TR.BG32_MagicItem_806 then                       -- Battlecruiser Portrait (trinket)
        E.TR.BG32_MagicItem_806 = {
            pick = function(g, p) local m = giveToken(g, p, CRUISER); if m then m.atk, m.hp = 12, 12 end end,
            refresh = function(g, p) E.addCruiserUpgradeToTavern(g, p) end,
        }
    end
    FX.BG31_HERO_801_Buddy = {tavernSpell = function(g, p, m, k)        -- Tychus Findlay
        m.tychusCount = (m.tychusCount or 0) + 1
        if m.tychusCount >= 2 then
            m.tychusCount = 0
            for _ = 1, k do E.giveSpell(g, p, E.randomCruiserUpgrade(g, p.tier)) end
        end
    end}

    ---------------------------------------------------------------------------
    -- Kerrigan: Larva and Zerg morph each turn into a Zerg of an unlocked Tier, keeping stats.
    local ZERG = {{"BG31_HERO_811t2", "BG31_HERO_811t3", "BG31_HERO_811t4"},
        {"BG31_HERO_811t5", "BG31_HERO_811t6", "BG31_HERO_811t7"},
        {"BG31_HERO_811t8", "BG31_HERO_811t9", "BG31_HERO_811t10"}}
    local IS_ZERG = {["BG31_HERO_811t"] = true}
    for _, row in ipairs(ZERG) do for _, id in ipairs(row) do IS_ZERG[id] = true end end
    E.IS_ZERG = IS_ZERG
    local function zergOptions(g, p)
        local list = {}
        for t = 1, math.min(3, p.zergTier or 1) do for _, id in ipairs(ZERG[t]) do list[#list + 1] = id end end
        shuffle(g, list)
        while #list > 3 do table.remove(list) end
        return list
    end
    local function morph(g, p, m)
        if m.noMorph or not indexOf(p.board, m) then return end
        choose(p, {options = zergOptions(g, p), label = card(m.id).name .. ": choose a Zerg to morph into",
            generated = true, golden = m.golden, transformTimewarp = {zone = "board", uid = m.uid, keepStats = true}})
        if p.bot then
            local guard = 0
            while p.discover and p.discover.transformTimewarp and guard < 10 do
                guard = guard + 1; E.discoverPick(g, p.color, 1)
            end
        end
    end
    local function zergFx(id, t)
        t.startTurn = function(g, p, m) morph(g, p, m) end
        FX[id] = t
        card(id).fx, card(id).note = "full", nil
    end
    zergFx("BG31_HERO_811t", {})
    zergFx("BG31_HERO_811t2", {soc = function(C, S, m)                                        -- Zergling
        local i = indexOf(S.list, m)
        summon(C, S, m.id, m.golden, i and i + 1 or nil, function(x) x.atk, x.hp = m.atk, m.hp end)
    end})
    card("BG31_HERO_811t3").taunt = true
    zergFx("BG31_HERO_811t3", {endTurn = function(_, p, m, k) buff(m, 0, (p.tier or 1) * k) end})   -- Roach
    card("BG31_HERO_811t4").windfury, card("BG31_HERO_811t4").rally = true, true
    zergFx("BG31_HERO_811t4", {onAttack = function(C, S, m, k)                                 -- Hydralisk
        local p = ownerOf(C, S); permanent(C, m, (p and p.tier or 1) * k, 0)
    end})
    card("BG31_HERO_811t5").deathrattle = true
    zergFx("BG31_HERO_811t5", {dr = function(C, S, m)                                          -- Baneling
        local foe = otherSide(C, S)
        local t = pick(C.g, alive(foe.list))
        if t and m.atk > 0 then dealDamage(C, foe, t, m.atk, m) end
    end})
    zergFx("BG31_HERO_811t6", {allyKill = function(C, _, m, k) permanent(C, m, 3 * k, 0) end})  -- Mutalisk
    card("BG31_HERO_811t7").stealth = true
    zergFx("BG31_HERO_811t7", {avenge = {n = 1, fn = function(C, S, m, k) permanent(C, m, k or 1, k or 1) end}})  -- Lurker
    card("BG31_HERO_811t8").venom = true
    zergFx("BG31_HERO_811t8", {soc = function(_, _, m) m.buddyImmuneAttack = true end})       -- Viper
    local function infest(p, k) for _, o in ipairs(p.board) do buff(o, k, k) end end
    zergFx("BG31_HERO_811t9", {afterPlay = function(_, p, _, _, k) infest(p, k) end,           -- Infestor
        anySpell = function(_, p, _, k) infest(p, k) end})
    card("BG31_HERO_811t10").cleave = true
    zergFx("BG31_HERO_811t10", {soc = function(_, _, m) buff(m, m.atk, m.hp) end})            -- Ultralisk
    HP.BG31_HERO_811 = {
        gameStart = function(g, p) p.zergTier, p.zergStageTurn = 1, g.turn; E.boardToken(g, p, "BG31_HERO_811t") end,
        cost = function(p, c)
            local g = E.lastGame
            local base = (p.zergTier or 1) >= 2 and 8 or 6
            return math.max(0, base - ((g and g.turn or 1) - (p.zergStageTurn or 1)))
        end,
        active = function(g, p)
            if (p.zergTier or 1) >= 3 then return false, "Ultralisk Cavern: your Zerg can already morph into Tier 3 Zerg." end
            p.zergTier = (p.zergTier or 1) + 1
            p.zergStageTurn = g.turn
            E.event(g, p.color, "hero_power", p.name .. " unlocked Tier " .. p.zergTier .. " Zerg.")
            return true
        end,
    }
    heroScripted("BG31_HERO_811")

    ---------------------------------------------------------------------------
    -- Sire Denathrius: choose one of two Quests at the start of the game.
    HP.BG24_HERO_100 = passive({gameStart = function(g, p)
        if p.quest or p.questOffer or not E.offerQuests then return end
        if E.offerQuests(g, p) then
            while #p.questOffer.options > 2 do table.remove(p.questOffer.options) end
            if p.bot then E.questPick(g, p.color, 1) end
        end
    end})
    heroScripted("BG24_HERO_100")
    FX.BG24_HERO_100_Buddy = {sell = function(g, p)                    -- Shady Aristocrat
        if (p.quest and not p.quest.done) or p.questOffer or not E.offerQuests then return end
        if E.offerQuests(g, p) then
            for _, o in ipairs(p.questOffer.options) do o.reward = "BG33_Reward_012" end   -- Coin Pouch
            if p.bot then E.questPick(g, p.color, 1) end
        end
    end}
    card("BG24_HERO_100_Buddy").note = "The Quest's Reward is a Coin Pouch."

    ---------------------------------------------------------------------------
    -- The Great Akazamzarak: choose a Secret; it triggers once in combat and is used up.
    local SECRETS = {
        {id = "TB_Bacon_Secrets_01", name = "Venomstrike Trap", on = "attacked"},
        {id = "TB_Bacon_Secrets_02", name = "Snake Trap", on = "attacked"},
        {id = "TB_Bacon_Secrets_04", name = "Splitting Image", on = "attacked"},
        {id = "TB_Bacon_Secrets_07", name = "Autodefense Matrix", on = "attacked"},
        {id = "TB_Bacon_Secrets_15", name = "Pack Tactics", on = "attacked"},
        {id = "TB_Bacon_Secrets_05", name = "Effigy", on = "death"},
        {id = "TB_Bacon_Secrets_08", name = "Avenge", on = "death"},
        {id = "TB_Bacon_Secrets_10", name = "Redemption", on = "death"},
        {id = "TB_Bacon_Secrets_12", name = "Ice Block", on = "hero"},
        {id = "TB_Bacon_Secrets_13", name = "Competitive Spirit", on = "turn"},
    }
    local SECRET_BY = {}
    for _, s in ipairs(SECRETS) do SECRET_BY[s.id] = s end
    E.SECRETS = SECRET_BY
    local function better(p)
        for _, m in ipairs(p.board) do if m.id == "TB_BaconShop_HERO_21_Buddy" then return mult(m) end end
        return 0
    end
    local function useSecret(p, id)
        for i, s in ipairs(p.secrets or {}) do if s == id then table.remove(p.secrets, i); return true end end
    end
    local function has(p, id) return p and p.secrets and indexOf(p.secrets, id) end
    local function summonCopy(C, S, src, after, setup)
        local i = indexOf(S.list, after)
        return summon(C, S, src.id, src.golden, i and i + 1 or nil, setup)
    end
    HP.TB_BaconShop_HERO_21 = {active = function(g, p)
        p.secrets = p.secrets or {}
        if #p.secrets >= 5 then return false, "You already have 5 Secrets." end
        local list = {}
        for _, s in ipairs(SECRETS) do if not indexOf(p.secrets, s.id) then list[#list + 1] = s.id end end
        shuffle(g, list)
        while #list > 3 do table.remove(list) end
        if #list == 0 then return false, "No Secrets left to choose." end
        choose(p, {moreHeroChoice = "akazam_secret", label = "Prestidigitation: Choose a Secret", options = list, cardOptions = true})
        if p.bot then E.discoverPick(g, p.color, 1) end
        return true
    end}
    heroScripted("TB_BaconShop_HERO_21")
    local basePick = E.moreHeroPick
    E.moreHeroPick = function(g, p, index)
        local d = p.discover
        if d and d.moreHeroChoice == "akazam_secret" then
            local id = d.options[index]
            if not id then return false, "That choice is unavailable." end
            p.secrets = p.secrets or {}
            p.secrets[#p.secrets + 1] = id
            p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue, 1) or nil
            E.event(g, p.color, "hero_power", p.name .. " set a Secret.")
            return true
        end
        return basePick(g, p, index)
    end
    E.TR.BGH_SECRETS = {
        attacked = function(g, p, C, S, target)
            if not target or target.hp <= 0 then return end
            local b = better(p)
            for _, s in ipairs(SECRETS) do
                if s.on == "attacked" and has(p, s.id) then
                    useSecret(p, s.id)
                    if s.id == "TB_Bacon_Secrets_07" then target.shield = true
                    elseif s.id == "TB_Bacon_Secrets_04" or (s.id == "TB_Bacon_Secrets_15" and b > 0) then
                        summonCopy(C, S, target, target, function(x) x.atk, x.hp = target.atk, target.hp end)
                    elseif s.id == "TB_Bacon_Secrets_15" then
                        summonCopy(C, S, target, target, function(x) x.atk, x.hp = 3, 3 end)
                    elseif s.id == "TB_Bacon_Secrets_02" then
                        for _ = 1, 3 do summonCopy(C, S, {id = "EX1_554t"}, target) end
                    elseif s.id == "TB_Bacon_Secrets_01" then
                        summonCopy(C, S, {id = "EX1_170"}, target, function(x) if b > 0 then x.reborn = true end end)
                    end
                    return
                end
            end
        end,
        death = function(g, p, C, S, dead)
            if not dead then return end
            for _, s in ipairs(SECRETS) do
                if s.on == "death" and has(p, s.id) then
                    useSecret(p, s.id)
                    if s.id == "TB_Bacon_Secrets_10" then
                        local full = better(p) > 0
                        summon(C, S, dead.id, dead.golden, nil, function(x)
                            if full then x.atk, x.hp = math.max(x.atk, dead.atk), math.max(x.hp, dead.maxhp or dead.hp, 1)
                            else x.hp = 1 end
                        end)
                    elseif s.id == "TB_Bacon_Secrets_08" then
                        local t = pick(C.g, alive(S.list, dead))
                        if t then buff(t, 3, 2) end
                    elseif s.id == "TB_Bacon_Secrets_05" then
                        local tier = card(dead.id).tier or 1
                        local m = drawFromPool(C.g, tier, tier)
                        if m then local id = m.id; returnToPool(C.g, m); summon(C, S, id, false) end
                    end
                    return
                end
            end
        end,
    }
    E.hasSecret, E.useSecret, E.betterSecrets = has, useSecret, better
    function E.iceBlock(g, p, n)
        if not has(p, "TB_Bacon_Secrets_12") then return false end
        if p.hp + p.armor - n > 0 then return false end
        useSecret(p, "TB_Bacon_Secrets_12")
        p.iceBlockTurn = g.turn
        return true
    end

    ---------------------------------------------------------------------------
    -- Remaining Buddies
    -- Pigeon Lord: Refreshes are free while the Tavern has no minion of your hero's type.
    local baseRefreshCost = E.refreshCost
    E.refreshCost = function(p, g)
        local c = baseRefreshCost(p, g)
        if c and c > 0 then
            for _, m in ipairs(p.board) do
                if m.id == "TB_BaconShop_HERO_12_Buddy" then
                    local tribe = heroTribe[p.hero]
                    if p.hero == "TB_BaconShop_HERO_12" and g and #(g.tribes or {}) > 0 then   -- The Rat King's type this turn
                        tribe = g.tribes[((g.turn - 1) % #g.tribes) + 1]
                    end
                    local seen = false
                    if tribe then for _, t in ipairs(p.tavern or {}) do if hasRace(t, tribe) then seen = true; break end end end
                    if tribe and not seen then return 0 end
                end
            end
        end
        return c
    end
    FX.TB_BaconShop_HERO_12_Buddy = FX.TB_BaconShop_HERO_12_Buddy or {}
    -- Chromie: one Refresh each turn is helpful - it rolls one of the Battlegrounds helpful shops.
    local UTILITY = {"BG_LOE_077", "BG25_354", "BG26_ICC_901", "BGS_009", "BGS_021"}
    local KEYWORD = {"shield", "taunt", "windfury", "reborn"}
    function E.helpfulRefresh(g, p)
        local slots = math.max(#p.tavern, tavernSize(p))
        local function clear() for _, m in ipairs(p.tavern) do returnToPool(g, m) end; p.tavern = {} end
        local function fill(maxT, minT, filter)
            while #p.tavern < slots do
                local m = drawFromPool(g, maxT or p.tier, minT or 1, filter)
                if not m then break end
                table.insert(p.tavern, m)
            end
        end
        local function take(id)
            if (g.pool[id] or 0) <= 0 or #p.tavern >= slots then return false end
            g.pool[id] = g.pool[id] - 1
            table.insert(p.tavern, E.newMinion(g, id, false))
            return true
        end
        local kinds = {"tribal", "copies", "higher", "golden", "buffed", "utility", "spells"}
        local kind = kinds[rnd(g, #kinds)]
        local label
        if kind == "tribal" then
            local best, count = nil, 0
            for _, r in ipairs(g.tribes or {}) do
                local n = 0
                for _, m in ipairs(p.board) do if hasRace(m, r) then n = n + 1 end end
                if n > count then best, count = r, n end
            end
            if not best then kind = "higher" else
                clear(); fill(p.tier, 1, function(c) return c.all or indexOf(c.races, best) end); fill()
                label = (E.RACE_NAME[best] or best) .. " shop"
            end
        end
        if kind == "copies" then
            clear()
            local counts = {}
            for _, m in ipairs(p.board) do if not m.golden and not m.generated then counts[m.id] = (counts[m.id] or 0) + 1 end end
            local ids = {}
            for id in pairs(counts) do ids[#ids + 1] = id end
            table.sort(ids, function(a, b) return counts[a] > counts[b] or (counts[a] == counts[b] and a < b) end)
            for _, id in ipairs(ids) do take(id) end
            for _, id in ipairs(ids) do if counts[id] >= 2 then take(id) end end
            fill(); label = "copies of your warband"
        elseif kind == "higher" then
            clear()
            local top = math.min(p.maxTier or 6, p.tier + 1)
            fill(top, top)
            if g.tierSeven ~= false and #p.tavern > 0 then
                local seven = drawFromPool(g, 7, 7)
                if seven then returnToPool(g, table.remove(p.tavern)); table.insert(p.tavern, seven) end
            end
            fill(); label = "higher-Tier minions"
        elseif kind == "golden" then
            local m = pick(g, p.tavern)
            if m then makeGolden(m) end
            label = "a Golden minion"
        elseif kind == "buffed" then
            for _, m in ipairs(p.tavern) do
                buff(m, p.tier, p.tier)
                m[KEYWORD[rnd(g, #KEYWORD)]] = true
            end
            label = "buffed minions"
        elseif kind == "utility" then
            clear()
            local list = {}
            for _, id in ipairs(UTILITY) do if card(id) and card(id).tier <= math.min(6, p.tier + 1) then list[#list + 1] = id end end
            shuffle(g, list)
            for i = 1, math.min(3, #list) do take(list[i]) end
            fill(); label = "utility minions"
        elseif kind == "spells" then
            E.rollSpellShop(g, p, true)
            label = "a shop of Tavern spells"
        end
        E.event(g, p.color, "hero_power", "Chromie's helpful Refresh: " .. (label or kind) .. ".")
        return kind
    end
    local baseRefresh = E.refresh
    E.refresh = function(g, color, free)
        local p = g.players[color]
        local chromie = false
        if p and p.chromieTurn ~= g.turn then
            for _, m in ipairs(p.board) do if m.id == "TB_BaconShop_HERO_57_Buddy" then chromie = true end end
        end
        local ok, err = baseRefresh(g, color, free)
        if ok and chromie then p.chromieTurn = g.turn; E.helpfulRefresh(g, p) end
        return ok, err
    end
    FX.TB_BaconShop_HERO_57_Buddy = FX.TB_BaconShop_HERO_57_Buddy or {}
    -- Street Magician: Prestidigitation's Secrets are the Better versions (stronger effects above).
    FX.TB_BaconShop_HERO_21_Buddy = FX.TB_BaconShop_HERO_21_Buddy or {}
    -- Nexus Lord: Arcane Alteration replaces with a card from one Tier higher.
    FX.TB_BaconShop_HERO_58_Buddy = FX.TB_BaconShop_HERO_58_Buddy or {}
    function E.nexusBonus(p)
        for _, m in ipairs(p.board) do if m.id == "TB_BaconShop_HERO_58_Buddy" then return 1 end end
        return 0
    end
    -- Stoneshell Guardian: the first Triple Reward played each turn Discovers from Golden minions.
    FX.BG33_HERO_000_Buddy = FX.BG33_HERO_000_Buddy or {}
    local triple = E.SPELLS.TB_BaconShop_Triples_01
    if triple then
        local baseCast = triple.cast
        triple.cast = function(g, p, ...)
            local ok, err = baseCast(g, p, ...)
            if ok and p.stoneshellTurn ~= g.turn then
                for _, m in ipairs(p.board) do
                    if m.id == "BG33_HERO_000_Buddy" then
                        local d = p.discoverQueue[#p.discoverQueue] or p.discover
                        if d then d.golden = true end
                        p.stoneshellTurn = g.turn
                        break
                    end
                end
            end
            return ok, err
        end
    end
    for _, id in ipairs({"TB_BaconShop_HERO_12_Buddy", "TB_BaconShop_HERO_57_Buddy", "TB_BaconShop_HERO_21_Buddy",
            "TB_BaconShop_HERO_58_Buddy", "BG33_HERO_000_Buddy", "BG24_HERO_100_Buddy", "BG31_HERO_801_Buddy"}) do
        local c = card(id)
        if c then c.fx = c.note and "simplified" or "full" end
    end
end

end
do
-- Battlegrounds v4: Hero Powers, Trinkets, Anomalies and Buddies (pure Lua, runs after bg_engine.lua).
-- Hero, trinket and anomaly data are imported from HearthstoneJSON (Scripts/bg_meta.lua).
-- HP[heroId]   = {active = fn(g, p, target) -> ok, msg; target = "board"|"tavern"|nil; uses; cost(p, base);
--                 unlock(g, p); passive = true; hooks: gameStart, startTurn, endTurn, buy, sell, play,
--                 refresh, upgrade, afterCombat(g, p, won, dmg, lost); soc(C, S, enemy, g)}
-- NOTE[heroId] = how the scripted power differs from the real one (shown on the hero and in HERO_COVERAGE.csv).
-- TR[trinketId], AN[anomalyId] use the same hooks. Tools/build_bg_meta.py reads the HP/TR/AN/NOTE lines.
local E = BG
local HP, TR, AN = E.HP, E.TR, E.AN
local NOTE = {}
E.NOTE = NOTE

local function card(id) return BG_CARDS[id] end
local function say(g, p, msg) E.event(g, p.color, "hero_power", msg) end
local function rnd(g, n) return g.rand(n) end

local function boardTarget(p, t)
    local i = (type(t) == "number" and t) or (type(t) == "table" and t.zone == "board" and t.index) or nil
    local m = i and p.board[i]
    if not m then return nil, "Pick up one of your minions on the board to choose the target." end
    return m, i
end
local function tavernTarget(p, t)
    local i = (type(t) == "table" and t.zone == "tavern" and t.index) or nil
    local m = i and p.tavern[i]
    if not m then return nil, "Pick up a minion in the Tavern to choose the target." end
    return m, i
end
local function give(g, p, m) if m then return E.addToHand(g, p, m) end return false end
local function handRoom(p) return E.handCount(p) < E.MAX_HAND end
local function raceFilter(race) return function(c) return c.all or E.indexOf(c.races, race) ~= nil end end
local function inPool(g, id) return (g.pool[id] or 0) > 0 end
local function plain(g, m) return E.newMinion(g, m.id, false) end
local function mostCommonRace(p)
    local n, best, bn = {}, nil, 0
    for _, m in ipairs(p.board) do
        for _, r in ipairs(card(m.id).races) do n[r] = (n[r] or 0) + 1; if n[r] > bn then best, bn = r, n[r] end end
    end
    return best
end


function E.timewarpSlots(g, p, options, tier)
    local powersOk = tier <= 3 and not p.secondPowerHero
    local powers, minions, spells = {}, {}, {}
    for _, id in ipairs(options) do
        local d = BG_TIMEWARP[id]
        if d.kind == "power" then
            if powersOk and not (E.hasPower and E.hasPower(p, id)) then powers[#powers + 1] = id end
        elseif d.kind == "minion" then minions[#minions + 1] = id
        else spells[#spells + 1] = id end
    end
    local chosen, used, cheap, dear = {}, {}, 0, 0
    local function take(id)
        chosen[#chosen + 1], used[id] = id, true
        if BG_TIMEWARP[id].cost <= 1 then cheap = cheap + 1 else dear = dear + 1 end
    end
    local function fits(id) if BG_TIMEWARP[id].cost <= 1 then return cheap < 3 end return dear < 2 end
    local function fill(list, n, strict)
        for _, id in ipairs(list) do
            if n <= 0 then break end
            if not used[id] and (not strict or fits(id)) then take(id); n = n - 1 end
        end
        return n
    end
    if powers[1] then take(powers[1]) end
    local need = 2 - #chosen
    need = fill(spells, need, true); fill(spells, need, false)
    local m = fill(minions, 3, true); fill(minions, m, false)
    if #chosen < 5 then
        local rest = {}
        for _, l in ipairs({minions, spells}) do for _, id in ipairs(l) do rest[#rest + 1] = id end end
        fill(rest, 5 - #chosen, false)
    end
    local slots = {}
    for i, id in ipairs(chosen) do slots[i] = {id = id} end
    return slots
end
-------------------------------------------------------------------------------
-- Hero Powers (current HearthstoneJSON text; scripted ones below)
HP["TB_BaconShop_HERO_01"] = {target = "board", cost = function(p, c) return c end, -- Edwin VanCleef
    active = function(g, p, t)
        local m, e = boardTarget(p, t); if not m then return false, e end
        local k = 2 + math.floor((p.counters.buysTotal or 0) / 4)
        E.buff(m, k, k); return true, "Sharpen Blades: +" .. k .. "/+" .. k .. "." end}
NOTE["TB_BaconShop_HERO_01"] = "Improves by +1/+1 for every 4 cards bought this game."
HP["TB_BaconShop_HERO_15"] = {target = "board", active = function(g, p, t) -- George the Fallen
    local m, e = boardTarget(p, t); if not m then return false, e end
