function E.skipsRecruit(g, p)
    return g.turn == 1 and p.hero == "BG22_HERO_201"
end

function E.releaseExpeditions(g,p)
    local spellPlans={}
    for _,plan in ipairs(p.spellExpeditions or {}) do
        if plan.gold and E.goldLocked(p,plan) then plan.turn=g.turn+1 end
        if (plan.gold and E.goldLocked(p,plan)) or (not plan.gold and plan.turn>g.turn) or not handRoom(p) then spellPlans[#spellPlans+1]=plan
        else p.spellHand[#p.spellHand+1]=plan.spell;E.raiseHandGained(g,p) end
    end
    p.spellExpeditions=spellPlans
    local pending=p.expeditions
    if not pending or #pending == 0 then return end
    local locked, delivered = {}, false
    for _, plan in ipairs(pending) do
        if plan.gold and E.goldLocked(p, plan) then plan.turn = g.turn + 1 end
        if (plan.gold and E.goldLocked(p, plan)) or (not plan.gold and ((plan.tier and plan.tier > p.tier) or (plan.turn and plan.turn > g.turn))) then
            table.insert(locked, plan)
        elseif E.addToHand(g, p, plan.minion) then
            delivered = true
            E.event(g, p.color, "card_draw", nil)
        elseif plan.reserved then
            E.returnToPool(g, plan.minion)
        end
    end
    p.expeditions = locked
    if delivered then E.checkTriples(g, p) end
end

-- A pre-fix saved first turn still has the three discoveries in its normal hand.
function E.restoreExpedition(g, p)
    if p.hero ~= "BG22_HERO_201" or p.expeditions or g.turn ~= 1 then return end
    local function updateOffer(offer)
        if offer and type(offer.label) == "string" then
            offer.unlockTier = tonumber(offer.label:match("^Expedition Plans: Tier (%d+)$")) or offer.unlockTier
        end
    end
    updateOffer(p.discover)
    for _, offer in ipairs(p.discoverQueue or {}) do updateOffer(offer) end
    local tierSeen, locked = {}, {}
    for _, m in ipairs(p.hand) do
        local info = BG_CARDS[m.id]
        local tier = info and info.tier
        if (tier == 2 or tier == 4 or tier == 6) and tier > p.tier and not tierSeen[tier] then
            tierSeen[tier] = true
            table.insert(locked, {tier = tier, minion = m, reserved = true})
        end
    end
    if #locked > 0 then
        local planned = {}
        for _, plan in ipairs(locked) do planned[plan.minion.uid] = true end
        local hand = {}
        for _, m in ipairs(p.hand) do if not planned[m.uid] then table.insert(hand, m) end end
        p.hand, p.expeditions = hand, locked
    end
end

HP["BG22_HERO_201"] = {passive = true, startTurn = function(g, p)
    if not E.skipsRecruit(g, p) then return end
    p.gold, p.ready, p.expeditions = 0, true, {}
    for _, tier in ipairs({6, 4, 2}) do
        E.startDiscover(g, p, tier, function(c) return c.tier == tier end, "Expedition Plans: Tier " .. tier, tier)
    end
end}
