    local function mode(g,p,id,optionNames,extra)
        if #optionNames==0 then return false,"No choices are available." end
        local d=extra or {}
        d.kind,d.options,d.powerId="hero_option",optionNames,id
        d.label=d.label or E.heroById(id).power
        if p.discover then p.discoverQueue[#p.discoverQueue+1]=d else p.discover=d end
        return true
    end
    function E.pickHeroOption(g,p,index)
        local d=p.discover
        local option=d.options[index]
        local run=resolvers[d.powerId]
        if not option or not run then return false,"That option is unavailable." end
        local nextChoice=#p.discoverQueue>0 and table.remove(p.discoverQueue,1) or nil
        p.discover=nextChoice
        local ok,err=run(g,p,option,d)
        if not ok then
            if nextChoice then table.insert(p.discoverQueue,1,nextChoice) end
            p.discover=d
            return false,err
        end
        E.checkTriples(g,p)
        return true
    end

    HP.BG20_HERO_301={target="board",active=function(g,p,t)
