            table.sort(ids);E.shuffle(g,ids)
            local options={ids[1],ids[2],ids[3]}
            local d={options=options,generated=true,label="Sign a New Artist · Discover a Buddy"}
            if p.discover then p.discoverQueue[#p.discoverQueue+1]=d else p.discover=d end
            return #options>0
        end}
    HP.TB_BaconShop_HERO_17={unlock=function(_,p)return p.tier>=4,"unlocks at Tavern Tier 4." end,
        active=function(g,p)
            return E.startDiscover(g,p,p.tier,function(c)return c.magnetic and E.indexOf(c.races,"MECHANICAL") end,"Discover a Magnetic Mech"),"There are no eligible Mechs in the pool."
        end}

    HP.TB_BaconShop_HERO_62={target="shop",active=function(g,p,t)
        if not handRoom(p) then return false,"Your hand is full." end
        if t and t.zone=="spellshop" and p.spellShop[t.index] then
            local spell=table.remove(p.spellShop,t.index)
            p.spellExpeditions=p.spellExpeditions or {}
            p.spellExpeditions[#p.spellExpeditions+1]={spell=spell,turn=g.turn+2}
            return true
        end
        local m,i=tavernTarget(p,t)
        if not m or m.id=="BG35_150t" then return false,"Choose a buyable Tavern card." end
        table.remove(p.tavern,i)
        p.expeditions=p.expeditions or {}
        p.expeditions[#p.expeditions+1]={minion=m,turn=g.turn+2,reserved=not m.generated}
        return true
    end}

    HP.BG25_HERO_103={target="board",active=function(_,p,t)
        local m,err=boardTarget(p,t)
        if not m then return false,err end
        p.reanimation=m.uid
        return true
    end,soc=function(C,S)
        local p=E.C.owner(C,S)
        local target=p and p.reanimation
        if not target then return end
        p.reanimation=nil
        for i,m in ipairs(S.list) do
            if m.src==target then
                local saved=E.copy(m)
                m.hp=0
                E.C.resolveDeaths(C)
                if #S.list<E.MAX_BOARD then E.C.summonCopy(C,S,saved,i) else S.reanimation={saved=saved,pos=i} end
                break
            end
        end
    end}

    HP.BG23_HERO_306={unlock=function(g)return g.turn>=3,"unlocks on Turn 3." end,
        active=function(g,p)
            local options={}
            for id in pairs(p.lastCombatDead or {}) do if card(id) and not card(id).deity then options[#options+1]=id end end
            if #options==0 then return false,"None of your minions died last combat." end
            table.sort(options);E.shuffle(g,options)
            while #options>3 do table.remove(options) end
            local d={options=options,generated=true,label="Reclaimed Souls"}
            if p.discover then p.discoverQueue[#p.discoverQueue+1]=d else p.discover=d end
            return true
        end}

    HP.BG30_HERO_304={passive=true,startTurn=function(g,p)
        if g.turn==5 and not p.offer then E.offerTrinkets(g,p,"Lesser") end
    end}
    HP.BG32_HERO_002={passive=true,startTurn=function(g,p)
        if g.turn==8 and not p.offer then E.offerTrinkets(g,p,"Greater") end
    end}

    local function choosePower(g,p,source,count)
        local ids={}
        for _,h in ipairs(BG_HEROES) do
            local power=HP[h.id]
            if h.id~=p.hero and E.heroAvailable(g,h.id) and power and power.active
                and h.id~="BG20_HERO_283" and not power.soc then ids[#ids+1]=h.id end
        end
        E.shuffle(g,ids)
        while #ids>count do table.remove(ids) end
        return mode(g,p,source,ids,{portraits=true})
    end
    HP.BG20_HERO_202={passive=true,startTurn=function(g,p)
        p.powerHero=nil
        choosePower(g,p,"BG20_HERO_202",2)
    end}
    HP.TB_BaconShop_HERO_40={passive=true,gameStart=function(g,p) choosePower(g,p,"TB_BaconShop_HERO_40",3) end}
    local function copyPower(_,p,id)
        p.powerHero=id
        return true
    end
    resolvers.BG20_HERO_202,resolvers.TB_BaconShop_HERO_40=copyPower,copyPower
    local function powerBuddy(g,p,k)
        local h=E.powerHero(p)
        if not h or not h.buddy then return end
        for _=1,k do
            if not handRoom(p) or not card(h.buddy) then return end
            local m=E.newMinion(g,h.buddy,false)
            m.generated=true;give(g,p,m)
        end
    end
    if card("BG20_HERO_202_Buddy") then
        local function grantAfterChoice(g,p,id,d)
            copyPower(g,p,id,d)
            for _,m in ipairs(p.board) do if m.id=="BG20_HERO_202_Buddy" then powerBuddy(g,p,E.mult(m)) end end
            return true
        end
        resolvers.BG20_HERO_202=grantAfterChoice
    end

    HP.BG27_HERO_801={passive=true,gameStart=function(g,p)
        local ids={}
        for id in pairs(g.allowed or BG_CARDS) do
            local c=card(id)
            if c.tier==7 and (g.allowed or c.pool) then
                local available=c.all or #c.races==0
                for _,race in ipairs(c.races) do if E.indexOf(g.tribes,race) then available=true;break end end
                if available then ids[#ids+1]=id end
            end
        end
        table.sort(ids);E.shuffle(g,ids)
        while #ids>3 do table.remove(ids) end
        if #ids>0 then
            local d={options=ids,generated=true,thorim=true,label="Choose Your Champion"}
            if p.discover then p.discoverQueue[#p.discoverQueue+1]=d else p.discover=d end
        end
    end,spendGold=function(g,p)
        local m=p.thorimChampion
        if m and (p.totalGoldSpent or 0)>=60 and give(g,p,m) then p.thorimChampion=nil end
    end,startTurn=function(g,p)
        local m=p.thorimChampion
        if m and (p.totalGoldSpent or 0)>=60 and give(g,p,m) then p.thorimChampion=nil end
    end}

    HP.TB_BaconShop_HERO_72={active=function(g,p)
        local choices={}
        for _,pair in ipairs(E.recruitPairings(g)) do
            if pair[2] and pair[1]~=p and pair[2]~=p then choices[#choices+1]=pair end
        end
        local pair=E.pick(g,choices)
        if not pair then return false,"There is no other live pairing for a wager." end
        local labels={}
        for _,o in ipairs(pair) do
            local description=E.hero(o)
            labels[o.color]=o.name..(description and (" · "..description.name) or "")
        end
        return mode(g,p,"TB_BaconShop_HERO_72",{pair[1].color,pair[2].color},
            {descriptions=labels,label="Friendly Wager · Pick the winner"})
    end}
    resolvers.TB_BaconShop_HERO_72=function(g,p,color) p.wager={color=color,turn=g.turn};return true end
    function E.resolveCombatWagers(g,results)
        local winners={}
        for _,r in ipairs(results) do
            if r.winner==1 then winners[r.a]=true elseif r.winner==2 and r.b then winners[r.b]=true end
        end
        for _,color in ipairs(g.order) do
            local p=g.players[color]
            if p.wager and p.wager.turn==g.turn then
                if winners[p.wager.color] then for _=1,3 do E.giveSpell(g,p,"BG28_810") end end
                p.wager=nil
            end
        end
    end

    HP.BG23_HERO_303={active=function(g,p)
        local opponent
        for _,pair in ipairs(E.recruitPairings(g)) do
            if pair[1]==p then opponent=pair[2];break elseif pair[2]==p then opponent=pair[1];break end
        end
        local roster=opponent and opponent.lastCombatStart
        if not roster or #roster==0 then return false,"Your opponent has no recorded minions from last combat." end
        local known,wrong={},{}
        for _,id in ipairs(roster) do known[id]=true end
        for id in pairs(g.pool) do if not known[id] and card(id).tier<=opponent.tier then wrong[#wrong+1]=id end end
        table.sort(wrong)
        local right,decoy=E.pick(g,roster),E.pick(g,wrong)
        if not decoy then return false,"No decoy is available." end
        return mode(g,p,"BG23_HERO_303",E.shuffle(g,{right,decoy}),{answer=right,minionChoices=true})
    end}
    resolvers.BG23_HERO_303=function(g,p,id,d)
        if id==d.answer then
            E.giveSpell(g,p,"BG28_810")
            for _,m in ipairs(p.board) do
                if m.id=="BG23_HERO_303_Buddy" then for _=1,E.mult(m) do
                    local copy=E.newMinion(g,id,false);copy.generated=true;give(g,p,copy)
                end end
            end
        end
        return true
    end
    if card("BG23_HERO_303_Buddy") then card("BG23_HERO_303_Buddy").fx="full" end
end

