-- Trinkets: Tools/build_bg_meta.py parses the simple ones ("Get a <minion>", gold, armor, stat auras)
-- into data fields; one generic script runs them.
for _, t in ipairs(BG_TRINKETS or {}) do
    if t.get or t.gold or t.armor or t.maxGold or t.socAll or t.socRace or t.endLeft then
        TR[t.id] = {pick = function(g, p)
            for _, id in ipairs(t.get or {}) do if card(id) then give(g, p, E.newMinion(g, id, false)) end end
            if t.gold then p.gold = p.gold + t.gold end
            if t.maxGold then p.extraMaxGold = (p.extraMaxGold or 0) + t.maxGold end
            if t.armor then p.armor = p.armor + t.armor end
        end}
        if t.socAll or t.socRace then
            TR[t.id].soc = function(C, S)
                for _, m in ipairs(S.list) do
                    if t.socAll then E.buff(m, t.socAll[1], t.socAll[2]) end
                    if t.socRace and E.hasRace(m, t.socRace[1]) then E.buff(m, t.socRace[2], t.socRace[3]) end
                end
            end
        end
        if t.endLeft then
            TR[t.id].endTurn = function(g, p) if p.board[1] then E.buff(p.board[1], t.endLeft[1], t.endLeft[2]) end end
        end
    end
end

-- Trinket shop (real rule since Season 8: turn 6 Lesser, turn 9 Greater; 4 offers, paid with Gold).
E.TRINKET_TURNS = {[6] = "Lesser", [9] = "Greater"}
local function offerTrinkets(g,p,kind)
    local counts,lobby,byName={},{},{}
    local most=0
    for _,race in ipairs(g.tribes or {}) do lobby[race]=true end
    for _,m in ipairs(p.board) do
        local c=card(m.id)
        if not c.all and not (m.darkGift and m.darkGift.allTypes) then
            for _,race in ipairs(c.races) do
                if lobby[race] then
                    counts[race]=(counts[race] or 0)+1
                    most=math.max(most,counts[race])
                end
            end
        end
    end
    local already={}
    for _,id in ipairs(p.trinkets or {}) do
        local t=E.trinket(id)
        if t and t.kind==kind then already[t.name]=true end
    end
    for _,t in ipairs(BG_TRINKETS or {}) do
        local effect=TR[t.id]
        if t.kind==kind and effect and not already[t.name] and (not effect.eligible or effect.eligible(g,p)) then
            local available,best=#t.races==0,0
            for _,race in ipairs(t.races) do
                if lobby[race] then available=true;best=math.max(best,counts[race] or 0) end
            end
            if available then
                local candidate={id=t.id,preference=t.automated and 2 or 1,related=best>0 and best==most,
                    weight=best>0 and (3+math.min(3,best)) or (#t.races==0 and 3 or 2)}
                local old=byName[t.name]
                if not old or candidate.preference>old.preference or candidate.preference==old.preference and candidate.id>old.id then
                    byName[t.name]=candidate
                end
            end
        end
    end
    local candidates={}
    for _,item in pairs(byName) do candidates[#candidates+1]=item end
    table.sort(candidates,function(a,b) return a.id<b.id end)
    local options={}
    for slot=1,math.min(4,#candidates) do
        local related=false
        if slot==1 then for _,t in ipairs(candidates) do if t.related then related=true;break end end end
        local total=0
        for _,t in ipairs(candidates) do if not related or t.related then total=total+t.weight end end
        local roll=rnd(g,total)
        for i,t in ipairs(candidates) do
            if not related or t.related then
                roll=roll-t.weight
                if roll<=0 then options[#options+1]=t.id;table.remove(candidates,i);break end
            end
        end
    end
    if #options>0 then
        E.shuffle(g,options)
        p.offer={kind="trinket",options=options,label=kind.." Trinket: choose one to buy"}
    end
end

E.offerTrinkets = offerTrinkets
E.SYS = {startTurn = function(g, p)
    local kind = g.trinkets and E.TRINKET_TURNS[g.turn]
    if kind and not p.offer and p.alive then
        offerTrinkets(g, p, kind)
        if p.offer and p.bot then p.offer.forced = true end
    end
end}
function E.trinket(id)
    if not E._trMap then E._trMap = {} for _, t in ipairs(BG_TRINKETS or {}) do E._trMap[t.id] = t end end
    return E._trMap[id]
end
function E.offerPick(g, color, i)
    local p = g.players[color]
    if not p or not p.offer then return false, "Nothing to choose." end
    local o = p.offer
    if i == nil then -- end of turn: buy the cheapest one you can afford, else keep the offer
        local best
        for k, id in ipairs(o.options) do
            local t = E.trinket(id)
            if t and t.cost <= p.gold and (not best or t.cost < E.trinket(o.options[best]).cost) then best = k end
        end
        if not best then return false end
        i = best
    end
    local id = o.options[i]
    local t = id and E.trinket(id)
    if not t or not TR[id] then return false, "No such option." end
    if p.gold < t.cost then return false, t.name .. " costs " .. t.cost .. " Gold." end
    p.gold = p.gold - t.cost
    E.spendGold(g, p, t.cost)
    p.trinkets = p.trinkets or {}
    table.insert(p.trinkets, id)
    p.offer = nil
    if TR[id] and TR[id].pick then TR[id].pick(g, p) end
    E.event(g, color, "hero_power", p.name .. " bought " .. t.name .. ".")
    E.checkTriples(g, p)
    return true
end

do
    local function owner(C,S) return E.C.owner(C,S) end
    local function race(m,r) return E.hasRace(m,r) end
    local function gain(p,n) p.gold=math.min(99,p.gold+n) end
    local function all(list,a,h,filter)
        for _,m in ipairs(list) do if not filter or filter(m) then E.buff(m,a,h) end end
    end
    local function grant(g,p,id,n,golden)
        for _=1,n or 1 do
            if not card(id) or not handRoom(p) then break end
            local m=E.newMinion(g,id,golden and true or false)
            m.generated=true
            give(g,p,m)
        end
    end
    local function spell(g,p,id,n)
        for _=1,n or 1 do if not E.giveSpell(g,p,id) then break end end
    end
    local function randomMinion(g,p,filter)
        local m=E.drawFromPool(g,p.tier,1,filter)
        if m and not give(g,p,m) then E.returnToPool(g,m) end
    end
    local function statsInShop(p,a,h)
        local prior=p.tavBuff.all or {0,0}
        p.tavBuff.all={prior[1]+a,prior[2]+h}
        all(p.tavern,a,h)
    end
    local function types(p)
        local seen,n={},0
        for _,m in ipairs(p.board) do
            local c=card(m.id)
            for _,r in ipairs(c.races) do if not seen[r] then n=n+1;seen[r]=true end end
        end
        return n
    end
    local function onEachTurn(fn) return {pick=fn,startTurn=fn} end
    local function splitEnds(list,a,h)
        if list[1] then E.buff(list[1],a,h) end
        if #list>1 then E.buff(list[#list],a,h) end
    end
    local function summonTraits(m) return m.darkGift and (m.darkGift.charisma or m.darkGift.gemRally or m.darkGift.fodderRally) or card(m.id).rally end
    local function isDeathrattle(m)
        local gift=m.darkGift
        return card(m.id).deathrattle or gift and (gift.freeRefreshes or gift.spellDeath or gift.golem or gift.sacrificeA or gift.sacrificeH)
    end
    local function counts(p) p.trinketCounts=p.trinketCounts or {};return p.trinketCounts end
    local function progress(p,id,n,limit)
        local values=counts(p)
        values[id]=(values[id] or 0)+n
        local times=math.floor(values[id]/limit)
        values[id]=values[id]%limit
        return times
    end
    local function own(p,id) return E.indexOf(p.trinkets or {},id)~=nil end
    local function full(id,effects)
        TR[id]=effects
        local t=E.trinket(id)
        if t then t.note=nil;t.automated=true end
    end
    for id, original in pairs(TR) do
        local t=E.trinket(id)
        if t and not t.note then t.automated=true end
    end
    local function addLegacyRule(id,trigger,action)
        if not TR[id] or not E.trinket(id).automated then full(id,{[trigger]=action}) end
    end
    local baseRules = {
        {trinket="BG30_MagicItem_403",trigger="soc",kind="multiply",count=3,filter="neutral"},
        {trinket="BG30_MagicItem_406",trigger="both",kind="spell",id="BG28_604",count=1},
        {trinket="BG30_MagicItem_414",trigger="buyCard",a=2,h=1,pos="random",list="board",count=2},
        {trinket="BG30_MagicItem_414t",trigger="buyCard",a=4,h=4,pos="random",list="board",count=2},
        {trinket="BG30_MagicItem_422",trigger="spellTarget",a=4,h=4,pos="self",list="board",count=1},
        {trinket="BG30_MagicItem_422t",trigger="spellTarget",a=10,h=10,pos="self",list="board",count=1},
        {trinket="BG30_MagicItem_543",trigger="both",kind="spell",id="EBG_Spell_032",count=1},
        {trinket="BG30_MagicItem_880",trigger="soc",a=2,h=1,pos="all",list="board"},
        {trinket="BG30_MagicItem_880t",trigger="soc",a=8,h=5,pos="all",list="board"},
        {trinket="BG30_MagicItem_900",trigger="cardPlayed",a=4,h=4,pos="random",list="board",count=1,race="DRAGON"},
        {trinket="BG30_MagicItem_900t",trigger="cardPlayed",a=6,h=4,pos="random",list="board",count=1,race="DRAGON"},
        {trinket="BG30_MagicItem_902",trigger="soc",kind="shield",pos="edges"},
        {trinket="BG30_MagicItem_914",trigger="play",a=5,h=5,pos="left",list="hand",count=1},
        {trinket="BG30_MagicItem_914t",trigger="play",a=10,h=10,pos="left",list="hand",count=1},
        {trinket="BG30_MagicItem_924",trigger="spendGold",a=3,h=3,pos="random",list="board",count=2,race="PIRATE"},
        {trinket="BG30_MagicItem_924t",trigger="spendGold",a=8,h=8,pos="random",list="board",count=2,race="PIRATE"},
        {trinket="BG30_MagicItem_970",trigger="soc",a=2,h=2,pos="all",list="board"},
        {trinket="BG30_MagicItem_970t",trigger="soc",a=6,h=6,pos="all",list="board"},
        {trinket="BG30_MagicItem_984",trigger="endTurn",a=3,h=0,pos="all",list="board",count=1,filter="shield"},
        {trinket="BG30_MagicItem_984t",trigger="endTurn",a=7,h=0,pos="all",list="board",count=1,filter="shield"},
        {trinket="BG32_MagicItem_281",trigger="tavernSpell",a=4,h=4,pos="all",list="board",count=1,filter="neutral"},
        {trinket="BG32_MagicItem_926",trigger="pick",kind="minion",id="BG27_513",count=1},
        {trinket="BG32_MagicItem_944",trigger="both",kind="spell",id="BG28_169",count=1},
        {trinket="BG32_MagicItem_998",trigger="pick",kind="minion",id="BG31_360",count=1},
        {trinket="BG35_MagicItem_710",trigger="tavernSpell",a=4,h=4,pos="all",list="board",race="PIRATE"},
        {trinket="BG36_MagicItem_400",trigger="pick",kind="spell",id="BG36_303",count=2},
        {trinket="BG36_MagicItem_800",trigger="tavernSpell",kind="shop",sa=1,sh=1},
        {trinket="BGDUO_MagicItem_007",trigger="both",kind="minion",id="BGDUO_119",count=1}
    }
    for _,r in ipairs(baseRules) do
        local function check(m)
            local c=card(m.id)
            if r.race then return race(m,r.race) end
            if r.filter=="shield" then return m.shield end
            if r.filter=="neutral" then return #c.races==0 and not c.all and not (m.darkGift and m.darkGift.allTypes) end
            return true
        end
        local function action(g,p,target)
            if r.a then
                local list=r.list=="hand" and p.hand or p.board
                if r.pos=="self" then E.buff(target,r.a,r.h)
                elseif r.pos=="left" then if list[1] then E.buff(list[1],r.a,r.h) end
                elseif r.pos=="edges" then splitEnds(list,r.a,r.h)
                elseif r.pos=="random" then
                    local choices={}
                    for _,m in ipairs(list) do if check(m) then choices[#choices+1]=m end end
                    E.shuffle(g,choices)
                    for i=1,math.min(#choices,r.count or 1) do E.buff(choices[i],r.a,r.h) end
                else all(list,r.a,r.h,check) end
            elseif r.kind=="spell" then spell(g,p,r.id,r.count)
            elseif r.kind=="minion" then grant(g,p,r.id,r.count,r.golden)
            elseif r.kind=="randomspell" then
                for _=1,r.count do E.getRandomSpell(g,p,6,false) end
            elseif r.kind=="cast" then
                for _=1,r.count do E.castGeneratedSpell(g,p,r.id) end
            elseif r.kind=="rollMinion" then
                for _=1,r.count do randomMinion(g,p,function(c) return E.indexOf(c.races,r.race) end) end
            elseif r.kind=="gems" then spell(g,p,"BG20_GEM",r.count)
            elseif r.kind=="gold" then gain(p,r.count)
            elseif r.kind=="armor" then p.armor=p.armor+r.count
            elseif r.kind=="refresh" then p.freeRefreshes=p.freeRefreshes+r.count
            elseif r.kind=="shop" then statsInShop(p,r.sa,r.sh)
            elseif r.kind=="spellAura" then
                p.bonusSpellAtk=(p.bonusSpellAtk or 0)+r.sa
                p.bonusSpellHp=(p.bonusSpellHp or 0)+r.sh
            end
        end
        if r.trigger=="soc" and (r.a or r.kind=="multiply" or r.kind=="shield") then
            addLegacyRule(r.trinket,"soc",function(_,S)
                for i,m in ipairs(S.list) do if check(m) and (r.pos~="edges" or i==1 or i==#S.list) then
                    if r.kind=="shield" then m.shield=true
