    end})
    full("BG35_MagicItem_850",onEachTurn(function(g,p) E.castGeneratedSpell(g,p,"BG34_444") end))
    full("BG35_MagicItem_850t",{pick=function(g,p) for _=1,4 do E.castGeneratedSpell(g,p,"BG34_444") end end,
        startTurn=function(g,p) for _=1,2 do E.castGeneratedSpell(g,p,"BG34_444") end end})
    full("BG35_MagicItem_890",onEachTurn(function(g,p)
        local bounties={"BG33_811","BG33_812","BG33_813","BG33_814","BG33_815"}
        for _=1,2 do spell(g,p,E.pick(g,bounties)) end
    end))
    local chroma={"BG34_634t","BG34_635t","BG34_636t","BG34_637t","BG34_638t"}
    full("BG35_MagicItem_840",onEachTurn(function(g,p) grant(g,p,E.pick(g,chroma)) end))
    full("BG35_MagicItem_840t",{pick=function(g,p) for _=1,2 do grant(g,p,E.pick(g,chroma)) end end,
        play=function(g,p,m) if card(m.id).battlecry and progress(p,"BG35_MagicItem_840t",1,7)>0 then
            for _=1,2 do grant(g,p,E.pick(g,chroma)) end
        end end})

    local function upgradeAfter(id,raceName,hook,needed,amount)
        s(id,{[hook]=function(g,p,...)
            local key="BG36_MagicItem_"..id
            local n=amount and amount(...) or 1
            if progress(p,key,n,needed)==0 then return end
            local options={}
            for _,t in ipairs(BG_TRINKETS) do
                if t.kind=="Greater" and t.automated and not own(p,t.id) and E.indexOf(t.races,raceName)
                    and (not TR[t.id].eligible or TR[t.id].eligible(g,p)) then options[#options+1]=t end
            end
            local new=E.pick(g,options)
            if new then
                local slot=E.indexOf(p.trinkets,key)
                if slot then p.trinkets[slot]=new.id;if TR[new.id].pick then TR[new.id].pick(g,p) end end
            end
        end})
    end
    upgradeAfter("305","NAGA","anySpell",18)
    upgradeAfter("408","PIRATE","spendGold",40,function(n)return n end)
    upgradeAfter("409","QUILBOAR","castFromHand",10,function(id)return id=="BG20_GEM" and 1 or 0 end)
    upgradeAfter("410","UNDEAD","summonTrinket",25)

    local dragonStaff="BG36_MagicItem_407"
    s("407",{attack=function(g,p)
        if not own(p,dragonStaff) or progress(p,dragonStaff,1,11)==0 then return end
        local candidates={}
        for _,t in ipairs(BG_TRINKETS) do
            if t.kind=="Greater" and t.automated and not own(p,t.id) and E.indexOf(t.races,"DRAGON") then candidates[#candidates+1]=t end
        end
        local t=E.pick(g,candidates)
        if t then p.trinkets[E.indexOf(p.trinkets,dragonStaff)]=t.id;if TR[t.id].pick then TR[t.id].pick(g,p) end end
    end})

    ---------------------------------------------------------------------------
    -- Battlegrounds Quests (setting "Quests"). Offered at the start of turn 4: three Quest + Reward pairs.
    -- Quest goals use Blizzard's published baselines, scaled by the paired Reward's strength and the hero's Armor.
    -- Rewards run on the same hooks as Trinkets (E.passives), but live in p.questRewards so they never take a
    -- Trinket slot. BG_QUESTS / BG_QUEST_REWARDS (names, text, weights) are generated from HearthstoneJSON.
    E.QUEST_TURN = 4
    E.QUEST_MULT = {0.75, 1.0, 1.35}
    local QUEST_BY_ID, REWARD_BY_ID = {}, {}
    for _, q in ipairs(BG_QUESTS) do QUEST_BY_ID[q.id] = q end
    for _, r in ipairs(BG_QUEST_REWARDS) do REWARD_BY_ID[r.id] = r end
    E.questDef, E.rewardDef = function(id) return QUEST_BY_ID[id] end, function(id) return REWARD_BY_ID[id] end
    local EMPTY = {}
    local function qr(p) p.qr = p.qr or {}; return p.qr end

    function E.passives(p)
        local tr = p.trinkets or EMPTY
        local rewards = p.questRewards
        local tracking = p.quest and not p.quest.done
        if not rewards and not tracking then return tr end
        local list = {}
        for i, id in ipairs(tr) do list[i] = id end
        for _, id in ipairs(rewards or EMPTY) do list[#list + 1] = id end
        if tracking then list[#list + 1] = "BGQ_TRACK" end
        return list
    end
    function E.specPassives(spec, owner)
        if owner then return E.passives(owner) end
        return spec and spec.trinkets or EMPTY
    end
    function E.ownsReward(p, id) return p.questRewards and E.indexOf(p.questRewards, id) ~= nil end

    local PLURAL = {UNDEAD = "Undead", NAGA = "Naga", QUILBOAR = "Quilboar", MECHANICAL = "Mechs"}
    local function racePlural(r)
        if PLURAL[r] then return PLURAL[r] end
        local n = (E.RACE_NAME and E.RACE_NAME[r]) or (r:sub(1, 1) .. r:sub(2):lower())
        return n .. "s"
    end
    function E.questText(entry)
        local q = QUEST_BY_ID[entry.quest]
        if not q then return "" end
        if entry.duo then return string.format(q.text, entry.goal, racePlural(entry.duo[1]), racePlural(entry.duo[2])) end
        return string.format(q.text, entry.goal)
    end

    local function eligibleQuest(g, q)
        if q.key == "duo" then return #(g.tribes or EMPTY) >= 2 end
        return true
    end
    local function eligibleReward(g, p, r)
        if r.offered == false or E.ownsReward(p, r.id) then return false end
        local tribes = {}
        for _, t in ipairs(g.tribes or EMPTY) do tribes[t] = true end
        if r.needs then
            local ok = false
            for _, t in ipairs(r.needs) do if tribes[t] then ok = true end end
            if not ok then return false end
        end
        if r.buddy and not E.buddyFor(p) then return false end
        if r.trinketShop and not (BG_TRINKETS and #BG_TRINKETS > 0) then return false end
        return true
    end

    -- Goals come in a fixed set (one text image per goal): base x Reward strength, 1 lower (2 for the warband
    -- quest) when the hero starts with 10+ Armor. Must match make_defs.py goals().
    function E.questGoal(g, p, q, r)
        local goal = math.floor(q.base * (E.QUEST_MULT[r.w or 2] or 1) + 0.5)
        local lo = q.key == "warband" and 10 or 2
        if q.key ~= "duo" and (p.armor or 0) >= 10 then goal = goal - (q.key == "warband" and 2 or 1) end
        return math.max(lo, goal)
    end

    -- Key of the baked text image: <quest>_<goal> or <quest>_<goal>_<TYPE A>_<TYPE B> (A < B).
    function E.questTextKey(entry)
        local id = entry.quest or entry.id
        if entry.duo then return id .. "_" .. entry.goal .. "_" .. entry.duo[1] .. "_" .. entry.duo[2] end
        return id .. "_" .. entry.goal
    end

    function E.offerQuests(g, p)
        local quests, rewards = {}, {}
        for _, q in ipairs(BG_QUESTS) do if eligibleQuest(g, q) then quests[#quests + 1] = q end end
        for _, r in ipairs(BG_QUEST_REWARDS) do if eligibleReward(g, p, r) then rewards[#rewards + 1] = r end end
        E.shuffle(g, quests); E.shuffle(g, rewards)
        local options = {}
        for i = 1, math.min(3, #quests, #rewards) do
            local q, r = quests[i], rewards[i]
            local o = {quest = q.id, reward = r.id, goal = E.questGoal(g, p, q, r)}
            if q.key == "duo" then
                local t = E.copy(g.tribes); E.shuffle(g, t)
                o.duo = {t[1], t[2]}
                table.sort(o.duo)
            end
            options[i] = o
        end
        if #options == 0 then return false end
        p.questOffer = {kind = "quest", turn = g.turn, options = options}
        p.trinkets = p.trinkets or {}
        return true
    end

    local function startQuest(g, p, o)
        local q = QUEST_BY_ID[o.quest]
        p.quest = {id = o.quest, reward = o.reward, goal = o.goal, progress = 0, key = q.key, duo = o.duo,
            repeats = o.repeats or 0}
        if q.key == "warband" then E.questWarband(g, p) end
    end

    function E.questPick(g, color, i)
        local p = g.players[color]
        local offer = p and p.questOffer
        if not offer then return false, "Nothing to choose." end
        local o = offer.options[i or 1]
        if not o then return false, "No such option." end
        p.questOffer = nil
        if offer.kind == "quest" then
            startQuest(g, p, o)
            E.event(g, color, "hero_power", p.name .. " chose the quest " .. QUEST_BY_ID[o.quest].name .. ".")
        elseif offer.kind == "reward" then -- Ethereal Evidence: swap this turn's Reward
            local s = qr(p)
            if s.ethereal then
                local at = E.indexOf(p.questRewards or EMPTY, s.ethereal)
                if at then table.remove(p.questRewards, at) end
            end
            s.ethereal = o.reward
            table.insert(p.questRewards, o.reward)
            local effect = TR[o.reward]
            if effect and effect.pick then effect.pick(g, p) end
        elseif offer.kind == "power" then -- Cosmic Reward
            p.secondPowerHero = o.hero
            p.secondPowerUses = 0
            E.event(g, color, "hero_power", p.name .. " discovered a second Hero Power.")
        end
        E.checkTriples(g, p)
        return true
    end

    function E.grantQuestReward(g, p, id)
        local r = REWARD_BY_ID[id]
        p.questRewards = p.questRewards or {}
        p.trinkets = p.trinkets or {}
        if not E.ownsReward(p, id) then table.insert(p.questRewards, id) end
        local effect = TR[id]
        if effect and effect.pick then effect.pick(g, p) end
        if r then E.event(g, p.color, "hero_power", p.name .. " completed a quest: " .. r.name .. "!") end
        E.checkTriples(g, p)
    end

    local function award(g, p)
        local q = p.quest
        q.done, q.pendingAward = true, nil
        local r = REWARD_BY_ID[q.reward]
        E.grantQuestReward(g, p, q.reward)
        if r and r.endless then
            p.quest = {id = q.id, reward = q.reward, goal = q.goal, progress = 0, key = q.key, duo = q.duo,
                repeats = (q.repeats or 0) + 1}
        end
    end
    E.awardQuest = award

    function E.questNote(g, p, key, n, inCombat)
        local q = p and p.quest
        if not q or q.done or q.key ~= key or (n or 0) <= 0 then return end
        q.progress = math.min(q.goal, q.progress + n)
        if q.progress >= q.goal then
            g = g or E.lastGame
            if inCombat or not g then q.pendingAward = true else award(g, p) end
        end
    end
    function E.questWarband(g, p)
        local q = p.quest
        if not q or q.done or q.key ~= "warband" then return end
        local total = 0
        for _, m in ipairs(p.board) do total = total + math.max(0, m.atk) end
        q.progress = math.min(q.goal, total)
        if total >= q.goal then award(g, p) end
    end
    function E.questPending(g, p)
        if p.quest and p.quest.pendingAward and not p.quest.done then award(g, p) end
    end

    -- "Increase a friendly minion's stats": called from buff() outside combat.
    function E.questStat(m)
        local g = E.lastGame
        if not g then return end
        for _, color in ipairs(g.order) do
            local p = g.players[color]
            local q = p.quest
            if q and not q.done and q.key == "stat" and (E.indexOf(p.board, m) or E.indexOf(p.hand, m)) then
                E.questNote(g, p, "stat", 1)
                return
            end
        end
    end
    local raise = E.raiseHandGained
    E.raiseHandGained = function(g, p, ...)
        local a, b = raise(g, p, ...)
        E.questNote(g, p, "hand", 1)
        return a, b
    end

    local function note(key) return function(g, p) E.questNote(g, p, key, 1); E.questWarband(g, p) end end
    TR.BGQ_TRACK = {
        refresh = note("refresh"),
        summonTrinket = function(g, p) E.questNote(g, p, "summon", 1, g.phase == "combat") end,
        summoned = function(g, p, C) if not C.recruit then E.questNote(g, p, "summon", 1, true) end end,
        afterCombat = function(g, p, won) if not won then E.questNote(g, p, "loseTie", 1) end; E.questPending(g, p) end,
        death = function(g, p, C) E.questNote(g, p, "friendlyDeath", 1, not C.recruit) end,
        soc = function(C, S)
            local p = E.C.owner(C, S)
            if not p or not p.quest or p.quest.key ~= "sorted" or #S.list < 2 then return end
            for i = 2, #S.list do if S.list[i].atk < S.list[i - 1].atk then return end end
            E.questNote(C.g, p, "sorted", 1, true)
        end,
        spendGold = function(g, p, n) E.questNote(g, p, "gold", n or 0) end,
        buyCard = function(g, p, m)
            local q = p.quest
            if q.key ~= "duo" or not (m and BG_CARDS[m.id] and q.duo) then return end
            if E.hasRace(m, q.duo[1]) or E.hasRace(m, q.duo[2]) then E.questNote(g, p, "duo", 1) end
        end,
        play = function(g, p, m)
            if m and BG_CARDS[m.id] and BG_CARDS[m.id].battlecry then E.questNote(g, p, "battlecryPlay", 1) end
            E.questWarband(g, p)
        end,
        buy = function(g, p) E.questNote(g, p, "buy", 1); E.questWarband(g, p) end,
        attacked = function(g, p, C, S, target) if target and target.taunt then E.questNote(g, p, "tauntHit", 1, true) end end,
        attack = function(g, p) E.questNote(g, p, "attack", 1, true) end,
        endTurn = function(g, p)
            local q = p.quest
            if q.key == "unspent" and p.gold > 0 and q.lastTurn ~= g.turn then q.lastTurn = g.turn; E.questNote(g, p, "unspent", 1) end
            E.questWarband(g, p)
        end,
        sell = note("sell"),
        enemyDeath = function(g, p) E.questNote(g, p, "kill", 1, true) end,
        anySpell = note("spell"),
        startTurn = function(g, p) E.questWarband(g, p) end,
    }

    -- Offer at the start of turn 4; bots choose at once. Pending awards land at the start of the next turn.
    local baseStart = E.SYS.startTurn
    E.SYS.startTurn = function(g, p)
        baseStart(g, p)
        E.lastGame = g
        if not p.alive then return end
        E.questPending(g, p)
        if g.questsEnabled and g.turn == E.QUEST_TURN and not p.quest and not p.questOffer then
            if E.offerQuests(g, p) and p.bot then E.questPick(g, p.color, g.rand(#p.questOffer.options)) end
        end
    end
    local baseHasChoice = E.hasChoice
    E.hasChoice = function(p) return baseHasChoice(p) or (p and p.questOffer and true) or nil end
    local baseClose = E.closeRecruit
    E.closeRecruit = function(g, ...)
        for _, color in ipairs(g.order) do
            local p = g.players[color]
            if p and p.questOffer then E.questPick(g, color, 1) end
        end
        return baseClose(g, ...)
    end
    local baseDiscovered = E.onDiscovered
    E.onDiscovered = function(g, p, picked, ...)
        local r = baseDiscovered(g, p, picked, ...)
        if picked and picked.id and E.ownsReward(p, "BG24_Reward_129") and BG_CARDS[picked.id] then -- Secret Sinstone
            local copy = E.newMinion(g, picked.id, picked.golden)
            copy.generated = true
            give(g, p, copy)
        end
        return r
    end

    ---------------------------------------------------------------------------
    -- Rewards
    local function R(id, effects) TR[id] = effects end
    local function boardOf(p, filter)
        local list = {}
        for _, m in ipairs(p.board) do if not filter or filter(m) then list[#list + 1] = m end end
        return list
    end
    local function randomOf(g, list, n)
        local copy = {}
        for i, m in ipairs(list) do copy[i] = m end
        E.shuffle(g, copy)
        local out = {}
        for i = 1, math.min(n or 1, #copy) do out[i] = copy[i] end
        return out
    end
    local function highestTier(list)
        local best
        for _, m in ipairs(list) do
            local t = card(m.id).tier
            if not m.golden and (not best or t > card(best.id).tier) then best = m end
        end
        return best
    end
    local function enemyOf(C, S) return C.sides[S.n == 1 and 2 or 1] end
    local function avenge(C, S, key, needed)
        C.questAvenge = C.questAvenge or {}
        local k = key .. S.n
        C.questAvenge[k] = (C.questAvenge[k] or 0) + 1
        if C.questAvenge[k] >= needed then C.questAvenge[k] = 0; return true end
        return false
    end
    local function craftEachTurn(id)
        local function give1(g, p) if E.giveSpell(g, p, id) then p.spellHand[#p.spellHand].expireTurn = g.turn end end
        return {pick = give1, startTurn = give1}
    end
    local function poolIds(filter)
        local ids = {}
        for id, c in pairs(BG_CARDS) do if filter(c) then ids[#ids + 1] = id end end
        table.sort(ids)
        return ids
    end
    local function buddyIds()
        return poolIds(function(c) return c.buddy and not c.id:find("_G$") end)
    end
    local function unGolden(m)
        if not m.golden then return end
        local c = card(m.id)
        m.golden = false
        m.atk = math.max(0, m.atk - (c.gatk - c.atk))
        m.hp = math.max(1, m.hp - (c.ghp - c.hp))
    end
    local function scepter(g, p)
        local counts, best, n = {}, nil, 0
        for _, m in ipairs(p.board) do
            for _, r in ipairs(card(m.id).races) do
                counts[r] = (counts[r] or 0) + 1
                if counts[r] > n then best, n = r, counts[r] end
            end
        end
        if not best then return end
        local have = 0
        for _, m in ipairs(p.tavern) do if E.hasRace(m, best) then have = have + 1 end end
        for i = #p.tavern, 1, -1 do
            if have >= 2 then break end
            local old = p.tavern[i]
            if not E.hasRace(old, best) and not old.frozenKeep then
                local new = E.drawFromPool(g, p.tier, 1, function(c) return c.all or E.indexOf(c.races, best) end)
                if not new then break end
                E.returnToPool(g, old)
                E.applyTavernBuff(p, new)
                p.tavern[i] = new
                have = have + 1
            end
        end
    end
    local function alterEgo(g, p)
        local s = qr(p)
        s.alterStart = s.alterStart or g.turn
        local even = (g.turn - s.alterStart) % 2 == 0
        s.alterFace = even and "BG24_Reward_321" or "BG24_Reward_321t"
        for _, m in ipairs(p.tavern) do
            local t = card(m.id).tier
            if m.alterEgo ~= g.turn and (t % 2 == 0) == even then m.alterEgo = g.turn; E.buff(m, 7, 7) end
        end
    end

    -- BG24 (Season 2) rewards
    R("BG24_Reward_107", {endTurn = function(g, p)
        local list = boardOf(p, function(m) return card(m.id).battlecry end)
        for _, m in ipairs(randomOf(g, list, 2)) do E.runBattlecry(g, p, m, 1) end
    end})
    R("BG24_Reward_109", {soc = function(_, S)
        if S.list[1] then E.makeGolden(S.list[1]) end
        if #S.list > 1 then E.makeGolden(S.list[#S.list]) end
    end})
    R("BG24_Reward_111", {soc = function(C, S)
        local best, at
        for i, m in ipairs(S.list) do if not best or m.hp > best.hp then best, at = m, i end end
        if best then E.C.summonCopy(C, S, best, at + 1) end
    end})
    R("BG24_Reward_113", {death = function(g, p, C, S, m)
        if C.recruit or not E.C.hasDeathrattle(m) then return end
        for _, o in ipairs(p.board) do if o.uid == m.src then E.buff(o, 5, 5); break end end
    end})
    R("BG24_Reward_115", {endTurn = function(g, p)
        local m = p.board[#p.board]
        if m then E.tempBuff(m, 0, 0, "stealth"); E.buff(m, 0, 8) end
    end})
    R("BG24_Reward_123", {extraBattlecry = function(p)
        local g = E.lastGame
        local s = qr(p)
        if g and s.conchTurn ~= g.turn then s.conchTurn = g.turn; return 2 end
        return 0
    end})
    R("BG24_Reward_125", {soc = function(_, S) for _, m in ipairs(S.list) do E.buff(m, 4, 0) end end,
        summoned = function(_, _, C, _, m) if not C.recruit then E.buff(m, 4, 0) end end})
    R("BG24_Reward_128", {refresh = function(g, p)
        local m = E.pick(g, p.tavern)
        if m then E.buff(m, 6, 6); m.shield = true end
    end})
    R("BG24_Reward_129", {})   -- Secret Sinstone: see E.onDiscovered above
    R("BG24_Reward_130", {pick = function(g, p) grant(g, p, "BG26_ICC_901"); p.extraEndTurn = (p.extraEndTurn or 0) + 1 end})
    R("BG24_Reward_131", {startTurn = function(g, p)
        local m = E.pick(g, p.hand)
        if m then E.buff(m, 12, 12) end
    end})
    R("BG24_Reward_134", {startTurn = function(g, p)
        local ids = buddyIds()
        for _ = 1, 2 do if #ids > 0 then grant(g, p, E.pick(g, ids)) end end
    end})
    R("BG24_Reward_135", {startTurn = function(g, p) E.timewarpWheel(g, p, 1) end})
    R("BG24_Reward_136", {endTurn = function(g, p)
        for _, m in ipairs(randomOf(g, boardOf(p, function(m) return card(m.id).tier <= 3 end), 3)) do E.buff(m, 3, 3) end
    end})
    R("BG24_Reward_138", {
        soc = function(C, S) local p = E.C.owner(C, S); if p then qr(p).lastDead = nil end end,
        death = function(g, p, C, S, m) if not C.recruit then qr(p).lastDead = m.id end end,
        afterCombat = function(g, p)
            local s = qr(p)
            if s.lastDead and BG_CARDS[s.lastDead] then grant(g, p, s.lastDead) end
            s.lastDead = nil
        end})
    R("BG24_Reward_305", {sell = function(g, p, m)
        local t = E.pick(g, p.tavern)
        if t and m then E.buff(t, math.max(0, m.atk), math.max(0, m.hp)) end
    end})
    R("BG24_Reward_306", {buy = function(g, p, m)
        local s = qr(p)
        local n = s.cooked or 2
        if m then E.buff(m, n, n) end
        s.cooked = n + 1
    end})
    R("BG24_Reward_308", {refresh = function(g, p)
        local s = qr(p)
