    end})
    R("BG33_Reward_021", {pick = function(g, p)
        local ids = poolIds(function(c) return c.pool and c.rally and c.tier <= math.max(1, p.tier) and not c.buddy end)
        if #ids == 0 then ids = poolIds(function(c) return c.pool and c.rally and not c.buddy end) end
        if #ids > 0 then grant(g, p, E.pick(g, ids)) end
