    TR.BG24_Reward_321t = TR.BG24_Reward_321

    function E.rewardText(p, id)
        local r = REWARD_BY_ID[id]
        if not r then return "" end
        local s = p and p.qr or EMPTY
        if id == "BG24_Reward_306" and s.cooked then return "After you buy a minion, give it +" .. s.cooked .. "/+" .. s.cooked .. " and improve this." end
        if id == "BG24_Reward_361" and s.vault then return "At the start of each turn, gain " .. s.vault .. " Gold. (Improves each turn!)" end
        if id == "BG28_Reward_508" and s.kobold then
            return "After you Refresh 5 times, make the highest-Tier minion in the Tavern Golden. (" .. (5 - s.kobold) .. " left!)"
        end
        if id == "BG28_Reward_509" and s.smelt then return "At the start of each turn, make a friendly Tier " .. s.smelt .. " minion Golden and improve this." end
        if id == "BG24_Reward_321" and s.alterFace == "BG24_Reward_321t" then return REWARD_BY_ID.BG24_Reward_321t and REWARD_BY_ID.BG24_Reward_321t.text or r.text end
        return r.text
    end

    function E.trinketMinionCost(p,m,cost,turn)
        local g=turn or p.trinketGameTurn
        if card(m.id).battlecry and own(p,"BG36_MagicItem_202") and (p.warcryTurn~=g or (p.warcryBought or 0)<2) then return 0 end
        return cost
    end

    function E.trinketSpellAura(g,p)
        local a,h=0,0
        for _,id in ipairs(E.passives(p)) do
            if TR[id] and TR[id].spellAura then local x,y=TR[id].spellAura(g,p);a,h=a+x,h+y end
        end
        return a,h
    end

    E.HP.BG36_HERO_105={passive=true,startTurn=function(g,p)
        if g.darkGiftsEnabled~=false and g.turn%4==0 then local lo,hi=E.darkGiftTiers(g);giftRange(g,p,lo,hi) end
    end}
    E.HP.BG36_HERO_101={passive=true,gameStart=function(g,p)
