    for hero, id in pairs({TB_BaconShop_HERO_33 = "TB_BaconShop_HP_033t", TB_BaconShop_HERO_93 = "TB_BaconShop_HP_105t",
            BG21_HERO_030 = "BG21_HERO_030t"}) do
