function E.buddyFor(p)
    local h = E.hero(p)
    return h and h.buddy and card(h.buddy) or nil
end

function E.buddyCost(g, p)
    local buddy = g.buddies and E.buddyFor(p)
    local bought = p.buddyCount or 0
    if not buddy or bought >= 2 or p.buddyDone then return nil end
    return math.max(0, 9 + 2 * buddy.tier + 2 * bought - (p.buddyDiscount or 0))
end

function E.buyBuddy(g, color)
    local p = g.players[color]
    local can, err = E.canAct(g, p)
    if not can then return false, err end
    if p.ready then return false, "Take your turn back before buying a Buddy." end
    local cost, buddy = E.buddyCost(g, p), E.buddyFor(p)
    if cost == nil then return false, "Your Buddy purchases are finished." end
    if p.gold < cost then return false, buddy.name .. " costs " .. cost .. " Gold." end
    local count = (p.buddyCount or 0) + 1
    if E.handCount(p) + count > E.MAX_HAND then return false, "Make room in your hand for your Buddy." end
    local added = {}
    for i = 1, count do
        local m = E.newMinion(g, buddy.id, false)
        m.generated = true
        added[i] = m
    end
    p.gold, p.buddyCount, p.buddyDiscount = p.gold - cost, count, 0
    p.buddyDone = count == 2
    for _, m in ipairs(added) do table.insert(p.hand, m) end
    E.spendGold(g, p, cost)
    E.checkTriples(g, p)
    E.event(g, color, "card_draw", nil)
    return true
end

E.BUDDY.afterCombat = function(g, p, won, damage, lost)
    if E.buddyCost(g, p) ~= nil then p.buddyDiscount = (p.buddyDiscount or 0) + (lost and 2 or 3) end
end

