-- Anomalies (one per lobby when enabled). Only scripted ones are drawn unless "whole pool" is on.
local function oneRace(race)
    return {canChoose = function(g)
        local count = 0
        for id, c in pairs(BG_CARDS) do
            local available = (g.allowed and g.allowed[id]) or (not g.allowed and c.pool)
            if available and c.tier == 1 and (c.all or E.indexOf(c.races, race)) then
                count = count + 1
                if count >= 2 then return true end
            end
        end
        return false
    end, setup = function(g)
        g.tribes = {race}
        for id in pairs(g.pool) do
            local c = card(id)
            if not (c.all or E.indexOf(c.races, race)) then g.pool[id] = nil end
        end
        for id, c in pairs(BG_CARDS) do
            local ok = c.pool
            if g.allowed then ok = g.allowed[id] and c.tier <= (g.maxTier or 6) end
            if ok and (c.all or E.indexOf(c.races, race)) and (g.fullMinions or g.allCards or c.fx ~= "none") then g.pool[id] = g.pool[id] or E.COPIES[c.tier] end
        end
        -- older seasons have few scripted minions of one type: top up thin tiers with unscripted ones
        local per = {}
        for id in pairs(g.pool) do local t = card(id).tier; per[t] = (per[t] or 0) + 1 end
        for id, c in pairs(BG_CARDS) do
            local ok = c.pool
            if g.allowed then ok = g.allowed[id] and c.tier <= (g.maxTier or 6) end
            if ok and (per[c.tier] or 0) < 3 and (c.all or E.indexOf(c.races, race)) and not g.pool[id] then
                g.pool[id] = E.COPIES[c.tier]
            end
        end
    end}
end
