function Draw.safeGUID(obj)
    if not obj then return nil end
    local ok, guid = pcall(function() return obj.getGUID() end)
    if ok then return guid end
end

function Draw.live(guid)
    if not guid then return nil end
    local ok, obj = pcall(function()
        local current = getObjectFromGUID(guid)
        if current and not current.isDestroyed() then return current end
    end)
    if ok then return obj end
end

function Draw.ready(guid)
    local obj = Draw.live(guid)
    if not obj then return nil end
    local ok, ready = pcall(function() return not obj.spawning and not obj.loading_custom end)
    if ok and ready then return obj end
end
-- Decals face local +z at yaw 0; the seated player is on the board's +z side, so art needs yaw 180 to be upright.
function Draw.decalYaw()
    return (180 + (settings.flip and 180 or 0) + (settings.decalFlip and 180 or 0)) % 360
end
local TIMER_MODES = {"Default", "Short", "Long", "No Timer"}
local TIMER_MULT = {Default = 1, Short = 0.6, Long = 1.5}
local SPEED_NAMES = {"Instant", "Fast", "Normal"}
local SPEED_STEP = {0, 0.55, 1.0}
local deadline = nil
local busy = false
local busySince = 0
local startError = nil
local settingsHost = nil  -- the host whose settings panel is open on the table
local SET = "_settings"     -- widgets key of the settings panel (drawn on this controller)
local hideController       -- defined with onLoad
local renderSettings      -- defined with the settings panel
local combatView = nil
local seats = {}        -- color -> {board = guid, bob = guid, tokens = {key -> guid}}
local tokenInfo = {}    -- guid -> {color, key, id, golden, d, face, decalKey}
function Draw.eventToken(obj)
    if not game or game.phase ~= "recruit" or not obj then return nil end
    local guid = Draw.safeGUID(obj)
    if not guid or not tokenInfo[guid] or not Draw.ready(guid) then return nil end
    return guid
end
local pendingDrop = {}
local aiming = {}       -- color -> true while a targeted Hero Power waits for its target

-------------------------------------------------------------------------------
-- utilities
local function U() return 500 end

local function say(color, msg, tint)
    if not msg then return end
    if color and Player[color] and Player[color].seated then
        Player[color].broadcast(msg, tint or {1, 0.85, 0.55})
    else
        broadcastToAll(msg, tint or {1, 0.85, 0.55})
    end
end

local function seat(color)
    seats[color] = seats[color] or {tokens = {}}
    seats[color].tokens = seats[color].tokens or {}
    return seats[color]
end

local function boardOf(color)
    local s = seats[color]
    return s and Draw.ready(s.board) or nil
end

local function bobOf(color)
    local s = seats[color]
    return s and Draw.ready(s.bob) or nil
end

local function urlPath(rel)
    return (tostring(rel):gsub("\\", "/"):gsub("[^%w%-%._~/]", function(ch) return string.format("%%%02X", string.byte(ch)) end))
end
local function uiArt(name) return CLOUD .. "ui/" .. name end
function Draw.newArt(path)
    local s15 = Draw.s15HeroAsset(path)
    if s15 then return s15 end
    local dir, file = path:match("^(%a+)/(.+)$")
    local have = dir == "power" and Draw.HAVE_POWER or dir == "hero" and Draw.HAVE_HERO or dir == "trinket" and Draw.HAVE_TRINKET
    if have and next(have) and not have[file] then
        if dir == "power" then
            local hid = file:match("^(.-)_[nru]_")
            if hid and have[hid .. "_n_passive.png"] then file = hid .. "_n_passive.png"
            else return Draw.hsjsonArt("bgs/latest/enUS/512x/" .. (hid or file:gsub("%.png$", "")) .. "p.png") end
        else
            return Draw.hsjsonArt("bgs/latest/enUS/512x/" .. file)
        end
    end
    return Draw.newArtRaw(dir and (dir .. "/" .. file) or path)
end
function Draw.newArtRaw(path) return "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/572db5814e98f7eea4b507db5e79778de3b3481b/hsbg/battlegrounds-multiplayer/hover-rope/" .. path end
function Draw.modeArt(path) return "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/513b58163257d816cf26568c42709978fc1cc9bc/hsbg/battlegrounds-multiplayer/buddies-anomalies/" .. path end
function Draw.recruitArt(path) return "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/6ba9282c2baf214487a09b44b512d846ed8f3d64/hsbg/battlegrounds-multiplayer/recruit-combat/" .. path end
