Draw.s15Gold = Draw.s15Gold or {}
function Draw.s15MinionAsset(id, golden, folder)
    if folder == "cards" and id and Draw.s15Override[id] and game and game.season == "s15" then
        if golden and Draw.s15Gold["override/" .. id] then return Draw.s15GoldRoot .. "override/g/" .. id .. ".png" end
        return Draw.s15AssetRoot .. "override/" .. id .. ".png"
    end
    if golden and id and Draw.s15Gold[folder .. "/" .. id] then return Draw.s15GoldRoot .. folder .. "/g/" .. id .. ".png" end
    if id == "S15T_monkey" then id = "S15_flying_monkey" end
    if id == "S15T_tentacle" then id = "S15_underrot_infestor" end
    if not id or id:sub(1, 4) ~= "S15_" or not BG_CARDS[id] then return nil end
    return Draw.s15AssetRoot .. folder .. (golden and "/g/" or "/n/") .. id .. ".png"
end
function Draw.spellArt(id)
    if Draw.s15OverrideSpell[id] and game and game.season == "s15" then return Draw.s15AssetRoot .. "override/" .. id .. ".png" end
    if Draw.s15SpellPrices[id] then return Draw.s15AssetRoot .. "spells/" .. id .. ".png" end
    if BG.SPELLS[id] and BG.SPELLS[id].timewarpArt then return BG.SPELLS[id].timewarpArt end
    return Draw.hsjsonArt("bgs/latest/enUS/512x/" .. id .. ".png")
end
function Draw.spellFaceFor(id)
    if Draw.s15SpellPrices[id] then return Draw.s15SpellFace end
    if BG.SPELLS[id] and BG.SPELLS[id].timewarpArt then return Draw.spellFace end
    return DEFAULT_FACE
end
-- Text box of a Hearthstone Tavern spell render (fractions of the 512x776 image).
Draw.SPELL_TEXT_BOX = {cx = .500, cy = .727, w = .640, h = .225}
function Draw.spellTextBox(face)
    if face == Draw.s15SpellFace then return Draw.s15SpellText end
    if face == DEFAULT_FACE then return Draw.SPELL_TEXT_BOX end
end
function Draw.spellCardText(p, d)
    local spell = BG.SPELLS[d.id]
    if not spell or not p or not game then return nil end
    local text = Draw.spellState(game, p, d)
    -- Spell power is already applied to every number by Draw.spellState (BG.spellText).
    if text == (spell.text or "") then return nil end
    return text
end

