function Draw.shopSpellArt(id, price)
    local maxPrice = Draw.s15SpellPrices[id]
    if maxPrice then
        local cost = math.max(0, math.min(maxPrice, math.floor(tonumber(price) or maxPrice)))
        return Draw.s15AssetRoot .. "shop/" .. id .. "_" .. cost .. ".png"
    end
    local key = id .. "_" .. tostring(price) .. ".png"
    if Draw.HSSPELL[key] then return "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/d9038fe6b7334ddaa6d30362a070e4c4db634236/hsbg/battlegrounds-multiplayer/s14-leaderboard/spellshop/" .. key end
    if Draw.HAVE_SHOP[key] then return Draw.recruitArt("shop/" .. key) end
    return Draw.spellArt(id)
end
Draw.fallbackHeroPowers={["BG20_HERO_201"]=true,["BG20_HERO_202"]=true,["BG20_HERO_283"]=true,["BG21_HERO_020"]=true,["BG22_HERO_001"]=true,["BG23_HERO_303"]=true,["BG23_HERO_306"]=true,["BG25_HERO_103"]=true,["BG25_HERO_105"]=true,["BG27_HERO_801"]=true,["BG30_HERO_304"]=true,["BG32_HERO_002"]=true,["TB_BaconShop_HERO_17"]=true,["TB_BaconShop_HERO_40"]=true,["TB_BaconShop_HERO_52"]=true,["TB_BaconShop_HERO_62"]=true,["TB_BaconShop_HERO_72"]=true}
Draw.recruitPowers = {["BG28_HERO_801"]=true,["BG31_HERO_006"]=true,["BG34_HERO_001"]=true}
Draw.spellFace = {r = 300 / 430}
function Draw.polish(path) return Draw.localArt .. "polished/" .. path end
function Draw.uiArt2(name)
    if name:sub(1, 13) == "refined-tier/" then return Draw.localArt .. "refined/tb/" .. name:sub(14) end
    if name:sub(1, 6) == "coins/" or name:sub(1, 7) == "tavern/" then
        return Draw.localArt .. "refined/" .. name
    end
    local family = name:match("^([a-z]+)/")
    if family == "hp" or family == "ar" or family == "sb" or family == "gd" or family == "st"
        or family == "sp" or family == "tier" or (family == "pw" and Draw.localPowers[name])
        or name == "bob.png" or name:sub(1, 3) == "et_" or name:sub(1, 9) == "fallback_" then
        return Draw.localArt .. name
    end
    return CLOUD .. "ui2/" .. name
end
local function cloudArt(kind, id) if id and CLOUD_HAVE[kind] and CLOUD_HAVE[kind][id] then return CLOUD .. kind .. "/" .. urlPath(id) .. ".png" end return nil end
local EXTRA_HEROES = {BG21_HERO_020 = true, BG20_HERO_201 = true}   -- Cookie the Cook, Vol'jin
local function heroArt(h)
    if h and Draw.s15Heroes[h.id] then return Draw.s15AssetRoot .. "heroes/" .. h.id .. ".png" end
    if h and EXTRA_HEROES[h.id] then return "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/9305c86609d818560470003f029fc4d9f490c609/hsbg/battlegrounds-multiplayer/s14-leaderboard/hero/" .. h.id .. ".png" end
    if h and Draw.heroes[h.id] then return Draw.polish("hero/" .. h.id .. ".png") end
    return h and (cloudArt("h", h.id) or Draw.hsjsonArt("256x/" .. h.id .. ".jpg")) or "" end
local function powerArt(h) return h and (cloudArt("p", h.id) or uiArt("hp_frame_stone.png")) or "" end
local function trinketArt(t)
    if Draw.trinkets[t.id] then return Draw.polish("trinkets/" .. t.id .. ".png") end
    return cloudArt("t", t.id) or uiArt(t.kind == "Greater" and "trinket_greater.png" or "trinket_lesser.png") end

local function turnSeconds()
    local m = TIMER_MULT[settings.timer]
    if not m or not game then return nil end
    local base = math.min(45 + 10 * (game.turn - 1), 90)
    return math.floor(base * m + 0.5)
end

local function raceText(c)
    if c.all then return "All" end
    local names = {}
    for _, r in ipairs(c.races or {}) do table.insert(names, BG.RACE_NAME[r] or r) end
    return table.concat(names, "/")
end

local function cardText(id, golden, atk, hp)
    local c = BG_CARDS[id]
    if not c then return tostring(id) end
    local race = raceText(c)
    local t = c.tier and ("Tier " .. c.tier) or "Card"
    if race ~= "" then t = t .. " " .. race end
    if atk ~= nil and hp ~= nil then t = t .. "  -  " .. atk .. "/" .. hp end
    if c.text and c.text ~= "" then t = t .. "\n" .. c.text .. (golden and " (Golden: doubled)" or "") end
    if c.note then t = t .. "\n[Table rule: " .. c.note .. "]" end
    if c.fx == "none" then t = t .. "\n[Not scripted yet: plays with its stats and keywords only.]" end
    return t
end

local function faceOf(id, golden)
    local kind = golden and "g" or "n"
    local warp = Draw.warpHandFaces[id]
    local clean = warp and warp[kind]
    if clean then
        return clean, Draw.patchArt("hand/" .. id .. (golden and "_g" or ""))
    end
    local f = BG_FACES and BG_FACES[id]
    if f then
        local v = golden and f.g or f.n
        if v then return v, CLOUD .. "f/" .. urlPath(id .. (golden and "_g" or "") .. ".png") end
    end
    return nil, nil
end

local function onlineArt(id, golden)
    local s15 = Draw.s15MinionAsset(id, golden, "cards")
    if s15 then return s15 end
    local a = BG_ART and BG_ART[id]
    local url = a and (golden and a.g or a.n) or ""
    if url == "" then
        local c = BG_CARDS[id]
        local gid = golden and c and c.gid ~= "" and c.gid or nil
        if gid and ({["BG24_300_G"]=true,["BG27_009_G"]=true,["BG28_404_G"]=true,["BG28_597_G"]=true,["BGFYM_002t_G"]=true,["BG_CS2_200_G"]=true,["TB_BaconShop_HERO_43_Buddy_G"]=true})[gid] then gid = nil end
        url = Draw.hsjsonArt("bgs/latest/enUS/512x/" .. (gid and (gid .. "_triple") or id) .. ".png")
    end
    return url
end

local function artFor(id, golden)
    local s15 = Draw.s15MinionAsset(id, golden, "cards")
    if s15 then return s15, Draw.s15MinionFace, false end
    local face, url = faceOf(id, golden)
    if face then return url, face, true end
    return onlineArt(id, golden), DEFAULT_FACE, false
end

-------------------------------------------------------------------------------
-- buttons. x/z are reader-relative world units: +x = reader's right, +z = toward the reader.
local function bpos(s, flip, x, y, z)
    if flip then x, z = -x, -z end
    return {x / s, y / s, z / s}
end

local function button(b, spec)
    local s = b.s
    local x, z = spec.x or 0, spec.z or 0
    local u = U()
    local label = spec.label
    if type(label) == "number" then label = tostring(label) end
    if type(label) ~= "string" or label == "" then label = " " end
    local params = {
        click_function = spec.click or "bgNoop",
        function_owner = self,
        label = label,
        position = bpos(s, b.flip, x, spec.y or (BOARD_Y + 0.05), z),
        rotation = b.flip and {0, 180, 0} or {0, 0, 0},
        scale = {1 / s, 1 / s, 1 / s},
        width = math.floor((spec.w or 1) * u),
        height = math.floor((spec.h or 1) * u),
        font_size = math.floor((spec.font or 0.3) * u),
        color = spec.color or {0.1, 0.1, 0.1, 0.92},
        font_color = spec.font_color or {1, 1, 1, 1},
        hover_color = spec.hover_color or spec.color or {0, 0, 0, 0},
        press_color = spec.press_color or spec.color or {0, 0, 0, 0},
    }
    if b.buttons then return Draw.setButton(b, spec.key, params) end
    b.obj.createButton(params)
    b.n = b.n + 1
    return b.n - 1
end

-------------------------------------------------------------------------------
-- geometry
local function slotRight(i,n)
    return (i-(n+1)/2)*PITCH*math.min(1,7/math.max(1,n))
end

local function boardPoint(board, right, near, up)
    -- Boards are rotated like their mat (seat yaw); the seated player is on local +z, so right = local -x.
    return board.positionToWorld({-right, BOARD_Y + (up or 0.25), near})
end

local function readerOf(board, pos)
    local l = board.positionToLocal(pos)
    return -l.x, l.z
end

local function cardRotation(board)
    local r = board.getRotation()
    return {0, (r.y + (settings.flip and 180 or 0)) % 360, 0}
end

local function inHand(color, obj)
    local pl, guid = Player[color], Draw.safeGUID(obj)
    if not pl or not guid then return false end
    local ok, list = pcall(function() return pl.getHandObjects(1) end)
    if not ok or not list then return false end
    for _, o in ipairs(list) do if Draw.safeGUID(o) == guid then return true end end
    return false
end

local function handPoint(color, index)
    local pl = Player[color]
    local ok, t = pcall(function() return pl.getHandTransform(1) end)
    if not ok or not t then return nil end
    local p = t.position
    return {p.x, p.y + 0.5 + (index or 0) * 0.15, p.z}
end

-------------------------------------------------------------------------------
-- board phase (Codex's board script: phase label + combat animation)
local function drainEvents()
    if not game then return end
    local events = game.events
    game.events = {}
    for _, e in ipairs(events) do
        if e.fx ~= "hero_select" and e.msg then broadcastToAll(e.msg, {0.95, 0.85, 0.6}) end
        if Draw.eventFx then pcall(Draw.eventFx, e) end
    end
end

-------------------------------------------------------------------------------
-- card tokens
Draw.ENCHANT_TEXT = {S15E_unholy = "Unholy Ritual: Deathrattle: Summon two 1/1 Skeletons.", S15E_dragonstorm = "Dragonstorm: At the end of your turn, gain +2/+2.", S15E_echo = "Echoing Roar: At the end of your turn, gain +3/+3."}
function Draw.magneticDetails(m)
    local lines,counts,order={},{},{}
    for _,part in ipairs(m.attachments or {}) do
        local c=BG_CARDS[part.id]
        local en=Draw.ENCHANT_TEXT[part.id]
        if en then
            if not counts[en] then counts[en]=0; order[#order+1]=en end
            counts[en]=counts[en]+1
        elseif c then
            local a=part.atk or (part.golden and c.gatk or c.atk)
            local h=part.hp or (part.golden and c.ghp or c.hp)
            local text=(part.golden and "Golden " or "")..c.name.." +"..a.."/+"..h
            if c.text and c.text~="" and c.text~="Magnetic" then text=text.." · "..c.text end
            if not counts[text] then counts[text]=0; order[#order+1]=text end
            counts[text]=counts[text]+1
        end
    end
    for _,text in ipairs(order) do lines[#lines+1]=(counts[text]>1 and (counts[text].."× ") or "")..text end
    return lines
end

function Draw.tokenDescription(d)
    if d.spell then
        return (d.zone == "tavern" and "Buy by dragging toward your hand.\n" or "") .. (d.abilityText or BG.SPELLS[d.id].text)
    end
    local details=cardText(d.id,d.golden,d.atk,d.hp)
    if d.warpIndex then details = "Buy by dragging toward your hand.\n" .. details end
    if d.zone == "tavern" and not d.warpIndex and game and game.season == "s15" then
        local owner = d.color and game.players[d.color]
        if owner then details = details .. "\nCost: " .. BG.s15MinionPrice(owner, d.src, game.turn) .. " Gold" end
    end
    local m=d.src or {}
    local magnetic=Draw.magneticDetails(m)
    if #magnetic>0 then details=details.."\n"..table.concat(magnetic,"\n") end
    if d.lockTier then return "Locked until Tavern Tier " .. d.lockTier .. "\n" .. details end
    if d.lockGold then return "Locked until you spend " .. d.lockGold .. " more Gold\n" .. details end
    if d.lockTurn then return "Locked until Turn " .. d.lockTurn .. "\n" .. details end
    return details
end

local function tokenData(color, d, oval, shape)
    local c = BG.SPELLS[d.id] or BG_CARDS[d.id]
    local s = scaleCache[shape] or 1
    local carrier = shape == "portrait"
    -- A neutral token supplies the collider; portrait pixels never enter its cutout mesh.
    local url = carrier and Draw.season14Art("coin-spent.png")
        or oval or (d.spell and Draw.spellArt(d.id)) or artFor(d.id, d.golden)
    local mergeDistance = carrier and 4.0 or 15.0
    return {
        Name = "Custom_Token",
        Transform = {posX = 0, posY = 0, posZ = 0, rotX = 0, rotY = 0, rotZ = 0, scaleX = s, scaleY = s, scaleZ = s},
        Nickname = (d.golden and "Golden " or "") .. c.name,
        Description = Draw.tokenDescription(d),
        Memo = JSON.encode({c = color, k = d.key, i = d.id, g = d.golden and true or false,
            portrait = oval ~= nil, carrier = carrier, price = d.price}),
        Tags = {CARD_TAG},
        Locked = d.combat or false, Grid = false, Snap = false, Hands = not d.combat, Tooltip = false, Sticky = false,
        -- No gravity and heavy drag: dropped cards stay put until the script snaps them (no bounce).
        Rigidbody = {Mass = 0.3, Drag = 8, AngularDrag = 8, UseGravity = false},
        ColorDiffuse = {r = 1, g = 1, b = 1},
        CustomImage = {ImageURL = url, ImageSecondaryURL = "", ImageScalar = 1.0, WidthScale = 0.0,
            CustomToken = {Thickness = 0.1, MergeDistancePixels = mergeDistance, StandUp = false, Stackable = false}},
    }
end

-- Scale a token so it is `target` tall (or across, for Bob) once TTS has finished building its mesh:
-- bounds read in the spawn callback can still be the placeholder's.
function Draw.measureToken(guid, kind, target, done)
    if not guid then return end
    local function measure()
        local o = Draw.ready(guid)
        if not o then return end
        local ok, b = pcall(function() return o.getBoundsNormalized() end)
        if not ok or not b or not b.size then return end
        local size = kind == "bob" and math.max(b.size.x, b.size.z) or b.size.z
        if size and size > 0.05 and size < 200 then
            local k = target / size
            local s = o.getScale().x * k
            if math.abs(k - 1) >= 0.02 then o.setScale({s, s, s}) end
            scaleCache[kind] = s
            if kind ~= "bob" then tokenTop = math.max(0.03, b.size.y / 2 * k) + 0.03 end
        end
        if done and Draw.ready(guid) then done(o) end
    end
    Wait.condition(measure, function()
        return not Draw.live(guid) or Draw.ready(guid) ~= nil
    end, 30)
end

local function hasTrigger(c)
    local t = string.lower(c.text or "")
    return c.rally or c.avenge or t:find("whenever", 1, true) or t:find("after ", 1, true)
        or t:find("start of combat", 1, true) or t:find("at the end of", 1, true) or t:find("at the start of", 1, true)
        or t:find("avenge", 1, true)
end

-- "w" white, "g" green (buffed above the printed stat), "r" red (damaged): the Hearthstone colours
local function statCodes(d)
    local c = BG_CARDS[d.id] or {}
    local baseA = (d.golden and c.gatk or c.atk) or d.atk
    local baseH = (d.golden and c.ghp or c.hp) or d.hp
    local a = d.atk > baseA and "g" or "w"
    local h = (d.maxhp and d.hp < d.maxhp) and "r" or (d.hp > baseH and "g" or "w")
    return a, h
end

