function Draw.ovalArt(d)
    if not d or d.zone == "hand" then return nil end
    local s15 = not d.spell and Draw.s15MinionAsset(d.id, d.golden, "ovals")
    if s15 then return s15 end
    if d.warp then return Draw.warpSpellArt(d.id) end
    if d.spell then return Draw.shopSpellArt(d.id, d.price) end
    if Draw.HSOVAL[d.id] then return "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/49ee3940f28cd2456e2a0b36adc91ed3a314ca4f/hsbg/battlegrounds-multiplayer/s14-leaderboard/ov2/" .. (d.golden and "g/" or "n/") .. d.id .. ".png" end
    if Draw.timewarpPortraits[d.id] then return Draw.timewarpPortraits[d.id] end
    if Draw.patchPortraits[d.id] then return Draw.patchArt("units/" .. d.id) end
    if Draw.extraPortraits and Draw.extraPortraits[d.id] then return Draw.extraPortraits[d.id] end
    if Draw.expandedPortraits[d.id] then return Draw.expandedPortraits[d.id] end
    if Draw.season14Portraits[d.id] then return Draw.season14Art("units/"..d.id..".png") end
    if Draw.localPortraits[d.id] then return Draw.localArt .. "refined/units/" .. d.id .. ".png" end
    if Draw.remotePortraits[d.id] then return Draw.portraitOrigin .. "o/" .. d.id .. ".png" end
    return nil
end

function Draw.statDigits(value, code, x, z, width, height, add, maxWidth)
    local digits = string.format("%.0f", value)
    local size = math.min(1, 2.6 / #digits)
    if maxWidth then
        size = math.min(size, maxWidth / (width * (1 + .46 * (#digits - 1))))
    end
    local step = .46 * width * size
    for i = 1, #digits do
        add("st/" .. code .. "/" .. digits:sub(i, i) .. ".png",
            x + (i - (#digits + 1) / 2) * step, z, width * size, height * size, i)
    end
end

function Draw.ovalDecals(obj, d, info)
    local scale = obj.getScale().x
    local height, width = UNIT_H, 2.48
    local y = math.max(.12, tokenTop) + .08
    local yaw = Draw.decalYaw()
    local list = {}
    local function add(name, path, x, z, w, h, artURL)
        if settings.flip then x, z = -x, -z end
        table.insert(list, {name = "hsbg_" .. name, url = artURL or Draw.localArt .. "refined/" .. path,
            position = {-x * width / scale, (y + #list * .009) / scale, z * height / scale},
            rotation = {90, yaw, 0}, scale = {w * width / scale, h * height / scale, 1}})
    end
    local c, m = BG_CARDS[d.id], d.src or {}
    local hs = not d.spell and (Draw.HSOVAL[d.id] or Draw.s15MinionAsset(d.id, false, "ovals"))
    if m.taunt or m.t then
        if hs then add("taunt", nil, 0, .04, 1.75, 1.33, "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/815a923ae92323c36f2e1f37f7bcd1ee8a469fe9/hsbg/battlegrounds-multiplayer/s14-leaderboard/kw/taunt_hs3.png")
        else add("taunt", "mo/taunt.png", 0, 0, 1.5, 1.4) end
    end
    local portrait = Draw.ovalArt(d)
    if portrait then
        -- Match the shared oval canvas aspect so the full frame stays visible.
        add("portrait", nil, 0, 0, height * (300 / 372) / width, 1, portrait)
    end
    local gx, gz = hs and .37 or .31, hs and .255 or .285
    if d.golden and not hs then add("gold", "mo/gold.png", 0, 0, 1.5, 1.4) end
    local softW, softH = hs and 1.42 or 1.5, hs and 1.34 or 1.4
    if m.stealth or m.x then add("stealth", "mo/stealth.png", 0, 0, softW, softH) end
    if m.reborn or m.r then add("reborn", "mo/reborn.png", 0, 0, softW, softH) end
    if m.shield or m.s then add("shield", "mo/shield.png", 0, 0, hs and 1.24 or 1.5, hs and 1.20 or 1.4) end
    if m.windfury or m.w then add("windfury", "mo/windfury.png", 0, 0, softW, softH) end
    if d.frozen then add("frozen", "mo/frozen.png", 0, 0, softW, softH) end
    local act = Draw.activateState and Draw.activateState(info, d)
    local pw = height * (300 / 372) / width
    if (act and act.enabled) or Draw.activateTarget(info, d) then
        add("actglow", nil, 0, 0, pw * 348 / 300, 420 / 372, "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/505f29f2a8d581c0b4cabcdd96322e7a7c404572/hsbg/battlegrounds-multiplayer/s14-leaderboard/ui/oval_glow_green.png")
    end
    if act then
        local cs = act.used and .30 or .27
        add("activate", nil, .33, -.40, cs, cs * width / height, act.url)
    end
    if d.zone == "tavern" and m.darkmoonTicket then add("ticket", nil, 0, .47, .56, .56 * width / 2.12 / height, "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/a6673688eafc49ad1aacfe780e7bba7bd54bd3ab/hsbg/battlegrounds-multiplayer/s14-leaderboard/ui/darkmoon_ticket.png") end
    local trigger = (c.deathrattle or BG.C.hasDeathrattle(m)) and "deathrattle" or (hasTrigger(c) and "trigger") or nil
    local venom = (m.venom or m.v) and "venomous" or ((m.poison or m.p) and "poisonous") or nil
    local iz = hs and .47 or .49
    if venom then add(venom, "icons/" .. venom .. ".png", trigger and -.15 or 0, iz, .29, .232) end
    if trigger then add(trigger, "icons/" .. trigger .. ".png", venom and .15 or 0, iz, .29, .232) end
    if d.atk and d.hp then
        local attack, health = statCodes(d)
        local function digits(name, value, code, x, z, w, h, maxWidth)
            Draw.statDigits(math.max(0, value), code, x, z, w, h, function(path, dx, dz, dw, dh, i)
                add(name .. "_digit" .. i, nil, dx, dz, dw, dh, Draw.uiArt2(path))
            end, maxWidth)
        end
        if d.atk < 100 then
            add("atk", nil, -gx, gz, .43, .35, Draw.polish("atk/" .. attack .. "/" .. math.max(0, d.atk) .. ".png"))
        else
            add("atk", nil, -gx, gz, .43, .35, Draw.uiArt2("fallback_atk.png"))
            digits("atk", d.atk, attack, -gx, gz, .43, .35, .58)
        end
        -- Keep the entire Health gem and draw the value independently in its lower half.
        add("hp", nil, gx, gz, .37, .32, Draw.uiArt2("fallback_hp.png"))
        digits("hp", d.hp, health, gx, gz + .036, .33, .27, .50)
    end
    if d.zone == "tavern" and not d.combat and c.tier then
        local tierNear = (m.taunt or m.t) and -.72 or -.54
        add("tier", "tb/" .. math.max(1, math.min(7, m.cardTier or c.tier)) .. ".png", 0, tierNear, .25, .22)
    end
    if info.splat then
        table.insert(list, {name = "hsbg_dmg", url = Draw.uiArt2("sp/" .. math.max(1, math.min(99, info.splat)) .. ".png"),
            position = {0, (y + .16) / scale, 0}, rotation = {90, yaw, 0}, scale = {2.05 / scale, 2.05 / scale, 1}})
    end
    return list
end

local function decalList(obj, d, info)
    if info.oval then return Draw.ovalDecals(obj, d, info) end
    local s = obj.getScale().x
    local face = info.face or DEFAULT_FACE
    local h = CARD_H
    local w = h * face.r
    local y = (tokenTop + 0.01) / s
    local yaw = Draw.decalYaw()
    local list = {}
    local layer = 0
    -- name = a ui2 path; (fx, fy) centre and (fw, fh) size as fractions of the card; each later decal sits a hair higher
    local function add(name, path, fx, fy, fw, fh)
        layer = layer + 1
        local right, near = (fx - 0.5) * w, (fy - 0.5) * h
        if settings.flip then right, near = -right, -near end
        table.insert(list, {name = "hsbg_" .. name, url = name == "locked" and Draw.polish("lock.png") or Draw.uiArt2(path),
            position = {-right / s, y + layer * 0.004 / s, near / s}, rotation = {90, yaw, 0}, scale = {fw * w / s, fh * h / s, 1}})
    end
    if d.zone ~= "hand" then
        local c = BG_CARDS[d.id] or {}
        local m = d.src or {}
        -- Hearthstone-style effects fitted to the portrait oval (whole-card overlays, bottom to top)
        if m.stealth or m.x then add("stealth", "kw/stealth.png", 0.5, 0.5, 1, 1) end
        if m.reborn or m.r then add("reborn", "kw/reborn.png", 0.5, 0.5, 1, 1) end
        if m.taunt or m.t then add("taunt", "kw/taunt.png", 0.5, 0.5, 1, 1) end
        if m.windfury or m.w then add("windfury", "kw/windfury.png", 0.5, 0.5, 1, 1) end
        if m.shield or m.s then add("shield", "kw/shield.png", 0.5, 0.5, 1, 1) end
        if d.frozen then add("frozen", "kw/frozen.png", 0.5, 0.5, 1, 1) end
        -- effect icons under the portrait, like minions in play: Deathrattle skull / trigger bolt / venom drop
        local icon = c.deathrattle and "deathrattle" or (hasTrigger(c) and "trigger") or nil
        local venom = (m.venom or m.v) and "venomous" or ((m.poison or m.p) and "poisonous") or nil
        -- Keep the indicators within the portrait and clear of the name and stat gems.
        local iw, iy = 0.13, 0.39
        if venom then add(venom, "kw/ic_" .. venom .. ".png", icon and 0.42 or 0.50, iy, iw, iw * face.r) end
        if icon then add(icon, "kw/ic_" .. icon .. ".png", venom and 0.58 or 0.50, iy, iw, iw * face.r) end
    end
    -- Attack and Health on the card's own gems (cloud faces have the printed numbers erased)
    if d.lockTier or d.lockTurn then
        add("locked", "", 0.52, 0.39, .41, .41 * face.r)
    end
    if d.spell and d.zone == "tavern" and d.price and BG.SPELLS[d.id] and d.price ~= BG.SPELLS[d.id].cost then
        add("price", "cn/" .. math.max(0, math.min(20, d.price)) .. ".png", 0.135, 0.125, 0.22, 0.22 * face.r)
    end
    if not info.local_ and d.atk and d.hp then
        add("atk", "fallback_atk.png", face.a[1], face.a[2], 0.28, 0.28 * face.r)
        add("health", "fallback_hp.png", face.a[3], face.a[4], 0.28, 0.28 * face.r)
    end
    if d.atk and d.hp then
        local ac, hc = statCodes(d)
        -- gem-sized numbers (the art is centred on the glyphs), on the Attack ball and the Health drop's bulb
        local sw = Draw.warpHandFaces[d.id] and .22 or .25
        local function stat(name, value, code, x, z)
            if value < 100 then
                add(name, "st/" .. code .. "/" .. math.max(0, value) .. ".png", x, z, sw, sw * face.r)
                return
            end
            Draw.statDigits(value, code, x, z, sw, sw * face.r, function(path, dx, dz, dw, dh, i)
                add(name .. "_digit" .. i, path, dx, dz, dw, dh)
            end)
        end
        local warp = Draw.warpHandFaces[d.id]
        stat("atk", d.atk, ac, face.a[1] + (warp and 0 or .01), face.a[2] - (warp and 0 or .018))
        stat("hp", d.hp, hc, face.a[3], face.a[4] - (warp and 0 or .004))
    end
    if info.splat then
        -- the damage number is part of the splat image (a label over a decal is hidden by TTS's sorting)
        local k = info.splatScale or 1
        table.insert(list, {name = "hsbg_dmg", url = Draw.uiArt2("sp/" .. math.max(1, math.min(99, info.splat)) .. ".png"),
            position = {0, y + (layer + 2) * 0.004 / s + 0.02 / s, (settings.flip and 0.16 or -0.16) * h / s}, rotation = {90, yaw, 0},
            scale = {0.78 * w * k / s, 0.78 * w * k / s, 1}})
    end
    return list
end

local function applyDecals(obj, d, info)
    if d.spell then return Draw.spellDecals(obj, d, info) end
    local m = d.src or {}
    local key = table.concat({
        tostring(settings.flip), tostring(settings.decalFlip), string.format("%.3f", obj.getScale().x),
        tostring(info.splat), d.zone, tostring(d.combat), tostring(d.atk), tostring(d.hp), tostring(d.maxhp), tostring(d.frozen),
        tostring(m.stealth or m.x), tostring(m.reborn or m.r), tostring(m.taunt or m.t),
        tostring(m.windfury or m.w), tostring(m.shield or m.s), tostring(m.venom or m.v), tostring(m.poison or m.p), tostring(m.darkmoonTicket), Draw.activateKey and Draw.activateKey(info, d) or ""
    }, "|")
    if info.decalKey == key then return end
    local decals = decalList(obj, d, info)
    if pcall(function() obj.setDecals(decals) end) then info.decalKey = key end
end

local CLEAR = {0, 0, 0, 0}
local WHITE = {1, 1, 1, 1}


-- Activate: the button art rides on the minion token; a transparent object button takes the click.
function Draw.activateState(info, d)
    if not game or game.phase ~= "recruit" or d.zone ~= "warband" or d.combat then return nil end
    local p = game.players[info.color]
    local m = d.src
    if not p or not m or p.bot then return nil end
    local cost, used = BG.activation(game, m)
    if not cost then return nil end
    local ok = BG.canAct(game, p)
    local enabled = ok and not used and p.gold >= cost and not p.discover
    return {cost = cost, used = used, enabled = enabled and true or false,
        url = used and "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/505f29f2a8d581c0b4cabcdd96322e7a7c404572/hsbg/battlegrounds-multiplayer/s14-leaderboard/ui/activate_used.png" or ("https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1c3dbbc7887ff04e8479e3d2688070035fab0d6a/hsbg/battlegrounds-multiplayer/s14-leaderboard/hp3/coin/" .. math.max(0, math.min(20, cost)) .. ".png")}
end
function Draw.activateTarget(info, d)
    if not game or game.phase ~= "recruit" or d.combat then return false end
    local p = game.players[info.color]
    local c = p and p.discover
    if not c or c.kind ~= "activate_target" or not d.src then return false end
    for _, uid in ipairs(c.options or {}) do if uid == d.src.uid then return true end end
    return false
end
function Draw.activateKey(info, d)
    local s = Draw.activateState(info, d)
    local t = Draw.activateTarget(info, d) and "T" or ""
    return (s and (s.cost .. (s.enabled and "e" or "l") .. (s.used and "u" or "")) or "") .. t
end
function Draw.activateButton(obj, d, info)
    local s = Draw.activateState(info, d)
    local key = s and Draw.activateKey(info, d) or ""
    if info.actKey == key then return end
    info.actKey = key
    pcall(function() obj.clearButtons() end)
    if not s then return end
    local scale = obj.getScale().x
    local fx, fz = .33, -.40
    if settings.flip then fx, fz = -fx, -fz end
    if s.used then return end
    pcall(function() obj.createButton({click_function = "bgActivateClick", function_owner = self, label = "",
        position = {-fx * 2.48 / scale, (math.max(.12, tokenTop) + .2) / scale, fz * 3.12 / scale}, rotation = {0, settings.flip and 180 or 0, 0},
        width = 210, height = 210, scale = {1 / scale, 1, 1 / scale}, color = {0, 0, 0, 0}, hover_color = {1, 1, 1, 0.08},
        press_color = {1, 1, 1, 0.18}, font_size = 1,
        tooltip = s.used and "Activate used this turn" or ("Activate · " .. s.cost .. " Gold\n" .. (BG_CARDS[d.id] and BG_CARDS[d.id].text or ""))}) end)
end
local function overlay(obj, d)
    local info = tokenInfo[obj.getGUID()]
    if not info or info.retiring then return end
    pcall(Draw.activateButton, obj, d, info)
    local m=d.src or {}
    local statKey=table.concat({tostring(d.atk),tostring(d.hp),d.zone,tostring(m.openTurn),
        m.openTurn and game and game.turn or 0,#(m.attachments or {})},"/")
    if not d.combat and info.stats ~= statKey then
        local description = Draw.tokenDescription(d)
        if info.description ~= description then obj.setDescription(description); info.description = description end
        info.stats = statKey
    end
    applyDecals(obj, d, info)
end

local function spawnToken(color, d, pos, rot)
    local _, face, isLocal = artFor(d.id, d.golden)
    if d.spell then face, isLocal = Draw.spellFaceFor(d.id), false end
    local st = seat(color)
    st.pendingTokens = st.pendingTokens or {}
    local oval = Draw.ovalArt(d)
    local carrier = oval ~= nil and not d.spell
    local shape = carrier and "portrait" or (oval and "oval" or "card")
    local bodyHeight = carrier and UNIT_H * .60 or (oval and UNIT_H or CARD_H)
    local data = tokenData(color, d, oval, shape)
    local info = {color = color, key = d.key, id = d.id, golden = d.golden, d = d, face = face,
        local_ = isLocal, oval = oval ~= nil, carrier = carrier, shopPrice = d.price, description = data.Description}
    local ticket = {info = info}
    st.pendingTokens[d.key] = ticket
    local function remember(obj)
        local guid = Draw.safeGUID(obj)
        if not guid then return nil end
        if ticket.guid and ticket.guid ~= guid then tokenInfo[ticket.guid] = nil end
        ticket.guid = guid
        st.tokens[d.key], tokenInfo[guid] = guid, info
        return guid
    end
    local ok, obj = pcall(spawnObjectData, {
        data = data, position = pos, rotation = rot,
        callback_function = function(o)
            if seats[color] ~= st or st.pendingTokens[d.key] ~= ticket then
                pcall(function() o.destruct() end)
                return
            end
            local guid = remember(o)
            st.pendingTokens[d.key] = nil
            if not guid then return end
            Draw.measureToken(guid, shape, bodyHeight, function(t)
                if tokenInfo[guid] ~= info then return end
                info.decalKey = nil
                if info.d then overlay(t, info.d) end
            end)
        end,
    })
    if not ok or not obj then st.pendingTokens[d.key] = nil; return nil end
    ticket.object = obj
    remember(obj)
    return obj
end

local function tokenFor(color, key)
    local st = seat(color)
    local guid = st.tokens[key]
    local obj = Draw.live(guid)
    if guid and not obj and not (st.pendingTokens and st.pendingTokens[key]) then
        st.tokens[key], tokenInfo[guid], pendingDrop[guid] = nil, nil, nil
    end
    return obj
end

local function destroyToken(color, key)
    local st = seat(color)
    local ticket = st.pendingTokens and st.pendingTokens[key]
    local guid = st.tokens[key]
    local obj = Draw.live(guid) or (ticket and ticket.object)
    st.tokens[key] = nil
    if st.pendingTokens then st.pendingTokens[key] = nil end
    if guid then tokenInfo[guid], pendingDrop[guid] = nil, nil end
    if obj then pcall(function() obj.destruct() end) end
end



local function entry(key, zone, index, count, m, golden)
    return {key = key, zone = zone, index = index, count = count, id = m.id, golden = golden and true or false,
        combat = key:sub(1, 1) ~= "u", atk = m.atk or m.a, hp = m.hp or m.h, shield = (m.shield or m.s) and true or false, src = m}
end

-- What this seat should show right now.
local function desired(color)
    local p = game and game.players[color]
    local list = {}
    if not p then return list end
    local function add(src, zone, prefix, extra)
        for i, m in ipairs(src) do
            local e = entry(prefix .. (m.uid or m.u), zone, i, #src, m, m.golden or m.g)
            if extra then extra(e, m) end
            table.insert(list, e)
        end
    end
    local handFrame
    if game.phase == "combat" then
        local v = combatView and combatView[color]
        if not v then return list end
        local f = v.frames[math.max(1, math.min(v.step, #v.frames))]
        local mine, theirs = f.a, f.b
        if v.side == 2 then mine, theirs = f.b, f.a end
        local function maxhp(e, m) e.maxhp = v.maxhp[m.u] end
        add(mine, "warband", "c", maxhp)
        add(theirs, "tavern", "e", maxhp)
        handFrame = f.hands and f.hands[v.side]
        if not handFrame or seat(color).combatHand == handFrame then return list, handFrame, true end
    elseif p.alive or game.phase == "over" then
        if game.phase == "recruit" and p.timewarpVisit then
            local visit = p.timewarpVisit
            local order = {}
            for i in ipairs(visit.slots) do order[#order + 1] = i end
            table.sort(order, function(a, b)
                local da, db = BG_TIMEWARP[visit.slots[a].id], BG_TIMEWARP[visit.slots[b].id]
                local ca, cb = da and da.cost or 0, db and db.cost or 0
                if ca ~= cb then return ca < cb end
                return a < b
            end)
            for pos, i in ipairs(order) do
                local slot = visit.slots[i]
                if not slot.taken and Draw.warpToken(slot.id) then
                    local c = BG_CARDS[slot.id]
                    local d = entry("w" .. visit.turn .. "x" .. i, "tavern", pos, #order, {id = slot.id, atk = c.atk, hp = c.hp}, false)
                    d.combat, d.warpIndex, d.warpVisit = false, i, visit
                    list[#list + 1] = d
                elseif not slot.taken and Draw.warpSpellToken(slot.id) then
                    local d = entry("w" .. visit.turn .. "x" .. i, "tavern", pos, #order, {id = slot.id}, false)
                    d.combat, d.warpIndex, d.warpVisit, d.spell, d.warp = false, i, visit, true, true
                    d.atk, d.hp = nil, nil
                    d.abilityText = BG.SPELLS[slot.id].text
                    list[#list + 1] = d
                end
            end
        end
        if game.phase == "recruit" and not p.timewarpVisit then
            local count = #p.tavern + #p.spellShop
            add(p.tavern, "tavern", "u", function(e) e.frozen, e.count, e.color = (p.frozen or (e.src and e.src.timewarpFrozen)) and true or false, count, color end)
            for i, spell in ipairs(p.spellShop) do
                local d = entry("s" .. spell.uid, "tavern", #p.tavern + i, count, spell, false)
                d.spell, d.combat, d.frozen = true, false, p.frozen
                d.price = BG.spellPrice(p, spell)
                d.abilityText = Draw.spellState(game, p, d)
                list[#list + 1] = d
            end
        end
        add(p.board, "warband", "u")
    end
    if p.alive then
        local hand = handFrame and handFrame.hand or p.hand
        local spells = handFrame and handFrame.spellHand or p.spellHand
        add(hand, "hand", "u")
        local locked = p.expeditions or {}
        local spellLocks=p.spellExpeditions or {}
        local count=#hand+#spells+#locked+#spellLocks
        for i, spell in ipairs(spells) do
            local d = entry("s" .. spell.uid, "hand", #hand + i, count, spell, false)
            d.spell, d.combat = true, false
            d.abilityText = Draw.spellState(game, p, d)
            list[#list + 1] = d
        end
        for i, plan in ipairs(locked) do
            local m = plan.minion
            local d = entry("l" .. m.uid, "hand", #hand + #spells + i, count, m, m.golden)
            d.lockTier, d.lockTurn, d.combat = plan.tier, plan.turn, false
            d.lockGold = plan.gold and math.max(0, plan.gold - (p.totalGoldSpent or 0)) or nil
            table.insert(list,d)
        end
        for i,plan in ipairs(spellLocks) do
            local d=entry("l"..plan.spell.uid,"hand",#hand+#spells+#locked+i,count,plan.spell,false)
            d.spell,d.combat,d.lockTurn=true,false,plan.turn
            d.lockGold=plan.gold and math.max(0,plan.gold-(p.totalGoldSpent or 0)) or nil
            d.abilityText = Draw.spellState(game, p, d)
            list[#list+1]=d
        end
    end
    return list,handFrame
end

local function targetOf(board, d)
    local near = d.zone == "tavern" and ROW_TAVERN or ROW_WARBAND
    return boardPoint(board, slotRight(d.index, d.count), near, 0.3)
end

function Draw.sameCombatArt(a, b)
    if a.atk ~= b.atk or a.hp ~= b.hp or a.maxhp ~= b.maxhp then return false end
    local old, new = a.src, b.src
    return old.t == new.t and old.s == new.s and old.r == new.r and old.w == new.w
        and old.v == new.v and old.p == new.p and old.x == new.x
end

local function syncSeat(color, snapGuid)
    local board = boardOf(color)
    if not board then return false end
    local st, rot = seat(color), cardRotation(board)
    local keep, missing = {}, false
    local inCombat = game and game.phase == "combat"
    local want, handFrame, keepHand = desired(color)
    if not inCombat then st.combatHand = nil end
    for _, d in ipairs(want) do keep[d.key] = true end
    local gone = {}
    for key, guid in pairs(st.tokens) do
        local info = tokenInfo[guid]
        local heldInHand = keepHand and info and info.d and info.d.zone == "hand"
        if not keep[key] and not heldInHand then gone[#gone + 1] = key end
    end
    for key, ticket in pairs(st.pendingTokens or {}) do
        if not st.tokens[key] and not keep[key] and not (keepHand and ticket.info.d.zone == "hand") then
            gone[#gone + 1] = key
        end
    end
    for _, key in ipairs(gone) do
        if inCombat and Draw.fx then
            local dying = tokenFor(color, key)
            local dinfo = dying and tokenInfo[dying.getGUID()]
            if dinfo and dinfo.d and dinfo.d.combat then pcall(Draw.fx, "death", dying.getPosition()) end
        end
        destroyToken(color, key)
    end

    for _, d in ipairs(want) do
        local ok, updated = pcall(function()
            local obj = tokenFor(color, d.key)
            local guid = st.tokens[d.key]
            local ticket = st.pendingTokens and st.pendingTokens[d.key]
            local info = guid and tokenInfo[guid] or (ticket and ticket.info)
            local wantsOval = Draw.ovalArt(d) ~= nil
            local wantsCarrier = wantsOval and not d.spell
            if info and (info.id ~= d.id or info.golden ~= d.golden or info.oval ~= wantsOval
                or info.carrier ~= wantsCarrier or (d.spell and info.shopPrice ~= d.price)) then
                destroyToken(color, d.key)
                obj, guid, ticket, info = nil, nil, nil, nil
            end
            if ticket then info.d = d; return true end
            if not obj then
                local pos = d.zone == "hand" and handPoint(color, d.index) or targetOf(board, d)
                return not pos or spawnToken(color, d, pos, rot) ~= nil
            end
            local ready = Draw.ready(guid)
            if not ready then if info then info.d = d end; return true end
            local previous = info and info.d
            local sameSlot = d.combat and info and info.combatHome and previous
                and previous.index == d.index and previous.count == d.count and previous.zone == d.zone
            local sameArt = d.combat and previous and info.decalKey and not info.splat and Draw.sameCombatArt(previous, d)
            if not sameSlot and not ready.held_by_color then
                if d.zone == "hand" then
                    if guid == snapGuid or not inHand(color, ready) then
                        local pos = handPoint(color, d.index)
                        if pos then ready.setPositionSmooth(pos, false, true); ready.setRotationSmooth(rot, false, true) end
                    end
                else
                    local t, p = targetOf(board, d), ready.getPosition()
                    local tx, tz = t.x or t[1], t.z or t[3]
                    if guid == snapGuid then
                        ready.setPosition(t); ready.setRotation(rot)
                        if not ready.locked then
                            pcall(function() ready.setVelocity({0, 0, 0}); ready.setAngularVelocity({0, 0, 0}) end)
                        end
                    elseif math.abs(p.x - tx) > .08 or math.abs(p.z - tz) > .08
                        or (inCombat and math.abs(p.y - (t.y or t[2])) > .09)
                        or (not inCombat and inHand(color, ready)) then
                        ready.setPositionSmooth(t, false, true)
                        if not inCombat then ready.setRotationSmooth(rot, false, true) end
                    end
                    if inCombat and info then info.combatHome = true end
                end
            end
            if info then
                if d.combat and previous and previous.hp then
                    local amount = previous.hp - d.hp
                    info.splat = amount > 0 and amount or nil
                    if amount > 0 and Draw.fx then pcall(Draw.fx, "hit", ready.getPosition()) end
                    if previous.shield and not d.shield and Draw.fx then pcall(Draw.fx, "shield", ready.getPosition()) end
                end
                info.d = d
            end
            if not sameArt then overlay(ready, d) end
            return true
        end)
        if not ok or not updated then missing = true end
    end
    local current = game
    if not current or current.phase ~= "recruit" then
        if handFrame and not keepHand and not missing then st.combatHand = handFrame end
        return not missing
    end
    if st.syncTurn ~= current.turn then st.syncTurn, st.syncAttempts = current.turn, 0 end
    if missing and not st.syncWaiting and st.syncAttempts < 6 then
        st.syncAttempts, st.syncWaiting = st.syncAttempts + 1, true
        local turn = current.turn
        Wait.time(function()
            st.syncWaiting = nil
            if game == current and game.phase == "recruit" and game.turn == turn and seats[color] == st then syncSeat(color) end
        end, .4)
    elseif not missing then
        st.syncAttempts = 0
    end
    return not missing
end


-------------------------------------------------------------------------------
-- lookups
local function heroOf(p) return p and p.hero and BG.heroById(p.hero) or nil end
local function anomalyOf(id)
    for _, a in ipairs(BG_ANOMALIES or {}) do if a.id == id then return a end end
    return nil
end
local function seasonOf(key)
    for _, s in ipairs(BG_SEASONS or {}) do if s.key == key then return s end end
    return nil
end
Draw.verifiedSeasons = {s14 = true, s15 = true}
Draw.SEASON_CYCLE = {"s14", "s15"}
function Draw.availableSeason(key)
    if key and Draw.verifiedSeasons[key] then return seasonOf(key) end
end
local function seasonName(s)
    if not s then return "Coming soon" end
    return "Season " .. s.season .. " - " .. (s.title or ("Patch " .. tostring(s.patch)))
end
local function powerLine(h)
    if not h then return "" end
    local hp = BG.HP[h.id]
    local tag = hp and (hp.active and "" or " (passive)") or " (not scripted)"
    local cost = (hp and hp.active) and (" (" .. tostring(h.cost) .. ")") or ""
    return h.power .. cost .. tag
end

