-- ---------------------------------------------------------------- VFX player
Draw.FX_BASE = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/0b2598b64641f565928b9450e207f63a12232cd2/hsbg/battlegrounds-multiplayer/s14-leaderboard/fx/"
Draw.FXDEF = {hit = {n = 8, size = 3.4}, shield = {n = 9, size = 4.2}, death = {n = 10, size = 4.0}, golden = {n = 12, size = 5.2},
    tierup = {n = 10, size = 4.2}, coin = {n = 8, size = 2.2}, darkgift = {n = 12, size = 4.6}}
Draw.fxPool = Draw.fxPool or {}
local FX_S, FX_SINK = 0.1, 1.2
function Draw.fxUrls()
    local list = {}
    for kind, def in pairs(Draw.FXDEF) do for i = 1, def.n do list[#list + 1] = Draw.FX_BASE .. kind .. "/" .. i .. ".png" end end
    return list
end
local function fxCarrier()
    for _, c in ipairs(Draw.fxPool) do
        if not c.busy and c.obj and not c.obj.isDestroyed() then return c end
    end
    if #Draw.fxPool >= 14 then return nil end
    -- A built-in block (never a custom import, so no import dialog can ever appear), kept out of sight; only its decal shows.
    local c = {busy = false}
    c.obj = spawnObject({type = "BlockSquare", position = {0, -30, 0}, rotation = {0, 0, 0}, scale = {FX_S, FX_S, FX_S}, sound = false,
        callback_function = function(o)
            pcall(function() o.setLock(true); o.interactable = false; o.setGMNotes("hsbg_fx"); o.setName(""); o.tooltip = false end)
        end})
    Draw.fxPool[#Draw.fxPool + 1] = c
    return c
end
function Draw.fx(kind, pos)
    local def = Draw.FXDEF[kind]
    if not def or not pos then return end
    local c = fxCarrier()
    if not c then return end
    c.busy = true
    local obj = c.obj
    local x, y, z = pos.x or pos[1], pos.y or pos[2], pos.z or pos[3]
    local yaw = Draw.decalYaw()
    local function run()
        if obj.isDestroyed() then c.busy = false; return end
        obj.setPosition({x, y - FX_SINK, z})
        obj.setRotation({0, 0, 0})
        local i = 0
        local function step()
            if obj.isDestroyed() then c.busy = false; return end
            i = i + 1
            if i > def.n then
                pcall(function() obj.setDecals({}) end); obj.setPosition({0, -30, 0}); c.busy = false
                return
            end
            pcall(function() obj.setDecals({{name = "fx", url = Draw.FX_BASE .. kind .. "/" .. i .. ".png",
                position = {0, (FX_SINK + 0.4) / FX_S, 0}, rotation = {90, yaw, 0}, scale = {def.size / FX_S, def.size / FX_S, 1}}}) end)
            Wait.frames(step, 3)
        end
        step()
    end
    if obj.spawning then Wait.condition(run, function() return obj.isDestroyed() or not obj.spawning end, 5, function() c.busy = false end)
    else run() end
end
function Draw.fxBoard(color, kind, right, near)
    local board = boardOf(color)
    if not board then return end
    local ok, p = pcall(boardPoint, board, right, near, 0.3)
    if ok and p then Draw.fx(kind, p) end
end
function Draw.fxCleanup()
    for _, o in ipairs(getAllObjects()) do
        local ok, notes = pcall(function() return o.getGMNotes() end)
        if ok and notes == "hsbg_fx" then pcall(function() o.destruct() end) end
    end
    Draw.fxPool = {}
end
function Draw.eventFx(e)
    if not e or not e.color or not game then return end
    local p = game.players[e.color]
    if not p or p.bot then return end
    if e.fx == "upgrade" then Draw.fxBoard(e.color, "tierup", SPOT.tierup[1], SPOT.tierup[2])
    elseif e.fx == "combine" then Draw.fxBoard(e.color, "golden", 0, ROW_WARBAND + 4.4)
    elseif e.fx == "buy" then Draw.fxBoard(e.color, "coin", 0, ROW_WARBAND + 4.4)
    elseif e.fx == "sell" then Draw.fxBoard(e.color, "coin", 0, ROW_TAVERN) end
end

-- TTS labels never Draw.wrap: break long text into lines of about `width` characters.
function Draw.wrap(text, width)
    local out = {}
    local src, paras, start = tostring(text or ""), {}, 1
    -- split on newlines with plain finds (MoonSharp rejects "(.-)\n" on long text: "pattern too complex")
    while true do
        local i = src:find("\n", start, true)
        if not i then table.insert(paras, src:sub(start)); break end
        table.insert(paras, src:sub(start, i - 1))
        start = i + 1
    end
    for _, para in ipairs(paras) do
        local line = ""
        for word in para:gmatch("%S+") do
            if #line > 0 and #line + 1 + #word > width then
                table.insert(out, line); line = word
            else
                line = (#line > 0) and (line .. " " .. word) or word
            end
        end
        table.insert(out, line)
    end
    return table.concat(out, "\n")
end

-- Keep text in one small native label above the artwork.
function Draw.addLabel(b, l, y)
    local width = l.width or math.max(3, math.min(12, #l.text * 0.15))
    return {button(b, {key = l.key, x = l.x, z = l.z, y = y, w = width, h = l.height or 0.62,
        font = l.font or 0.30, label = l.text, color = l.background or {0.18, 0.12, 0.08, 0.97}, font_color = l.color or WHITE})}
end

function Draw.artDims(url)
    if url and url:find("/s14-leaderboard/hero/", 1, true) then return {300, 352} end
    if url then
        local powers = Draw.recruitArt("powers/")
        if url:sub(1, #powers) == powers then return {256, 286} end
        local base = Draw.newArt("")
        if url:sub(1, #base) == base then
            local family = url:sub(#base + 1):match("^(%a+)/")
            if family == "power" then return {256, 286} end
            return {300, 430}
        end
    end
    if url and (url:sub(1, #CLOUD) == CLOUD or url:sub(1, #Draw.localArt) == Draw.localArt) then
        local localAsset = url:sub(1, #Draw.localArt) == Draw.localArt
        if localAsset then
            local path = url:sub(#Draw.localArt + 1)
            if path:sub(1, 14) == "polished/hero/" then return {300, 352} end
            if path:sub(1, 15) == "polished/power/" or path:sub(1, 18) == "polished/trinkets/" then return {1, 1} end
            if path:sub(1, 14) == "polished/tier/" then return {300, 360} end
            if path:sub(1, 14) == "refined/coins/" then return {1240, 128} end
            if path:sub(1, 15) == "refined/tavern/" then return {300, 360} end
        end
        local kind, name = "ui2", url:sub(#Draw.localArt + 1)
        if not localAsset then kind, name = url:sub(#CLOUD + 1):match("^(%w+)/(.+)$") end
        if localAsset and name:sub(1, 3) == "et_" then return {320, 178} end
        if localAsset and name:sub(1, 5) == "tier/" then return {260, 138} end
        if kind == "ui" then return DIMS[name] end
        if kind == "ui2" then
            local set = name:match("^(%a+)/")
            if set == "kw" and name:find("/ic_", 1, true) then return {128, 128} end
            if set == "gd" then   -- the Gold bar: an N/M pill plus one coin per slot
                local c, m = name:match("^gd/(%d+)_(%d+)")
                local slots = math.max(tonumber(m) or 0, math.min(tonumber(c) or 0, 10))
                return {266 + 92 * math.max(1, slots), 120}
            end
            return DIMS2[name] or (set and UI2_SETS[set]) or nil
        end
        if kind then return DIMS[kind] end
    end
    return nil
end

-- Decal size (with any transparent border) and content size, in world units.
function Draw.widgetSize(spec)
    if spec.dimensions then return table.unpack(spec.dimensions) end
    if not spec.url then return spec.size, spec.size, spec.size, spec.size end
    if spec.face then
        local h = spec.size
        local w = h * spec.face.r
        if spec.url:sub(1, #CLOUD) == CLOUD then
            local px = h / FACE_PX
            return w + 2 * TOKEN_PAD * px, h + 2 * TOKEN_PAD * px, w, h
        end
        return w, h, w, h
    end
    local d = Draw.artDims(spec.url) or {256, 256}
    local ar = d[1] / d[2]
    local w, h
    if spec.fit == "h" or ar < 1 then h = spec.size; w = h * ar else w = spec.size; h = w / ar end
    spec.dimensions = {w, h, w, h}
    return w, h, w, h
end

local function ensureTile(color, key, spec)
    widgets[color] = widgets[color] or {}
    widgets[color][key] = spec
    return spec
end

local function tileOf(color, key)
    return widgets[color] and widgets[color][key] or nil
end

local function removeTile(color, key)
    if widgets[color] then widgets[color][key] = nil end
end

local function removeTiles(color, prefix)
    local list = widgets[color]
    if not list then return end
    local keys = {}
    for k in pairs(list) do if not prefix or k:sub(1, #prefix) == prefix then table.insert(keys, k) end end
    for _, k in ipairs(keys) do list[k] = nil end
end

function Draw.widgetHost(color)
    if color == SET then return self, self.getScale().x, CONTROLLER_TOP end
    local board = boardOf(color)
    if board then return board, 1, BOARD_Y end
    return nil
end

function Draw.hasLabel(board)
    for _, b in ipairs(board.getButtons() or {}) do
        if b.click_function == "arenaPhaseLabel" then return true end
    end
    return false
end

-- Codex's board prints its phase ("Setup", "Recruit", ...) on a button along the player's edge. Our
-- status line sits there instead, so the phase label is moved under the board (its script only ever edits
-- the label and colour, so it stays hidden).
function Draw.hidePhaseLabel(board)
    for _, b in ipairs(board.getButtons() or {}) do
        if b.click_function == "arenaPhaseLabel" then
            local p = b.position or {}
            if (p.y or p[2] or 0) > -1 then
                pcall(function() board.editButton({index = b.index, position = {0, -4, 10.98}, font_size = 0, width = 0, height = 0}) end)
            end
        end
    end
end

local leaderList
Draw.settingsButtons = {}

function Draw.setButton(b, key, params)
    b.seen[key] = true
    local old = b.buttons[key]
    if old then
        old.hidden = nil
        local changes
        for field, value in pairs(params) do
            local before = old.params[field]
            local equal = value == before
            if not equal and type(value) == "table" and type(before) == "table" then
                equal = #value == #before
                for i = 1, #value do
                    if value[i] ~= before[i] then equal = false; break end
                end
            end
            if not equal then
                changes = changes or {index = old.index}
                changes[field] = value
            end
        end
        if changes then
            b.obj.editButton(changes)
            old.params = params
        end
        return old.index
    end
    b.obj.createButton(params)
    local index = b.n
    b.n = index + 1
    b.buttons[key] = {index = index, params = params}
    return index
end

-- Removing a button shifts every later native index. Visit the cached buttons
-- in order so the Lua cache always points at the same live controls.
function Draw.removeObsoleteButtons(b)
    for key, entry in pairs(b.buttons) do
        if not b.seen[key] and not entry.hidden then
            local hidden = {index = entry.index, label = " ", width = 1, height = 1, font_size = 1,
                color = {0, 0, 0, 0}, font_color = {0, 0, 0, 0}, hover_color = {0, 0, 0, 0}, press_color = {0, 0, 0, 0},
                position = {0, -12, 0}, scale = {.001, .001, .001}, click_function = "bgNoop", tooltip = ""}
            local ok = pcall(function() b.obj.editButton(hidden) end)
            if ok then
                hidden.index = nil
                entry.params, entry.hidden = hidden, true
            end
        end
    end
end

local function flushSeat(color)
    local host, s, top = Draw.widgetHost(color)
    if not host or host.spawning or host.loading_custom then return end
    local st = color ~= SET and seats[color] or nil
    local buttons = st and st.buttons or Draw.settingsButtons
    if st and not st.buttons then
        Draw.hidePhaseLabel(host)
        st.buttons = {}
        buttons = st.buttons
    end
    local b = {obj = host, s = s, flip = st and settings.flip or false,
        buttons = buttons, seen = {}, n = st and st.nextButton or Draw.nextSettingsButton}
    if b.n == nil then b.n = #(host.getButtons() or {}) end
    local topW = top * s
    local list = widgets[color] or {}
    local keys = {}
    for k in pairs(list) do table.insert(keys, k) end
    table.sort(keys, function(a, c)
        local la, lc = list[a].layer or 1, list[c].layer or 1
        if la ~= lc then return la < lc end
        return a < c
    end)
    local decals, art = {}, {}
    local yaw = Draw.decalYaw()
    for _, key in ipairs(keys) do
        local w = list[key]
        local dw, dh, cw, ch = Draw.widgetSize(w)
        local x, z = w.right or 0, w.near or 0
        local layer, lift = w.layer or 1, w.lift or 0
        local rx, rz = x, z
        if b.flip then rx, rz = -x, -z end
        if w.url then
            local y = top + (0.004 + 0.004 * layer + lift) / s
            local angle = (yaw + (w.angle or 0)) % 360
            table.insert(decals, {name = "hsbg_" .. key, url = w.url, position = {-rx / s, y, rz / s},
                rotation = {90, angle, 0}, scale = {dw / s, dh / s, 1}})
            table.insert(art, table.concat({key, w.url, rx, rz, y, dw, dh, angle}, "|"))
        end
        local y = topW+0.03+0.01*layer+lift
        if w.click then
            button(b, {key = key, x = x + (w.cx or 0), z = z + (w.cz or 0), y = y + 0.01, w = w.cw or cw, h = w.ch or ch,
                font = w.font or 0.3, click = "bgW_" .. key,
                label = w.buttonText or "", color = w.buttonColor or CLEAR,
                hover_color = w.buttonColor or CLEAR, press_color = w.buttonColor or CLEAR})
        end
        for i, l in ipairs(w.labels or {}) do
            if l.text and l.text ~= "" then
                Draw.addLabel(b, {key = key .. ":label:" .. i, text = l.text, x = x + l.x, z = z + l.z,
                    width = l.width, height = l.height, font = l.font, color = l.color, background = l.background}, y + LABEL_LIFT)
            end
        end
    end
    Draw.removeObsoleteButtons(b)
    local sig = table.concat(art, "\n")
    if st then st.nextButton = b.n else Draw.nextSettingsButton = b.n end
    local oldSig = st and st.decalSig or settingsDecals
    if oldSig ~= sig then
        local ok = pcall(function() host.setDecals(decals) end)
        if ok then
            if st then st.decalSig = sig else settingsDecals = sig end
        end
    end
end


function Draw.hpGem(n) return Draw.uiArt2("hp/" .. math.max(0, math.min(99, n or 0)) .. ".png") end
function Draw.armorGem(n) return Draw.uiArt2("ar/" .. math.max(1, math.min(99, n or 1)) .. ".png") end
function Draw.coinGem(n) return Draw.uiArt2("cn/" .. math.max(0, math.min(20, n or 0)) .. ".png") end
function Draw.goldArt(c, m) return Draw.uiArt2("coins/" .. math.max(0, math.min(40, c or 0)) .. "_" .. math.max(0, math.min(10, m or 0)) .. ".png") end

-- A Draw.badge (Health, Armor, a cost) drawn over the corner of other art: one layer up and raised a little.
function Draw.badge(color, key, url, spot, dr, dn, tip)
    ensureTile(color, key, {url = url, size = spot[3], right = spot[1] + (dr or 0), near = spot[2] + (dn or 0),
        layer = 3, lift = key == "b_armor" and .44 or (key == "b_hp" and .35 or .20), tip = tip})
end

-- Hero damage after combat: a splat with the number pops on the hero portrait, holds, then goes.
function Draw.showHeroDamage(color, dmg)
    if not dmg or dmg <= 0 then return end
    local st = seats[color]
    if not st then return end
    local token = {}
    st.popToken = token
    ensureTile(color, "b_pop", {url = Draw.uiArt2("sp/" .. math.min(99, dmg) .. ".png"), size = 2.75,
        right = DOOR_RIGHT, near = HERO_NEAR, layer = 4, lift = 0.12})
    Wait.time(function()
        if seats[color] ~= st or st.popToken ~= token then return end
        st.popToken = nil
        removeTile(color, "b_pop")
        flushSeat(color)
    end, 1.4)
end

