-- board text + controls
-- Everyone, best first (the in-game leaderboard down the board's left rail).
leaderList = function()
    local list, order = {}, {}
    if not game then return list end
    for i, color in ipairs(game.order) do
        list[i] = game.players[color]
        order[color] = i
    end
    table.sort(list, function(a, b)
        if a.alive ~= b.alive then return a.alive end
        local aScore = a.alive and (a.hp + a.armor) or -(a.place or 9)
        local bScore = b.alive and (b.hp + b.armor) or -(b.place or 9)
        if aScore ~= bScore then return aScore > bScore end
        return order[a.color] < order[b.color]
    end)
    return list
end

