function Draw.darkGiftColor(turns)
    if turns==1 and os.time()%4==0 then return {1,1,.78,1} end
    return GOLD_TEXT
end

function Draw.pulseDarkGift(color)
    local card=tileOf(color,"darkgift")
    if not card or card.upgradeIn~=1 or not (card.labels and card.labels[1]) then return false end
    local tone=Draw.darkGiftColor(1)
    if card.labels[1].color[1]==tone[1] and card.labels[1].color[2]==tone[2] then return false end
    card.labels[1].color=tone
    return true
end

function Draw.renderCardActions(color,p,canAct)
    for i=1,BG.MAX_BOARD do removeTile(color,"activate"..i) end
    removeTile(color,"darkgift")
    removeTile(color,"b_deity")
    removeTile(color,"b_aim_activate")
    if not p.alive or p.bot then return end
    if game.deity then
        local c=BG_CARDS[game.deity]
        local view=combatView and combatView[color]
        local frame=view and view.frames[view.step]
        local count=frame and frame.sacrifices and frame.sacrifices[view.side] or 0
        local attack = (p.goldenDeity and c.gatk or c.atk) + (p.deityAtk or 0)
        local health = (p.goldenDeity and c.ghp or c.hp) + (p.deityHealth or 0)
        local text = c.name .. " · " .. attack .. " Attack / " .. health .. " Health"
        local url, face = Draw.previewCard({id=game.deity,golden=p.goldenDeity})
        local deityRight,deityLabel=Draw.heroTopSlot(p,"deity")
        ensureTile(color,"b_deity",{url=Draw.season14Art("deity-sigil.png"),face={r=1},size=.94,
            right=deityRight,near=HERO_NEAR-Draw.heroTopOffset,layer=9,lift=.35,tip=text.."\n"..BG.deityNeed(game.deity).." friendly Aberration deaths awaken your Deity.",
            labels={{text=count.."/"..BG.deityNeed(game.deity),x=deityLabel,z=.03,width=1.1,height=.50,font=.24,color=GOLD_TEXT}},
            preview={url=url,face=face,size=4.8,right=DOOR_RIGHT+2.95,near=HERO_NEAR-2.35,
                tip=text,stats={attack=attack, health=health, baseAttack=c.atk, baseHealth=c.hp}}})
    end
    if game.phase~="recruit" then return end
    local choice = p.discover
    if choice and (choice.kind=="activate_target" or choice.kind=="hero_option" and choice.pickTarget) then
        local zone=choice.zone=="board" and "warband" or "Tavern"
        local hint=choice.pickTarget and "Pick up the second minion for Spirit Swap" or
            (choice.zone=="hand" and "Pick up the card in your hand to discard" or ("Activate: pick up a "..zone.." target"))
        ensureTile(color,"b_aim_activate",{size=1,right=0,near=.15,layer=8,lift=tokenTop+.15,
            labels={{text=hint,x=0,z=0,width=6.4,height=.45,font=.28,color=GOLD_TEXT}}})
    end
    for i,m in ipairs(p.board) do
        local cost,used=BG.activation(game,m)
        if cost then
            local enabled=canAct and not used and p.gold>=cost
            local path="activate/"..(enabled and "ready-" or "locked-")..math.min(4,cost)..".png"
            if false then ensureTile(color,"activate"..i,{url=Draw.season14Art(path),face={r=152/175},size=1.23,fit="h",
                right=slotRight(i,#p.board),near=ROW_WARBAND-1.95,layer=6,lift=tokenTop+.13,
                click=enabled,action="activate",index=i,uid=m.uid,cw=1.05,ch=1.20,
                tip=used and "Activate used this turn" or ("Activate · "..cost.." Gold\n"..BG_CARDS[m.id].text)}) end
        end
    end
    if not p.timewarpVisit and game.darkGiftsEnabled~=false and game.season=="s14" and game.turn>=3 and (p.darkGifts or 0)<3 then
        local enabled=canAct and p.gold>=3 and BG.darkGiftState(game,p)
        local minTier, maxTier, turns = BG.darkGiftTiers(game)
        local tier = minTier == maxTier and tostring(minTier) or (minTier .. "–" .. maxTier)
        local upgrade = turns and ("Upgrades in " .. turns .. (turns == 1 and " turn" or " turns")) or "Fully upgraded"
        local finish = SPOT.endturn
        ensureTile(color,"darkgift",{url=Draw.season14Art("dark-gift-"..(enabled and "ready" or "locked")..".png"),
            face={r=236/262},size=2.3,fit="h",right=14.1,near=-4.8,layer=6,
            click=enabled,action="darkgift",cw=2.05,ch=2.3,upgradeIn=turns,
            preview={boxText={text="Discover a Tier "..(minTier == maxTier and tostring(minTier) or (minTier.." or "..maxTier)).." minion with a Dark Gift. ("..
                    ((3-(p.darkGifts or 0)) == 1 and "1 use left!" or ((3-(p.darkGifts or 0)).." uses left!"))..")", cx = 256 / 500, cy = 467 / 650, w = 270 / 500, h = 108 / 650},
                url="https://raw.githubusercontent.com/Jnipko488/mtg-table-data/72f0ebbe8cdfd467229fafe9e377827db95beb3c/hsbg/battlegrounds-multiplayer/s14-leaderboard/ui/dark_discovery.png",
                face={r=500/650},size=4.8,right=10.75,near=-4.9,layer=12,lift=1}})
    end
end

-- Keep the changing part of an ability in the same text as its rule and expose it
-- separately for the small in-world counter. Saved games already store these fields.
function Draw.liveAbilityText(text, status, printed, current)
    text = (text or ""):gsub("%)[%d]+[A-Z].*$", ")")
    if not status then return text end
    if printed and current and printed ~= current then
        local old = "%+" .. printed .. "/%+" .. printed
        text = text:gsub(old, "+" .. current .. "/+" .. current, 1)
    end
    local clean, changed = text:gsub("%s*%(%d+[^()]* left!%)$", "")
    if changed == 0 then clean = text end
    return clean .. " (" .. status .. ")"
end

function Draw.turnStatus(remaining)
    return remaining <= 0 and "Due this turn" or (remaining .. (remaining == 1 and " turn left" or " turns left"))
end

