    BG34_HERO_004 = 5, BG34_HERO_000 = 8, BG36_HERO_101 = 7}
Draw.powerPeriods = {BG36_HERO_105 = 4, TB_BaconShop_HERO_75 = 3, TB_BaconShop_HERO_94 = 4, BG26_HERO_104 = 3}

function Draw.powerState(g, p, h)
    if Draw.s15PowerText[h.id] then return Draw.s15PowerText[h.id](g, p, h) end
    if h.id == "BG21_HERO_000" then
        local n, a, hh = (p.carielTargets or 1), (p.carielAttack or 1), (p.carielHealth or 1)
        return "Give " .. n .. " random friendly minion" .. (n > 1 and "s" or "") .. " +" .. a .. "/+" .. hh .. ". Passive: After each combat, choose an improvement.", nil
    elseif h.id == "BG20_HERO_283" and p.flight and BG.FLIGHT_TEXT and BG.FLIGHT_TEXT[p.flight.path] then
        local left = math.max(0, p.flight.arrival - g.turn)
        return p.flight.path .. ": " .. BG.FLIGHT_TEXT[p.flight.path]:format(left, left == 1 and "" or "s") .. " (" .. left .. (left == 1 and " turn" or " turns") .. " left!)", nil
    end
    local id, status, base, value = h.id
    local counter, due, period = Draw.powerCounters[id], Draw.powerDue[id], Draw.powerPeriods[id]
    local buys = (p.counters and p.counters.buysTotal) or 0
    if counter then
        local count, goal = p[counter[2]] or 0, counter[1]
        if counter.cycle then count = count % goal end
        local left = math.max(0, goal - count)
        status = left == 0 and counter[3] or (left .. (counter.unit or "") .. " left")
    elseif due then
        status = g.turn < due and Draw.turnStatus(due - g.turn) or "Unlocked"
    elseif period then
        local remaining = period - g.turn % period
        if id == "BG26_HERO_104" and remaining == period and g.turn > 0 and not g.recruitClosed then remaining = 0 end
        status = Draw.turnStatus(remaining)
        if id == "TB_BaconShop_HERO_75" then base, value = 1, p.spellAtk or 1 end
    elseif id == "TB_BaconShop_HERO_01" then
        base, value = 2, 2 + math.floor(buys / 4)
        status = (4 - buys % 4) .. " left"
    elseif id == "BG20_HERO_102" then
        base, value = 1, 1 + math.floor(buys / 3)
        status = (3 - buys % 3) .. " left"
    elseif id == "BG20_HERO_280" then
        local count = p.kurtrusTurn == g.turn and #(p.kurtrusCandidates or {}) or 0
        status = count >= 3 and "Done this turn" or ((3 - count) .. " left")
    elseif id == "BG28_HERO_800" then
        local left = 2 - (p.spellsBought or 0) % 3
        status = left == 0 and "Next spell is free" or (left .. " left")
    elseif id == "BG20_HERO_283" and p.flight then
        status = p.flight.path .. " · " .. Draw.turnStatus(p.flight.arrival - g.turn)
    elseif id == "BG28_HERO_400" and (p.snakeWait or 0) > 0 then
        status = Draw.turnStatus(p.snakeWait)
    end
    if h.id == "BG36_HERO_105" and g.darkGiftsEnabled == false then status = "Dark Gifts disabled" end
    return Draw.liveAbilityText(h.text, status, base, value), status
end

Draw.trinketGoals = {
    BG36_MagicItem_380 = 5, BG35_MagicItem_920 = 14, BG35_MagicItem_840t = 7,
    BG36_MagicItem_850 = 5, BG36_MagicItem_407 = 11, BG36_MagicItem_408 = 40,
    BG36_MagicItem_409 = 10, BG36_MagicItem_305 = 18, BG36_MagicItem_410 = 25,
    BG30_MagicItem_713 = 8, BG30_MagicItem_931 = 6, BG30_MagicItem_710 = 5,
    BG30_MagicItem_951 = 6, BG30_MagicItem_982 = 2, BG30_MagicItem_919 = 2,
    BG36_MagicItem_307 = 2, BG36_MagicItem_418 = 3,
}

function Draw.trinketState(g, p, t)
    local id = t.id
    local values = p.trinketCounts or {}
    local status, base, value
    local goal = Draw.trinketGoals[id] or (values[id] ~= nil and tonumber((t.text or ""):match("%((%d+)[^()]* left!%)")))
    if goal then
        local unit = id == "BG36_MagicItem_408" and " Gold" or ""
        status = (math.max(0, goal - (values[id] or 0))) .. unit .. " left"
    end
    if id == "BG36_MagicItem_380" then base, value = 1, 1 + (p.essence or 0) end
    local finished
    if id == "BG35_MagicItem_920" and p.bubbleComplete then
        status, finished = "Bonus active", true
    elseif id == "BG35_MagicItem_931" or id == "BG35_MagicItem_931t" then
        local limit = id == "BG35_MagicItem_931" and 2 or 4
        local left = math.max(0, limit - (p.typewritten or 0))
        finished = left == 0
        status = finished and "Complete" or (left .. " left")
    elseif id == "BG36_MagicItem_202" then
        local used = p.warcryTurn == g.turn and (p.warcryBought or 0) or 0
        local left = math.max(0, 2 - used)
        finished = left == 0
        status = left .. (left == 1 and " free buy left" or " free buys left")
    elseif id == "BG36_MagicItem_606" then
        finished = p.tentacleTurn == g.turn
        status = finished and "Used this turn" or "1 left"
    elseif id == "BG36_MagicItem_370" then
        status = Draw.turnStatus(2 - (g.turn - (p.daggerTurn or g.turn)))
    end
    local tracker = not finished and status or nil
    return Draw.liveAbilityText(t.text, status, base, value), status, tracker
end

function Draw.spellState(g, p, d)
    local spell, m = BG.SPELLS[d.id], d.src or {}
    local text = BG.spellText(p, d.id, d.src) or spell.text or ""
    local status
    if d.lockGold then status = "Unlocks after " .. d.lockGold .. " more Gold spent"
    elseif d.lockTurn then status = "Unlocks · " .. Draw.turnStatus(d.lockTurn - g.turn)
    elseif m.openTurn then status = "Opens · " .. Draw.turnStatus(m.openTurn - g.turn)
    elseif m.expireTurn then
        status = m.expireTurn == g.turn and "Expires at end of turn" or ("Expires · " .. Draw.turnStatus(m.expireTurn - g.turn))
    end
    if d.id == "BG28_603" or d.id == "BG28_603t" then
        local a, h = 2 + (p.beetleA or 0), 2 + (p.beetleH or 0)
        text = text:gsub("2/2 Beetles", a .. "/" .. h .. " Beetles", 1)
    elseif d.id == "BG20_GEM" then
        text = ("Give a minion +%d/+%d."):format(p.gemA or 1, p.gemH or 1)
        local kwName = ({taunt = "Taunt", shield = "Divine Shield", reborn = "Reborn"})[m.gemKeyword or ""]
        if kwName then text = text .. " If it's a Quilboar, also give it " .. kwName .. "." end
    elseif spell.spellcraft and (m.craftPower or 1) > 1 then
        local k = m.craftPower
        text = text:gsub("%+(%d+)/%+(%d+)", function(a, h) return "+" .. a*k .. "/+" .. h*k end)
    end
    return Draw.liveAbilityText(text, status), status
end

