        labels = {{text = status, x = 0, z = 0, width = compact and 1.82 or 2.55,
            height = compact and .29 or .40, font = compact and .17 or .22, color = {1, .93, .68}}}})
end

function Draw.spellTimers(color, p)
    local lines = {}
    if p.majorPrizeRepeat then
        lines[#lines+1] = "Darkmoon Prize · " .. Draw.turnStatus(p.majorPrizeRepeat - game.turn)
    end
    if p.timeManagement then lines[#lines+1] = "Time Management · Next turn" end
    if p.nextChronum and p.nextChronum > 0 then lines[#lines+1] = "Next Timewarp · +" .. p.nextChronum .. " Chronum" end
    if #lines == 0 then removeTile(color, "b_spell_timers"); return end
    ensureTile(color, "b_spell_timers", {size=1,right=12.35,near=2.2,layer=6,
        labels={{text=table.concat(lines,"\n"),x=0,z=0,width=4.65,height=.39*#lines,font=.23,color=GOLD_TEXT}}})
end

local function renderControls(color, p)
    local h = heroOf(p)
    if not h then
        for _, k in ipairs(CONTROL_KEYS) do removeTile(color, k) end
        return
    end
    local recruit = game.phase == "recruit" and p.alive and not game.recruitClosed
    local act = recruit and not p.bot and not BG.skipsRecruit(game, p) and not BG.hasChoice(p)
    -- hero portrait in the hero door, Health and Armor gems on its right edge
    ensureTile(color, "hero", {url = heroArt(h), size = DOOR_H, fit = "h", right = DOOR_RIGHT, near = HERO_NEAR,
        tip = h.name .. " (" .. p.name .. ")" .. (p.alive and "" or " - eliminated") .. "\n"
            .. (p.alive and p.hp or 0) .. " Health · " .. p.armor .. " Armor · Tier " .. p.tier .. "\n"
            .. powerLine(h) .. "\n" .. Draw.powerState(game, p, h)})
    Draw.badge(color, "b_hp", Draw.hpGem(p.alive and p.hp or 0), SPOT.heroHp)
    if p.armor > 0 then Draw.badge(color, "b_armor", Draw.armorGem(p.armor), SPOT.heroArmor) else removeTile(color, "b_armor") end
    local owned = {}
    for _, id in ipairs(p.trinkets or {}) do
        local trinket = BG.trinket(id)
        if trinket then owned[trinket.kind] = trinket end
    end
    for i, kind in ipairs({"Lesser", "Greater"}) do
        local tr, spot = owned[kind], SPOT["tr" .. i]
        local key = "tr" .. i
        local tracker
        if tr then
            local description, status
            description, status, tracker = Draw.trinketState(game, p, tr)
            ensureTile(color, key, {url = trinketArt(tr), size = spot[3], right = spot[1], near = spot[2],
                preview = {url = Draw.newArt("trinket/" .. tr.id .. ".png"), ability = status and description or nil, abilityBase = tr.text, tip = not status and description or nil}})
        elseif game.trinkets and p.alive then
            local turn = i == 1 and 6 or 9
            local text = game.turn < turn and ("Offers open on turn " .. turn .. ".") or "Purchase a Trinket from its offer."
            ensureTile(color, key, {url = Draw.polish("trinkets/locked_" .. kind .. ".png"),
                size = spot[3], right = spot[1], near = spot[2], tip = kind .. " Trinket locked\n" .. text})
        else
            removeTile(color, key)
        end
        Draw.progressLabel(color, "b_trinket_progress_" .. i, tracker, spot, 1.07, true)
    end
    Draw.spellTimers(color, p)
    Draw.renderBuddy(color, p, act)
    Draw.renderCardActions(color, p, act)
    Draw.renderQuest(color, p)
    Draw.renderSecrets(color, p)
    if p.bot or not p.alive then
        for _,k in ipairs({"tierup","refresh","freeze","power","b_power_cost","b_tavern_tier","b_used","gold","endturn"}) do removeTile(color,k) end
        for i=1,10 do removeTile(color,"b_wallet_"..i) end
        return
    end
    if p.timewarpVisit and game.phase == "recruit" then
        removeTile(color, "b_tavern_tier")
        for _, k in ipairs({"tierup", "refresh", "freeze"}) do removeTile(color, k) end
    elseif game.phase == "combat" then
        ensureTile(color,"b_tavern_tier",{url=Draw.uiArt2("refined-tier/"..p.tier..".png"),
            face={r=128/138},size=1.13,right=DOOR_RIGHT-1.92,near=HERO_NEAR+1.0,layer=7,lift=.13,
            tip="Tavern Tier "..p.tier})
        -- Shop buttons are hidden during combat.
        for _, k in ipairs({"tierup", "refresh", "freeze"}) do removeTile(color, k) end
    else
        local right,near=BOB_RIGHT-1.95,BOB_NEAR+1.0
        ensureTile(color,"b_tavern_tier",{url=Draw.uiArt2("refined-tier/"..p.tier..".png"),
            face={r=128/138},size=1.18,right=right,near=near,layer=7,lift=.13,
            tip="Tavern Tier "..p.tier})
        local up = BG.upgradeCost(p)
        local T = SPOT.tierup
        local tuUrl = up and Draw.polish(string.format("tier/tu_%d_%d_%d.png", math.min(7, p.tier + 1), math.max(0, math.min(11, up)),
            (act and p.gold >= up) and 1 or 0)) or (p.tier == 7 and Draw.uiArt2("refined-tier/7.png") or Draw.polish("tier/tmax.png"))
        ensureTile(color, "tierup", {url = tuUrl, size = T[3], fit = "h", right = T[1], near = T[2], click = act and up ~= nil, action = "upgrade",
            tip = up and ("Tavern Tier " .. p.tier .. "\nUpgrade to Tavern Tier " .. (p.tier + 1) .. " (" .. up .. " Gold)" .. (p.gold < up and " - not enough Gold" or ""))
                or ("Tavern Tier " .. p.tier .. " (max)")})
        -- Refresh and Freeze right of Bob
        local rc = BG.refreshCost(p)
        local R = SPOT.refresh
        local malHp = rc > 0 and BG.malchezaarActive(game, p)
        local rfUrl = malHp and ("https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1b76cbb1671ce919cff6cd535fe3a922049fe989/hsbg/battlegrounds-multiplayer/s14-leaderboard/rf/rf_hp_" .. math.min(2, rc) .. "_" .. ((act and p.hp > rc) and 1 or 0) .. ".png")
            or Draw.uiArt2(string.format("tavern/rf_%d_%d.png", math.max(0, math.min(5, rc)), (act and p.gold >= rc) and 1 or 0))
        ensureTile(color, "refresh", {url = rfUrl,
            size = R[3], fit = "h", right = R[1], near = R[2], click = act, action = "refresh",
            tip = malHp and ("Refresh the Tavern (" .. rc .. " Health - Malchezaar, " .. (p.malLeft or 0) .. " left)") or ("Refresh the Tavern (" .. rc .. " Gold)")})
        local F = SPOT.freeze
        ensureTile(color, "freeze", {url = Draw.uiArt2(string.format("tavern/fz_%s_%d.png", p.frozen and "on" or "off", act and 1 or 0)),
            size = F[3], fit = "h", right = F[1], near = F[2],
            click = act, action = "freeze", tip = p.frozen and "Unfreeze the Tavern" or "Freeze the Tavern (keep it for next turn)"})
    end
    h=BG.powerHero(p) or h
    local hp=BG.HP[h.id]
    local active=hp and hp.active
    local cost = active and BG.powerCost(p) or nil
    local locked = active and BG.powerLock(game, p, hp)
    local state = locked and "u" or (act and not p.ready and active and p.gold >= cost and "r" or "n")
    local P = SPOT.power
    local price = cost and tostring(math.min(99, cost)) or "passive"
    local key = h.id .. "_" .. state .. "_" .. price .. ".png"
    local fallback=active and Draw.fallbackHeroPowers[h.id]
    local haveKey=Draw.recruitPowers[h.id] and Draw.HAVE_RPOW[key] or (not Draw.recruitPowers[h.id] and Draw.HAVE_POWER[key])
    if active and not haveKey and Draw.HAVE_POWER[h.id.."_n_passive.png"] then fallback=true end
    if fallback and not Draw.HAVE_POWER[h.id.."_n_passive.png"] then fallback=false end
    local medallion=Draw.recruitPowers[h.id] and Draw.recruitArt("powers/"..key) or Draw.newArt("power/"..key)
    local detail=h.id..(cost and cost~=h.cost and ("_"..price) or "")
    removeTile(color,"b_power_cost")
    if fallback then
        -- medallion with the coin cut out (normal / ready glow / used grey + padlock) and the cost coin exactly in its place
        medallion="https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1c3dbbc7887ff04e8479e3d2688070035fab0d6a/hsbg/battlegrounds-multiplayer/s14-leaderboard/hp3/"..h.id.."_"..state..".png"
        detail=h.id
        ensureTile(color,"b_power_cost",{url="https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1c3dbbc7887ff04e8479e3d2688070035fab0d6a/hsbg/battlegrounds-multiplayer/s14-leaderboard/hp3/coin/"..math.max(0,math.min(20,cost))..".png",
            face={r=1},size=P[3]*.2896,fit="h",right=P[1],near=P[2]-P[3]*.3741,layer=8,lift=.02})
    end
    local description, status = Draw.powerState(game, p, h)
    Draw.progressLabel(color, "b_power_progress", status, P, 1.96)
    local preview = {url=Draw.newArt("hero/"..detail..".png"),
            ability=status and description or nil,abilityBase=h.text,tip=not status and description or nil}
    if Draw.HSHP[h.id] then
        medallion = ((active and cost) and "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1b6d2900037f9d1bff7b816b03bf845fd26cf06c/hsbg/battlegrounds-multiplayer/s14-leaderboard/hp4/" or "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/bc1d2f6100135874c8be93eb518429bbf40455fc/hsbg/battlegrounds-multiplayer/s14-leaderboard/hp4b/") .. h.id .. "_" .. (active and state or "n") .. ".png"
        removeTile(color, "b_power_cost")
        if active and cost then
            ensureTile(color,"b_power_cost",{url="https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1c3dbbc7887ff04e8479e3d2688070035fab0d6a/hsbg/battlegrounds-multiplayer/s14-leaderboard/hp3/coin/"..math.max(0,math.min(20,cost))..".png",
                face={r=1},size=P[3]*.2896,fit="h",right=P[1],near=P[2]-P[3]*.3741,layer=8,lift=.02})
        end
        preview = {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1b6d2900037f9d1bff7b816b03bf845fd26cf06c/hsbg/battlegrounds-multiplayer/s14-leaderboard/hpcard/" .. h.id .. ".png", face = {r = 500 / 650}, size = 4.6,
            boxText = {text = description or h.text or "", base = h.text, cx = 256 / 500, cy = 467 / 650, w = 270 / 500, h = 108 / 650}, sig = description}
    end
    ensureTile(color, "power", {url = medallion, size = P[3], fit = "h", right = P[1], near = P[2],
        cw = 3.2, ch = 3.1, cz = .20, click = act and active and (not locked or aiming[color]) and true or false,
        action="power",preview=preview})
    if aiming[color] then
        ensureTile(color, "b_used", {url = Draw.uiArt2("hp_target.png"), size = P[3] * 0.72, right = P[1], near = P[2] + P[3] * 0.06,
            layer = 3, lift = 0.05})
    else
        removeTile(color, "b_used")
    end
    local second=p.secondPowerHero and BG.heroById(p.secondPowerHero)
    if second then
        local ability=BG.HP[second.id]
        local secondCost=ability and BG.powerCost(p,true)
        local usable=act and secondCost and secondCost<=p.gold and not BG.powerLock(game,p,ability,true)
        local secondText, secondStatus = Draw.powerState(game, p, second)
        local spot = {P[1] + 2.65, P[2]}
        local hs2 = Draw.HSHP[second.id]
        ensureTile(color,"power2",{url=hs2 and ("https://raw.githubusercontent.com/Jnipko488/mtg-table-data/bc1d2f6100135874c8be93eb518429bbf40455fc/hsbg/battlegrounds-multiplayer/s14-leaderboard/hp4b/" .. second.id .. "_n.png") or Draw.newArt("power/"..second.id.."_n_passive.png"),size=P[3]*.7,
            right=spot[1],near=spot[2],fit="h",click=usable and true or false,action="power2",
            preview=hs2 and {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1b6d2900037f9d1bff7b816b03bf845fd26cf06c/hsbg/battlegrounds-multiplayer/s14-leaderboard/hpcard/" .. second.id .. ".png", face = {r = 500 / 650}, size = 4.6,
                boxText = {text = secondText or second.text or "", base = second.text, cx = 256 / 500, cy = 467 / 650, w = 270 / 500, h = 108 / 650}, sig = secondText}
                or {url=Draw.newArt("hero/"..second.id..".png"),ability=secondStatus and secondText or nil,tip=not secondStatus and secondText or nil}})
        Draw.progressLabel(color, "b_power2_progress", secondStatus, spot, 1.54)
    else
        removeTile(color,"power2")
        removeTile(color,"b_power2_progress")
    end
    -- Gold like Hearthstone: an N/M pill and a row of coins in the gold tray of the board's bottom-right frame
    local G=SPOT.gold
    ensureTile(color,"gold",{url=Draw.season14Art("gold-counter.png"),face={r=246/103},size=.74,fit="h",
        right=G[1]+.95,near=G[2],tip="Gold: "..p.gold.." of "..p.maxGold,
        labels={{text=p.gold.."/"..p.maxGold,x=0,z=.012,width=1.74,height=.65,font=.40,color=GOLD_TEXT}}})
    local pips=math.min(10,math.max(p.gold,p.maxGold))
    for i=1,10 do
        local key="b_wallet_"..i
        if i<=pips then
            ensureTile(color,key,{url=Draw.season14Art(i<=p.gold and "coin.png" or "coin-spent.png"),
                face={r=95/96},size=.50,right=G[1]+2.32+(i-1)*.64,near=G[2],layer=5})
        else
            removeTile(color,key)
        end
    end
    -- End Turn in the slot on the right rail
    local E = SPOT.endturn
    local etUrl = Draw.uiArt2("et_end.png")
    if game.phase == "combat" then etUrl = Draw.uiArt2("et_combat.png")
    elseif p.ready or game.recruitClosed then etUrl = Draw.uiArt2("et_wait.png") end
    ensureTile(color, "endturn", {url = etUrl, size = E[3], right = E[1], near = E[2], cw = 3.1, ch = 1.52, click = act, action = "ready",
        tip = p.ready and "Take your turn back" or "End your turn"})
end

-- Leaderboard: every hero, best first, down the scroll on the board's left rail, Health on each.
Draw.LB3 = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/d3d2bfe205af7efdf38041c2d6f70c018ecea299/hsbg/battlegrounds-multiplayer/s14-leaderboard/lb2/"
-- The board mesh supplies the rail. Portraits and their hit areas share one
-- centerline, with the existing glow and sword marking the upcoming opponent.
function Draw.renderLeaderTile(color, i, q, h, x, near, size, opponent)
    local nextUp = q.color ~= color and opponent == q.color
    local url, face = Draw.lbTileUrl(q.hero)
    local inner = size * .78
    if i == 1 and q.alive then
        ensureTile(color, "b_lbx_crown", {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/2c40891aa33670f6cd9e9c8034d020bef8a8c637/hsbg/battlegrounds-multiplayer/s14-leaderboard/lb4/crown.png", face = {r = 244 / 215}, size = size * .46, fit = "h",
            right = x, near = near - size * .93, layer = 8, lift = .3})
    end
    if not q.alive then
        ensureTile(color, "b_lbxd" .. i, {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/aad69be76b1947479dada2deb6890b95167c71ea/hsbg/battlegrounds-multiplayer/s14-leaderboard/dim.png", face = {r = 1}, size = inner, fit = "h", right = x, near = near,
            layer = 5, lift = .06})
        ensureTile(color, "b_lbxs" .. i, {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/2c40891aa33670f6cd9e9c8034d020bef8a8c637/hsbg/battlegrounds-multiplayer/s14-leaderboard/lb4/skull.png", face = {r = 74 / 70}, size = size * .34, fit = "h",
            right = x, near = near + size * .2, layer = 8, lift = .2})
    end
    local panelUrl, panelFace = Draw.op2Top(q), {r = 504 / 672}
    local psize = 672 * Draw.OP2_K
    local pnear = math.max(-10.2 + (336 - 146) * Draw.OP2_K, math.min(10.2 - (1012 - 62) * Draw.OP2_K, near))
    ensureTile(color, "lb" .. i, {url = url, face = face, size = inner, fit = "h", right = x, near = near, layer = 4,
        preview = {url = panelUrl, face = panelFace, size = psize, right = x + 3.2 + 252 * Draw.OP2_K, near = pnear, lbPanel = q.color,
            lbTile = {x = x, near = near, size = size},
            sig = table.concat({q.color, q.hp, q.armor, q.tier or 1, q.triplesMade or 0, q.winStreak or 0, #(q.combatLog or {})}, "|")}})
    if nextUp then
        ensureTile(color, "b_lbg" .. i, {url = Draw.lbArt("lb_glow.png"), face = {r = 1}, size = size * 1.26, fit = "h",
            right = x, near = near, layer = 3})
    end
    local kind = not q.alive and "dead" or (q.color == color and "blue" or "red")
    local medal = (i >= 2 and i <= 4) and tostring(i) or ""
    local frame = "f_" .. kind .. medal .. ((nextUp and kind ~= "blue") and "s" or "") .. ".png"
    ensureTile(color, "b_lbf" .. i, {url = Draw.LB3 .. frame, face = {r = 1}, size = size * 1.4, fit = "h", right = x, near = near,
        layer = 5, lift = .12})
    if q.alive then
        local bw, bh = size * .68, size * .105
        ensureTile(color, "b_lbb" .. i, {url = Draw.lbArt("lb_bar_bg.png"), face = {r = bw / bh}, size = bh, fit = "h",
            right = x, near = near + size * .30, layer = 6, lift = .14})
        local frac = math.max(0, math.min(1, q.hp / math.max(q.maxHp or (h and h.hp) or 30, 1)))
        if frac > 0 then
            local fw, fh = (bw - .08) * frac, bh * .62
            ensureTile(color, "b_lbh" .. i, {url = Draw.lbArt("lb_bar_fill.png"), face = {r = fw / fh}, size = fh, fit = "h",
                right = x - (bw - .08) / 2 + fw / 2, near = near + size * .30, layer = 7, lift = .15})
        end
    else
        removeTile(color, "b_lbb" .. i)
    end
end
Draw.OP2 = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/83d74885dc67ff401db8ddd00f4a2ebc6d25ae79/hsbg/battlegrounds-multiplayer/s14-leaderboard/op2/"
Draw.OP2_K = 4.0 / 504          -- world units per pixel of the parchment art (504 x 1012)
function Draw.op2Top(q)
    if not q.alive then return Draw.OP2 .. "top/KELTHUZAD_dead.png" end
    local id = q.hero or ""
    if Draw.lbHeroes and Draw.lbHeroes[id] then return Draw.OP2 .. "top/" .. id .. ".png" end
    return Draw.OP2 .. "top/KELTHUZAD.png"
end
local PLURAL = {QUILBOAR = "Quilboar", UNDEAD = "Undead"}
function Draw.topTribe(q)
    local best, count = nil, 0
    for _, r in ipairs((game and game.tribes) or {}) do
        local n = 0
        for _, m in ipairs(q.board or {}) do if BG.hasRace(m, r) then n = n + 1 end end
        if n > count then best, count = r, n end
    end
    if not best then return nil, 0 end
    return PLURAL[best] or ((BG.RACE_NAME[best] or best) .. "s"), count
end
-- Hover panel for a standings entry, laid out like Battlegrounds: the header decal (hero arch on the parchment top)
-- is drawn by renderPreview; everything below is one parchment strip per section, each with its own contents
-- centred on it so TTS always draws them over the strip.
function Draw.renderOpponentPanel(color, preview)
    local q = game and game.players[preview.lbPanel]
    if not q then return end
    local L, N, lift = preview.layer or 12, preview.near, preview.lift
    local k = Draw.OP2_K
    local px = preview.right
    local function X(xp) return px + (xp - 252) * k end
    local function Z(yp) return N + (yp - 62) * k end

    -- header: gems + who is playing
    if q.alive then
        ensureTile(color, "b_preview_lbhp", {url = Draw.hpGem(q.hp), face = {r = 1}, size = .95, fit = "h",
            right = X(440), near = Z(168), layer = L + 2, lift = lift + .45})
        if (q.armor or 0) > 0 then
            ensureTile(color, "b_preview_lbar", {url = Draw.armorGem(q.armor), face = {r = 1}, size = .8, fit = "h",
                right = X(440), near = Z(66), layer = L + 2, lift = lift + .45})
        end
    end
    local h = BG.heroById and q.hero and BG.heroById(q.hero)
    Draw.hsText(color, "b_preview_lbn1", "Played by " .. (q.name or "..."), nil, X(252), Z(300) - .12, 3.2, .5, L + 1, lift + .05, {panel = false})
    -- middle strip: top minion type, tier / triples / win streak, "Combat History"
    local midH = 242 * k
    local tribe, count = Draw.topTribe(q)
    ensureTile(color, "b_preview_lbmid", {url = Draw.OP2 .. "mid.png", face = {r = 504 / 242}, size = midH, fit = "h",
        right = X(252), near = Z(519), layer = L, lift = lift})
    Draw.hsText(color, "b_preview_lbn2", tribe and (tribe .. "  x" .. tostring(count)) or "No minions yet", nil, X(252), Z(460), 3.2, .62,
        L + 2, lift + .08, {white = true, allBold = true, panel = false})
    Draw.hsText(color, "b_preview_lbn3", "Combat History", nil, X(252), Z(616), 2.6, .46, L + 2, lift + .08, {panel = false, allBold = true})
    local icon = .56
    ensureTile(color, "b_preview_lbtier", {url = Draw.uiArt2("refined-tier/" .. (q.tier or 1) .. ".png"), face = {r = 128 / 138},
        size = icon, fit = "h", right = X(120), near = Z(540), layer = L + 1, lift = lift + .12})
    ensureTile(color, "b_preview_lbtri", {url = Draw.lbArt("icon_triples.png"), face = {r = 133 / 124}, size = icon * .92, fit = "h",
        right = X(252), near = Z(540), layer = L + 1, lift = lift + .12})
    Draw.questDigits(color, "b_preview_lbtrid", tostring(q.triplesMade or 0), X(266), Z(546), icon * .5, L + 2, lift + .16)
    ensureTile(color, "b_preview_lbfire", {url = Draw.lbArt("icon_flame.png"), face = {r = 1}, size = icon * .92, fit = "h",
        right = X(384), near = Z(540), layer = L + 1, lift = lift + .12})
    Draw.questDigits(color, "b_preview_lbfired", tostring(q.winStreak or 0), X(392), Z(548), icon * .5, L + 2, lift + .16)
    -- Combat History rows (newest first)
    local rows = {{"r1", 640, 756}, {"r2", 756, 872}, {"r3", 872, 1012}}
    local myUrl, myFace = Draw.lbTileUrl(q.hero)
    for i, r in ipairs(rows) do
        local y0, y1 = r[2], r[3]
        local cy = (y0 + y1) / 2
        ensureTile(color, "b_preview_lb" .. r[1], {url = Draw.OP2 .. r[1] .. ".png", face = {r = 504 / (y1 - y0)}, size = (y1 - y0) * k,
            fit = "h", right = X(252), near = Z(cy), layer = L, lift = lift})
        local c = (q.combatLog or {})[i]
        if c then
            local rowY = 640 + (i - 1) * 116 + 48
            local ts = .6
            ensureTile(color, "b_preview_lbme" .. i, {url = myUrl, face = myFace, size = ts * .82, fit = "h",
                right = X(96), near = Z(rowY), layer = L + 1, lift = lift + .1})
            ensureTile(color, "b_preview_lbmf" .. i, {url = Draw.lbArt("lb_frame_blue.png"), face = {r = 1}, size = ts, fit = "h",
                right = X(96), near = Z(rowY), layer = L + 2, lift = lift + .12})
            local ourl, oface = Draw.lbTileUrl(c.hero)
            ensureTile(color, "b_preview_lbop" .. i, {url = ourl, face = oface, size = ts * .82, fit = "h",
                right = X(410), near = Z(rowY), layer = L + 1, lift = lift + .1})
            ensureTile(color, "b_preview_lbof" .. i, {url = Draw.lbArt("lb_frame_red.png"), face = {r = 1}, size = ts, fit = "h",
                right = X(410), near = Z(rowY), layer = L + 2, lift = lift + .12})
            local dmg = math.max(0, math.min(40, c.dmg or 0))
            if c.res == "win" and dmg > 0 then
                ensureTile(color, "b_preview_lbbu" .. i, {url = Draw.lbArt("burst/" .. dmg .. ".png"), face = {r = 1}, size = .62, fit = "h",
                    right = X(330), near = Z(rowY + 4), layer = L + 3, lift = lift + .16})
            elseif c.res == "loss" and dmg > 0 then
                ensureTile(color, "b_preview_lbbu" .. i, {url = Draw.OP2 .. "burst_red/" .. dmg .. ".png", face = {r = 1}, size = .62, fit = "h",
                    right = X(176), near = Z(rowY + 4), layer = L + 3, lift = lift + .16})
            end
        end
    end
    -- Hero Power beside the panel
    local powerId = q.alive and (q.powerHero or q.hero) or nil
    if powerId then
        local cardH = 3.1
        if Draw.HSHP[powerId] then
            local ph = BG.heroById(powerId)
            local txt = ph and (select(1, Draw.powerState(game, q, ph)) or ph.text) or ""
            local cw = cardH * 500 / 650
            local cxp, czp = X(504) + .3 + cw / 2, Z(150)
            ensureTile(color, "b_preview_lbpow", {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1b6d2900037f9d1bff7b816b03bf845fd26cf06c/hsbg/battlegrounds-multiplayer/s14-leaderboard/hpcard/" .. powerId .. ".png", face = {r = 500 / 650},
                size = cardH, fit = "h", right = cxp, near = czp, layer = L, lift = lift})
            Draw.hsText(color, "b_preview_lbpt", txt, ph and ph.text, cxp + (256 / 500 - .5) * cw, czp + (467 / 650 - .5) * cardH,
                270 / 500 * cw, 108 / 650 * cardH, L + 1, lift + .03, {panel = false, lines = 3})
        else
            ensureTile(color, "b_preview_lbpow", {url = Draw.newArt("hero/" .. powerId .. ".png"), face = {r = 300 / 430},
                size = cardH, fit = "h", right = X(504) + .3 + cardH * (300 / 430) / 2, near = Z(150), layer = L, lift = lift})
        end
    end
end
function Draw.renderLeaderboard(color)
    local st = seat(color)
    local leaders, signature = {}, {}
    local opponent = Draw.nextOpponent(color)
    if game and game.phase ~= "hero" then
        for i, q in ipairs(leaderList()) do
            leaders[i] = q
            signature[i] = table.concat({q.color, q.hero or "", q.name, q.hp, q.armor, q.alive and "alive" or (q.place or 0),
                q.tier or 1, q.triplesMade or 0, #(q.combatLog or {}), q.winStreak or 0, q.maxHp or 0, tostring(opponent)}, "|")
        end
    end
    local key = table.concat(signature, "\n")
    if st.leaderKey == key then return false end
    st.leaderKey = key
    removeTiles(color, "lb"); removeTiles(color, "b_lb")
    local rail = SPOT.lead
    local pitch = (rail.last - rail.first) / 3
    local center = (rail.first + rail.last) / 2
    if false then
        local width, length = 2.18, (#leaders - 1) * pitch + 3.0
        ensureTile(color, "b_lb_rail", {url = Draw.lbArt("lb_bar_bg.png"), face = {r = length / width},
            size = width, fit = "h", angle = 90, right = rail.right, near = center, layer = 2})
    end
    local size = rail.height
    if #leaders > 4 then
        pitch = math.min(pitch, 15.6 / (#leaders - 1))
        size = math.min(size, pitch * .86)
        center = -.75
    end
    for i, q in ipairs(leaders) do
        local near = center + (i - (#leaders + 1) / 2) * pitch
        Draw.renderLeaderTile(color, i, q, heroOf(q), rail.right, near, size, opponent)
    end
    return true
end

-- Bob stands in the top door only while recruiting; in combat the opponent's hero stands there.
function Draw.setBobShown(color, shown)
    local s, bob = seats[color], bobOf(color)
    if not s or not bob or s.bobShown == shown then return end
    s.bobShown = shown
    pcall(function() bob.setInvisibleTo(shown and {} or ALL_COLORS) end)
end

function Draw.updateTimer(color, p)
    local st = seats[color]
    if not st then return false end
    local old = tileOf(color,"b_timer")
    local turn=tileOf(color,"b_turn_number")
    local showTurn=false
    local changed=false
    local clock = SPOT.clock
    if showTurn and (not turn or turn.turn~=game.turn) then
        ensureTile(color,"b_turn_number",{size=1,right=clock[1],near=clock[2],layer=3,turn=game.turn,
            labels={{text="Turn "..game.turn,x=0,z=0,width=1.78,height=.43,font=.24,color=GOLD_TEXT,
                background={.12,.15,.19,.96}}}})
        changed=true
    elseif not showTurn and turn then removeTile(color,"b_turn_number");changed=true end
    local active = deadline and game.phase == "recruit" and p and p.alive and not p.bot
        and not p.ready and not BG.skipsRecruit(game, p) and not Draw.pendingChoice(p)
    local left = active and (deadline - os.time()) or 0
    if left <= 0 then
        if not old then return changed end
        removeTile(color, "b_timer"); removeTile(color, "b_timerbg")
        return true
    end
    if old and old.seconds==left then return changed end
    left = math.max(0, math.floor(left + .5))
    local label = left < 60 and (left .. "s") or string.format("%d:%02d", math.floor(left / 60), left % 60)
    local ink = left <= 10 and {1, .56, .39, 1} or {1, .95, .82, 1}
    if old then
        old.labels[1].text = label
        old.labels[1].color = ink
        old.seconds = left
        local button = st.buttons and st.buttons["b_timer:label:1"]
        local host = button and boardOf(color)
        if host and button.params.font_size ~= 0 then
            local ok = pcall(function() host.editButton({index = button.index, label = label, font_color = ink}) end)
            if ok then
                button.params.label = label
                button.params.font_color = ink
                return changed
            end
        end
    else
        ensureTile(color, "b_timerbg", {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/d33ef6e0463f4f169e37bcd1d7252a076ea46ca3/hsbg/battlegrounds-multiplayer/s14-leaderboard/ui/tooltip_frame.png", face = {r = 162 / 61}, size = .62, fit = "h",
            right = SPOT.endturn[1] - 2.55, near = SPOT.endturn[2], layer = 3})
        ensureTile(color, "b_timer", {size = 1, right = SPOT.endturn[1] - 2.55, near = SPOT.endturn[2], layer = 4,
            seconds = left, labels = {{text = label, x = 0, z = 0,
                width=1.32,height=.38,font=.28,color=ink,background={.235,.235,.22,1}}}})
    end
    return true
end


local renderBoard
renderBoard = function(color)
    local board = boardOf(color)
    if not board then return end
    local s = seat(color)
    if not Draw.hasLabel(board) and (s.labelWait or 0) < 30 then
        if not s.labelRetry then
            s.labelRetry = true
            Wait.time(function()
                s.labelRetry = false
                s.labelWait = (s.labelWait or 0) + 1
                if game then renderBoard(color) end
            end, 1)
        end
        return
    end
    local p = game and game.players[color]
    if p then
        if s.feedback and (s.feedback.phase ~= game.phase or s.feedback.turn ~= game.turn) then
            Draw.clearFeedback(color)
        end
        if game.phase~="recruit" or s.lastFodderTurn~=game.turn then removeTiles(color,"b_fodder") end
        renderControls(color,p)
        Draw.scheduleFodder(color,p)
        Draw.updateTimer(color,p)
        Draw.renderLeaderboard(color)
        Draw.renderAnomaly(color)
        local v = game.phase == "combat" and combatView and combatView[color]
        local foe = v and v.enemy and game.players[v.enemy]
        local fh = foe and heroOf(foe) or (v and v.result.ghostHero and BG.heroById(v.result.ghostHero))
        if v and v.result and v.result.ghost then
            ensureTile(color, "opp", {url = Draw.KT_PANEL, face = {r = 258 / 352}, size = DOOR_H * 1.12, fit = "h",
                right = BOB_RIGHT, near = BOB_NEAR + DOOR_H * .05, tip = "Kel'Thuzad (" .. (v.enemyName or "Ghost") .. ")"})
        elseif fh then
            ensureTile(color, "opp", {url = heroArt(fh), size = DOOR_H, fit = "h", right = BOB_RIGHT, near = BOB_NEAR,
                tip = fh.name .. " (" .. (foe and foe.name or v.enemyName) .. ")"
                    .. (foe and ("\n" .. foe.hp .. " Health · " .. foe.armor .. " Armor") or "")})
            if foe then Draw.badge(color, "b_opp", Draw.hpGem(foe.hp), {BOB_RIGHT + 2.18, BOB_NEAR + 1.33, 1.15})
            else removeTile(color, "b_opp") end
        else
            removeTile(color, "opp"); removeTile(color, "b_opp")
        end
        Draw.setBobShown(color, game.phase ~= "hero" and game.phase ~= "combat")
    end
    flushSeat(color)
end

local function refreshController()
    if not game then return end
    for _, color in ipairs(game.order) do
        if widgets[color] and Draw.renderLeaderboard(color) then flushSeat(color) end
    end
end

-- Bob carries no decals (v4.4): the only tier art is the Tier Up button beside him.
function Draw.bobDecals(color)
    local bob, p = bobOf(color), game and game.players[color]
    if not bob or not p then return end
    local key = tostring(p.tier) .. tostring(settings.flip) .. tostring(settings.decalFlip)
    local s = seat(color)
    if s.bobKey == key then return end
    s.bobKey = key
    -- v4.4: Bob fills his door like a hero portrait
    pcall(function() bob.setDecals({}) end)
end

