-- Hero draft on the board and a separate raised tray at each choosing player's seat.
function Draw.pendingChoice(p)
    return p and p.alive and not p.bot and BG.hasChoice(p)
end

function Draw.scheduleFodder(color,p)
    if game.phase~="recruit" or game.recruitClosed or not p.fodderPending or p.bot then return end
    local s,expected,turn=seats[color],game,game.turn
    local epoch=p.fodderEpoch
    if s.fodderTicket and s.fodderTicket.turn==turn and s.fodderTicket.epoch==epoch then return end
    local ticket={turn=turn,epoch=epoch}
    s.fodderTicket=ticket
    Wait.time(function()
        if s.fodderTicket~=ticket then return end
        s.fodderTicket=nil
        if game~=expected or game.phase~="recruit" or game.recruitClosed or game.turn~=turn or p.fodderEpoch~=epoch then return end
        local changes=BG.feedFodder(game,p,true)
        if not changes then return end
        s.lastFodderTurn=turn
        removeTiles(color,"b_fodder")
        syncSeat(color)
        for i,m in ipairs(p.board) do
            local v=changes[m.uid]
            if v then ensureTile(color,"b_fodder"..i,{size=1,right=slotRight(i,#p.board),near=ROW_WARBAND-1.8,
                layer=10,lift=tokenTop+.25,labels={{text="+"..v.a.."/+"..v.h,x=0,z=0,width=1.8,height=.49,font=.32,color={.55,1,.40}}}}) end
        end
        flushSeat(color)
        Wait.time(function()
            if game==expected and game.turn==turn and not s.fodderTicket then removeTiles(color,"b_fodder");flushSeat(color) end
        end,1.25)
    end,1.15)
end

-------------------------------------------------------------------------------
-- Quests: the gem above the hero portrait (shared with the Deity sigil), the Quest + Reward hover
-- (quest card -> progress arrow -> golden reward card, like Battlegrounds) and the turn-4 choice.
-- Every word is baked into the art in Hearthstone's fonts (TTS labels sit on dark boxes):
--   quest-card.png (frame, transparent art window) + name/<quest>.png + text/<quest>_<goal>.png on top,
--   the HearthstoneJSON painting underneath; cards/<reward>.png is a finished golden card.
Draw.questArt = function(path) return BG_QUEST_ART_BASE .. path end
Draw.QUEST_CARD = {r = 0.7143, art = {0.1288, 0.0791, 0.8878, 0.4858}, name = {0.125, 0.4866, 0.8708, 0.5699},
    text = {0.1583, 0.6622, 0.8396, 0.8601}}
Draw.REWARD_R = 0.7031
Draw.DIGIT_R = {["0"] = .5692, ["1"] = .5692, ["2"] = .5692, ["3"] = .5692, ["4"] = .5692, ["5"] = .5692,
    ["6"] = .5692, ["7"] = .5692, ["8"] = .5692, ["9"] = .5692, ["/"] = .4385}
local QUEST_TILE_KEYS = {"_art", "_name", "_text"}

function Draw.questVisible(p)
    return game and p and p.quest and p.alive and not p.bot and game.phase ~= "hero"
end
function Draw.deityVisible(p)
    return game and game.deity and p and p.alive and not p.bot
end
-- Above the hero portrait: one item sits centred; Deity + Quest sit side by side, each counter on its outer side.
Draw.heroTopOffset = 2.05
function Draw.heroTopSlot(p, which)
    local both = Draw.questVisible(p) and Draw.deityVisible(p)
    if not both then return DOOR_RIGHT, .83 end
    if which == "deity" then return DOOR_RIGHT - .62, -.86 end
    return DOOR_RIGHT + .62, .86
end

function Draw.rewardCardUrl(id) return Draw.questArt("cards/" .. id .. ".png") end
function Draw.rewardMedallion(id) return Draw.questArt("rewards/" .. id .. ".png") end
function Draw.questPainting(id) return Draw.hsjsonArt("512x/" .. id .. ".jpg") end

-- Digits ("7/45") as outlined Belwe images, centred on (right, near).
function Draw.questDigits(color, prefix, text, right, near, height, layer, lift)
    removeTiles(color, prefix)
    local step, widths = 0, {}
    for i = 1, #text do
        local c = text:sub(i, i)
        widths[i] = height * (Draw.DIGIT_R[c] or .5) * .66
        step = step + widths[i]
    end
    local x = right - step / 2
    for i = 1, #text do
        local c = text:sub(i, i)
        if Draw.DIGIT_R[c] then
            ensureTile(color, prefix .. i, {url = Draw.questArt("digits/" .. (c == "/" and "slash" or c) .. ".png"),
                face = {r = Draw.DIGIT_R[c]}, size = height, fit = "h", right = x + widths[i] / 2, near = near,
                layer = layer, lift = lift})
        end
        x = x + widths[i]
    end
end

-- The three layers that sit with the quest frame: painting under it, name and text over it.
function Draw.questCardLayers(color, key, entry, right, near, h, layer, lift)
    local C = Draw.QUEST_CARD
    local w = h * C.r
    local left, top = right - w / 2, near - h / 2
    local id = entry.quest or entry.id   -- an offer uses .quest, a chosen quest (p.quest) uses .id
    local function box(b, name, url, l, dl)
        local bw, bh = (b[3] - b[1]) * w, (b[4] - b[2]) * h
        ensureTile(color, key .. name, {url = url, face = {r = bw / bh}, size = bh, fit = "h",
            right = left + (b[1] + b[3]) / 2 * w, near = top + (b[2] + b[4]) / 2 * h, layer = l, lift = lift + dl})
    end
    box(C.art, "_art", Draw.questPainting(id), layer - 1, -.012)
    box(C.name, "_name", Draw.questArt("name/" .. id .. ".png"), layer + 1, .012)
    box(C.text, "_text", Draw.questArt("text/" .. BG.questTextKey(entry) .. ".png"), layer + 1, .012)
end
function Draw.clearQuestLayers(color, key)
    for _, k in ipairs(QUEST_TILE_KEYS) do removeTile(color, key .. k) end
end

-- Combat is resolved when the turn ends and replayed afterwards, so during the replay the gem shows the
-- progress recorded in the frame being played (each frame stores both sides' quest progress).
function Draw.questLive(color)
    if not game or game.phase ~= "combat" or not combatView then return nil end
    local v = combatView[color]
    if not v or not v.frames or #v.frames == 0 or not v.side then return nil end
    local f = v.frames[math.max(1, math.min(v.step or 1, #v.frames))]
    return f and f.quests and f.quests[v.side]
end

-- The counter never skips: when progress jumps (3 Gold spent, two minions dying at once), the shown number
-- climbs to it one step at a time. Draw.questShown[color] = {id = quest, value = number on screen}.
Draw.questShown = {}
function Draw.questStepTo(color, q, target)
    local st = Draw.questShown[color]
    if not st or st.id ~= q.id or target < st.value or q.done then
        st = {id = q.id, value = target}
        Draw.questShown[color] = st
        return target
    end
    if st.value < target and not st.ticking and Wait and Wait.time then
        st.ticking = true
        local gap = target - st.value
        Wait.time(function()
            st.ticking = false
            local p = game and game.players[color]
            local cur = p and p.quest
            if Draw.questShown[color] ~= st or not cur or cur.id ~= st.id or cur.done then return end
            st.value = st.value + 1
            Draw.renderQuest(color, p)
            flushSeat(color)
        end, math.max(.06, math.min(.22, 1.4 / gap)))
    end
    return st.value
end

function Draw.questProgressText(q, live)
    if q.done then return ((q.repeats or 0) > 0) and tostring(q.repeats + 1) or nil end
    return (live or q.progress) .. "/" .. q.goal
end

function Draw.renderQuest(color, p)
    removeTile(color, "b_quest"); removeTiles(color, "b_qnum")
    if not Draw.questVisible(p) then return end
    local right, labelX = Draw.heroTopSlot(p, "quest")
    local near = HERO_NEAR - Draw.heroTopOffset
    local q = p.quest
    local rewardId = q.reward == "BG24_Reward_321" and (p.qr and p.qr.alterFace) or q.reward
    local live = not q.done and Draw.questLive(color) or nil
    local target = live or q.progress
    local held = Draw.questShown[color]
    -- combat is already resolved when the turn ends: hold the number until the replay reaches each kill/summon
    if not live and game.phase == "combat" and held and held.id == q.id then target = math.min(target, held.value) end
    local shown = q.done and q.progress or Draw.questStepTo(color, q, target)
    local ready = shown >= q.goal
    local url, face = Draw.questArt("gem.png"), {r = .7695}
    if q.done then url, face = Draw.rewardMedallion(rewardId), {r = .9922}
    elseif ready then url, face = Draw.questArt("gem-ready.png"), {r = .7715} end
    local cardH = 4.4
    local cw = cardH * Draw.QUEST_CARD.r
    local qdef = BG.questDef(q.id)
    local progress = Draw.questProgressText(q, shown)
    ensureTile(color, "b_quest", {url = url, face = face, size = .94, fit = "h", right = right, near = near, layer = 9, lift = .35,
        -- the hover is ~2.9 card widths wide; DOOR_RIGHT - .94 card widths centres it over the hero
        preview = {url = Draw.questArt("quest-card.png"), face = {r = Draw.QUEST_CARD.r}, size = cardH,
            right = DOOR_RIGHT - cw * 0.94, near = near - .94 / 2 - cardH / 2 - .45,
            -- sig only keys the hover refresh (a tip would add a text box); the art carries every word
            sig = (qdef and qdef.name or "") .. " " .. (progress or "") .. (q.done and " done" or ""),
            quest = {entry = q, progress = q.done and "Done" or progress, reward = rewardId}}})
    if progress then
        Draw.questDigits(color, "b_qnum", progress, right + labelX + (labelX > 0 and .12 or -.12), near + .02, .40, 10, .37)
    end
end

-- Hover: painting + name + text around the frame (b_preview), the arrow with progress, the golden reward card.
function Draw.renderQuestPreview(color, preview)
    local Q = preview.quest
    local h = preview.size
    local w = h * Draw.QUEST_CARD.r
    Draw.questCardLayers(color, "b_preview_q", Q.entry, preview.right, preview.near, h, preview.layer, preview.lift)
    -- spacing measured from the Battlegrounds screenshot: arrow centred .45 card-widths past the quest card,
    -- the reward card (about the quest card's height) starting .40 card-widths after the arrow
    local arrowH = h * .46
    local arrowRight = preview.right + w / 2 + w * .45
    local arrowNear = preview.near + h * .01
    ensureTile(color, "b_preview_qarrow", {url = Draw.questArt("arrow.png"), face = {r = .7812}, size = arrowH, fit = "h",
        right = arrowRight, near = arrowNear, layer = preview.layer + 2, lift = preview.lift + .03})
    if Q.progress == "Done" then
        removeTiles(color, "b_preview_qd")
    else
        Draw.questDigits(color, "b_preview_qd", Q.progress, arrowRight - arrowH * .03, arrowNear,
            arrowH * .34, preview.layer + 3, preview.lift + .05)
    end
    local rh = h * 1.04
    ensureTile(color, "b_preview_qreward", {url = Draw.rewardCardUrl(Q.reward), face = {r = Draw.REWARD_R}, size = rh, fit = "h",
        right = arrowRight + w * .40 + rh * Draw.REWARD_R / 2, near = preview.near - h * .015,
        layer = preview.layer, lift = preview.lift})
end

function Draw.clearQuestPreview(color)
    Draw.clearQuestLayers(color, "b_preview_q")
    removeTile(color, "b_preview_qarrow"); removeTile(color, "b_preview_qreward"); removeTiles(color, "b_preview_qd")
end

-- Turn 4 choice (and Ethereal Evidence / Cosmic Reward choices).
function Draw.questPickModel(p)
    local offer = p.questOffer
    if not offer then return nil end
    local opts = {}
    for i, o in ipairs(offer.options) do
        if offer.kind == "power" then
            local h = BG.heroById(o.hero)
            if h then opts[#opts + 1] = {kind = "hero_option", index = i, power = h, text = h.power, description = h.text} end
        else
            opts[#opts + 1] = {kind = "quest", index = i, reward = o.reward, entry = o.quest and o or nil}
        end
    end
    local title = offer.kind == "quest" and "Choose a Quest" or (offer.kind == "power" and "Cosmic Reward: Discover a Hero Power"
        or "Ethereal Evidence: Choose this turn's Reward")
    local sig = {"q", game.turn, offer.kind}
    for _, o in ipairs(offer.options) do sig[#sig + 1] = (o.quest or "") .. (o.reward or o.hero or "") .. (o.goal or "") end
    return {kind = "quest", title = title, options = opts, sig = table.concat(sig, "|")}
end

function Draw.renderQuestPick(color, i, o, right, lift)
    if not o.entry then   -- a Reward on its own (Ethereal Evidence)
        local rh = Draw.CHOICE_H * 1.04
        ensureTile(color, "pick" .. i, {url = Draw.rewardCardUrl(o.reward), face = {r = Draw.REWARD_R}, size = rh, fit = "h",
            right = right, near = Draw.CHOICE_NEAR, lift = lift, layer = 8, click = true, action = "pick", kind = "quest", index = o.index})
        return
    end
    -- Hovering the quest shows its full Reward card.
    local h = Draw.CHOICE_H
    local near = Draw.CHOICE_NEAR
    local side = right > 0 and -1 or 1   -- Reward card opens toward the middle of the board
    local rw = h * Draw.REWARD_R
    ensureTile(color, "pick" .. i, {url = Draw.questArt("quest-card.png"), face = {r = Draw.QUEST_CARD.r}, size = h, fit = "h",
        right = right, near = near, lift = lift, layer = 8, click = true, action = "pick", kind = "quest", index = o.index,
        preview = {url = Draw.rewardCardUrl(o.reward), face = {r = Draw.REWARD_R}, size = h,
            right = right + side * (h * Draw.QUEST_CARD.r / 2 + rw / 2 + .25), near = near}})
    Draw.questCardLayers(color, "b_pkq" .. i, o.entry, right, near, h, 8, lift)

end


-- Board portraits for minions that had none (they showed the full card instead of the oval).
Draw.extraPortraits = {}
Draw.extraPortraits["EX1_554t"] = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/aad69be76b1947479dada2deb6890b95167c71ea/hsbg/battlegrounds-multiplayer/s14-leaderboard/tokens/EX1_554t.png"
Draw.extraPortraits["EX1_170"] = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/aad69be76b1947479dada2deb6890b95167c71ea/hsbg/battlegrounds-multiplayer/s14-leaderboard/tokens/EX1_170.png"
for _, id in ipairs({"BG31_HERO_802pt", "BG31_HERO_802pt1", "BG31_HERO_802pt1t", "BG31_HERO_802pt4", "BG31_HERO_802pt5",
        "BG31_HERO_802pt7", "BG31_HERO_801pt"}) do
    Draw.extraPortraits[id] = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/2e30aa62f7e2fce9b8d7189d7b47c088eed2849b/hsbg/battlegrounds-multiplayer/s14-starcraft/" .. id .. ".png"
end

function Draw.pickModel(color)
    local p = game and game.players[color]
    if not p or p.bot then return nil end
    if game.phase == "hero" and not p.hero then
        local opts = {}
        for index, hid in ipairs(p.heroOptions or {}) do
            local h = BG.heroById(hid)
            if h and BG.heroAvailable(game, hid) then table.insert(opts, {kind = "hero", hero = h, index = index}) end
        end
        return {kind = "hero", title = "Choose your Hero", options = opts, sig = "hero" .. table.concat(p.heroOptions or {}, ",")}
    end
    if game.phase ~= "recruit" or not p.alive then return nil end
    local visit=p.timewarpVisit
    if visit then
        local options={}
        for i,slot in ipairs(visit.slots) do
            local def=BG_TIMEWARP[slot.id]
            options[i]={kind="timewarp",id=slot.id,index=i,cost=def.cost,name=def.name,
                spell=def.kind~="minion",taken=slot.taken,canBuy=not slot.taken and def.cost<=visit.chronum}
        end
        return {kind="timewarp",title=(visit.tier==3 and "Minor Timewarp" or "Major Timewarp")..
            "  ·  "..visit.chronum.." Chronum",options=options,canPass=true,
            sig=table.concat({"timewarp",visit.turn,visit.revision,visit.chronum},":")}
    end
    if p.discover and (p.discover.kind=="activate_target" or p.discover.kind=="hero_option" and p.discover.pickTarget) then return nil end
    if p.discover then
        local opts = {}
        for index, id in ipairs(p.discover.options or {}) do
            if p.discover.showPowerPortraits then
                local h=BG.heroById(id)
                if h then opts[#opts+1]={kind="hero_option",index=index,power=h,text=h.power,description=h.text} end
            elseif p.discover.showTargets then
                local list=p[p.discover.zone] or {}
                for _,m in ipairs(list) do
                    if m.uid==id then opts[#opts+1]={kind="card",id=m.id,index=index,golden=m.golden};break end
                end
                if p.discover.zone=="hand" then
                    for _,m in ipairs(p.spellHand) do if m.uid==id then opts[#opts+1]={kind="spell",id=m.id,index=index};break end end
                end
            elseif p.discover.kind=="hero_option" and p.discover.minionChoices then
                table.insert(opts,{kind="card",id=id,index=index})
            elseif p.discover.kind=="hero_option" then
                local hero=p.discover.portraits and BG.heroById(id)
                table.insert(opts,{kind="hero_option",index=index,power=hero,
                    text=hero and hero.power or id,description=hero and hero.text or p.discover.descriptions and p.discover.descriptions[id]})
            elseif (p.discover.kind=="spell" or p.discover.timewarpMixed) and BG.SPELLS[id] then
                table.insert(opts, {kind = "spell", id = id, index = index})
            elseif p.discover.kind == "spell_mode" or p.discover.kind == "minion_mode" then
                local minion = p.discover.minionId
                table.insert(opts, {kind = "mode", text = id, id = minion or p.discover.spellId, minion = minion, index = index})
            elseif p.discover.kind == "minion_target" then
                local zone=p.discover.zone
                local targets=(zone=="tavern" or zone=="tavern_any") and p.tavern or p.board
                if zone=="tavern_any" then
                    for _,s in ipairs(p.spellShop) do
                        if s.uid==id then opts[#opts+1]={kind="spell",id=s.id,index=index}; break end
                    end
                end
                for _, m in ipairs(targets) do
                    if m.uid == id then table.insert(opts, {kind = "card", id = m.id, golden = m.golden, index = index}); break end
                end
            elseif BG_CARDS[id] then
                table.insert(opts, {kind = "card", id = id, golden = p.discover.golden and true or false, index = index,
                    gift = p.discover.gifts and p.discover.gifts[id]})
            end
        end
        return {kind = "discover", title = p.discover.label or "Discover", options = opts,
            sig = table.concat({"d", game.turn, p.discover.kind or "", p.discover.uid or "",
                table.concat(p.discover.options or {}, ","), #(p.discoverQueue or {})}, "|"),
            canPass = #opts == 0}
    end
    local questModel = Draw.questPickModel(p)
    if questModel then return questModel end
    if p.offer and p.offer.kind == "trinket" then
        local opts, affordable = {}, false
        for index, id in ipairs(p.offer.options or {}) do
            local t = BG.trinket(id)
            if t and type(t.cost) == "number" then
                table.insert(opts, {kind = "trinket", trinket = t, index = index})
                affordable = affordable or t.cost <= (p.gold or 0)
            end
        end
        return {kind = "trinket", title = p.offer.label or "Choose a Trinket", options = opts,
            sig = "t" .. table.concat(p.offer.options or {}, ",") .. "/" .. tostring(p.gold),
            canPass = not affordable}
    end
    return nil
end

function Draw.clearPicks(color)
    local s = seats[color]
    if s and s.feedback and s.feedback.shown and s.feedback.shown:sub(1, 11) == "widget:pick" then
        Draw.clearFeedback(color)
    end
    removeTiles(color, "pick"); removeTiles(color, "b_pk"); removeTile(color, "ptitle")
    removeTile(color, "skip"); removeTile(color, "dtitle"); removeTile(color, "b_choice"); removeTile(color, "b_tribes"); removeTiles(color, "b_trb")
end

