function Draw.timewarpRow(color, p, model)
    local near, lift = ROW_TAVERN, .66
    local titleZ = near - CARD_H / 2 - .58
    ensureTile(color, "dtitle", {right = 0, near = titleZ, size = 1, layer = 8, lift = lift,
        labels = {{text = p.timewarpVisit.tier == 3 and "Minor Timewarp" or "Major Timewarp",
            x = 0, z = 0, width = 5.6, height = .54, font = .37, color = GOLD_TEXT}}})
    ensureTile(color, "b_pkwallet", {url = Draw.patchArt("timewarp/chronum"), face={r=1}, size=.68,
        right=3.37,near=titleZ,layer=9,lift=lift,tip=model.title,
        labels={{text=tostring(p.timewarpVisit.chronum),x=.55,z=0,width=.64,height=.45,font=.32,color=GOLD_TEXT}}})
    ensureTile(color, "b_pksigil", {url=Draw.patchArt("timewarp/badge"),face={r=1},size=.72,
        right=-3.37,near=titleZ,layer=9,lift=lift})
    local order = {}
    for i in ipairs(model.options) do order[i] = i end
    table.sort(order, function(a, b)
        local ca, cb = model.options[a].cost or 0, model.options[b].cost or 0
        if ca ~= cb then return ca < cb end
        return a < b
    end)
    local slotOf = {}
    for pos, i in ipairs(order) do slotOf[i] = pos end
    for i, o in ipairs(model.options) do
        local right = slotRight(slotOf[i], #model.options)
        if not o.taken then
            ensureTile(color, "b_pkcoin" .. i, {url = Draw.patchArt("timewarp/chronum-" .. o.cost), face = {r = 1}, size = .56,
                right = right, near = near - .49 * UNIT_H - .62, layer = 9, lift = lift + .45,
                tip = o.canBuy and "Drag to your hand to buy" or ("Requires " .. o.cost .. " Chronum")})
        end
    end
    ensureTile(color,"skip",{size=1,right=12.38,near=near-.17,layer=9,lift=lift,
        cw=3.26,ch=.82,buttonText="Return to Tavern",buttonColor={.12,.16,.27,1},
        font=.31,click=true,action="skip",tip="Return to the Tavern. Remaining Chronum expires."})
end

-- A board transition has one bounded pulse per seat. Frames reuse the same two
-- textures so expanding/fading the effect does not reload the underlying shop.
function Draw.timewarpPulse(color, opening)
    local st, current = seats[color], game
    if not st or not boardOf(color) or settings.speed == "Instant" then return end
    local ticket = (st.warpPulse or 0) + 1
    st.warpPulse = ticket
    local function frame(i)
        if game ~= current or seats[color] ~= st or st.warpPulse ~= ticket then return end
        removeTile(color,"b_warp_pulse")
        removeTile(color,"b_warp_echo")
        if i <= 3 and game.phase == "recruit" then
            ensureTile(color,"b_warp_pulse",{url=Draw.patchArt("effects/warp"),face={r=1},
                size=({3.4,5.2,6.85})[i],right=BOB_RIGHT,near=opening and -4.35 or -3.82,
                layer=5,lift=.22})
            if i <= 2 then
                ensureTile(color,"b_warp_echo",{url=Draw.patchArt("effects/warp-echo"),face={r=1},size=2.8+i*.70,
                    right=BOB_RIGHT,near=-4.85,layer=6,lift=.30})
            end
            Wait.time(function() frame(i+1) end,.095)
        end
        flushSeat(color)
    end
    frame(1)
end

local function renderPick(color)
    local p = game and game.players[color]
    local model = p and Draw.pickModel(color) or nil
    local s = seat(color)
    local sig = model and model.sig or nil
    if s.pickSig == sig and (not model or tileOf(color, "pick1") or tileOf(color, "skip") or tileOf(color, "b_pkhide")) then return end
    local had = s.pickSig ~= nil or tileOf(color, "pick1") ~= nil or tileOf(color, "b_pkhide") ~= nil
    Draw.clearPicks(color)
    if s.pickHiddenSig ~= sig then s.pickHidden = false end
    s.pickSig = sig
    local warp = p and p.timewarpVisit
    if (warp ~= nil) ~= (s.showingTimewarp == true) then
        s.showingTimewarp = warp ~= nil
        Draw.clearFeedback(color)
        Draw.timewarpPulse(color, s.showingTimewarp)
    end
    if not model or not boardOf(color) then
        if had then flushSeat(color) end
        return
    end
    local n = #model.options
    if s.pickHidden and model.kind ~= "timewarp" then
        Draw.choiceHideButton(color, Draw.choiceLift, Draw.CHOICE_NEAR)
        Draw.updateTimer(color, p)
        flushSeat(color)
        return
    end
    if model.kind ~= "hero" then s.heroSel = nil end
    if model.kind == "hero" then
        local lift = Draw.choiceLift
        local sel = s.heroSel
        ensureTile(color, "ptitle", {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/61e4fc3f523515efad4e3ddb668e157c2a886927/hsbg/battlegrounds-multiplayer/s14-leaderboard/select/banner.png", face = {r = 900 / 200}, size = 3.0, fit = "h",
            right = 0, near = -6.4, lift = lift, layer = 8})
        local names = {}
        for _, race in ipairs(game.tribes) do names[#names + 1] = BG.RACE_NAME[race] or race end
        removeTiles(color, "b_trb")
        ensureTile(color, "b_tribes", {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/83d74885dc67ff401db8ddd00f4a2ebc6d25ae79/hsbg/battlegrounds-multiplayer/s14-leaderboard/op2/ribbon.png", face = {r = 1800 / 110}, size = .78, fit = "h",
            right = 0, near = -4.45, layer = 8, lift = lift})
        local chips, total, gap, ch = {"_label"}, 0, .22, .5
        for _, race in ipairs(game.tribes or {}) do if Draw.TRIBE_CHIP[race] then chips[#chips + 1] = race end end
        for _, k in ipairs(chips) do total = total + Draw.TRIBE_CHIP[k] * ch + gap end
        local k = math.min(1, 12.2 / math.max(.1, total - gap))
        local x = -(total - gap) * k / 2
        for i, key in ipairs(chips) do
            local w = Draw.TRIBE_CHIP[key] * ch * k
            ensureTile(color, "b_trb" .. i, {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/b430b1cdb7387af4161a58ea4648ab209cab68a8/hsbg/battlegrounds-multiplayer/s14-leaderboard/tribes/" .. key .. ".png", face = {r = Draw.TRIBE_CHIP[key]}, size = ch * k, fit = "h",
                right = x + w / 2, near = -4.45, layer = 9, lift = lift + .02})
            x = x + w + gap * k
        end
        local ph = 6.6
        local pw = ph * (340 / 410)
        local pitch = math.min(pw + .9, 31 / math.max(1, n))
        for i, o in ipairs(model.options) do
            local h = o.hero
            local right = (i - (n + 1) / 2) * pitch
            local url, face = Draw.lbPanelUrl(h.id)
            if sel == o.index then
                ensureTile(color, "b_pkglow", {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/61e4fc3f523515efad4e3ddb668e157c2a886927/hsbg/battlegrounds-multiplayer/s14-leaderboard/select/glow_green.png", face = {r = 460 / 530}, size = ph * 530 / 410, fit = "h",
                    right = right, near = .2, layer = 7, lift = lift})
            end
            local side = right > 0 and -1 or 1
            ensureTile(color, "pick" .. i, {url = url, face = face, size = ph, fit = "h", right = right, near = .2,
                lift = lift, layer = 8, click = true, action = "pick", kind = "hero", index = o.index,
                preview = {url = Draw.newArt("hero/" .. h.id .. ".png"), face = {r = 300 / 430}, size = 5.4,
                    right = right + side * (pw / 2 + 2.15), near = .2}})
        end
        ensureTile(color, "b_pkconfirm", {url = sel and "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/61e4fc3f523515efad4e3ddb668e157c2a886927/hsbg/battlegrounds-multiplayer/s14-leaderboard/select/confirm.png" or "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/61e4fc3f523515efad4e3ddb668e157c2a886927/hsbg/battlegrounds-multiplayer/s14-leaderboard/select/confirm_off.png", face = {r = 420 / 150},
            size = 1.7, fit = "h", right = 0, near = 5.0, lift = lift, layer = 8,
            click = sel ~= nil, action = "heroconfirm", cw = 3.2, ch = 1.05})
        flushSeat(color)
        return
    end
    if model.kind == "timewarp" then
        Draw.timewarpRow(color, p, model)
        Draw.updateTimer(color, p)
        flushSeat(color)
        return
    end
    local CH, CN, K = Draw.CHOICE_H, Draw.CHOICE_NEAR, Draw.CHOICE_H / CARD_H
    local lift = Draw.choiceLift
    local pitch = CH * .80
    if n >= 5 then pitch = math.min(pitch, 33 / n) end
    Draw.choiceBackdrop(color, lift, (n - 1) / 2 * pitch + CH * .42 + .6, CN - CH / 2 - 1.8, CN + CH / 2 + 2.4)
    ensureTile(color, "dtitle", {right = 0, near = CN - CH / 2 - 1.05, size = 1, layer = 9, lift = lift,
        labels = {{text = model.title, x = 0, z = 0, width = 16, height = .9, font = .62, color = GOLD_TEXT, background = CLEAR}}})
    for i, o in ipairs(model.options) do
        local right = (i - (n + 1) / 2) * pitch
        if o.kind=="quest" then
            Draw.renderQuestPick(color,i,o,right,lift)
        elseif o.kind == "card" then
            local url, face = Draw.previewCard(o)
            if not url then url, face = artFor(o.id, o.golden) end
            local gift, labels = o.gift
            if gift then
                local gw = math.min(5.6, pitch * .98)
                local gh = gw * 558 / 1024
                local top = CN + CH / 2 - .35
                local tx, tw = right + (.63 - .5) * gw, .58 * gw
                ensureTile(color, "b_pkgp" .. i, {url = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/6df43cbf4f8282530e1ca162c89a6e7ea7608caa/hsbg/battlegrounds-multiplayer/s14-leaderboard/darkgift/banner.png", face = {r = 1024 / 558}, size = gh, fit = "h",
                    right = right, near = top + gh / 2, layer = 7, lift = lift - .02})
                Draw.hsText(color, "b_pkgt" .. i, gift.title or gift.label or "Dark Gift", nil, tx, top + gh * .2, tw, gh * .3,
                    10, lift + .02, {white = true, allBold = true, panel = false})
                Draw.hsText(color, "b_pkgd" .. i, gift.description or gift.label or "", nil, tx, top + gh * .57, tw, gh * .46,
                    10, lift + .02, {white = true, panel = false, lines = 3})
            end
            ensureTile(color, "pick" .. i, {url = url, face = face or DEFAULT_FACE, size = CH, right = right, near = CN,
                layer = 8, lift = lift, click = true, action = "pick", kind = "card", index = o.index,
                gifted=gift~=nil, labels=labels})
        elseif o.kind == "spell" then
            local url = Draw.spellArt(o.id)
            local face = Draw.spellFaceFor(o.id)
            ensureTile(color, "pick" .. i, {url = url, face = face, size = CH, right = right, near = CN,
                layer = 8, lift = lift, click = true, action = "pick", kind = "spell", index = o.index})
            Draw.spellTextOver(color, "b_pkst" .. i, game.players[color], {id = o.id, spell = true}, right, CN, CH, face, 9, lift + .03)
        elseif o.kind=="hero_option" and Draw.OPTION_HP[o.text] then
            local W = CH * 500 / 650
            ensureTile(color,"pick"..i,{url="https://raw.githubusercontent.com/Jnipko488/mtg-table-data/c969a94d7d110f50d839e408133f168dd4dac075/hsbg/battlegrounds-multiplayer/s14-leaderboard/hpcard/"..Draw.OPTION_HP[o.text]..".png",face={r=500/650},size=CH,right=right,near=CN,
                lift=lift,layer=8,click=true,action="pick",kind="hero_option",index=o.index})
            Draw.hsText(color,"b_pkhp"..i,o.description or "",nil,right+(256/500-.5)*W,CN+(467/650-.5)*CH,270/500*W,108/650*CH,9,lift+.03,{panel=false})
        elseif o.kind=="hero_option" and (Draw.OPTION_CARDS[o.text] or game.players[o.text]) then
            local optCard, foe = Draw.OPTION_CARDS[o.text], game.players[o.text]
            if optCard then
                ensureTile(color,"pick"..i,{url=Draw.lbArt("options/"..optCard..".png"),face={r=optCard:find("283",1,true) and 337/495 or 221/329},
                    size=CH,right=right,near=CN,lift=lift,layer=8,click=true,action="pick",kind="hero_option",index=o.index})
            else
                local url, face = Draw.lbPanelUrl(foe.alive and foe.hero or nil)
                ensureTile(color,"pick"..i,{url=url,face=face,size=CH*.85,right=right,near=CN,lift=lift,layer=8,
                    click=true,action="pick",kind="hero_option",index=o.index,
                    labels={{text=foe.name,x=0,z=CH*.85/2+.45,width=5.6,height=.55,font=.38,color=GOLD_TEXT,background=CLEAR}}})
            end
        elseif o.kind=="hero_option" then
            if o.power then
                local url=Draw.newArt("hero/"..o.power.id..".png")
                ensureTile(color,"pick"..i,{url=url,size=CH,right=right,near=CN,lift=lift,layer=8,
                    click=true,action="pick",kind="hero_option",index=o.index})
            else
                ensureTile(color,"pick"..i,{size=1,right=right,near=CN,lift=lift,layer=8,cw=5.4,ch=2.9,
                    buttonText=o.text,buttonColor={.17,.11,.07,1},font=.36,click=true,action="pick",kind="hero_option",index=o.index,
                    labels={{text=Draw.wrap(o.description or "",26),x=0,z=2.4,width=5.6,height=1.5,font=.3,color=GOLD_TEXT,background=CLEAR}}})
            end
        elseif o.kind == "mode" then
            local url, face
            if o.minion then url, face = Draw.previewCard({id = o.id}) else url, face = Draw.spellArt(o.id), Draw.spellFaceFor(o.id) end
            ensureTile(color,"pick"..i,{url=url,face=face,size=CH,right=right,near=CN,
                layer=8,lift=lift,click=true,action="pick",kind="mode",index=o.index,
                labels={{text=Draw.wrap(o.text,28),x=0,z=CH/2+.9,width=5.8,height=1.4,font=.32,color=GOLD_TEXT,background=CLEAR}}})
        else
            local t = o.trinket
            ensureTile(color, "pick" .. i, {url = Draw.newArt("trinket/" .. t.id .. ".png"), face = {r = 300 / 430}, size = CH,
                right = right, near = CN, layer = 8, lift = lift, click = true, action = "pick", kind = "trinket", index = o.index,
                labels = {{text = t.cost .. " Gold", x = 0, z = CH / 2 + .5, width = 3, height = .6, font = .42, color = GOLD_TEXT, background = CLEAR}}})
        end
    end
    Draw.choiceHideButton(color, lift, CN + CH / 2 + (model.canPass and 3.4 or 2.4))
    Draw.updateTimer(color, p)
    if model.canPass then
        local message = n == 0 and "No options available" or "No affordable option"
        ensureTile(color, "skip", {size = 1, right = 0, near = n == 0 and Draw.CHOICE_NEAR or (Draw.CHOICE_NEAR + Draw.CHOICE_H / 2 + 1.25),
            layer = 9, lift = lift, cw = 5.4, ch = 0.85, buttonText = "Continue", buttonColor = {0.11, 0.12, 0.15, 1},
            click = true, action = "skip", tip = message})
    end
    flushSeat(color)
end

Draw.CHOICE_H, Draw.CHOICE_NEAR = 7.4, -0.9
Draw.DIM_URL = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/aad69be76b1947479dada2deb6890b95167c71ea/hsbg/battlegrounds-multiplayer/s14-leaderboard/dim.png"
-- A black, semi-transparent sheet over the whole board while a choice is open (like Battlegrounds).
-- Four strips around the choice window: TTS sorts see-through decals by camera distance, so one sheet under the
-- cards could be drawn over them. The strips never overlap the cards.
function Draw.choiceBackdrop(color, lift, halfW, top, bottom)
    local X, Z = 15.2, 10.4
    local function strip(key, x0, x1, z0, z1)
        local w, h = x1 - x0, z1 - z0
        if w <= 0 or h <= 0 then return end
        ensureTile(color, key, {url = Draw.DIM_URL, face = {r = w / h}, size = h, fit = "h", right = (x0 + x1) / 2,
            near = (z0 + z1) / 2, layer = 7, lift = lift - .1})
    end
    strip("b_pkdim1", -X, X, -Z, top)
    strip("b_pkdim2", -X, X, bottom, Z)
    strip("b_pkdim3", -X, -halfW, top, bottom)
    strip("b_pkdim4", halfW, X, top, bottom)
end
function Draw.choiceHideButton(color, lift, near)
    local s = seats[color]
    local hidden = s and s.pickHidden
    -- beside the End Turn button, clear of the hero and the cards
    ensureTile(color, "b_pkhide", {size = 1, right = 12.7, near = 1.35, layer = 9, lift = lift, cw = 2.6, ch = .78,
        buttonText = hidden and "Show choices" or "Hide", buttonColor = {.13, .09, .06, .96}, font = .3,
        click = true, action = "pickhide"})
end
function Draw.toggleChoices(color)
    local s = seats[color]
    if not s then return end
    s.pickHidden = not s.pickHidden
    s.pickHiddenSig = s.pickSig
    s.pickSig = nil
    renderPick(color)
end

