function Draw.lbArt(path) return Draw.LB_BASE .. path end
function Draw.lbTileUrl(heroId)
    if heroId and Draw.lbHeroes[heroId] then return Draw.lbArt("tile/" .. heroId .. ".png"), {r = 1} end
    local h = heroId and BG.heroById(heroId)
    return h and heroArt(h) or uiArt("bob.png"), nil
end
function Draw.lbPanelUrl(heroId)
    if heroId and Draw.lbHeroes[heroId] then return Draw.lbArt("panel/" .. heroId .. ".png"), {r = 340 / 410} end
    local h = heroId and BG.heroById(heroId)
    return h and heroArt(h) or uiArt("bob.png"), nil
end
