-- The player this seat fights next (the dead player whose ghost it fights, if any).
function Draw.nextOpponent(color)
    if not game or game.phase ~= "recruit" then return nil end
    local ok, pairs_ = pcall(BG.recruitPairings, game)
    if not ok then return nil end
    for _, pair in ipairs(pairs_ or {}) do
        local a, b = pair[1], pair[2]
        if a and a.color == color then
            if b then return b.color end
            local ghost = game.eliminated[#game.eliminated]
            return ghost and ghost.color
        elseif b and b.color == color then return a.color end
    end
    return nil
end
function Draw.renderLeaderTileOld(color, i, q, h, x, near, size)
    if q.color ~= color and Draw.nextOpponent(color) == q.color then x = x + .6 end
    local url, face = Draw.lbTileUrl(q.hero)
    if not q.alive then url, face = Draw.KT_TILE, {r = 1} end
    local inner = size * .78
    local panelUrl, panelFace = Draw.op2Top(q), {r = 504 / 672}
    local psize = 672 * Draw.OP2_K
    local pnear = math.max(-10.2 + (336 - 146) * Draw.OP2_K, math.min(10.2 - (1012 - 62) * Draw.OP2_K, near))
    ensureTile(color, "lb" .. i, {url = url, face = face, size = inner, fit = "h", right = x, near = near, layer = 4,
        preview = {url = panelUrl, face = panelFace, size = psize, right = x + 3.2 + 252 * Draw.OP2_K, near = pnear, lbPanel = q.color,
            lbTile = {x = x, near = near, size = size},
            sig = table.concat({q.color, q.hp, q.armor, q.tier or 1, q.triplesMade or 0, q.winStreak or 0, #(q.combatLog or {})}, "|")}})
    local frame = q.color == color and "lb_frame_blue.png" or (q.alive and "lb_frame_red.png" or "lb_frame_dead.png")
    ensureTile(color, "b_lbf" .. i, {url = Draw.lbArt(frame), face = {r = 1}, size = size, fit = "h", right = x, near = near,
        layer = 5, lift = .12})
    removeTile(color, "b_lbh" .. i)
    if q.alive then
        local bw, bh = size * .80, size * .13
        ensureTile(color, "b_lbb" .. i, {url = Draw.lbArt("lb_bar_bg.png"), face = {r = bw / bh}, size = bh, fit = "h",
            right = x, near = near + size * .36, layer = 6, lift = .14})
        local frac = math.max(0, math.min(1, q.hp / math.max(q.maxHp or 30, q.hp, 1)))
        if frac > 0 then
            local fw, fh = (bw - .08) * frac, bh * .62
            ensureTile(color, "b_lbh" .. i, {url = Draw.lbArt("lb_bar_fill.png"), face = {r = fw / fh}, size = fh, fit = "h",
                right = x - (bw - .08) / 2 + fw / 2, near = near + size * .36, layer = 7, lift = .15})
        end
    else
        removeTile(color, "b_lbb" .. i)
    end
end
-- The hover panel: framed portrait + Health, the Hero Power card, and the scroll (Tier, triples, streak, last combats).
function Draw.renderOpponentPanelOld(color, preview)
    local q = game and game.players[preview.lbPanel]
    if not q then return end
    local L, N, lift = preview.layer or 12, preview.near, preview.lift
    local size = preview.size
    local pw = size * (340 / 410)
    local px = preview.right

    if q.alive then
        ensureTile(color, "b_preview_lbhp", {url = Draw.hpGem(q.hp), face = {r = 1}, size = size * .27, fit = "h",
            right = px + pw * .50, near = N + size * .38, layer = L + 2, lift = lift + .03})
        if (q.armor or 0) > 0 then
            ensureTile(color, "b_preview_lbar", {url = Draw.armorGem(q.armor), face = {r = 1}, size = size * .22, fit = "h",
                right = px + pw * .50, near = N + size * .16, layer = L + 2, lift = lift + .03})
        end
    end
    -- Hero Power card
    local powerId = q.alive and (q.powerHero or q.hero) or nil
    local cardH = size * .90
    local cx = px + pw / 2 + .2 + cardH * (300 / 430) / 2
    if powerId then
        ensureTile(color, "b_preview_lbpow", {url = Draw.newArt("hero/" .. powerId .. ".png"), face = {r = 300 / 430},
            size = cardH, fit = "h", right = cx, near = N + .15, layer = L, lift = lift})
    end
    -- Scroll
    local sh = size * 1.12
    local sw = sh * (850 / 1010)
    local sx = cx + cardH * (300 / 430) / 2 + .25 + sw / 2
    ensureTile(color, "b_preview_lbscroll", {url = Draw.lbArt("scroll.png"), face = {r = 850 / 1010}, size = sh, fit = "h",
        right = sx, near = N, layer = L, lift = lift})
    local top = N - sh * .19
    local icon = sh * .13
    ensureTile(color, "b_preview_lbtier", {url = Draw.uiArt2("refined-tier/" .. (q.tier or 1) .. ".png"), face = {r = 128 / 138},
        size = icon * 1.05, fit = "h", right = sx - sw * .27, near = top, layer = L + 1, lift = lift + .02})
    ensureTile(color, "b_preview_lbtri", {url = Draw.lbArt("icon_triples.png"), face = {r = 133 / 124}, size = icon * .9, fit = "h",
        right = sx - sw * .02, near = top, layer = L + 1, lift = lift + .02})
    Draw.questDigits(color, "b_preview_lbtrid", tostring(q.triplesMade or 0), sx + sw * .05, top + icon * .22, icon * .55, L + 2, lift + .04)
    ensureTile(color, "b_preview_lbfire", {url = Draw.lbArt("icon_flame.png"), face = {r = 1}, size = icon * .9, fit = "h",
        right = sx + sw * .24, near = top, layer = L + 1, lift = lift + .02})
    Draw.questDigits(color, "b_preview_lbfired", tostring(q.winStreak or 0), sx + sw * .31, top + icon * .22, icon * .55, L + 2, lift + .04)
    -- last combats
    for i, c in ipairs(q.combatLog or {}) do
        local rn = N - sh * .02 + (i - 1) * sh * .16
        local rh = sh * .12
        local burst = Draw.lbArt("burst/" .. math.max(0, math.min(40, c.dmg or 0)) .. ".png")
        local swordX, burstX = sx - sw * .26, sx - sw * .05
        if c.res == "loss" then swordX, burstX = sx - sw * .05, sx - sw * .26 end
        if c.res ~= "tie" then
            ensureTile(color, "b_preview_lbsw" .. i, {url = Draw.lbArt("icon_sword.png"), face = {r = 1}, size = rh * .9, fit = "h",
                right = swordX, near = rn, layer = L + 1, lift = lift + .02})
        end
        ensureTile(color, "b_preview_lbbu" .. i, {url = burst, face = {r = 1}, size = rh, fit = "h",
            right = c.res == "tie" and (sx - sw * .15) or burstX, near = rn, layer = L + 2, lift = lift + .03})
        local ourl, oface = Draw.lbTileUrl(c.hero)
        ensureTile(color, "b_preview_lbop" .. i, {url = ourl, face = oface, size = rh * .82, fit = "h",
            right = sx + sw * .24, near = rn, layer = L + 1, lift = lift + .02})
        ensureTile(color, "b_preview_lbof" .. i, {url = Draw.lbArt("lb_frame_red.png"), face = {r = 1}, size = rh * 1.05, fit = "h",
            right = sx + sw * .24, near = rn, layer = L + 2, lift = lift + .03})
    end
end
-- Akazamzarak's Secrets, in a row left of the space above the hero.
local SECRET_TEXT = {
    TB_Bacon_Secrets_01 = "When one of your minions is attacked, summon a 2/3 Venomous Cobra.",
    TB_Bacon_Secrets_02 = "When one of your minions is attacked, summon three 1/1 Snakes.",
    TB_Bacon_Secrets_04 = "When one of your minions is attacked, summon a copy of it.",
    TB_Bacon_Secrets_05 = "When a friendly minion dies, summon a random minion of the same Tier.",
    TB_Bacon_Secrets_07 = "When one of your minions is attacked, give it Divine Shield.",
    TB_Bacon_Secrets_08 = "When one of your minions dies, give a random friendly minion +3/+2.",
    TB_Bacon_Secrets_10 = "When a friendly minion dies, return it to life with 1 Health.",
    TB_Bacon_Secrets_12 = "When your hero takes fatal damage, prevent it.",
    TB_Bacon_Secrets_13 = "When your turn starts, give your minions +1/+1.",
    TB_Bacon_Secrets_15 = "When a friendly minion is attacked, summon a 3/3 copy of it.",
}
function Draw.renderSecrets(color, p)
    removeTiles(color, "b_secret")
    if not p or not p.alive or not p.secrets then return end
    for i, id in ipairs(p.secrets) do
        local info = BG.SECRETS and BG.SECRETS[id]
        ensureTile(color, "b_secret" .. i, {url = Draw.lbArt("secret.png"), face = {r = 1}, size = .72, fit = "h",
            right = -1.55 - (i - 1) * .78, near = HERO_NEAR - 2.27, layer = 9, lift = .22,
            tip = "Secret: " .. (info and info.name or id) .. "\n" .. (SECRET_TEXT[id] or "")})
    end
end


