Draw.HSG_KW = {"Start of Combat","Divine Shield","Choose One","Bonus Keyword","Blood Gems","Blood Gem","Battlecry","Deathrattle",
    "Taunt","Reborn","Windfury","Venomous","Stealth","Poisonous","Magnetize","Magnetic","Avenge","Rally","Spellcraft","Discover",
    "Refreshed","Refresh","Deity","Activate","Freeze","Spellcraft"}
function Draw.hsTextStyle(text, base)
    local style = {}
    for i = 1, #text do style[i] = "r" end
    for _, kw in ipairs(Draw.HSG_KW) do
        local s = 1
        while true do
            local a, b = text:find(kw, s, true)
            if not a then break end
            for i = a, b do style[i] = "b" end
            s = b + 1
        end
    end
    if base then
        local bn, k, i = {}, 0, 1
        for n in base:gmatch("%d+") do bn[#bn + 1] = n end
        while i <= #text do
            local a, b = text:find("%d+", i)
            if not a then break end
            k = k + 1
            if bn[k] ~= text:sub(a, b) then
                for j = a, b do style[j] = "g" end
                if a > 1 and text:sub(a - 1, a - 1) == "+" then style[a - 1] = "g" end
            end
            i = b + 1
        end
    end
    return style
end

function Draw.hsPut(color, key, spec)
    if Draw.HSCAP then Draw.HSCAP[#Draw.HSCAP + 1] = spec else ensureTile(color, key, spec) end
end
function Draw.hsText(color, key, text, base, cx, cz, bw, bh, layer, lift, opts)
    if not Draw.HSCAP then removeTiles(color, key) end
    if not text or text == "" then return end
    opts = opts or {}
    local adv, style = Draw.HSG_ADV, Draw.hsTextStyle(text, base)
    if opts.white then for i = 1, #style do style[i] = style[i] == "r" and "w" or (style[i] == "b" and "v" or style[i]) end end
    if opts.allBold then for i = 1, #style do if style[i] == "r" then style[i] = "b" elseif style[i] == "w" then style[i] = "v" end end end
    local words = {}
    for a, b in text:gmatch("()%S+()") do words[#words + 1] = {a, b - 1} end
    local function cw(i, h) return (adv[text:byte(i)] or .5) * h * ((style[i] ~= "r" and style[i] ~= "w") and 1.03 or 1) end
    local h, lines = bh / (opts.lines or 2.1), nil
    for _ = 1, 14 do
        lines = {}
        local cur, sp = nil, adv[32] * h
        for _, wd in ipairs(words) do
            local ww = 0
            for i = wd[1], wd[2] do ww = ww + cw(i, h) end
            if cur and cur.w + sp + ww <= bw then cur.w = cur.w + sp + ww; cur.words[#cur.words + 1] = wd
            else cur = {w = ww, words = {wd}}; lines[#lines + 1] = cur end
        end
        if #lines * h * .95 <= bh then break end
        h = h * .9
    end
    if opts.panel ~= false then
        Draw.hsPut(color, key .. "bg", {url = opts.panel or (Draw.HSG .. "patch.png"), face = {r = (bw * 1.1) / (bh * 1.15)}, size = bh * 1.15, fit = "h",
            right = cx, near = cz, layer = layer, lift = lift})
    end
    local n, pitch = 0, h * .95
    local top = cz - (#lines - 1) * pitch / 2
    for li, ln in ipairs(lines) do
        local x, z = cx - ln.w / 2, top + (li - 1) * pitch
        for wi, wd in ipairs(ln.words) do
            if wi > 1 then x = x + adv[32] * h end
            for i = wd[1], wd[2] do
                local c, st = text:byte(i), style[i]
                local fam = (st == "g") and "b" or st
                local gw = (Draw.HSG_W[fam][c] or .5) * h
                local off = (({r = 1, b = 3, w = 4, v = 5})[fam] or 3) / 106 * h
                local root = (st == "w" or st == "v") and Draw.HSG2 or Draw.HSG
                n = n + 1
                Draw.hsPut(color, key .. "g" .. n, {url = root .. st .. "/" .. c .. ".png", face = {r = gw / h}, size = h, fit = "h",
                    right = x + gw / 2 - off, near = z, layer = layer, lift = lift + .05})
                x = x + cw(i, h)
            end
        end
    end
end
function Draw.spellTextOver(color, key, p, d, right, near, size, face, layer, lift)
    removeTiles(color, key)
    local B = Draw.spellTextBox(face)
    if not B then return end
    local text = Draw.spellCardText(p, d)
    if not text then return end
    local w = size * face.r
    local spell = BG.SPELLS[d.id]
    Draw.hsText(color, key, text, spell and spell.text, right + (B.cx - .5) * w, near + (B.cy - .5) * size, B.w * w, B.h * size, layer, lift)
end

function Draw.renderPicks()
    for _, color in ipairs(SEAT_COLORS) do if seats[color] then renderPick(color) end end
end

function Draw.hidePicks()
    for color, s in pairs(seats) do
        local had = s.pickSig ~= nil or tileOf(color, "pick1") ~= nil
        Draw.clearPicks(color)
        s.pickSig = nil
        if had then flushSeat(color) end
    end
end

function Draw.previewCard(d)
    if d.spell then return Draw.spellArt(d.id), Draw.spellFaceFor(d.id) end
    local url = onlineArt(d.id, d.golden)
    if Draw.s15MinionAsset(d.id, d.golden, "cards") then return url, Draw.s15MinionFace end
    local ratio = Draw.localDetails[d.id]
    if ratio and (not d.golden or url:sub(-4) == ".jpg") then
        return Draw.localArt .. "refined/details/" .. d.id .. ".png", {r = ratio}
    end
    if url:sub(-4) == ".jpg" then
        local packed, face = artFor(d.id, d.golden)
        return packed, face
    end
    return url, DEFAULT_FACE
end

function Draw.hoverCardRight(board, obj, info)
    local localPos = board.positionToLocal(obj.getPosition())
    local right, near = -localPos.x, localPos.z
    if settings.flip then right, near = -right, -near end
    local url, face = Draw.previewCard(info.d)
    local size = 5.2
    local width = info.oval and 2.2 or CARD_H * (info.face or DEFAULT_FACE).r
    return {url = url, face = face, size = size,
        right = right + width / 2 + size * (face or DEFAULT_FACE).r / 2 + .3, near = near,
        layer=12,lift=math.max(Draw.choiceLift+.65,localPos.y-BOARD_Y+tokenTop+1.15),
        gifted=info.d.src and info.d.src.darkGift~=nil, detailLines=math.min(12,(info.d.spell and 9 or 4)+2*#((info.d.src or {}).attachments or {})),
        spellCard=info.d.spell and info.d or nil, spellOwner=info.color}
end

function Draw.hoverWidget(color, board)
    local read, pos = pcall(function() return Player[color].getPointerPosition() end)
    if not read or not pos or not (pos.x or pos[1]) then return nil end
    local right, near = readerOf(board, pos)
    if settings.flip then right, near = -right, -near end
    if math.abs(right) > 17.5 or math.abs(near) > 15.5 then return nil end
    local key, target, best
    for k, w in pairs(widgets[color] or {}) do
        if w.preview or (w.tip and w.tip ~= "" and not w.action and not w.click) then
            local _, _, width, height = Draw.widgetSize(w)
            local dx = math.abs(right - (w.right or 0))
            local dz = math.abs(near - (w.near or 0))
            if dx <= (w.kind == "mode" and w.cw or width) / 2 and dz <= (w.kind == "mode" and w.ch or height) / 2 then
                local score = (w.layer or 1) * 10 - dx - dz
                if not best or score > best then key, target, best = k, w, score end
            end
        end
    end
    return key, target
end

function Draw.liveCardInfo(p, d)
    local lines, id, m = {}, d.id, d.src or {}
    if d.spell then
        local text = Draw.spellState(game, p, d)
        local printed = BG.SPELLS[d.id] and BG.SPELLS[d.id].text or ""
        if text ~= "" and text ~= printed then lines[#lines + 1] = text end
    elseif d.lockTier or d.lockTurn then
        lines[#lines + 1] = d.lockGold and ("Locked until you spend " .. d.lockGold .. " more Gold")
            or d.lockTier and ("Locked until Tavern Tier " .. d.lockTier)
            or ("Unlocks · " .. Draw.turnStatus(d.lockTurn - game.turn))
    end
    local k = d.golden and 2 or 1
    if id=="BG36_360" and m.paradox then
        local descriptions={[3]="After you play a card, gain Health.",[4]="Divine Shield takes multiple hits.",
            [5]="Rally adds a minion of your most common type.",[6]="Gains stats from your Battlecries.",
            [9]="Deathrattle summons a Golem with its stats."}
        lines[#lines+1]="Tier "..m.cardTier.." · "..(descriptions[m.paradox] or "")
    elseif id=="BG33_890t" and m.taughtSpell and BG.SPELLS[m.taughtSpell] then
        local spell=BG.SPELLS[m.taughtSpell]
        lines[#lines+1]=spell.name.." · "..spell.text
    elseif id == "S15_growing_ooze" then
        local a, h = BG.growingOoze(p)
        lines[#lines + 1] = "If discarded: your minions and Deity +" .. a .. "/+" .. h
    elseif id == "BG36_202" then
        local n = p.lobster or 0
        lines[#lines + 1] = "Deathrattle now gives +" .. (2 + n) * k .. "/+" .. (1 + n) * k
    elseif id=="BG36_372" then
        lines[#lines+1]=(p.hp<=15 and "Active: +" or "At 15 Health: +")..30*k.."/+"..30*k
    elseif id == "BG31_893" or id == "BG34_689" or id == "BG30_123" or id == "BG36_341" then
        lines[#lines + 1] = "Blood Gems now give +" .. (p.gemA or 1) .. "/+" .. (p.gemH or 1)
    elseif id == "BG31_816" or id == "BG31_818" or id == "BG36_181" then
        local n = (p.baller or 0) + (id == "BG36_181" and 2 or 1)
        local stats = id == "BG31_816" and ("+" .. n * k .. " Attack") or id == "BG31_818" and ("+" .. n * k .. " Health") or ("+" .. n * k .. "/+" .. n * k)
        lines[#lines + 1] = "Sell effect now gives " .. stats
    elseif id == "BG31_810" then
        local n = (4 + (m.uv or 0)) * k
        lines[#lines + 1] = "Start of Combat now gives +" .. n .. "/+" .. n
    elseif id == "BG35_602" then
        lines[#lines + 1] = "Beast summon bonus now +" .. ((game and game.season == "s15" and 2 or 3) + (m.lev or 0)) * k .. " Attack"
    elseif id == "BG31_924" or id == "BG31_925" then
        local n = math.floor((p.spellsCast or 0) / 3)
        local a, h = (id == "BG31_925" and 2 or 1) + n, 1 + n
        lines[#lines + 1] = "Current spell-scaled bonus · +" .. a * k .. "/+" .. h * k
    end
    local spell = BG.SPELLS[id]
    if id == "BG32_237" or (spell and spell.pool and string.find(spell.text, "+", 1, true)) then
        local a, h = BG.spellBonuses(p)
        if a > 0 or h > 0 or id == "BG32_237" then
            lines[#lines + 1] = "Tavern spell stat bonus · +" .. a .. "/+" .. h
        end
    end
    if m.darkGift then
        local gift = m.darkGift
        if false then lines[#lines+1] = gift.label end
        if gift.counter then lines[#lines+1] = "Current bonus · +"..(m.giftAuraA or 0).."/+"..(m.giftAuraH or 0) end
        if gift.affinity or gift.replicate then lines[#lines+1] = (2-(m.giftTicks or 0)%2).." turns left" end
        if m.darkGift.incubateTurn then lines[#lines+1]="Incubation · "..math.max(0,m.darkGift.incubateTurn-game.turn).." turns" end
    end
    if m.winterfinnerAtk then lines[#lines+1]="Winterfinner · +"..m.winterfinnerAtk.."/+"..m.winterfinnerHp end
    local printed=BG_CARDS[id] and (BG_CARDS[id].text or "") or ""
    local names={}
    for _,keyword in ipairs({"taunt","shield","reborn","windfury","venom","stealth","poison"}) do
        local name=BG.KEYWORD_NAMES[keyword]
        if m[keyword] and not printed:find(name,1,true) then names[#names+1]=name end
    end
    if #names>0 then lines[#lines+1]=table.concat(names," · ") end
    for _,line in ipairs(Draw.magneticDetails(m)) do lines[#lines+1]=line end
    if (m.buddyHats or 0) > 0 then lines[#lines + 1] = "Hats carried · " .. m.buddyHats end
    local c = BG_CARDS[id]
    if c and c.historicalStats and game and game.season then
        local atk, hp = d.golden and c.gatk or c.atk, d.golden and c.ghp or c.hp
        lines[#lines + 1] = "Season " .. game.season:sub(2) .. " · Tier " .. c.tier .. " · Base " .. atk .. "/" .. hp
    end
    if c and c.fx == "none" then lines[#lines + 1] = "Ability not scripted" end
    return #lines > 0 and table.concat(lines, "\n") or nil
end

function Draw.hoverTarget(color, board)
    local key, widget = Draw.hoverWidget(color, board)
    if key ~= "b_deity" and (not widget or widget.action ~= "pick") then
        local ok, guid = pcall(function()
            local obj = Player[color].getHoverObject()
            if obj then return obj.getGUID() end
        end)
        if ok and guid then
            local info = tokenInfo[guid]
            local obj = info and info.color == color and Draw.ready(guid)
            if obj and not obj.held_by_color and info.d then
                local tip = Draw.liveCardInfo(game.players[color], info.d)
                return "card:" .. guid .. "|" .. (tip or ""), tip, function() return Draw.hoverCardRight(board, obj, info) end
            end
            if not widget and seats[color].bob == guid and game.phase == "recruit" then
                return "bob", "Drag a minion from your warband to Bob to sell it for 1 Gold."
            end
        end
    end
    if not widget then return nil end
    local preview = widget.preview
    if not preview then return "widget:" .. key .. "|" .. widget.tip, widget.tip end
    local _, height = Draw.widgetSize(widget)
    local size = preview.size or 5.2
    local clearance = widget.action == "pick" and .65 or .33
    return "widget:" .. key .. "|" .. preview.url .. "|" .. (preview.ability or (preview.tooltip and preview.tooltip.text) or (preview.boxText and preview.boxText.text) or preview.tip or preview.sig or ""), preview.tip,
        {url = preview.url, face = preview.face, size = size, fit = "h", right = preview.right or widget.right,
         near = preview.near or widget.near - height / 2 - size / 2 - clearance, layer = 12,
         lift=math.max(Draw.choiceLift+.65,(widget.lift or .1)+.62),gifted=widget.gifted,stats=preview.stats,quest=preview.quest,ability=preview.ability,abilityBase=preview.abilityBase,tooltip=preview.tooltip,boxText=preview.boxText,lbPanel=preview.lbPanel,lbTile=preview.lbTile}
end

function Draw.clearPreview(color)
    removeTile(color, "b_preview")
    removeTiles(color, "b_preview_spelltext")
    removeTiles(color, "b_preview_lb")
    Draw.clearQuestPreview(color)
    removeTile(color, "b_preview_attack")
    removeTile(color, "b_preview_health")
    removeTiles(color, "b_preview_rules")
    removeTiles(color, "b_preview_tt")
end

function Draw.renderPreview(color, preview)
    ensureTile(color, "b_preview", preview)
    if preview.spellCard and game then
        Draw.spellTextOver(color, "b_preview_spelltext", game.players[preview.spellOwner or color], preview.spellCard,
            preview.right, preview.near, preview.size, preview.face or DEFAULT_FACE, (preview.layer or 12) + 1, (preview.lift or 1) + .03)
    end
    if preview.lbPanel then Draw.renderOpponentPanel(color, preview) end
    if preview.quest then Draw.renderQuestPreview(color, preview) end
    removeTiles(color, "b_preview_rules")
    removeTiles(color, "b_preview_tt")
    if preview.boxText then
        local b, w = preview.boxText, preview.size * (preview.face and preview.face.r or 1)
        Draw.hsText(color, "b_preview_tt3", b.text, b.base, preview.right + (b.cx - .5) * w, preview.near + (b.cy - .5) * preview.size,
            b.w * w, b.h * preview.size, preview.layer + 1, preview.lift + .03, {panel = false, lines = 3})
    end
    if preview.tooltip then
        local w = preview.size * (preview.face and preview.face.r or 1)
        Draw.hsText(color, "b_preview_tt1", preview.tooltip.title, nil, preview.right, preview.near - preview.size * .26, w * .8, preview.size * .34,
            preview.layer + 1, preview.lift + .03, {white = true, allBold = true, panel = false})
        Draw.hsText(color, "b_preview_tt2", preview.tooltip.text, nil, preview.right, preview.near + preview.size * .12, w * .84, preview.size * .5,
            preview.layer + 1, preview.lift + .03, {white = true, panel = false, lines = 2})
    end
    if preview.ability then
        Draw.hsText(color, "b_preview_rules", (preview.ability:gsub("\n", " ")), preview.abilityBase,
            preview.right, preview.near + preview.size * .197, preview.size * .505, preview.size * .295,
            preview.layer + 1, preview.lift + .03)
    end
    local stats = preview.stats
    if not stats then return end
    local face, size = preview.face or DEFAULT_FACE, preview.size
    local anchors = face.a or DEFAULT_FACE.a
    local width = size * face.r
    for i, name in ipairs({"attack", "health"}) do
        local value = stats[name]
        local changed = value > stats[i == 1 and "baseAttack" or "baseHealth"]
        local code = changed and "g" or "w"
        local labels
        local asset = i == 1 and Draw.polish("atk/" .. code .. "/" .. math.min(99, value) .. ".png")
            or "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/b430b1cdb7387af4161a58ea4648ab209cab68a8/hsbg/battlegrounds-multiplayer/s14-leaderboard/hpgem/" .. code .. "/" .. math.min(99, value) .. ".png"
        if value > 99 then
            asset = Draw.uiArt2(i == 1 and "fallback_atk.png" or "fallback_hp.png")
            labels = {{text=tostring(value),x=0,z=0,width=1.0,height=.55,font=.32,color={.46,1,.40,1}}}
        end
        ensureTile(color, "b_preview_" .. name, {url=asset,face={r=1},size=size*.23,fit="h",
            right=preview.right+(anchors[i*2-1]-.5)*width,near=preview.near+(anchors[i*2]-.5)*size,
            lift=preview.lift+.018,layer=preview.layer+1,labels=labels})
    end
end

function Draw.clearFeedback(color)
    local s = seats[color]
    if s then s.feedback = nil end
    removeTile(color, "helper")
    Draw.clearPreview(color)
end

function Draw.pollFeedback()
    if not game then return end
    for _, color in ipairs(game.order) do
        local p, s, board = game.players[color], seats[color], boardOf(color)
        if p and not p.bot and s and board then
            local h = s.feedback
            if not Player[color].seated then
                if h then Draw.clearFeedback(color); flushSeat(color) end
            else
                local key, tip, preview = Draw.hoverTarget(color, board)
                h = h or {samples = 0, phase = game.phase, turn = game.turn}
                s.feedback = h
                if key ~= h.candidate then
                    h.candidate, h.samples = key, 1
                else
                    h.samples = math.min(4, h.samples + 1)
                end
                if key ~= h.shown and h.samples >= (key and 2 or 4) then
                    h.shown = key
                    removeTile(color, "helper")
                    Draw.clearPreview(color)
                    local cardTip = type(preview) == "function"
                    if cardTip then preview = preview() end
                    if tip then
                        local wrapped = Draw.wrap(tip, cardTip and 32 or 63)
                        local count, offset = 1, 1
                        local maxLines=cardTip and preview.detailLines or 6
                        while count<=maxLines do
                            local nextLine = wrapped:find("\n", offset, true)
                            if not nextLine then break end
                            if count==maxLines then wrapped=wrapped:sub(1,nextLine-1); break end
                            offset, count = nextLine + 1, count + 1
                        end
                        ensureTile(color, "helper", {size = 1, right = cardTip and preview.right or 0,
                            near = cardTip and (preview.near + preview.size / 2 + .60) or -10.6,
                            lift = cardTip and preview.lift or 0, layer = cardTip and 13 or 8,
                            labels = {{text = wrapped, x = 0, z = 0, width = cardTip and 5 or 13, height = .52 + count * .24,
                                       font = .27, color = (cardTip and preview.gifted) and {1,.34,.35,1} or GOLD_TEXT}}})
                    end
                    if preview then Draw.renderPreview(color, preview) end
                    flushSeat(color)
                end
            end
        end
    end
end


function Draw.renderBuddy(color, p, act)
    local buddy = game.buddies and BG.buddyFor(p)
    if not buddy or not p.alive or p.bot then
        removeTile(color, "buddy"); removeTile(color, "b_buddy_price")
        return
    end
    local x = (game.trinkets or tileOf(color, "tr1") or tileOf(color, "tr2")) and -7.18 or -3.55
    local near, size = 5.71, 2.88
    local price = BG.buddyCost(game, p)
    local count = (p.buddyCount or 0) + 1
    local enabled = act and not p.ready and price ~= nil
    local ready = enabled and p.gold >= price and BG.handCount(p) + count <= BG.MAX_HAND
    local state = price == nil and "u" or (ready and "r" or "n")
    local url, face = Draw.previewCard({id = buddy.id, golden = false})
    local label = price and ("Get " .. count .. (count == 1 and " Buddy" or " Buddies") .. " for " .. price .. " Gold\nWin or tie: costs 3 less · Loss: costs 2 less")
        or "Buddy purchases complete"
    if not BG.FX[buddy.id] then label = label .. "\nThis table uses this Buddy's stats and keywords." end
    ensureTile(color, "buddy", {url = Draw.modeArt("buddy/" .. buddy.id .. "_" .. state .. ".png"),
        size = size, right = x, near = near, action = "buddy", click = enabled,
        preview = {url = url, face = face, tip = label}})
    if price then
        ensureTile(color, "b_buddy_price", {url = Draw.modeArt("coin/" .. price .. ".png"), size = .92,
            right = x, near = near - 1.27, layer = 4, lift = .64})
    else
        removeTile(color, "b_buddy_price")
    end
end

function Draw.showBuddyReward(color, id, count)
    local st, current = seat(color), game
    local button = tileOf(color, "buddy")
    if not button then return end
    local ticket = {}
    st.buddyReward = ticket
    local url, face = Draw.previewCard({id = id, golden = false})
    local function step(i)
        if seats[color] ~= st or st.buddyReward ~= ticket then return end
        removeTiles(color, "b_buddy_reward")
        if game ~= current or game.phase ~= "recruit" or i > 5 then
            st.buddyReward = nil
            flushSeat(color)
            return
        end
        local t = i / 5
        for j = 1, count do
            ensureTile(color, "b_buddy_reward" .. j, {url = url, face = face, size = 2.3 + 1.85 * t,
                right = button.right * (1 - t) + (j - (count + 1) / 2) * (1.18 + t), near = button.near + 4 * t,
                layer = 11, lift = Draw.choiceLift + .48})
        end
        flushSeat(color)
        Wait.time(function() step(i + 1) end, i == 5 and .40 or .095)
    end
    step(0)
end

function Draw.renderAnomaly(color)
    local anomaly = game.anomaly and anomalyOf(game.anomaly)
    if not anomaly then removeTile(color, "anomaly"); removeTile(color, "b_anomaly_intro"); return end
    local draft = game.phase == "hero"
    local right, near = draft and .3 or 13.10, draft and -9.26 or -5.14
    local full = Draw.modeArt("anomaly/" .. anomaly.id .. ".png")
    local face = {r = 340 / 480}
    ensureTile(color, "anomaly", {url = Draw.modeArt("icon/" .. anomaly.id .. ".png"),
        size = 1.75, right = right, near = near,
        preview = {url = full, face = face,
            size = 6.05, right = draft and 4.10 or 9.7, near = draft and -6.0 or -4.0,
            tip = anomaly.note and ("Table rule: " .. anomaly.note) or nil}})
    local p, st = game.players[color], seat(color)
    if not draft or p.hero then
        removeTile(color, "b_anomaly_intro")
    elseif not p.bot and not st.anomalyShown then
        st.anomalyShown = true
        ensureTile(color, "b_anomaly_intro", {url = full, face = face, size = 6.05,
            right = 10.6, near = -5.55, layer = 8, lift = Draw.choiceLift})
        Wait.time(function()
            if seats[color] ~= st or not tileOf(color, "b_anomaly_intro") then return end
            removeTile(color, "b_anomaly_intro")
            flushSeat(color)
        end, 3.6)
    end
end



Draw.PRELOADED, Draw.PRELIST = {}, {}
function Draw.preload(urls)
    local added = false
    for _, u in ipairs(urls) do
        if type(u) == "string" and u ~= "" and not Draw.PRELOADED[u] then
            Draw.PRELOADED[u] = true
            Draw.PRELIST[#Draw.PRELIST + 1] = {name = "pl" .. #Draw.PRELIST, url = u}
            added = true
        end
    end
    if added then pcall(function() self.UI.setCustomAssets(Draw.PRELIST) end) end
end
function Draw.preloadCore(into)
    local list = into or {}
    for _, u in ipairs({"https://raw.githubusercontent.com/Jnipko488/mtg-table-data/6df43cbf4f8282530e1ca162c89a6e7ea7608caa/hsbg/battlegrounds-multiplayer/s14-leaderboard/darkgift/banner.png","https://raw.githubusercontent.com/Jnipko488/mtg-table-data/72f0ebbe8cdfd467229fafe9e377827db95beb3c/hsbg/battlegrounds-multiplayer/s14-leaderboard/ui/dark_discovery.png","https://raw.githubusercontent.com/Jnipko488/mtg-table-data/d33ef6e0463f4f169e37bcd1d7252a076ea46ca3/hsbg/battlegrounds-multiplayer/s14-leaderboard/ui/tooltip_frame.png","https://raw.githubusercontent.com/Jnipko488/mtg-table-data/2c40891aa33670f6cd9e9c8034d020bef8a8c637/hsbg/battlegrounds-multiplayer/s14-leaderboard/lb4/crown.png","https://raw.githubusercontent.com/Jnipko488/mtg-table-data/2c40891aa33670f6cd9e9c8034d020bef8a8c637/hsbg/battlegrounds-multiplayer/s14-leaderboard/lb4/skull.png","https://raw.githubusercontent.com/Jnipko488/mtg-table-data/b578cc887ab33b2700f9e621efc55f02cc43f12b/hsbg/battlegrounds-multiplayer/s14-leaderboard/hstext/patch.png"}) do list[#list + 1] = u end
    local roots = {r = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/b578cc887ab33b2700f9e621efc55f02cc43f12b/hsbg/battlegrounds-multiplayer/s14-leaderboard/hstext/", b = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/b578cc887ab33b2700f9e621efc55f02cc43f12b/hsbg/battlegrounds-multiplayer/s14-leaderboard/hstext/", w = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/d3b9295c1f8f6e51998a1b281a63f059d0b73324/hsbg/battlegrounds-multiplayer/s14-leaderboard/hstext/", v = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/d3b9295c1f8f6e51998a1b281a63f059d0b73324/hsbg/battlegrounds-multiplayer/s14-leaderboard/hstext/"}
    for fam, root in pairs(roots) do
        for c in pairs((Draw.HSG_W and Draw.HSG_W[fam]) or {}) do
            if c ~= 32 then list[#list + 1] = root .. fam .. "/" .. c .. ".png" end
        end
    end
    for c = 48, 57 do list[#list + 1] = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/b578cc887ab33b2700f9e621efc55f02cc43f12b/hsbg/battlegrounds-multiplayer/s14-leaderboard/hstext/g/" .. c .. ".png" end
    list[#list + 1] = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/b578cc887ab33b2700f9e621efc55f02cc43f12b/hsbg/battlegrounds-multiplayer/s14-leaderboard/hstext/g/43.png"
    if not into then Draw.preload(list) end
end
function Draw.preloadGame()
    -- One download per game, when the hero offers exist: every card the lobby can show. A single setCustomAssets call
    -- avoids the mid-game hitches that repeated calls caused.
    if not game or Draw.preloadGameRef == game then return end
    local offered = false
    for _, p in pairs(game.players or {}) do if p.heroOptions and #p.heroOptions > 0 then offered = true end end
    if not offered then return end
    Draw.preloadGameRef = game
    local list = {}
    Draw.preloadCore(list)
    for _, p in pairs(game.players or {}) do
        for _, hid in ipairs(p.heroOptions or {}) do
            if Draw.HSHP and Draw.HSHP[hid] then
                list[#list + 1] = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1b6d2900037f9d1bff7b816b03bf845fd26cf06c/hsbg/battlegrounds-multiplayer/s14-leaderboard/hpcard/" .. hid .. ".png"
                for _, st in ipairs({"n", "r", "u"}) do list[#list + 1] = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/1b6d2900037f9d1bff7b816b03bf845fd26cf06c/hsbg/battlegrounds-multiplayer/s14-leaderboard/hp4/" .. hid .. "_" .. st .. ".png" end
            end
        end
    end
    for id in pairs(game.allowed or game.pool or {}) do
        local s15 = Draw.s15MinionAsset(id, false, "ovals")
        if s15 then
            list[#list + 1] = s15
            list[#list + 1] = Draw.s15MinionAsset(id, false, "cards")
            list[#list + 1] = Draw.s15MinionAsset(id, true, "ovals")
            list[#list + 1] = Draw.s15MinionAsset(id, true, "cards")
        end
        if Draw.HSOVAL and Draw.HSOVAL[id] then list[#list + 1] = "https://raw.githubusercontent.com/Jnipko488/mtg-table-data/49ee3940f28cd2456e2a0b36adc91ed3a314ca4f/hsbg/battlegrounds-multiplayer/s14-leaderboard/ov2/n/" .. id .. ".png" end
    end
    for id, sp in pairs(BG.SPELLS or {}) do
        if Draw.s15SpellPrices[id] then
            if game.season == "s15" then
                list[#list + 1] = Draw.spellArt(id)
                if sp.pool then
                    for price = 0, sp.cost do list[#list + 1] = Draw.shopSpellArt(id, price) end
                end
            end
        elseif sp.pool then
            list[#list + 1] = Draw.spellArt(id)
            list[#list + 1] = Draw.shopSpellArt(id, sp.cost)
        end
    end
    if Draw.fxUrls then for _, u in ipairs(Draw.fxUrls()) do list[#list + 1] = u end end
    printToAll("Downloading Hearthstone Cards for better Performance. Please wait.", {1, 0.85, 0.4})
    Draw.preload(list)
    Wait.condition(function() printToAll("Hearthstone card preload finished.", {0.6, 1, 0.6}) end,
        function() local ok, loading = pcall(function() return self.UI.loading end); return not ok or not loading end, 180)
end
local function renderAll()
    if game then
        pcall(Draw.preloadGame)
        for _, color in ipairs(game.order) do renderBoard(color); syncSeat(color); Draw.bobDecals(color) end
    end
    Draw.renderPicks()
end

