-- tables: spawn / remove boards and Bob
function Draw.removeTable()
    for _, tag in ipairs({CARD_TAG, BOB_TAG, BOARD_TAG, UI_TAG}) do
        for _, obj in ipairs(getObjectsWithTag(tag)) do pcall(function() obj.destruct() end) end
    end
    seats, tokenInfo, aiming, pendingDrop = {}, {}, {}, {}
    Draw.epoch = Draw.epoch + 1
    widgets = {[SET] = widgets[SET]}
end

local function spawnBob(color, board)
    local s = scaleCache.bob or 1
    local pos = boardPoint(board, BOB_RIGHT, BOB_NEAR, 0.2)
    local url = Draw.uiArt2("bob.png")   -- Bob in the same arch frame as the heroes, sized to his door
    local guid
    local obj = spawnObjectData({
        data = {
            Name = "Custom_Token", Nickname = "Bob the Bartender",
            Description = "Drag a minion from your warband up to the tavern (or onto Bob) to sell it for 1 Gold.",
            Transform = {posX = 0, posY = 0, posZ = 0, rotX = 0, rotY = 0, rotZ = 0, scaleX = s, scaleY = s, scaleZ = s},
            Tags = {BOB_TAG}, Memo = color, Locked = true, Hands = false, Tooltip = false,
            ColorDiffuse = {r = 1, g = 1, b = 1},
            CustomImage = {ImageURL = url, ImageSecondaryURL = "", ImageScalar = 1.0, WidthScale = 0.0,
                CustomToken = {Thickness = 0.25, MergeDistancePixels = 15.0, StandUp = false, Stackable = false}},
        },
        position = pos, rotation = cardRotation(board),
        callback_function = function()
            local st = seats[color]
            if not st or st.bob ~= guid then return end
            Draw.measureToken(guid, "bob", BOB_SIZE, function()
                if seats[color] ~= st or st.bob ~= guid then return end
                Draw.setBobShown(color, game and game.phase ~= "hero" and game.phase ~= "combat")
            end)
        end,
    })
    if obj then
        local st = seat(color)
        guid = obj.getGUID()
        st.bob = guid
        st.bobShown = nil
        -- Bob only stands in his door while recruiting (hidden for the hero draft and in combat)
        if game and (game.phase == "hero" or game.phase == "combat") then Draw.setBobShown(color, false) end
    end
end

function Draw.setLauncherLabel(label, tooltip)
    local launcher = getObjectFromGUID(LAUNCHER_GUID)
    if launcher then launcher.call("bgSetLabel", {label = label, tooltip = tooltip or ""}) end
end
local IDLE_LABEL = "Play Hearthstone Battlegrounds"

local function showError(msg)
    local text = tostring(msg or "unknown error")
    text = text:gsub("^[%w_%-%. ]*:%(%d+,[%d%-]+%):%s*", ""):gsub("^[%w_%-%. ]*:%d+:%s*", "")
    startError = text
    broadcastToAll("Battlegrounds problem: " .. startError, {1, 0.45, 0.35})
    if settingsHost then pcall(renderSettings) end
    pcall(function() Draw.setLauncherLabel(IDLE_LABEL, "Last error: " .. startError) end)
end

local function guard(name, fn, ...)
    local args = {...}
    local ok, err = pcall(function() return fn(table.unpack(args)) end)
    if not ok then showError(name .. ": " .. tostring(err)) end
    return ok
end

local function activeTargets()
    local targets = {}
    for _, s in ipairs(SEATS) do
        local mat = getObjectFromGUID(s.guid)
        if mat then
            local c = mat.getPosition()
            if c.y > -20 then
                local b = mat.getBounds()
                local surface = math.max(c.y, b.center.y + b.size.y / 2)
                table.insert(targets, {color = s.color, position = {c.x, surface + 0.125, c.z}, rotation = {0, s.yaw, 0}})
            end
        end
    end
    if #targets >= 2 then return targets, false end
    local home = {}
    for _, s in ipairs(SEATS) do
        if s.home then table.insert(home, {color = s.color, position = s.home, rotation = {0, s.yaw, 0}}) end
    end
    if #home >= 2 then return home, true end
    return targets, false
end

local tableReady = false
local function spawnTable(targets, done)
    Draw.removeTable()
    local pending, spawned = 0, {}
    local epoch = Draw.epoch
    for _, t in ipairs(targets) do
        pending = pending + 1
        local color = t.color
        local obj = spawnObjectJSON({
            json = BOARD_JSON, position = t.position, rotation = t.rotation, sound = false,
            callback_function = function(board)
                if Draw.epoch ~= epoch then return end
                pcall(function()
                    board.addTag(BOARD_TAG)
                    board.setName("Battlegrounds - " .. color)
                    board.setLock(true)
                end)
                pending = pending - 1
            end,
        })
        if obj then
            seat(color).board = obj.getGUID()
            seat(color).phase = nil
            table.insert(spawned, color)
        else
            pending = pending - 1
        end
    end
    if #spawned == 0 then error("TTS did not spawn any Battlegrounds board (spawnObjectJSON returned nil).") end
    local function finish(ok)
        if Draw.epoch ~= epoch then return end
        for _, t in ipairs(targets) do
            local board = boardOf(t.color)
            if board then spawnBob(t.color, board) end
        end
        done(ok)
    end
    local function labelsReady()
        for _, color in ipairs(spawned) do
            local board = boardOf(color)
            if not board or not Draw.hasLabel(board) then return false end
        end
        return true
    end
    Wait.condition(function() finish(true) end,
        function() return Draw.epoch ~= epoch or (pending <= 0 and labelsReady()) end, 30,
        function() finish(false) end)
end

-------------------------------------------------------------------------------
-- flow
local beginRecruit, startCombat
local lastResults = nil

function Draw.openRecruitSeat(color, current, turn, retries)
    if game ~= current or current.phase ~= "recruit" or current.turn ~= turn then return end
    local ready = boardOf(color)
    if ready then
        -- A decoration or a late board label must never prevent the shop tokens from spawning.
        local ok, synced = pcall(syncSeat, color)
        local drawn = pcall(renderBoard, color)
        if ok and synced and drawn then
            local st, p = seats[color], current.players[color]
            local complete = true
            for _, minion in ipairs(p.tavern) do
                if not Draw.ready(st.tokens["u" .. minion.uid]) then complete = false; break end
            end
            if complete then return end
        end
    end
    if retries > 0 then
        Wait.time(function() Draw.openRecruitSeat(color, current, turn, retries - 1) end, .45)
    end
end

beginRecruit = function()
    pcall(Draw.hidePicks)
    BG.beginRecruit(game, function(stage, color, err)
        print("Battlegrounds " .. stage .. " (" .. color .. "): " .. tostring(err))
    end)
    local secs = turnSeconds()
    deadline = secs and (os.time() + secs) or nil
    drainEvents()
    local current, turn = game, game.turn
    for _, color in ipairs(current.order) do Draw.openRecruitSeat(color, current, turn, 6) end
    pcall(Draw.renderPicks)
end

function Draw.clearDamage(color)
    removeTiles(color, "b_score_")
end

function Draw.scoreNumber(color, key, number, right, near, impact)
    local value = tostring(number)
    if number <= 99 then
        local art = impact and ("sp/" .. math.max(1, number) .. ".png") or ("st/w/" .. number .. ".png")
        ensureTile(color, key, {url = Draw.uiArt2(art), size = impact and 2.65 or 1.85,
            right = right, near = near, layer = 7, lift = .73})
    else
        ensureTile(color, key, {size = 1.6, right = right, near = near, layer = 7, lift = .73,
            labels = {{text = value, x = 0, z = 0, width = 2, height = .8, font = .6, color = GOLD_TEXT}}})
    end
end

function Draw.damageSequence(replay, complete, gap)
    local hasHit = false
    for _, v in pairs(replay) do if v.result.winner ~= 0 then hasHit = true; break end end
    if not hasHit then Wait.time(complete, .6); return end
    local current = 0
    local function animate()
        if combatView ~= replay or not game or game.phase ~= "combat" then return end
        for color, v in pairs(replay) do
            local result = v.result
            if result.winner ~= 0 then
                Draw.clearDamage(color)
                local mine = result.winner == v.side
                local fromX, fromZ = mine and DOOR_RIGHT or BOB_RIGHT, mine and HERO_NEAR or BOB_NEAR
                local toX, toZ = mine and (BOB_RIGHT + 2.18) or SPOT.heroHp[1],
                    mine and (BOB_NEAR + 1.33) or SPOT.heroHp[2]
                local parts = result.parts
                if current <= 5 then
                    local total = parts.base
                    local row = mine and ROW_WARBAND or ROW_TAVERN
                    for i, tier in ipairs(parts.tiers) do
                        local ease = math.max(0, math.min(1, current * .32 - (i - 1) * .085))
                        local x = slotRight(i, #parts.tiers)
                        if ease < 1 then
                            ease = ease * ease * (3 - 2 * ease)
                            ensureTile(color, "b_score_t" .. i, {url = Draw.uiArt2("refined-tier/" .. tier .. ".png"),
                                size = .92, layer = 7, lift = .70, right = x + (fromX - x) * ease,
                                near = (row - 1.36) + (fromZ - row + 1.36) * ease})
                        else
                            total = total + tier
                        end
                    end
                    Draw.scoreNumber(color, "b_score_total", total, fromX, fromZ)
                else
                    local amount = math.min(result.damage, v.cap)
                    local ease = math.min(1, (current - 6) / 4)
                    ease = ease * ease
                    local x = fromX + (toX - fromX) * ease
                    local z = fromZ + (toZ - fromZ) * ease - .63 * math.sin(math.pi * ease)
                    Draw.scoreNumber(color,"b_score_total",amount,x,z,current==10)
                    if current==10 then Draw.combatEffect(color,v,"hero-impact",toX,toZ,3.0,true) end
                end
                flushSeat(color)
            end
        end
        if current == 10 then complete(true); return end
        current = current + 1
        Wait.time(function()
            if not guard("combat damage", animate) then complete() end
        end, current == 1 and .24 or (current == 6 and .29 or .094))
    end
    Wait.time(function() if not guard("combat damage", animate) then complete() end end, gap)
end

local function finishCombat(showImpact)
    local current = game
    local replay = combatView
    local over=BG.applyCombat(current)
    if over then
        for _,player in pairs(current.players) do
            if player.profileKey and #player.board>0 then lastWarbands[player.profileKey]=BG.copy(player.board) end
        end
        for _,result in ipairs(current.eliminated or {}) do
            local player=current.players[result.color]
            if player and player.profileKey and #result.board>0 then lastWarbands[player.profileKey]=BG.copy(result.board) end
        end
    end
    lastResults = nil
    drainEvents()
    local function advance()
        if game ~= current then return end
        for color in pairs(replay or {}) do
            Draw.clearDamage(color)
            removeTiles(color,"b_combat_")
        end
        combatView, busy = nil, false
        game.phase = over and "over" or "recruit-wait"
        if over then
            deadline = nil
            renderAll()
            pcall(Draw.setLauncherLabel, IDLE_LABEL, "Host only. Open the Battlegrounds settings.")
        else
            beginRecruit()
        end
    end
    if showImpact and replay then
        -- Apply armor and Health at impact while the final warbands are still displayed.
        for color, v in pairs(replay) do
            if over then
                local mine = current.players[color]
                local enemy = v.enemy and current.players[v.enemy]
                if mine then
                    Draw.badge(color, "b_hp", Draw.hpGem(math.max(0, mine.hp)), SPOT.heroHp)
                    if mine.armor <= 0 then removeTile(color, "b_armor") end
                end
                if enemy then Draw.badge(color, "b_opp", Draw.hpGem(math.max(0, enemy.hp)), {BOB_RIGHT + 2.18, BOB_NEAR + 1.33, 1.15}) end
                flushSeat(color)
            else
                renderBoard(color)
            end
        end
        Wait.time(function() guard("combat cleanup", advance) end, .52)
    else
        advance()
    end
end

function Draw.combatToken(color,uid)
    if not uid then return nil end
    local obj=tokenFor(color,"c"..uid) or tokenFor(color,"e"..uid)
    return Draw.ready(Draw.safeGUID(obj))
end

function Draw.combatEffect(color,v,art,right,near,size,deferFlush)
    v.effect=(v.effect or 0)+1
    local ticket=v.effect
    removeTile(color,"b_combat_ripple")
    ensureTile(color,"b_combat_effect",{url=Draw.season14Art("effects/"..art..".png"),
        face={r=1},size=size,right=right,near=near,layer=14,lift=tokenTop+.24})
    local texture = art == "strike" and "impact" or (art == "divine-shield" and "shield" or "summon")
    ensureTile(color,"b_combat_flash",{url=Draw.patchArt("effects/"..texture),face={r=1},
        size=size*1.12,right=right,near=near,layer=15,lift=tokenTop+.29})
    if not deferFlush then flushSeat(color) end
    local function current()
        return combatView and combatView[color]==v and v.effect==ticket
    end
    Wait.time(function()
        if not current() then return end
        removeTile(color,"b_combat_flash")
        ensureTile(color,"b_combat_ripple",{url=Draw.patchArt("effects/"..(art=="strike" and "ripples" or texture)),
            face={r=1},size=size*1.48,right=right,near=near,layer=13,lift=tokenTop+.22})
        flushSeat(color)
    end,.08)
    Wait.time(function()
        if current() then
            removeTile(color,"b_combat_effect")
            removeTile(color,"b_combat_flash")
            removeTile(color,"b_combat_ripple")
            flushSeat(color)
        end
    end,.27)
end

function Draw.playCombatEffect(color,v,f,prior,deferFlush)
    local fx=f.fx
    local art=(fx=="attack" and "strike") or (fx=="shield_break" and "divine-shield")
        or (fx=="deity_summon" and "deity") or (fx=="reborn" and "reborn")
        or (fx=="defeat" and "strike") or (fx=="start_of_combat" and "deity")
    if not art then return end
    local uid=f.effectTarget or f.tu or f.au
    if not uid then return end
    for _,source in ipairs({f,prior}) do
        local own,enemy=source.a,source.b
        if v.side==2 then own,enemy=enemy,own end
        for row,list in ipairs({own,enemy}) do
            for i,m in ipairs(list) do
                if m.u==uid then
                    local size=fx=="deity_summon" and 3.6 or (fx=="defeat" and 2 or 2.65)
                    Draw.combatEffect(color,v,art,slotRight(i,#list),row==1 and ROW_WARBAND or ROW_TAVERN,size,deferFlush)
                    return true
                end
            end
        end
    end
end

function Draw.nudgeAttack(color,au,tu,windup)
    local a,t=Draw.combatToken(color,au),Draw.combatToken(color,tu)
    if not a or not t then return false end
    local ai,ti=tokenInfo[Draw.safeGUID(a)],tokenInfo[Draw.safeGUID(t)]
    if ai then ai.combatHome=nil end
    local moved=pcall(function()
        local p,q=a.getPosition(),t.getPosition()
        local dx,dz=q.x-p.x,q.z-p.z
        if windup then
            a.setPositionSmooth({p.x-dx*.12,p.y+.24,p.z-dz*.12},false,false)
        else
            a.setPositionSmooth({p.x+dx*.85,p.y+.36,p.z+dz*.85},false,true)
            if ti then ti.combatHome=nil end
            t.setPositionSmooth({q.x+dx*.055,q.y+.07,q.z+dz*.055},false,true)
        end
    end)
    return moved
end

local function healthCeilings(frames, final)
    local limits = {}
    local function collect(frame)
        for _, side in ipairs({frame.a, frame.b}) do
            for _, m in ipairs(side) do limits[m.u] = math.max(limits[m.u] or 0, m.h) end
        end
    end
    for _, f in ipairs(frames) do collect(f) end
    collect(final)
    return limits
end

startCombat = function()
    if busy or not game or game.phase ~= "recruit" then return end
    busy = true
    deadline = nil
    aiming = {}
    if not game.recruitClosed then
        local current, counts = game, {}
        for _, color in ipairs(current.order) do
            local p = current.players[color]
            if p.alive and not p.bot then counts[color] = BG.handCount(p) end
        end
        BG.closeRecruit(current, true)
        drainEvents()
        local drawn, needsChoice = false, false
        for color, count in pairs(counts) do
            local p = current.players[color]
            if BG.handCount(p) ~= count then drawn = true; syncSeat(color) end
            if Draw.pendingChoice(p) then needsChoice = true end
        end
        if drawn or needsChoice then for color in pairs(counts) do renderBoard(color) end end
        if needsChoice then
            Draw.renderPicks()
            busy = false
            return
        end
        if drawn then
            Wait.time(function()
                if game ~= current or game.phase ~= "recruit" then return end
                busy = false
                guard("combat after turn end", startCombat)
            end, .72)
            return
        end
    end
    Draw.hidePicks()
    local step = SPEED_STEP[settings.speed]
    local results = BG.endRecruit(game, {fast = step == 0})
    lastResults = results
    drainEvents()
    local replay, cap = {}, BG.damageCap(game)
    combatView = replay
    local longest = 0
    for _, r in ipairs(results) do
        local A, B = game.players[r.a], r.b and game.players[r.b]
        if not A.bot or B and not B.bot then
            local frames = r.frames
            if #frames == 0 then frames = {r.final}
            else frames[#frames + 1] = r.final end
            local maxhp = healthCeilings(frames, r.final)
            local function view(player, foe, side)
                if not player or player.bot then return end
                replay[player.color] = {frames = frames, step = 1, side = side, maxhp = maxhp, result = r,
                    cap = cap, enemy = foe and foe.color, enemyName = foe and foe.name or r.bName}
            end
            view(A, B, 1)
            view(B, A, 2)
            longest = math.max(longest, #frames)
        end
    end
    renderAll()
    local function stillPlaying()
        return combatView == replay and game and game.phase == "combat"
    end
    local function complete(impact)
        if not stillPlaying() or not game.pending then return end
        if not guard("combat end", finishCombat, impact) then busy = false end
    end
    if longest<=1 then Draw.damageSequence(replay,complete,.62); return end
    if step==0 then
        local function showKeyFrame(i)
            if not stillPlaying() then return end
            for color,v in pairs(replay) do
                local f=v.frames[i]
                if f then
                    local prior=v.frames[math.max(1,v.step)]
                    v.step=i
                    syncSeat(color)
                    Draw.playCombatEffect(color,v,f,prior,true)
                    Draw.renderCardActions(color,game.players[color],false)
                    Draw.renderQuest(color,game.players[color])
                    flushSeat(color)
                end
            end
            if i<longest then Wait.time(function() showKeyFrame(i+1) end,.34)
            else Draw.damageSequence(replay,complete,.24) end
        end
        showKeyFrame(1)
        return
    end
    local i = 1
    local function playFrame()
        if not stillPlaying() then return end
        i = i + 1
        local move = false
        for color, v in pairs(replay) do
            local nextFrame = v.frames[i]
            if nextFrame and nextFrame.au and nextFrame.tu then
                if Draw.nudgeAttack(color,nextFrame.au,nextFrame.tu,true) then move=true end
            end
        end
        local function settle()
            if not stillPlaying() then return end
            for color, v in pairs(replay) do
                local nextFrame=v.frames[i]
                if nextFrame then
                    local priorFrame=v.frames[v.step]
                    local prior=priorFrame.sacrifices
                    local n=nextFrame.sacrifices and nextFrame.sacrifices[v.side]
                    v.step=i
                    syncSeat(color)
                    local hasEffect = Draw.playCombatEffect(color,v,nextFrame,priorFrame,true)
                    local deityChanged = n and n~=(prior and prior[v.side])
                    local questChanged = (nextFrame.quests and nextFrame.quests[v.side]) ~= (priorFrame.quests and priorFrame.quests[v.side])
                    if questChanged then Draw.renderQuest(color,game.players[color]) end
                    hasEffect = hasEffect or questChanged
                    if deityChanged then Draw.renderCardActions(color,game.players[color],false) end
                    if hasEffect or deityChanged then flushSeat(color) end
                end
            end
            if i < longest then
                Wait.time(function()
                    if not guard("combat frame", playFrame) then complete() end
                end, move and step * .52 or step * .66)
            else
                Draw.damageSequence(replay, complete, .35)
            end
        end
        if not move then settle(); return end
        Wait.time(function()
            if not stillPlaying() then return end
            for color,v in pairs(replay) do
                local f=v.frames[i]
                if f and f.au and f.tu then Draw.nudgeAttack(color,f.au,f.tu,false) end
            end
            Wait.time(function() if not guard("combat boards",settle) then complete() end end,step*.24)
        end,step*.18)
    end
    Wait.time(function() if not guard("combat frame", playFrame) then complete() end end, .75)
end


function Draw.seated(color)
    local player = Player[color]
    return player and player.seated
end

function Draw.fillVacantHeroPicks()
    local connected = false
    for _, color in ipairs(game.order) do
        local p = game.players[color]
        if not p.bot and Draw.seated(color) then
            connected = true
            if not p.hero then return end
        end
    end
    if not connected then return end
    for _, color in ipairs(game.order) do
        local p = game.players[color]
        if not p.hero and not Draw.seated(color) then
            for i = 1, #p.heroOptions do if BG.chooseHero(game, color, i) then break end end
        end
    end
end

function Draw.connectedReady()
    local connected = false
    for _, p in ipairs(BG.alivePlayers(game)) do
        if not p.bot and Draw.seated(p.color) then
            connected = true
            if not p.ready and not BG.skipsRecruit(game, p) then return false end
        end
    end
    return connected
end

function Draw.finishVacantChoices(p)
    BG.botTimewarp(game,p)
    for _ = 1, 32 do
        local d = p.discover
        if not d then break end
        for i = #(d.options or {}), 1, -1 do if BG.discoverPick(game, p.color, i) then break end end
        if p.discover == d then
            p.discover = #p.discoverQueue > 0 and table.remove(p.discoverQueue, 1) or nil
        end
    end
    if p.offer and p.offer.kind == "trinket" and not BG.offerPick(game, p.color) then p.offer = nil end
end

local function ticker()
    if not game then return end
    if game.phase == "hero" and tableReady and not busy then
        Draw.fillVacantHeroPicks()
        if BG.allHeroesChosen(game) then
            drainEvents()
            beginRecruit()
            return
        end
        Draw.renderPicks()
        return
    end
    if game.phase == "recruit" and not busy then
        for _, color in ipairs(game.order) do
            local updated=Draw.updateTimer(color,game.players[color])
            if Draw.pulseDarkGift(color) or updated then flushSeat(color) end
        end
        local advance = game.recruitClosed or Draw.connectedReady() or (deadline and os.time() >= deadline)
        for _, color in ipairs(game.order) do
            local p = game.players[color]
            if p.timewarpVisit and deadline and os.time()>=deadline then
                BG.finishTimewarp(game,p)
                syncSeat(color)
                renderBoard(color)
                renderPick(color)
            end
            if Draw.pendingChoice(p) then
                if advance and not Draw.seated(color) then
                    Draw.finishVacantChoices(p)
                    drainEvents()
                    syncSeat(color)
                    renderBoard(color)
                end
                if Draw.pendingChoice(p) then
                    Draw.renderPicks()
                    return
                end
            end
        end
        if advance then
            startCombat()
            return
        end
    end
end

-------------------------------------------------------------------------------
-- player actions
local function actorFor(color, owner)
    if not game or game.phase ~= "recruit" or game.recruitClosed then return nil end
    local p = owner and game.players[owner]
    if not p or not p.alive or p.bot or BG.skipsRecruit(game, p) then return nil end
    if color ~= owner then
        say(color, "That belongs to " .. p.name .. ".")
        return nil
    end
    if Draw.pendingChoice(p) then
        renderPick(color)
        say(color, "Finish the choice above your board first.")
        return nil
    end
    return p
end

local function flash(obj, ok)
    if obj then pcall(function() obj.highlightOn(ok and {0.4, 1, 0.4} or {1, 0.3, 0.25}, 0.5) end) end
end

local function after(p, ok, err, obj)
    if not ok and err then say(p.color, err, {1, 0.5, 0.4}) end
    flash(obj, ok)
    drainEvents()
    syncSeat(p.color, Draw.safeGUID(obj))
    renderBoard(p.color)
    Draw.bobDecals(p.color)
    renderPick(p.color)
    refreshController()
end

local function ownerOfBoard(obj)
    if not obj then return nil end
    for color, s in pairs(seats) do if s.board == obj.getGUID() then return color end end
    return nil
end

function bgUpgrade(obj, color) local p = actorFor(color, ownerOfBoard(obj)); if p then after(p, BG.upgrade(game, p.color)) end end
function bgRefresh(obj, color) local p = actorFor(color, ownerOfBoard(obj)); if p then after(p, BG.refresh(game, p.color)) end end
function bgFreeze(obj, color) local p = actorFor(color, ownerOfBoard(obj)); if p then after(p, BG.toggleFreeze(game, p.color)) end end
function bgBuddy(obj, color)
    local p = actorFor(color, ownerOfBoard(obj))
    if not p then return end
    local ok, err = BG.buyBuddy(game, p.color)
    after(p, ok, err)
    if ok then Draw.showBuddyReward(p.color, BG.buddyFor(p).id, p.buddyCount) end
end

function bgReady(obj, color)
    local p = actorFor(color, ownerOfBoard(obj)); if not p then return end
    BG.setReady(game, p.color, not p.ready)
    renderBoard(p.color)
    ticker()
end
function bgHeroPower(obj, color)
    local p = actorFor(color, ownerOfBoard(obj)); if not p then return end
    local h=BG.powerHero(p)
    local hp=h and BG.HP[h.id]
    if aiming[p.color] then aiming[p.color] = nil; renderBoard(p.color); return end
    if hp and hp.active and hp.target then
        local cost = BG.powerCost(p) or 0
        local locked = BG.powerLock(game, p, hp)
        if locked then return say(p.color, locked, {1, 0.5, 0.4}) end
        if p.gold < cost then return say(p.color, h.power .. " costs " .. cost .. " Gold.", {1, 0.5, 0.4}) end
        aiming[p.color] = hp.target
        local message=({tavern="pick up a Tavern minion",shop="pick up a Tavern card",any="pick up a minion",board="pick up a warband minion"})[hp.target]
        say(p.color,h.power.." · "..(message or "pick up a target"),{.8,.7,1})
        renderBoard(p.color)
        return
    end
    after(p, BG.heroPower(game, p.color, nil))
end

local function indexByUid(list, uid)
    for i, m in ipairs(list) do if tostring(m.uid) == tostring(uid) then return i end end
    return nil
end

local function insertPos(p, right, skipIndex)
    local total, pos = #p.board, 1
    for i = 1, total do
        if i ~= skipIndex and right > slotRight(i, total) then pos = pos + 1 end
    end
    return pos
end

local function zoneOfToken(info)
    local p = game and game.players[info.color]
    if not p then return nil end
    if info.key:sub(1,1)=="s" then
        local i=indexByUid(p.spellShop,info.key:sub(2))
        if i then return "spellshop",i end
        return nil
    end
    if info.key:sub(1, 1) ~= "u" then return nil end
    local uid = info.key:sub(2)
    local ti, bi = indexByUid(p.tavern, uid), indexByUid(p.board, uid)
    if ti then return "tavern", ti end
    if bi then return "board", bi end
    return nil
end

-- A Timewarp visit blocks ordinary recruit actions. Its own offers remain draggable.
function Draw.activeWarpOffer(p, info)
    local visit, d = p and p.timewarpVisit, info.d
    local slot = visit and d and d.warpVisit == visit and visit.slots[d.warpIndex]
    return slot and not slot.taken and slot.id == d.id
end

local function resolveDrop(color, obj, info, releasePosition, viaHand)
    local guid, owner = Draw.safeGUID(obj), info.color
    if info.d and (info.d.lockTier or info.d.lockTurn) then
        if color == owner then
            local release = info.d.lockGold and ("after " .. info.d.lockGold .. " more Gold is spent")
                or info.d.lockTier and ("Tavern Tier " .. info.d.lockTier) or ("Turn " .. info.d.lockTurn)
            say(color, "This minion unlocks at " .. release .. ".")
        end
        return syncSeat(owner, guid)
    end
    local warp = info.key:sub(1, 1) == "w"
    local p
    if warp then
        p = color == owner and game.players[owner]
        if not p or p.bot or not p.alive or not Draw.activeWarpOffer(p, info) then return syncSeat(owner, guid) end
    else
        p = actorFor(color, owner)
        if not p then return syncSeat(owner, guid) end
    end
    local board, bob = boardOf(owner), bobOf(owner)
    if not board then return end
    local kind, uid = info.key:sub(1, 1), info.key:sub(2)
    if kind ~= "u" and kind ~= "s" and kind ~= "w" then return syncSeat(owner, guid) end
    local pos = releasePosition or obj.getPosition()
    local right, near = readerOf(board, pos)
    local onBoard = math.abs(right) < BOARD_HALF_W and near > BOARD_FAR and near < BOARD_NEAR
    local handStrip = math.abs(right) < BOARD_HALF_W and near > HAND_NEAR
    local inPlayerHand = viaHand or handStrip or (not onBoard and inHand(owner, obj))
    if warp then
        if inPlayerHand or (onBoard and near > -0.6) then
            local ok, err = BG.timewarpPick(game, owner, info.d.warpIndex)
            return after(p, ok, err, obj)
        end
        return syncSeat(owner, guid)
    end
    if kind == "s" then return Draw.spellDrop(p, obj, inPlayerHand, onBoard, right, near, uid, after) end

    local onBob = false
    if bob then
        local b = bob.getPosition()
        onBob = (pos.x - b.x) ^ 2 + (pos.z - b.z) ^ 2 < (BOB_SIZE * .75) ^ 2
    end
    local ti, hi, bi = indexByUid(p.tavern, uid), indexByUid(p.hand, uid), indexByUid(p.board, uid)
    local ok, err
    if ti then
        if inPlayerHand or (not onBoard and near > 0) then
            ok, err = BG.buy(game, owner, ti)
            return after(p, ok, err, obj)
        end
        if onBoard and near > PLAY_NEAR and near < BUY_PLAY_NEAR then
            ok, err = BG.buy(game, owner, ti)
            if ok then
                local h = indexByUid(p.hand, uid)
                if h then ok, err = BG.play(game, owner, h, insertPos(p, right)) end
            end
            return after(p, ok, err, obj)
        end
    elseif hi then
        if not inPlayerHand and onBoard and near > PLAY_NEAR then
            if math.abs(near - ROW_WARBAND) <= .82 then
                for i, target in ipairs(p.board) do
                    if math.abs(right - slotRight(i, #p.board)) <= .92 and BG.canMagnetize(p.hand[hi], target) then
                        ok, err = BG.magnetize(game, owner, hi, i)
                        return after(p, ok, err, obj)
                    end
                end
            end
            ok, err = BG.play(game, owner, hi, insertPos(p, right))
            return after(p, ok, err, obj)
        end
        if onBob then say(owner, "Play the minion first. Bob only buys minions from your warband.") end
    elseif bi then
        if onBob or (onBoard and near < SELL_NEAR) then
            ok, err = BG.sell(game, owner, bi)
            return after(p, ok, err, obj)
        end
        if inPlayerHand then
            say(owner, "Drag minions in play up to the Tavern to sell them.")
        else
            local to = insertPos(p, right, bi)
            if to ~= bi then BG.move(game, owner, bi, to) end
        end
    end
    syncSeat(owner, guid)
end

function Draw.queueDrop(guid, info, color, pos, viaHand)
    local current = pendingDrop[guid]
    if current then
        if type(current) == "table" then
            if pos and not current.pos then current.pos = pos end
            current.viaHand = current.viaHand or viaHand
        end
        return
    end
    local ticket = {game = game, turn = game.turn, info = info, pos = pos, viaHand = viaHand}
    pendingDrop[guid] = ticket
    local remaining = 3
    local function dispatch()
        if pendingDrop[guid] ~= ticket then return end
        local active = game == ticket.game and game.phase == "recruit" and game.turn == ticket.turn and tokenInfo[guid] == info
        local obj = active and Draw.ready(guid)
        local readable, held = false, nil
        if obj then readable, held = pcall(function() return obj.held_by_color end) end
        if readable and held and remaining > 0 then
            remaining = remaining - 1
            Wait.frames(dispatch, 2)
            return
        end
        pendingDrop[guid] = nil
        if readable and not held then
            guard("drop", function() resolveDrop(color, obj, info, ticket.pos, ticket.viaHand) end)
        end
    end
    Wait.frames(dispatch, 3)
end


function Draw.spellDecals(obj, d, info)
    local scale = obj.getScale().x
    local src=d.src or {}
    local turns=d.zone=="hand" and (d.lockTurn or src.openTurn)
    if turns and game then turns=math.max(0,turns-game.turn) end
    local liveText = d.zone == "hand" and game and game.players[info.color] and Draw.spellCardText(game.players[info.color], d) or nil
    local key=table.concat({tostring(d.frozen),tostring(settings.flip),tostring(settings.decalFlip),scale,tostring(turns),liveText or ""},"|")
    if info.decalKey == key then return end
    local list = {}
    if d.frozen then
        list[1] = {name = "hsbg_frozen", url = Draw.localArt .. "refined/mo/frozen.png",
            position = {0, (math.max(.13, tokenTop) + .13) / scale, 0}, rotation = {90, Draw.decalYaw(), 0},
            scale = {2.63 / scale, 3.32 / scale, 1}}
    end
    if turns then
        local orient=settings.flip and -1 or 1
        local z=-1.64*orient/scale
        local yaw=Draw.decalYaw()
        local y=(math.max(.13,tokenTop)+.21)/scale
        list[#list+1]={name="hsbg_lockbox_lock",url=Draw.polish("lock.png"),position={.32*orient/scale,y,z},
            rotation={90,yaw,0},scale={.66/scale,.66/scale,1}}
        list[#list+1]={name="hsbg_lockbox_turns",url=Draw.uiArt2("st/w/"..math.min(99,turns)..".png"),
            position={-.36*orient/scale,y,z},rotation={90,yaw,0},scale={.87/scale,.87/scale,1}}
    end

    local face = Draw.spellFaceFor(d.id)
    local B = Draw.spellTextBox(face)
    if d.zone == "hand" and liveText and B then
        local H = CARD_H
        local W = H * face.r
        local spell = BG.SPELLS[d.id]
        Draw.HSCAP = {}
        pcall(Draw.hsText, info.color, "hx", liveText, spell and spell.text, (B.cx - .5) * W, (B.cy - .5) * H, B.w * W, B.h * H, 1, 0)
        local cap = Draw.HSCAP
        Draw.HSCAP = nil
        local yaw, y0 = Draw.decalYaw(), (tokenTop + .02) / scale
        for i, t in ipairs(cap) do
            local right, near = t.right, t.near
            if settings.flip then right, near = -right, -near end
            local h = t.size
            list[#list + 1] = {name = "hsbg_tx" .. i, url = t.url, position = {-right / scale, y0 + (i == 1 and 0 or .03) / scale, near / scale},
                rotation = {90, yaw, 0}, scale = {h * t.face.r / scale, h / scale, 1}}
        end
    end
    if pcall(function() obj.setDecals(list) end) then info.decalKey = key end
end

function Draw.spellDrop(p, obj, held, onBoard, right, near, uid, refresh)
    local bought = indexByUid(p.spellShop, uid)
    if bought then
        if held or (near > PLAY_NEAR and (not onBoard or near < BOARD_NEAR)) then
            local ok, err = BG.buyTavernSpell(game, p.color, bought)
            return refresh(p, ok, err, obj)
        end
        return syncSeat(p.color, Draw.safeGUID(obj))
    end
    local hand = indexByUid(p.spellHand, uid)
    if not hand or held or not onBoard then return syncSeat(p.color, Draw.safeGUID(obj)) end
    local spell = BG.SPELLS[p.spellHand[hand].id]
    local target = nil
    if spell.target then
        local shop = spell.target == "any" and math.abs(near - ROW_TAVERN) < math.abs(near - ROW_WARBAND)
        local minions = shop and p.tavern or p.board
        local count = #minions + (shop and #p.spellShop or 0)
        local row = shop and ROW_TAVERN or ROW_WARBAND
        if math.abs(near - row) < 1.8 then
            for i = 1, #minions do
                if math.abs(right - slotRight(i, count)) <= PITCH / 2 then
                    target = {zone = shop and "tavern" or "board", index = i}
                    break
                end
            end
        end
    elseif near < PLAY_NEAR then
        return syncSeat(p.color, Draw.safeGUID(obj))
    end
    local ok, err = BG.castTavernSpell(game, p.color, hand, target)
    return refresh(p, ok, err, obj)
end



local function highlightZones(color, on, kind)
    local bob = bobOf(color)
    if bob then
        if on and kind == "board" then pcall(function() bob.highlightOn({1, 0.8, 0.3}) end)
        else pcall(function() bob.highlightOff() end) end
    end
end

function Draw.activationTargetIndex(p, info)
    local choice = p and p.discover
    if not choice or (choice.kind~="activate_target" and not (choice.kind=="hero_option" and choice.pickTarget)) then return nil end
    local zone=info.d and info.d.zone=="hand" and "hand" or zoneOfToken(info)
    if choice.kind=="hero_option" then
        if zone~="board" and zone~="tavern" then return nil end
    elseif zone~=choice.zone and not (choice.zone=="tavern_any" and (zone=="tavern" or zone=="spellshop")) then return nil end
    local uid = info.key:sub(2)
    for index, option in ipairs(choice.options) do
        if tostring(option) == uid then return index end
    end
end

function onPlayerAction(player, action, targets)
    if not game or not player then return end
    local color = player.color
    for _, obj in ipairs(targets or {}) do
        local guid = Draw.safeGUID(obj)
        local info = guid and tokenInfo[guid]
        if info then
            local p = game.players[color]
            if game.phase ~= "recruit" or game.recruitClosed or info.d and info.d.combat
                or info.color ~= color or not p or p.bot or not p.alive then return false end
            if info.d and (info.d.lockTier or info.d.lockTurn) then return false end
            if Draw.pendingChoice(p) and not Draw.activeWarpOffer(p, info)
                and not Draw.activationTargetIndex(p, info) then return false end
            if not Player.Action or (action ~= Player.Action.PickUp and action ~= Player.Action.Select) then return false end
        elseif guid then
            for _, s in pairs(seats) do
                if guid == s.board or guid == s.bob then return false end
            end
        end
    end
end

function onObjectPickUp(color, obj)
    local guid = Draw.eventToken(obj)
    if not guid then return end
    local info = tokenInfo[guid]
    local p = game.players[color]
    if Draw.pendingChoice(p) then
        if info.color ~= color then return end
        local index = Draw.activationTargetIndex(p, info)
        if index then
            pendingDrop[guid] = "skip"
            local ok, err = BG.discoverPick(game, color, index)
            after(p, ok, err, obj)
        end
        return
    end
    if aiming[color] and info.color == color then
        local zone, index = zoneOfToken(info)
        local want = aiming[color]
        if zone and (zone==want or want=="any" and (zone=="tavern" or zone=="board")
            or want=="shop" and (zone=="tavern" or zone=="spellshop")) then
            aiming[color] = nil
            pendingDrop[guid] = "skip"
            local p = game.players[color]
            local ok,err=BG.heroPower(game,color,{zone=zone,index=index})
            after(p,ok,err,obj)
            return
        end
        say(color,"Choose an eligible Hero Power target.",{1,.5,.4})
        return
    end
    local zone = zoneOfToken(info)
    if zone then highlightZones(info.color, true, zone) end
end

function onObjectDrop(color, obj)
    local guid = Draw.eventToken(obj)
    if not guid then return end
    local info = tokenInfo[guid]
    highlightZones(info.color, false)
    if pendingDrop[guid] == "skip" then
        pendingDrop[guid] = nil
        local oldGame, turn = game, game.turn
        Wait.frames(function()
            if game == oldGame and game.phase == "recruit" and game.turn == turn and tokenInfo[guid] == info then
                guard("return hero power target", syncSeat, info.color, guid)
            end
        end, 3)
        return
    end
    local ok, pos = pcall(function() return obj.getPosition() end)
    Draw.queueDrop(guid, info, color, ok and pos or nil, false)
end

function onObjectEnterZone(zone, obj)
    local guid = Draw.eventToken(obj)
    if not guid or not zone or pendingDrop[guid] == "skip" then return end
    local ok, t = pcall(function() return zone.type end)
    if not ok or t ~= "Hand" then return end
    local info = tokenInfo[guid]
    local current = Draw.ready(guid)
    local location = zoneOfToken(info)
    local p = game.players[info.color]
    if not current or current.held_by_color then return end
    if location ~= "tavern" and location ~= "spellshop" and not Draw.activeWarpOffer(p, info) then return end
    if inHand(info.color, current) then Draw.queueDrop(guid, info, info.color, nil, true) end
end

