-- choices: click a hero portrait, a Discover card or a trinket on the table
local function choosePick(color, i)
    local p = game and game.players[color]
    if not p then return end
    local model = Draw.pickModel(color)
    if not model then return end
    local ok, err
    if model.kind == "hero" then
        ok, err = BG.chooseHero(game, color, i)
        drainEvents()
        renderPick(color)
        renderBoard(color)
        refreshController()
        if not ok and err then say(color, err, {1, 0.5, 0.4}) end
        ticker()
        return
    elseif model.kind=="quest" then
        ok,err=BG.questPick(game,color,i)
    elseif model.kind=="timewarp" then
        ok,err=BG.timewarpPick(game,color,i)
    elseif model.kind == "discover" then
        ok, err = BG.discoverPick(game, color, i)
    elseif model.kind == "trinket" then
        ok, err = BG.offerPick(game, color, i)
    end
    after(p, ok, err)
end

local function passUnavailableChoice(color)
    local p = game and game.players[color]
    local model = p and Draw.pickModel(color)
    if not model or not model.canPass then return end
    if model.kind=="timewarp" then return after(p,BG.finishTimewarp(game,p)) end
    if model.kind == "discover" then
        local queue = p.discoverQueue
        p.discover = queue and #queue > 0 and table.remove(queue, 1) or nil
    elseif model.kind == "trinket" then
        p.offer = nil
    end
    renderPick(color)
    renderBoard(color)
end

