-- settings screen: a panel on the table beside the Setup Box (opened from the box, host only)
local function hostOnly(color)
    local pl = Player[color]
    if not pl or not pl.host then
        say(color, "Only the host can change the Battlegrounds setup.")
        return false
    end
    return true
end

local ROSTER_MODES = {"rotation", "full"}
local ROSTER_LABELS = {full = "Full Roster", rotation = "Five Tribes"}
local ROSTER_TIPS = {
    full = "All minion types in this season. Tier 7 upgrades require an effect that unlocks them.",
    rotation = "Five random minion types, including stats-and-keywords-only cards. Tiers 1 to 6.",
    scripted = "Five random eligible minion types. Cards without scripted abilities are excluded.",
}
local function seasonInfo()
    local s = Draw.availableSeason(settings.season)
    return (s and s.patch and ("Archived patch " .. s.patch .. ". ") or "") .. (ROSTER_TIPS[settings.roster] or ROSTER_TIPS.full)
end

local function seatYaw(color)
    for _, s in ipairs(SEATS) do if s.color == color then return s.yaw end end
    return 0
end

local function closeSettings()
    widgets[SET] = nil
    settingsDecals = nil
    settingsHost, Draw.seasonPicker = nil, nil
    pcall(function() self.setDecals({}) end)
    hideController()
end

local function onOff(v) return v and "On" or "Off" end

-- The settings panel is this controller (a flat 11.8 x 7.1 board with the tavern-table art as its own
-- texture), moved next to the Setup Box on the host's side, facing the host, and shown only while open.
-- Every word on it that sits on art is baked into the art (ui2/opt/*.png); the two info lines lie on the
-- bare table art. (v4.2 used Codex's Foundry texture here, mirrored, under a panel decal that hid the text.)
local SETTINGS_ROWS = {
    {"season", 0, -1.55, "wide"},
    {"timer",-3.55,-.50},{"trinkets",0,-.50},{"bots",3.55,-.50},
    {"speed",-3.55,.47},{"anomalies",0,.47},{"start",3.55,.47},
    {"whole",-3.55,1.44},{"buddies",0,1.44},{"close",3.55,1.44},
    {"darkgifts",0,2.41},{"timewarp",-3.55,2.41},{"quests",3.55,2.41},
}
local SETTINGS_TOGGLE_KEY = {quests="quests",timewarp="timewarp",buddies = "buddies", trinkets = "trinkets", anomalies = "anomalies", bots = "bots"}
local SETTINGS_TIP = {
    season = "Choose a season", timer = "Turn timer (click to cycle)",
    buddies = "Buddies", trinkets = "Trinkets (offered on turns 6 and 9)", anomalies = "Anomalies (one rule for the whole game)",
    bots = "Fill empty seats with bots", speed = "Combat animation speed",
    timewarp="Optional Minor and Major Timewarped Taverns on turns 6 and 9",
    quests="Quests: on turn 4 every player chooses one of three Quests, each paired with a Reward",
    start = "Start the game", close = "Close the settings",
}

function Draw.optionLabel(key)
    if key == "season" then
        return seasonName(Draw.availableSeason(settings.season))
    elseif key == "timer" then
        return "Timer: " .. settings.timer
    elseif key == "speed" then
        return "Combat: " .. SPEED_NAMES[settings.speed or 2]
    elseif key=="darkgifts" then
        return "Dark Gifts: "..onOff(settings.darkgifts~=false)
    elseif key == "whole" then
        return ROSTER_LABELS[settings.roster] or ROSTER_LABELS.full
    elseif SETTINGS_TOGGLE_KEY[key] then
        local name = key:sub(1, 1):upper() .. key:sub(2)
        return name .. ": " .. onOff(settings[SETTINGS_TOGGLE_KEY[key]])
    end
    return key == "start" and "Start" or "Close"
end


renderSettings = function()
    if not settingsHost then return end
    local launcher = getObjectFromGUID(LAUNCHER_GUID)
    local base = launcher and launcher.getPosition() or {x = 0, y = 1.5, z = 0}
    local bx, by, bz = base.x or base[1], base.y or base[2], base.z or base[3]
    local floor = by - 0.5
    pcall(function() local bb = launcher.getBounds(); floor = bb.center.y - bb.size.y / 2 end)
    local hostYaw = seatYaw(settingsHost)
    local yaw = hostYaw
    if launcher then
        local ok, facing = pcall(function()
            local angle = launcher.getRotation().y
            for _, button in ipairs(launcher.getButtons() or {}) do
                if button.click_function == "toggleTableArena" then
                    local rotation = button.rotation or {}
                    return angle + (rotation.y or rotation[2] or 0)
                end
            end
            return angle
        end)
        if ok then yaw = facing % 360 end
    end
    local a = math.rad(hostYaw)
    -- on the host's side of the box: the host sits on the panel's local +z, which points to (sin a, cos a)
    local toward = 6.6   -- Setup Box half depth 2.42 + panel half depth 3.57 + a 0.6 gap
    local pos = {bx + toward * math.sin(a), floor + 0.06, bz + toward * math.cos(a)}
    pcall(function()
        self.setLock(true)
        self.setPosition(pos)
        self.setRotation({0, yaw, 0})
        self.setInvisibleTo({})
    end)
    widgets[SET] = {}
    if startError then
        ensureTile(SET, "footer", {right = 0, near = -1.89, size = 1,
            labels = {{text = Draw.wrap(startError, 52), x = 0, z = 0, font = 0.24, color = {1, 0.62, 0.54, 1}}}})
    end
    for _, r in ipairs(SETTINGS_ROWS) do
        local key = r[1]
        if key == "season" then
            ensureTile(SET, "o_season", {size = 1, right = r[2], near = r[3], cw = 10.35, ch = 0.85, font = 0.32,
                buttonText = Draw.optionLabel(key), buttonColor = {0.13, 0.14, 0.16, 1}, click = true, action = "set_season",
                tip = "Click to change the season (Season 14 is the default)"})
        elseif key == "start" and not Draw.availableSeason(settings.season) then
            ensureTile(SET, "o_start", {size = 1, right = r[2], near = r[3],
                labels = {{text = "Start", x = 0, z = 0, width = 3.3, height = .85, font = .32, color = {.68, .65, .60, 1}}}})
        else
            ensureTile(SET, "o_" .. key, {size = 1, right = r[2], near = r[3],
                cw = r[4] == "wide" and 10.35 or 3.3, ch = 0.85, font = 0.32,
                buttonText = Draw.optionLabel(key), buttonColor = {0.13, 0.14, 0.16, 1},
                click = true, action = "set_" .. key, tip = key == "season" and seasonInfo() or ROSTER_TIPS[key == "whole" and settings.roster] or SETTINGS_TIP[key]})
        end
    end
    flushSeat(SET)
end

function bgShowSettings(params)
    local color = type(params) == "table" and params.color or params
    if not hostOnly(color) then return false end
    if game and game.phase ~= "over" then say(color, "A game is running. Use End Battlegrounds first."); return false end
    if settingsHost and settingsHost ~= color then closeSettings() end
    settingsHost = color
    renderSettings()
    return true
end

local function cycle(list, value, step)
    for i, v in ipairs(list) do if v == value then return list[(i - 1 + (step or 1)) % #list + 1] end end
    return list[1]
end

local SETTINGS_TOGGLE = {set_quests="quests",set_timewarp="timewarp",set_darkgifts="darkgifts",set_buddies = "buddies", set_trinkets = "trinkets", set_anomalies = "anomalies", set_bots = "bots"}

local function settingsClick(color, action, season)
    if not hostOnly(color) then return end
    if action == "set_close" then closeSettings(); return end
    if action == "set_start" then
        if Draw.startPending then return end
        local ticket = {}
        Draw.startPending = ticket
        local expires = os.time() + 90
        closeSettings()
        pcall(Draw.setLauncherLabel, "Starting...", "Starting Hearthstone Battlegrounds...")
        local function attempt()
            if Draw.startPending ~= ticket then return end
            local ok, reason = bgStart(nil, color, false, true)
            if not ok and reason == "moving" and os.time() < expires then
                Wait.time(attempt, .3)
                return
            end
            Draw.startPending = nil
            if not ok then
                settingsHost = color
                renderSettings()
            end
        end
        Wait.frames(attempt, 2)
        return
    end
    if action == "set_timer" then
        settings.timer = cycle(TIMER_MODES, settings.timer)
    elseif action == "set_speed" then
        settings.speed = (settings.speed or 2) % #SPEED_NAMES + 1
    elseif action == "set_season" then
        settings.season = cycle(Draw.SEASON_CYCLE, settings.season)
    elseif action == "set_whole" then
        settings.roster = cycle(ROSTER_MODES, settings.roster)
    elseif SETTINGS_TOGGLE[action] then
        local k = SETTINGS_TOGGLE[action]
        settings[k] = not settings[k]
    end
    renderSettings()
end

local WIDGET_ACTIONS = {
    upgrade = function(obj, color) bgUpgrade(obj, color) end,
    refresh = function(obj, color) bgRefresh(obj, color) end,
    freeze = function(obj, color) bgFreeze(obj, color) end,
    power = function(obj, color) bgHeroPower(obj, color) end,
    power2=function(obj,color)
        local p=actorFor(color,ownerOfBoard(obj))
        if p then after(p,BG.activateSecondPower(game,color)) end
    end,
    buddy = function(obj, color) bgBuddy(obj, color) end,
    ready = function(obj, color) bgReady(obj, color) end,
}

-- A click on a widget's invisible button: obj is the board it is drawn on (or this controller).

function bgActivateClick(obj, color, alt)
    if alt or not game then return end
    local info = tokenInfo[obj.getGUID()]
    if not info or not info.d or not info.d.src then return end
    local owner = info.color
    local p = actorFor(color, owner)
    if not p then return end
    local uid = info.d.src.uid
    guard("activate", function()
        for i, m in ipairs(p.board) do
            if m.uid == uid then
                local ok, err = BG.activateMinion(game, owner, i)
                after(p, ok, err)
                return
            end
        end
    end)
end
local function widgetClick(obj, color, key)
    local owner
    if obj and obj.getGUID and obj.getGUID() == self.getGUID() then owner = SET else owner = ownerOfBoard(obj) end
    local w = owner and tileOf(owner, key)
    if not w or not w.click then return end
    local action = w.action
    if owner == SET then guard("settings", settingsClick, color, action, w.season); return end
    if action == "pick" or action == "skip" then
        if color ~= owner then say(color, "Those choices belong to " .. owner .. "."); return end
        local s = seats[owner]
        local model = Draw.pickModel(owner)
        if not s or not model or s.choiceClick then return end
        if model.kind == "hero" and action == "pick" then
            s.heroSel = w.index
            s.pickSig = nil
            renderPick(owner)
            return
        end
        s.choiceClick = true
        local index, signature = w.index, model.sig
        Wait.frames(function()
            if seats[owner] ~= s then return end
            s.choiceClick = false
            local current = Draw.pickModel(owner)
            if not current or current.sig ~= signature then return end
            if action == "pick" then guard("choice", choosePick, color, index)
            else guard("continue", passUnavailableChoice, color) end
        end, 1)
        return
    end
    if action == "activate" or action == "darkgift" then
        local p = actorFor(color, owner)
        if not p then return end
        guard(action, function()
            local ok, err
            if action == "darkgift" then
                ok, err = BG.buyDarkGift(game, owner)
                local dg = ok and tileOf(owner, "darkgift")
                if dg and Draw.fxBoard then pcall(Draw.fxBoard, owner, "darkgift", dg.right, dg.near) end
            elseif p.board[w.index] and p.board[w.index].uid == w.uid then
                ok, err = BG.activateMinion(game, owner, w.index)
            end
            after(p, ok, err)
        end)
        return
    end
    if action == "heroconfirm" then
        if color ~= owner then return end
        local s = seats[owner]
        if s and s.heroSel then
            local index = s.heroSel
            s.heroSel = nil
            guard("choice", choosePick, color, index)
        end
        return
    end
    if action == "pickhide" then
        if color == owner then guard("hide choices", Draw.toggleChoices, owner) end
        return
    end
    local fn = WIDGET_ACTIONS[action]
    if fn then guard(action, fn, obj, color) end
end
