-- start / stop
local function launchGame(hostColor)
    if not ROSTER_LABELS[settings.roster] then settings.roster = "rotation" end
    local targets, fallback = activeTargets()
    if #targets == 0 then error("no MTG player mats were found on the table.") end
    local s = Draw.availableSeason(settings.season)
    local roster = ROSTER_LABELS[settings.roster] and settings.roster or "full"
    BG.activateSeason(s and s.key)
    local s15 = s and s.key == "s15"
    local g = BG.new({fullMinions = false, tierSeven = roster == "full", allTribes = roster == "full",
        pool = s and s.pool or nil, season = s and s.key or nil,
        trinkets=settings.trinkets and not s15,buddies=settings.buddies,anomalies=settings.anomalies,
        timewarp=settings.timewarp or s15,quests=settings.quests,heroChoices=4})
    g.darkGiftsEnabled=settings.darkgifts~=false and not s15
    g.historicalStats = s ~= nil
    for _, t in ipairs(targets) do
        local pl = Player[t.color]
        if pl and pl.seated then
            local p=BG.addPlayer(g,t.color,pl.steam_name or t.color,false)
            p.profileKey=tostring(pl.steam_id or pl.steam_name or t.color)
            p.lastGameBoard=BG.copy(lastWarbands[p.profileKey] or {})
        elseif settings.bots then
            BG.addPlayer(g, t.color, t.color .. " Bot", true)
        end
    end
    local started, why = BG.startGame(g)
    if not started then
        error(why or "Battlegrounds needs at least 2 players. Turn Bots on or seat more players.")
    end
    game = g
    startError = nil
    tableReady = false
    local playing = {}
    for _, t in ipairs(targets) do
        local player = game.players[t.color]
        if player and not player.bot then table.insert(playing, t) end
    end
    if #playing == 0 then
        for _, t in ipairs(targets) do if game.players[t.color] then table.insert(playing, t) end end
    end
    busy, busySince = true, os.time()
    if fallback then broadcastToAll("Battlegrounds: fewer than 2 mats are displayed; using the default four seats.", {1, 0.85, 0.4}) end
    local names = {}
    for _, r in ipairs(game.tribes or {}) do table.insert(names, BG.RACE_NAME[r] or r) end
    broadcastToAll(seasonName(s) .. ". " .. ROSTER_LABELS[roster] .. ". Minion types: " .. table.concat(names, ", ") .. " (plus neutral minions).", {0.85, 0.9, 1})
    local a = game.anomaly and anomalyOf(game.anomaly)
    if a then broadcastToAll("Anomaly: " .. a.name .. " - " .. (a.text or ""), {0.8, 0.7, 1}) end
    drainEvents()
    spawnTable(playing, function(success)
        busy = false
        if not game then return end
        tableReady = true
        if not success then broadcastToAll("A board was slow to load; starting anyway.", {1, 0.6, 0.4}) end
        guard("boards", function() renderAll() end)
        for _, t in ipairs(playing) do
            local player, board = Player[t.color], boardOf(t.color)
            if player and player.seated and board then
                pcall(function()
                    player.lookAt({position = board.getPosition(), pitch = 84,
                        yaw = (board.getRotation().y + 180) % 360, distance = 25})
                end)
            end
        end
        pcall(Draw.setLauncherLabel, "End Battlegrounds", "Host only. End the Battlegrounds game.")
        ticker()
    end)
end

function bgStart(_, color, fromLauncher, waitForMats)
    if not hostOnly(color) then return false end
    if not Draw.availableSeason(settings.season) then
        say(color, "Coming soon")
        return false, "season_locked"
    end
    if game and game.phase ~= "over" then
        say(color, "A Battlegrounds game is already running. End it first.")
        return false
    end
    if busy then
        if os.time() - busySince < 45 then
            say(color, "Battlegrounds is still setting up the boards...")
            return false
        end
        busy = false
    end
    if Global.getVar("mtBusy") then
        return false, "moving"
    end
    if not fromLauncher then
        local launcher = getObjectFromGUID(LAUNCHER_GUID)
        if launcher then
            local ok, state = pcall(function() return launcher.call("bgClearArenaBoards") end)
            if ok and state == "busy" then
                if not waitForMats then say(color, "The Setup Box is still opening its boards. Try again in a moment.") end
                return false, "moving"
            end
        end
    end
    game = nil
    Draw.hidePicks()
    local ok, err = pcall(launchGame, color)
    if not ok then
        game, busy, deadline, combatView = nil, false, nil, nil
        BG.activateSeason(nil)
        pcall(Draw.removeTable)
        showError(err)
        return false
    end
    return true
end

function bgStop(_, color)
    if not hostOnly(color) then return end
    Draw.startPending = nil
    game, deadline, combatView, busy = nil, nil, nil, false
    BG.activateSeason(nil)
    pcall(Draw.removeTable)
    pcall(Draw.setLauncherLabel, IDLE_LABEL, "Host only. Open the Battlegrounds settings.")
    broadcastToAll("Battlegrounds game ended by the host.", {1, 0.6, 0.4})
end

function bgFlip(params)
    local color = type(params) == "table" and params.color or params
    if not hostOnly(color) then return end
    settings.flip = not settings.flip
    for c, s in pairs(seats) do
        for key in pairs(s.tokens or {}) do destroyToken(c, key) end
        s.bobKey, s.combatHand = nil, nil
        s.pickSig, s.decalSig = nil, nil
        local bob = bobOf(c)
        if bob then local board = boardOf(c); if board then bob.setRotationSmooth(cardRotation(board), false, true) end end
    end
    renderAll()
end
function bgFlipIcons(params)
    local color = type(params) == "table" and params.color or params
    if not hostOnly(color) then return end
    settings.decalFlip = not settings.decalFlip
    for _, info in pairs(tokenInfo) do info.decalKey = nil end
    for _, s in pairs(seats) do s.bobKey, s.decalSig, s.combatHand = nil, nil, nil end
    settingsDecals = nil
    if settingsHost then renderSettings() end
    renderAll()
end

-- Called by the Tabletop Arena Setup Box one frame after its button is clicked (never nested).
function bgLauncherToggle(params)
    local color = type(params) == "table" and params.color or params
    if Draw.startPending then return true end
    if game and game.phase ~= "over" then bgStop(nil, color); return true end
    if game and game.phase == "over" and hostOnly(color) then
        -- a finished game stays on the table until the host opens the settings again
        game, deadline, combatView, busy = nil, nil, nil, false
        BG.activateSeason(nil)
        pcall(Draw.removeTable)
    end
    bgShowSettings({color = color})
    return game ~= nil
end
function bgPing() return "pong" end
function bgNoop() end
function bgDebugState() return game, settings, seats end
function bgDebugReader(board, pos) return readerOf(board, pos) end   -- for tests
function bgDebugDraw() return Draw end   -- for tests
function bgIsRunning() return game ~= nil and game.phase ~= "over" end

-------------------------------------------------------------------------------
-- save / load
function onSave()
    local data={settings=settings,seats={},lastWarbands=lastWarbands}
    for color, s in pairs(seats) do if color ~= SET then data.seats[color] = {board = s.board, bob = s.bob, loop = s.loop} end end
    if game then
        local g = {}
        for k, v in pairs(game) do
            if k ~= "rand" and k ~= "events" and k ~= "pending" then g[k] = v end
        end
        if game.pending then
            g.pending = {}
            for _, result in ipairs(game.pending) do
                table.insert(g.pending, {a = result.a, b = result.b, bName = result.bName, winner = result.winner,
                    damage = result.damage, permanent = result.permanent})
            end
        end
        data.game = g
    end
    return JSON.encode(data)
end

local function restore(saved)
    if not saved or saved == "" then return end
    local ok, data = pcall(JSON.decode, saved)
    if not ok or type(data) ~= "table" then return end
    if type(data.settings) == "table" then
        local old = data.settings.layout ~= LAYOUT_VERSION
        for k, v in pairs(data.settings) do
            -- cardScale/bobScale/tokenTop (v4.2) were measured too early and made cards tiny: never restored.
            -- flip/decalFlip from older layouts are reset: v4.3 draws art upright for the seated player.
            if k ~= "cardScale" and k ~= "bobScale" and k ~= "tokenTop" and not (old and (k == "flip" or k == "decalFlip")) then
                settings[k] = v
            end
        end
        settings.layout, settings.season = LAYOUT_VERSION, "s14"
        if type(settings.timer) ~= "string" or not (TIMER_MULT[settings.timer] or settings.timer == "No Timer") then settings.timer = "Default" end
    end
    lastWarbands=type(data.lastWarbands)=="table" and data.lastWarbands or {}
    for color, s in pairs(data.seats or {}) do seats[color] = {board = s.board, bob = s.bob, loop = s.loop, tokens = {}} end
    if type(data.game) == "table" then
        game=data.game
        BG.initDeity(game)
        BG.activateSeason(game.historicalStats and game.season or nil)
        game.rand = math.random
        game.events = {}
        game.order = game.order or {}
        for _, p in pairs(game.players or {}) do
            p.hand, p.board, p.tavern = p.hand or {}, p.board or {}, p.tavern or {}
            p.heroOptions, p.discoverQueue = p.heroOptions or {}, p.discoverQueue or {}
            p.counters = p.counters or {pogo = 0, bought = 0, piratesBought = 0, elementals = 0, buysTotal = 0}
            if p.hero and not BG.heroById(p.hero) then p.hero = nil end
            local legacy = p.spellShop == nil
            BG.ensurePlayer(p)
            BG.bindExistingStatCards(p)
            p.maxTier = (game.anomaly == "BG27_Anomaly_504" or p.tierSevenUnlocked) and 7 or 6
            if legacy and game.phase == "recruit" and p.alive then BG.rollSpellShop(game, p) end
            BG.restoreExpedition(game, p)
            for _,m in ipairs(p.board) do
                if m.deityConduitTurn==game.turn then BG.deityConduits[m]=p end
            end
        end
        game.eliminated = game.eliminated or {}
        tableReady = true
        if game.phase == "combat" or game.phase == "ready" or game.phase == "recruit-wait" then
            local resumed = game
            game.phase = "recruit-wait"
            Wait.time(function()
                if game ~= resumed then return end
                if game.pending then
                    lastResults = game.pending
                    guard("resume combat result", finishCombat)
                else
                    guard("resume recruit", beginRecruit)
                end
            end, 3)
        elseif game.phase == "recruit" and not game.recruitClosed then
            local secs = turnSeconds(); deadline = secs and (os.time() + secs) or nil
        end
    end
end

local function adoptTokens()
    for _, obj in ipairs(getObjectsWithTag(CARD_TAG)) do
        local ok, m = pcall(JSON.decode, obj.memo or "")
        if ok and type(m) == "table" and m.c and m.k and game and seats[m.c] then
            seat(m.c).tokens[m.k] = obj.getGUID()
            pcall(function() obj.clearButtons(); obj.tooltip = false end)
            local _, face, isLocal = artFor(m.i, m.g and true or false)
            if BG.SPELLS[m.i] then face, isLocal = Draw.spellFaceFor(m.i), false end
            tokenInfo[obj.getGUID()] = {color = m.c, key = m.k, id = m.i, golden = m.g and true or false, face = face, local_ = isLocal, oval = m.portrait == true, carrier = m.carrier == true, shopPrice = m.price}
        else
            obj.destruct()
        end
    end
end

-- The controller is not part of the idle table: it sits under the table, hidden from everyone.
hideController = function()
    Draw.settingsButtons, Draw.nextSettingsButton = {}, nil
    pcall(function()
        if CONTROLLER_HOME then self.setPosition(CONTROLLER_HOME) end
        self.setLock(true)
        self.clearButtons()
        self.setDecals({})
        self.setInvisibleTo({"White", "Brown", "Red", "Orange", "Yellow", "Green", "Teal", "Blue", "Purple", "Pink", "Grey", "Black"})
    end)
end

function onLoad(saved)
    Wait.time(function() if Draw.fxCleanup then pcall(Draw.fxCleanup) end end, 1)
    math.randomseed(os.time())
    hideController()
    restore(saved)
    Wait.time(function()
        guard("load", function()
            -- controls and choices are rebuilt from the game state
            for _, o in ipairs(getObjectsWithTag(UI_TAG)) do pcall(function() o.destruct() end) end
            widgets = {}
            local humanBoard = false
            for color in pairs(seats) do
                local p = game and game.players[color]
                if p and not p.bot then humanBoard = true; break end
            end
            for color, st in pairs(seats) do
                local p = game and game.players[color]
                if humanBoard and p and p.bot then
                    for _, guid in ipairs({st.board, st.bob}) do
                        local obj = Draw.live(guid)
                        if obj then pcall(function() obj.destruct() end) end
                    end
                    seats[color] = nil
                else
                    st.pickSig, st.decalSig, st.leaderKey = nil, nil, nil
                    local board = boardOf(color)
                    if board then pcall(function() board.call("setArenaPhase", {phase = "recruit"}) end) end
                end
            end
            adoptTokens()
            renderAll()
        end)
        Wait.time(function()
            if not guard("turn", ticker) then busy = false end
        end, 1, -1)
        Wait.time(function()
            if game then guard("hover", Draw.pollFeedback) end
        end, .12, -1)
    end, 1.5)
end
